Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-587-babylonian-destruction-of-jerusalem-and-first-temple-21"]||=( {} ),{"title":"تدمير البابليين للقدس والهيكل الأول","location":"القدس / يهوذا","story":"استولت القوات البابلية على القدس ودمرت الهيكل الأول وأنهت مملكة يهوذا.","context":"هذا الحدث جزء من السجل الزمني للعنف الموثق ضد المجتمع اليهودي وانهيار المملكة تحت الإمبراطورية البابلية.","aftermath":"غير الدمار والسبي الحياة والهوية والمؤسسات اليهودية بصورة عميقة، وأصبحت بابل مركزًا مهمًا للحياة اليهودية.","sourceStatus":"ثقة عالية"});
Object.assign(window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-539-cyrus-conquers-babylon-and-permits-return-22"]||=( {} ),{"title":"כורש כובש את בבל ומתיר שיבה","location":"בבל / האימפריה הפרסית / יהודה","story":"כורש השני מלך פרס כבש את בבל בשנת 539 לפנה״ס. המדיניות הפרסית אפשרה לעמים שהוגלו, ובהם יהודאים, לשקם מקדשים וקהילות. המקרא קושר מדיניות זו לשיבה מגלות בבל ולבנייה מחדש בירושלים.","context":"האירוע ממקם את השיבה בתוך המעבר הרחב משלטון בבלי לשלטון פרסי. פרטי השיבה היהודאית נשענים בחלקם על מקורות מקראיים.","aftermath":"השיבה לא הייתה מלאה; קהילה יהודית גדולה נשארה בבבל, בעוד ירושלים ויהודה החלו תהליך של שיקום תחת שלטון פרסי.","sourceStatus":"ראיות חזקות לכיבוש הפרסי ולמדיניות שיקום; פרטי השיבה ליהודה נשענים בחלקם על מקורות מקראיים"});
Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-539-cyrus-conquers-babylon-and-permits-return-22"]||=( {} ),{"title":"كورش يغزو بابل ويسمح بالعودة","location":"بابل / الإمبراطورية الفارسية / يهوذا","story":"غزا كورش الثاني ملك فارس بابل سنة 539 قبل الميلاد. وسمحت السياسة الفارسية للشعوب المهجرة، ومن بينها اليهوديون، بإعادة بناء المعابد والمجتمعات. وتربط النصوص التوراتية هذه السياسة بالعودة من السبي البابلي وإعادة البناء في القدس.","context":"يضع الحدث العودة ضمن الانتقال الأوسع من الحكم البابلي إلى الحكم الفارسي. وتعتمد تفاصيل العودة اليهودية جزئيًا على المصادر التوراتية.","aftermath":"لم تكن العودة كاملة؛ بقي مجتمع يهودي كبير في بابل، بينما بدأت القدس ويهوذا عملية إعادة بناء تحت الحكم الفارسي.","sourceStatus":"أدلة قوية على الغزو الفارسي وسياسة الاستعادة؛ تفاصيل العودة إلى يهوذا تعتمد جزئيًا على المصادر التوراتية"});

window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-332-alexander-the-great-conquers-the-levant-23"]={"title":"אלכסנדר הגדול כובש את הלבנט","location":"הלבנט / יהודה","story":"כיבושיו של אלכסנדר סיימו את השליטה הפרסית בלבנט והכניסו את יהודה לעולם המדיני ההלניסטי. ירושלים עצמה אינה מתועדת בוודאות כזירת קרב גדול במסעו, אך הכיבוש שינה את הסביבה הפוליטית שבה התפתחו מאוחר יותר עימותים יהודיים.","context":"האירוע מציג שינוי אימפריאלי רחב שהשפיע על יהודה, תוך הבחנה בין הכיבוש האזורי המתועד היטב לבין מסורות מאוחרות על אלכסנדר וירושלים.","aftermath":"יהודה עברה לשלטון הלניסטי, ותהליכי הלניזציה והמאבקים בין הממלכות היורשות עיצבו את התקופה הבאה.","sourceStatus":"רמת ודאות גבוהה מאוד לגבי הכיבוש האזורי; סיפורים מאוחרים על אלכסנדר וירושלים פחות מבוססים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-200-seleucid-control-of-judea-after-the-battle-of-panium-24"]={"title":"שליטה סלאוקית ביהודה לאחר קרב פניון","location":"יהודה / קוילה־סוריה","story":"לאחר עשרות שנים של מלחמות בין בית תלמי לבית סלאוקוס, ניצחונו של אנטיוכוס השלישי העביר את יהודה לשלטון סלאוקי. בתחילה זכו המוסדות היהודיים להגנות, אך משברים פוליטיים וכלכליים מאוחרים יותר תרמו לעימות בתקופת אנטיוכוס הרביעי.","context":"המעבר לשלטון סלאוקי היה חלק ממאבק רחב בין ממלכות הלניסטיות ולא החל כרדיפה דתית של יהודים.","aftermath":"המתחים המאוחרים בתוך יהודה ובאימפריה הסלאוקית יצרו את התנאים למשבר ולמרד החשמונאים.","sourceStatus":"ראיות היסטוריות הלניסטיות חזקות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-168-antiochus-iv-captures-jerusalem-and-suppresses-jewish-practices-25"]={"title":"אנטיוכוס הרביעי כובש את ירושלים ומדכא מנהגים יהודיים","location":"ירושלים / יהודה","story":"במהלך סערה פוליטית ביהודה התערבו כוחותיו של אנטיוכוס הרביעי אפיפנס בירושלים. מקורות יהודיים עתיקים מתארים הרג, ביזת המקדש, הגבלות על מנהגים יהודיים והכנסת פולחן פגאני למקדש. צעדים אלה סייעו להצית מרד מזוין.","context":"המשבר שילב מאבקי כוח פנימיים ביהודה עם התערבות סלאוקית ומדיניות כפייה דתית; הסדר המדויק והמניעים עדיין נידונים במחקר.","aftermath":"הדיכוי והפגיעה במקדש תרמו ישירות לפרוץ מרד החשמונאים.","sourceStatus":"ראיות ספרותיות עתיקות חזקות; הרצף המדויק והמניעים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-167-maccabean-revolt-26"]={"title":"מרד החשמונאים","location":"יהודה","story":"מרד יהודי פרץ נגד השלטון הסלאוקי על רקע מדיניות הכפייה של אנטיוכוס הרביעי ועימותים פנימיים בחברה היהודאית.","context":"המרד היה גם התנגדות לשלטון ולכפייה דתית וגם חלק ממאבק פנימי על הנהגה וזהות ביהודה ההלניסטית.","aftermath":"המורדים השיגו הישגים צבאיים, השיבו את השליטה במקדש ובהמשך הניחו את היסודות לשלטון החשמונאי.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-164-maccabees-recapture-and-rededicate-the-temple-27"]={"title":"החשמונאים כובשים מחדש וחונכים את המקדש","location":"ירושלים / יהודה","story":"כוחות בהנהגת יהודה המכבי השתלטו על מתחם המקדש בירושלים וחנכו מחדש את המקדש לאחר חילולו תחת השלטון הסלאוקי. האירוע נעשה לבסיס חג החנוכה, בעוד המלחמה נגד הכוחות הסלאוקיים נמשכה.","context":"חנוכת המקדש הייתה הישג מרכזי במרד אך לא סיימה את המלחמה ולא יצרה מיד עצמאות מדינית מלאה.","aftermath":"הלחימה נמשכה, והצלחת המרד הובילה בהדרגה לעליית הנהגה חשמונאית עצמאית.","sourceStatus":"ראיות ספרותיות עתיקות חזקות"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-332-alexander-the-great-conquers-the-levant-23"]={"title":"الإسكندر الأكبر يغزو بلاد الشام","location":"بلاد الشام / يهوذا","story":"أنهت فتوحات الإسكندر السيطرة الفارسية على بلاد الشام وأدخلت يهوذا في العالم السياسي الهلنستي. ولا توجد وثائق مؤكدة تجعل القدس نفسها ساحة لمعركة كبرى في حملته، لكن الفتح غير البيئة السياسية التي تطورت فيها الصراعات اليهودية اللاحقة.","context":"يعرض الحدث تحولًا إمبراطوريًا واسعًا أثر في يهوذا، مع التمييز بين الفتح الإقليمي الموثق جيدًا وبين الروايات اللاحقة عن الإسكندر والقدس.","aftermath":"انتقلت يهوذا إلى الحكم الهلنستي، وشكلت الهلننة والصراعات بين الممالك الخلف المرحلة التالية.","sourceStatus":"ثقة عالية جدًا في الفتح الإقليمي؛ الروايات اللاحقة عن الإسكندر والقدس أقل ثبوتًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-200-seleucid-control-of-judea-after-the-battle-of-panium-24"]={"title":"السيطرة السلوقية على يهوذا بعد معركة بانيوم","location":"يهوذا / جوف سوريا","story":"بعد عقود من الحروب البطلمية السلوقية، أدى انتصار أنطيوخوس الثالث إلى انتقال يهوذا إلى الحكم السلوقي. وحظيت المؤسسات اليهودية في البداية بحماية، لكن أزمات سياسية ومالية لاحقة ساهمت في المواجهة في عهد أنطيوخوس الرابع.","context":"كان الانتقال إلى الحكم السلوقي جزءًا من صراع أوسع بين الممالك الهلنستية ولم يبدأ كاضطهاد ديني لليهود.","aftermath":"هيأت التوترات اللاحقة داخل يهوذا والإمبراطورية السلوقية الظروف للأزمة ولثورة المكابيين.","sourceStatus":"أدلة تاريخية هلنستية قوية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-168-antiochus-iv-captures-jerusalem-and-suppresses-jewish-practices-25"]={"title":"أنطيوخوس الرابع يستولي على القدس ويقمع الممارسات اليهودية","location":"القدس / يهوذا","story":"خلال اضطراب سياسي في يهوذا تدخلت قوات أنطيوخوس الرابع إبيفانيس في القدس. وتصف مصادر يهودية قديمة القتل ونهب الهيكل وفرض قيود على الممارسات اليهودية وإقامة عبادة وثنية في الحرم. وساعدت هذه الإجراءات على إشعال تمرد مسلح.","context":"جمعت الأزمة بين صراعات سلطة داخلية في يهوذا والتدخل السلوقي وسياسات الإكراه الديني؛ ولا يزال التسلسل الدقيق والدوافع موضع بحث.","aftermath":"ساهم القمع وانتهاك الهيكل مباشرة في اندلاع ثورة المكابيين.","sourceStatus":"أدلة أدبية قديمة قوية؛ التسلسل الدقيق والدوافع موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-167-maccabean-revolt-26"]={"title":"ثورة المكابيين","location":"يهوذا","story":"اندلعت ثورة يهودية ضد الحكم السلوقي في ظل سياسات أنطيوخوس الرابع القسرية والصراع داخل المجتمع اليهودي.","context":"كانت الثورة مقاومة للحكم والإكراه الديني وفي الوقت نفسه جزءًا من صراع داخلي على القيادة والهوية في يهوذا الهلنستية.","aftermath":"حقق المتمردون نجاحات عسكرية واستعادوا السيطرة على الهيكل ومهدوا لاحقًا لقيام الحكم الحشموني.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-164-maccabees-recapture-and-rededicate-the-temple-27"]={"title":"المكابيون يستعيدون الهيكل ويعيدون تدشينه","location":"القدس / يهوذا","story":"سيطرت قوات بقيادة يهوذا المكابي على حرم الهيكل في القدس وأعادت تدشينه بعد تدنيسه في ظل الحكم السلوقي. وأصبح الحدث أساس عيد حانوكا، بينما استمرت الحرب ضد القوات السلوقية.","context":"كان تدشين الهيكل إنجازًا رئيسيًا للثورة لكنه لم ينه الحرب ولم يحقق فورًا استقلالًا سياسيًا كاملًا.","aftermath":"استمر القتال وأدى نجاح الثورة تدريجيًا إلى صعود قيادة حشمونية مستقلة.","sourceStatus":"أدلة أدبية قديمة قوية"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-142-hasmonean-independence-emerges-28"]={"title":"עצמאות חשמונאית מתגבשת","location":"יהודה","story":"תחת שמעון השיגה ההנהגה החשמונאית עצמאות מדינית אפקטיבית מן השליטה הסלאוקית. השושלת שצמחה מן המרד הרחיבה מאוחר יותר את שליטתה מעבר ליהודה באמצעות מלחמות וכיבושים.","context":"החשמונאים עברו מתנועת מרד לשושלת שלטונית, ולכן התקופה כוללת גם עצמאות יהודית וגם התפשטות צבאית כלפי שכנים.","aftermath":"המדינה החשמונאית נעשתה כוח אזורי והמשיכה להתרחב בדורות הבאים.","sourceStatus":"ראיות ספרותיות והיסטוריות עתיקות חזקות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-125-hasmonean-conquest-of-idumea-29"]={"title":"הכיבוש החשמונאי של אדום","location":"אדום / דרום יהודה","story":"יוחנן הורקנוס הרחיב את המדינה החשמונאית לאדום. מקורות עתיקים מספרים שהאדומים שולבו במדינה היהודאית ונדרשו לאמץ מנהגים יהודיים, ובהם ברית מילה. חוקרים מודרניים דנים במידת הכפייה ובאופן שבו נכון לתאר את התהליך.","context":"האירוע חשוב משום שהמדינה החשמונאית, שקמה מתוך מרד נגד כפייה סלאוקית, הפעילה בעצמה כוח כלפי אוכלוסיות שכנות.","aftermath":"אדום שולבה במדינה החשמונאית, ושילוב זה השפיע מאוחר יותר גם על עליית בית הורדוס.","sourceStatus":"עדויות ספרותיות עתיקות; אופיו ומידת הכפייה בתהליך הגיור שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-103-hasmonean-expansion-under-alexander-jannaeus-30"]={"title":"ההתפשטות החשמונאית תחת אלכסנדר ינאי","location":"יהודה והשטחים הסמוכים","story":"אלכסנדר ינאי הרחיב את השטח החשמונאי באמצעות מלחמות חוזרות נגד ערים ועמים שכנים. תקופתו כללה גם עימות פנימי חריף בין המלוכה לבין מתנגדים המזוהים במקורות מאוחרים עם הפרושים.","context":"האירוע מציג הן את ההתפשטות הצבאית של המדינה היהודית והן את האלימות הפנים־יהודית בתקופת החשמונאים.","aftermath":"הממלכה התרחבה, אך העימותים הפנימיים החלישו את היציבות הפוליטית והעמיקו מחלוקות.","sourceStatus":"עדויות ספרותיות עתיקות; מספרי הנפגעים ותיאורי הפלגים דורשים זהירות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-88-hasmonean-civil-conflict-and-repression-31"]={"title":"עימות פנימי ודיכוי בתקופה החשמונאית","location":"יהודה","story":"מקורות עתיקים מתארים עימות פנימי מר בתקופת אלכסנדר ינאי, כולל מרד נגד המלך ופעולות תגמול אכזריות. יוסף בן מתתיהו מדווח על הוצאות להורג המוניות, אך יש להתייחס בזהירות למספרים ולפרטים הדרמטיים שלו.","context":"זהו פרק של אלימות פנים־יהודית ולא רדיפה שבוצעה בידי כוח חיצוני.","aftermath":"העימות העמיק את הקרעים הפוליטיים והדתיים בתוך יהודה והותיר מורשת של חוסר יציבות.","sourceStatus":"עדויות ספרותיות עתיקות, בעיקר יוסף בן מתתיהו; המספרים המדויקים אינם ודאיים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-67-hasmonean-civil-war-hyrcanus-ii-and-aristobulus-ii-32"]={"title":"מלחמת האזרחים החשמונאית: הורקנוס השני ואריסטובולוס השני","location":"יהודה / ירושלים","story":"סכסוך ירושה בין הורקנוס השני לאריסטובולוס השני הידרדר למלחמת אזרחים. שני הצדדים ביקשו תמיכה חיצונית, ובכך יצרו את התנאים להתערבותו של המצביא הרומי פומפיוס ביהודה.","context":"המאבק הפנים־חשמונאי החליש את העצמאות המדינית והזמין מעורבות רומית ישירה.","aftermath":"התערבות רומא הובילה למצור על ירושלים ולהכנסת יהודה לתחום ההשפעה הרומי.","sourceStatus":"ראיות ספרותיות עתיקות חזקות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-63-pompey-s-siege-and-capture-of-jerusalem-33"]={"title":"המצור של פומפיוס וכיבוש ירושלים","location":"ירושלים","story":"המצביא הרומי פומפיוס התערב במלחמת האזרחים החשמונאית, הטיל מצור על ירושלים והכניס את יהודה לתחום ההשפעה של רומא.","context":"הכיבוש נבע במידה רבה ממאבק הירושה החשמונאי ומבקשות ההתערבות של הצדדים היריבים.","aftermath":"עצמאותה של יהודה הצטמצמה באופן משמעותי, ורומא נעשתה הכוח החיצוני המרכזי בפוליטיקה המקומית.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-37-herod-and-roman-forces-capture-jerusalem-34"]={"title":"הורדוס והכוחות הרומיים כובשים את ירושלים","location":"ירושלים","story":"הורדוס, בגיבוי כוחות רומיים, הטיל מצור על ירושלים וכבש אותה מידי אנטיגונוס השני מתתיהו, המלך החשמונאי האחרון. הכיבוש סיים את המלוכה החשמונאית העצמאית וביסס את הורדוס כמלך חסות של רומא ביהודה.","context":"האירוע היה חלק ממאבק שושלתי ופוליטי שבו כוחות יהודיים ורומיים לחמו משני הצדדים.","aftermath":"שלטון בית הורדוס החל תחת חסות רומית, והעצמאות החשמונאית הגיעה לקצה.","sourceStatus":"ראיות ספרותיות עתיקות והיסטוריות מן התקופה הרומית חזקות"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-142-hasmonean-independence-emerges-28"]={"title":"بروز الاستقلال الحشموني","location":"يهوذا","story":"في عهد سمعان حققت القيادة الحشمونية استقلالًا سياسيًا فعليًا عن السيطرة السلوقية. ثم وسعت السلالة التي خرجت من الثورة حكمها خارج يهوذا بالحروب والفتوحات.","context":"انتقل الحشمونيون من حركة تمرد إلى سلالة حاكمة، ولذلك تشمل المرحلة الاستقلال اليهودي وكذلك التوسع العسكري تجاه الجيران.","aftermath":"أصبحت الدولة الحشمونية قوة إقليمية وواصلت التوسع في الأجيال التالية.","sourceStatus":"أدلة أدبية وتاريخية قديمة قوية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-125-hasmonean-conquest-of-idumea-29"]={"title":"الفتح الحشموني لأدوم","location":"أدوم / جنوب يهوذا","story":"وسع يوحنا هيركانوس الدولة الحشمونية إلى أدوم. وتذكر مصادر قديمة أن الأدوميين أُدمجوا في الكيان اليهودي وطُلب منهم تبني ممارسات يهودية منها الختان. ويناقش المؤرخون المعاصرون درجة الإكراه وأفضل توصيف للعملية.","context":"الحدث مهم لأن الدولة الحشمونية التي نشأت من ثورة ضد الإكراه السلوقي استخدمت بدورها القوة تجاه جماعات مجاورة.","aftermath":"دُمجت أدوم في الدولة الحشمونية، وكان لهذا الاندماج أثر لاحق في صعود الأسرة الهيرودية.","sourceStatus":"أدلة أدبية قديمة؛ طبيعة ودرجة الإكراه في التحول الديني موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-103-hasmonean-expansion-under-alexander-jannaeus-30"]={"title":"التوسع الحشموني في عهد ألكسندر ينايوس","location":"يهوذا والأراضي المجاورة","story":"وسع ألكسندر ينايوس الأراضي الحشمونية عبر حروب متكررة ضد مدن وشعوب مجاورة. وشهد عهده أيضًا صراعًا يهوديًا داخليًا شديدًا بين الملكية ومعارضين تربطهم مصادر لاحقة بالفريسيين.","context":"يعرض الحدث التوسع العسكري للدولة اليهودية وكذلك العنف الداخلي اليهودي في العصر الحشموني.","aftermath":"توسعت المملكة، لكن الصراعات الداخلية أضعفت الاستقرار السياسي وعمقت الانقسامات.","sourceStatus":"أدلة أدبية قديمة؛ أعداد الضحايا ووصف الفصائل يتطلبان الحذر"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-88-hasmonean-civil-conflict-and-repression-31"]={"title":"الصراع الأهلي والقمع الحشموني","location":"يهوذا","story":"تصف روايات قديمة صراعًا داخليًا مريرًا في عهد ألكسندر ينايوس، شمل تمردًا ضد الملك وأعمال انتقام قاسية. ويذكر يوسيفوس إعدامات جماعية، لكن أرقامه وتفاصيله الدرامية يجب التعامل معها بحذر.","context":"هذه مرحلة من العنف اليهودي الداخلي وليست اضطهادًا نفذته قوة خارجية.","aftermath":"عمق الصراع الانقسامات السياسية والدينية داخل يهوذا وترك إرثًا من عدم الاستقرار.","sourceStatus":"أدلة أدبية قديمة، أساسًا يوسيفوس؛ الأرقام الدقيقة غير مؤكدة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-67-hasmonean-civil-war-hyrcanus-ii-and-aristobulus-ii-32"]={"title":"الحرب الأهلية الحشمونية: هيركانوس الثاني وأرسطوبولوس الثاني","location":"يهوذا / القدس","story":"تحول نزاع على الخلافة بين هيركانوس الثاني وأرسطوبولوس الثاني إلى حرب أهلية. وسعى الطرفان إلى دعم خارجي، مما هيأ الظروف لتدخل القائد الروماني بومبي في يهوذا.","context":"أضعف الصراع الحشموني الداخلي الاستقلال السياسي ودعا إلى تدخل روماني مباشر.","aftermath":"أدى التدخل الروماني إلى حصار القدس ودخول يهوذا في دائرة النفوذ الروماني.","sourceStatus":"أدلة أدبية قديمة قوية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-63-pompey-s-siege-and-capture-of-jerusalem-33"]={"title":"حصار بومبي للقدس والاستيلاء عليها","location":"القدس","story":"تدخل القائد الروماني بومبي في الحرب الأهلية الحشمونية وحاصر القدس وأدخل يهوذا في دائرة النفوذ الروماني.","context":"نشأ الفتح بدرجة كبيرة من صراع الخلافة الحشموني وطلب الأطراف المتنافسة التدخل الخارجي.","aftermath":"تقلص استقلال يهوذا بصورة كبيرة وأصبحت روما القوة الخارجية الرئيسية في السياسة المحلية.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-37-herod-and-roman-forces-capture-jerusalem-34"]={"title":"هيرودس والقوات الرومانية يستولون على القدس","location":"القدس","story":"حاصر هيرودس، بدعم قوات رومانية، القدس واستولى عليها من أنتيغونوس الثاني متاثياس، آخر الملوك الحشمونيين. وأنهى الفتح الملكية الحشمونية المستقلة ورسخ هيرودس ملكًا تابعًا لروما في يهوذا.","context":"كان الحدث جزءًا من صراع أسري وسياسي قاتلت فيه قوات يهودية ورومانية على جانبي النزاع.","aftermath":"بدأ حكم الأسرة الهيرودية تحت الرعاية الرومانية وانتهى الاستقلال الحشموني.","sourceStatus":"أدلة أدبية قديمة وتاريخية قوية من العصر الروماني"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-6-judea-becomes-a-roman-province-and-census-resistance-35"]={"title":"יהודה נעשית פרובינקיה רומית והתנגדות למפקד","location":"יהודה","story":"רומא הדיחה את הורדוס ארכלאוס והעבירה את יהודה למינהל רומי ישיר. המפקד המזוהה עם קוויריניוס עורר התנגדות המתועדת במקורות עתיקים וסייע לעצב תנועות אנטי־רומיות מאוחרות יותר.","context":"האירוע מוצג תוך תשומת לב למגבלות ולהטיות של המקורות העתיקים ששרדו, במיוחד כאשר מקורות ספרותיים מאוחרים מספקים מניעים או מספרי נפגעים.","aftermath":"המעבר לשלטון רומי ישיר צמצם את האוטונומיה הפוליטית והעמיק מתחים שימשיכו לאורך המאה הראשונה.","sourceStatus":"עדויות ספרותיות עתיקות; ההקשר הפוליטי מבוסס היטב"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-38-alexandria-anti-jewish-violence-36"]={"title":"אלימות אנטי־יהודית באלכסנדריה","location":"אלכסנדריה, מצרים הרומית","story":"אלימות קהילתית קשה פרצה באלכסנדריה בין תושבים יוונים ליהודים על רקע סכסוך פוליטי בתקופת הנציב הרומי אאולוס אביליוס פלאקוס. פילון מתאר יהודים שנדחקו לרובע מוגבל, בתים וחנויות שנבזזו ואנשים שהותקפו ונהרגו.","context":"מצרים הרומית כללה מתחים פוליטיים, אזרחיים וקהילתיים. האירוע מזהה את המשתתפים ואינו מציג את האלימות כעימות אתני רציף ופשוט.","aftermath":"האירוע העמיק את חוסר הביטחון של הקהילה היהודית באלכסנדריה והוביל למאבקים ופניות נוספות לשלטון הרומי.","sourceStatus":"עדות ספרותית חזקה בת התקופה מפילון; מספר הנפגעים המדויק אינו ידוע"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-46-roman-crucifixion-of-jacob-and-simon-sons-of-judas-the-galilean-37"]={"title":"צליבת יעקב ושמעון, בני יהודה הגלילי, בידי רומא","location":"יהודה","story":"יוסף בן מתתיהו מספר שהנציב הרומי טיבריוס יוליוס אלכסנדר הורה לצלוב את יעקב ושמעון, בני יהודה הגלילי, שתנועתו התנגדה למיסוי הרומי. האירוע ממחיש את המשך ההתנגדות ואת הדיכוי הרומי לפני המרד הגדול של שנת 66.","context":"יהודה הרומית כללה דיכוי אימפריאלי, התנגדות יהודית ועימותים פנימיים. המקור המרכזי כאן הוא יוסף בן מתתיהו.","aftermath":"המתחים בין תנועות התנגדות יהודיות לשלטון הרומי נמשכו והחריפו בעשורים הבאים.","sourceStatus":"עדות ספרותית עתיקה, בעיקר יוסף בן מתתיהו"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-50-jewish-samaritan-violence-under-roman-rule-38"]={"title":"אלימות יהודית–שומרונית תחת שלטון רומא","location":"יהודה / שומרון","story":"לאחר שעולי רגל מן הגליל נהרגו בדרכם דרך שומרון, קבוצות יהודיות ביצעו פעולות תגמול נגד כפרים שומרוניים. לאחר מכן התערבה רומא. האירוע מראה שהאלימות בארץ תחת רומא לא הייתה רק עימות בין יהודים לרומאים אלא כללה גם עימותים בין־קהילתיים חמורים.","context":"האירוע מוצג כעימות בין קהילות מסוימות תחת שלטון רומי, ולא כמלחמה רציפה בין עמים שלמים.","aftermath":"ההתערבות הרומית לא פתרה את המתחים, והיחסים בין הקהילות נותרו מורכבים.","sourceStatus":"עדויות ספרותיות עתיקות; הפרטים נשענים בעיקר על יוסף בן מתתיהו"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-64-gessius-florus-and-escalating-violence-in-judea-39"]={"title":"גסיוס פלורוס והחרפת האלימות ביהודה","location":"ירושלים / יהודה","story":"הנציב הרומי גסיוס פלורוס נודע במקורות יהודיים בשל מיסוי כבד ואלימות. נטילת כספים מאוצר המקדש ודיכוי אכזרי של מחאות בירושלים סייעו להפוך מתחים ממושכים למרד גלוי.","context":"המקורות העתיקים עוינים במיוחד את פלורוס, ולכן יש להבחין בין עצם המשבר המתועד לבין פרטים ומניעים שעברו דרך נקודת מבט פוליטית.","aftermath":"העימותים בירושלים היו בין הגורמים המיידיים לפרוץ המרד היהודי הגדול נגד רומא בשנת 66.","sourceStatus":"עדויות ספרותיות עתיקות חזקות; המניעים והפרטים מסוננים דרך מקורות עוינים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-66-first-jewish-roman-war-40"]={"title":"המרד הגדול — המלחמה היהודית–רומית הראשונה","location":"יהודה הרומית","story":"מרד יהודי גדול נגד השלטון הרומי החל בשנת 66 לספירה ודוכא במהלך כמה שנות מלחמה.","context":"המלחמה נבעה משילוב של מתחים פוליטיים, כלכליים, דתיים וחברתיים, וכללה גם מאבקים פנימיים בין פלגים יהודיים.","aftermath":"המלחמה הובילה לכיבוש ירושלים ולחורבן בית המקדש השני בשנת 70; מוקדי התנגדות מסוימים המשיכו לאחר מכן.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-66-defeat-of-cestius-gallus-at-beth-horon-41"]={"title":"תבוסת קסטיוס גאלוס בבית חורון","location":"יהודה","story":"בתחילת המרד התקדם מושל סוריה קסטיוס גאלוס לעבר ירושלים ולאחר מכן נסוג. כוחות יהודאיים תקפו את הצבא הנסוג ליד בית חורון והנחילו לרומאים תבוסה קשה, שחיזקה מאוד את המרד והבטיחה תגובה אימפריאלית רחבה.","context":"האירוע מתועד בעיקר במקורות ספרותיים עתיקים, ויש להיזהר במספרי נפגעים מדויקים.","aftermath":"הניצחון חיזק את ביטחון המורדים אך גם הביא את רומא לשלוח כוח גדול יותר תחת אספסיאנוס.","sourceStatus":"עדויות ספרותיות עתיקות חזקות; מספרי הנפגעים המדויקים אינם ודאיים"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-6-judea-becomes-a-roman-province-and-census-resistance-35"]={"title":"تحول يهوذا إلى ولاية رومانية ومقاومة الإحصاء","location":"يهوذا","story":"عزلت روما هيرودس أرخيلاوس وأخضعت يهوذا للإدارة الرومانية المباشرة. وأثار الإحصاء المرتبط بكيرينيوس مقاومة تذكرها المصادر القديمة وساهم في تشكيل حركات لاحقة مناهضة لروما.","context":"يُعرض الحدث مع الانتباه إلى حدود وانحيازات المصادر القديمة الباقية، خاصة عندما تقدم الروايات الأدبية اللاحقة دوافع أو أعداد ضحايا.","aftermath":"قلص الانتقال إلى الحكم الروماني المباشر الاستقلال السياسي وعمق التوترات التي استمرت خلال القرن الأول.","sourceStatus":"أدلة أدبية قديمة؛ السياق السياسي ثابت جيدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-38-alexandria-anti-jewish-violence-36"]={"title":"عنف معادٍ لليهود في الإسكندرية","location":"الإسكندرية، مصر الرومانية","story":"اندلع عنف طائفي شديد في الإسكندرية بين السكان اليونانيين واليهود وسط نزاع سياسي في عهد الوالي الروماني أولوس أفيليوس فلاكوس. ويصف فيلون إجبار اليهود على منطقة محدودة ونهب المنازل والمتاجر والاعتداء على أشخاص وقتلهم.","context":"شهدت مصر الرومانية توترات سياسية ومدنية وطائفية. ويحدد الحدث المشاركين بدل تصوير العنف كصراع عرقي واحد متواصل.","aftermath":"عمق الحدث انعدام الأمن لدى المجتمع اليهودي في الإسكندرية وأدى إلى نزاعات واحتجاجات إضافية أمام السلطة الرومانية.","sourceStatus":"أدلة أدبية معاصرة قوية من فيلون؛ العدد الدقيق للضحايا غير معروف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-46-roman-crucifixion-of-jacob-and-simon-sons-of-judas-the-galilean-37"]={"title":"صلب يعقوب وسمعان ابني يهوذا الجليلي على يد الرومان","location":"يهوذا","story":"يسجل يوسيفوس أن الوالي الروماني تيبيريوس يوليوس ألكسندر أمر بصلب يعقوب وسمعان، ابني يهوذا الجليلي الذي قاومت حركته الضرائب الرومانية. ويوضح الحدث استمرار المقاومة والقمع الروماني قبل الثورة الكبرى سنة 66.","context":"ضمت يهوذا الرومانية قمعًا إمبراطوريًا ومقاومة يهودية وصراعات داخلية. والمصدر الرئيسي هنا هو يوسيفوس.","aftermath":"استمرت التوترات بين حركات المقاومة اليهودية والحكم الروماني واشتدت في العقود التالية.","sourceStatus":"أدلة أدبية قديمة، أساسًا يوسيفوس"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-50-jewish-samaritan-violence-under-roman-rule-38"]={"title":"عنف يهودي–سامري تحت الحكم الروماني","location":"يهوذا / السامرة","story":"بعد مقتل حجاج من الجليل أثناء مرورهم عبر السامرة، ردت جماعات يهودية بهجمات على قرى سامرية. ثم تدخلت روما. ويبين الحدث أن العنف في فلسطين الرومانية لم يكن مجرد صراع بين اليهود وروما، بل شمل أيضًا صراعات طائفية خطيرة.","context":"يُعرض الحدث كصراع بين مجتمعات محددة تحت الحكم الروماني، لا كحرب متواصلة بين شعوب كاملة.","aftermath":"لم ينه التدخل الروماني التوترات، وظلت العلاقات بين المجتمعات معقدة.","sourceStatus":"أدلة أدبية قديمة؛ التفاصيل تعتمد أساسًا على يوسيفوس"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-64-gessius-florus-and-escalating-violence-in-judea-39"]={"title":"غيسيوس فلوروس وتصاعد العنف في يهوذا","location":"القدس / يهوذا","story":"اشتهر الوالي الروماني غيسيوس فلوروس في المصادر اليهودية بالضرائب القاسية والعنف. وساهم استيلاؤه على أموال من خزانة الهيكل وقمعه الوحشي للاحتجاجات في القدس في تحويل التوترات الطويلة إلى تمرد مفتوح.","context":"المصادر القديمة معادية بشدة لفلوروس، ولذلك ينبغي التمييز بين الأزمة الموثقة وبين التفاصيل والدوافع التي نقلتها وجهات نظر سياسية.","aftermath":"كانت المواجهات في القدس من الأسباب المباشرة لاندلاع الثورة اليهودية الكبرى ضد روما سنة 66.","sourceStatus":"أدلة أدبية قديمة قوية؛ الدوافع والتفاصيل منقولة عبر مصادر معادية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-66-first-jewish-roman-war-40"]={"title":"الثورة الكبرى — الحرب اليهودية الرومانية الأولى","location":"يهوذا الرومانية","story":"بدأ تمرد يهودي كبير ضد الحكم الروماني سنة 66م وقُمِع خلال عدة سنوات من الحرب.","context":"نشأت الحرب من مزيج من التوترات السياسية والاقتصادية والدينية والاجتماعية، وشملت أيضًا صراعات داخلية بين فصائل يهودية.","aftermath":"أدت الحرب إلى الاستيلاء على القدس وتدمير الهيكل الثاني سنة 70، بينما استمرت بعض بؤر المقاومة بعد ذلك.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-66-defeat-of-cestius-gallus-at-beth-horon-41"]={"title":"هزيمة سيستيوس غالوس عند بيت حورون","location":"يهوذا","story":"في بداية الثورة تقدم حاكم سوريا سيستيوس غالوس نحو القدس ثم انسحب. وهاجمت قوات يهودية الجيش المنسحب قرب بيت حورون وألحقت بالرومان هزيمة خطيرة عززت التمرد وضمنت ردًا إمبراطوريًا واسعًا.","context":"يوثق الحدث أساسًا في مصادر أدبية قديمة، وينبغي الحذر من أعداد الضحايا الدقيقة.","aftermath":"عزز النصر ثقة المتمردين لكنه دفع روما أيضًا إلى إرسال قوة أكبر بقيادة فسباسيان.","sourceStatus":"أدلة أدبية قديمة قوية؛ أعداد الضحايا الدقيقة غير مؤكدة"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-67-roman-campaign-in-galilee-42"]={"title":"המסע הרומי בגליל","location":"הגליל","story":"כוחות רומיים בפיקוד אספסיאנוס וטיטוס כבשו מחדש באופן שיטתי את הגליל במהלך המרד הגדול. מרכזים חשובים ובהם יודפת נפלו לאחר מצורים; יוסף בן מתתיהו מתאר הרג נרחב, שעבוד ועקירה.","context":"העדויות הספרותיות והארכאולוגיות חזקות, אך מספרי הנפגעים אצל יוסף בן מתתיהו עשויים להיות מוגזמים.","aftermath":"נפילת הגליל אפשרה לרומאים לרכז את המערכה בהמשך ביהודה ובירושלים.","sourceStatus":"עדויות ספרותיות וארכאולוגיות עתיקות חזקות; מספרי הנפגעים אצל יוסף בן מתתיהו עשויים להיות מנופחים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-68-jewish-factional-fighting-inside-jerusalem-43"]={"title":"לחימה בין פלגים יהודיים בתוך ירושלים","location":"ירושלים","story":"עם גבור הלחץ הרומי נלחמו פלגים יהודיים יריבים באלימות על השליטה בירושלים. מקורות עתיקים מתארים הרג והרס בתוך העיר לפני המצור הרומי ובמהלכו. העימות הפנימי החליש את ההגנה ומראה שהמלחמה הייתה גם מאבק אזרחי יהודי, ולא רק רומאים נגד יהודים.","context":"המקור המרכזי הוא יוסף בן מתתיהו, שהיה משתתף במלחמה ובהמשך עבר לצד הרומי; נקודת מבטו הפוליטית מחייבת קריאה ביקורתית.","aftermath":"המאבק הפנימי פגע ביכולת ההתנגדות של העיר בזמן שהצבא הרומי התקרב.","sourceStatus":"עדויות ספרותיות עתיקות חזקות, במיוחד יוסף בן מתתיהו; הפרשנות מושפעת מנקודת מבטו הפוליטית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-70-destruction-of-jerusalem-and-second-temple-44"]={"title":"חורבן ירושלים ובית המקדש השני","location":"ירושלים","story":"כוחות רומיים בפיקוד טיטוס כבשו את ירושלים והחריבו את בית המקדש השני. מספרי הנפגעים העתיקים שנויים במחלוקת.","context":"החורבן התרחש לאחר כמה שנות מרד ומצור והיה נקודת מפנה מרכזית בהיסטוריה היהודית תחת רומא.","aftermath":"חורבן המקדש שינה באופן עמוק את החיים הדתיים והפוליטיים היהודיים; מוסדות ומרכזים חדשים התפתחו לאחר המלחמה, בעוד יהודים המשיכו לחיות בארץ ובתפוצות.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-73-siege-and-fall-of-masada-45"]={"title":"המצור ונפילת מצדה","location":"מצדה, מדבר יהודה","story":"כוחות רומיים הטילו מצור על מבצר מצדה, שבו החזיקו מורדים יהודים לאחר נפילת ירושלים. יוסף בן מתתיהו מספר שהמגינים בחרו במוות המוני במקום בשבי. הארכאולוגיה מאשרת את מערך המצור הרומי ואת החורבן, אך חוקרים דנים בפרטים של סיפור המוות הסופי.","context":"המצור הרומי מתועד היטב מבחינה ארכאולוגית; תיאור ההחלטה והמוות ההמוני תלוי בעיקר ביוסף בן מתתיהו.","aftermath":"נפילת מצדה סימנה את סופו של אחד ממוקדי ההתנגדות האחרונים שנותרו לאחר המרד הגדול.","sourceStatus":"ראיות ארכאולוגיות חזקות מאוד למצור; סיפור המוות הסופי תלוי ביוסף בן מתתיהו"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-115-kitos-war-diaspora-revolt-46"]={"title":"מלחמת קיטוס / מרד התפוצות","location":"מזרח האימפריה הרומית","story":"מרידות יהודיות פרצו בכמה פרובינקיות מזרחיות של האימפריה הרומית בתקופת טראיאנוס ודוכאו באלימות.","context":"המרידות התרחשו בהקשר של מלחמות טראיאנוס במזרח וכללו גם אלימות בין־קהילתית קשה. המספרים העתיקים לגבי נפגעים אינם מהימנים.","aftermath":"הדיכוי גרם נזק כבד לכמה קהילות יהודיות בתפוצות ושינה את מצבן באזורים מסוימים של מזרח האימפריה.","sourceStatus":"האירועים מתועדים היטב; מספרי הנפגעים אינם ודאיים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-116-trajanic-revolt-spreads-through-jewish-diaspora-47"]={"title":"המרד בימי טראיאנוס מתפשט בתפוצות היהודיות","location":"מצרים, קירנאיקה, קפריסין ומסופוטמיה","story":"במהלך מלחמות טראיאנוס במזרח פרצו מרידות יהודיות גדולות ואלימות בין־קהילתית בכמה אזורים בעולם הרומי. מורדים יהודים, כוחות רומיים ואוכלוסיות מקומיות ספגו אבדות כבדות. מספרי הנפגעים העצומים במקורות העתיקים נחשבים בדרך כלל לבלתי אמינים.","context":"האירוע מוצג תוך תשומת לב למגבלות ולהטיות של המקורות העתיקים, במיוחד לגבי מספרי נפגעים ומניעים.","aftermath":"המרידות התפשטו על פני כמה פרובינקיות והביאו לתגובה צבאית רומית חריפה.","sourceStatus":"מקורות עתיקים מרובים; היקף האירועים ברור אך מספרי הנפגעים אינם מהימנים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-117-roman-suppression-of-the-diaspora-revolt-48"]={"title":"הדיכוי הרומי של מרד התפוצות","location":"קירנאיקה / מצרים / קפריסין / מסופוטמיה","story":"מלחמת קיטוס, או מרד התפוצות, התפשטה בכמה פרובינקיות מזרחיות של רומא. מקורות עתיקים מתארים הרג נרחב שבוצע בידי מורדים יהודים ובידי יריביהם. הכוחות הרומיים דיכאו לבסוף את המרידות, עם השלכות קשות על כמה קהילות יהודיות.","context":"האירוע מזהה אלימות מצד כמה צדדים ואינו מקבל את מספרי הנפגעים הדרמטיים של המקורות העתיקים כפשוטם.","aftermath":"קהילות יהודיות מסוימות, במיוחד באזורים שנפגעו קשות, הצטמצמו או איבדו ממעמדן לאחר הדיכוי.","sourceStatus":"המרד מתועד היטב; מספרי הנפגעים העתיקים בלתי מהימנים במידה רבה"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-67-roman-campaign-in-galilee-42"]={"title":"الحملة الرومانية في الجليل","location":"الجليل","story":"استعادت القوات الرومانية بقيادة فسباسيان وتيطس الجليل بصورة منهجية خلال الثورة اليهودية الأولى. وسقطت مراكز مهمة منها يودفات بعد حصارات، ويصف يوسيفوس قتلًا واسعًا واستعبادًا وتهجيرًا.","context":"الأدلة الأدبية والأثرية قوية، لكن أعداد الضحايا لدى يوسيفوس قد تكون مبالغًا فيها.","aftermath":"سمح سقوط الجليل للرومان بتركيز الحملة لاحقًا على يهوذا والقدس.","sourceStatus":"أدلة أدبية وأثرية قديمة قوية؛ قد تكون أعداد الضحايا لدى يوسيفوس مبالغًا فيها"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-68-jewish-factional-fighting-inside-jerusalem-43"]={"title":"اقتتال الفصائل اليهودية داخل القدس","location":"القدس","story":"مع ازدياد الضغط الروماني، قاتلت فصائل يهودية متنافسة بعنف للسيطرة على القدس. وتصف مصادر قديمة عمليات قتل ودمار داخل المدينة قبل الحصار الروماني وأثناءه. وأضعف الصراع الداخلي الدفاع ويبين أن الحرب كانت أيضًا صراعًا أهليًا يهوديًا لا مجرد رومان ضد يهود.","context":"المصدر الرئيسي هو يوسيفوس، الذي شارك في الحرب ثم انتقل إلى الجانب الروماني؛ ولذلك تتطلب وجهة نظره السياسية قراءة نقدية.","aftermath":"أضر الصراع الداخلي بقدرة المدينة على المقاومة بينما كان الجيش الروماني يقترب.","sourceStatus":"أدلة أدبية قديمة قوية، خاصة يوسيفوس؛ التفسير متأثر بمنظوره السياسي"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-70-destruction-of-jerusalem-and-second-temple-44"]={"title":"تدمير القدس والهيكل الثاني","location":"القدس","story":"استولت القوات الرومانية بقيادة تيطس على القدس ودمرت الهيكل الثاني. وأعداد الضحايا الواردة في المصادر القديمة موضع خلاف.","context":"جاء الدمار بعد عدة سنوات من الثورة والحصار وشكل نقطة تحول كبرى في التاريخ اليهودي تحت الحكم الروماني.","aftermath":"غير تدمير الهيكل الحياة الدينية والسياسية اليهودية بصورة عميقة؛ ونشأت مؤسسات ومراكز جديدة بعد الحرب، بينما استمر اليهود في العيش في البلاد والشتات.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-73-siege-and-fall-of-masada-45"]={"title":"حصار وسقوط مسادا","location":"مسادا، صحراء يهوذا","story":"حاصرت القوات الرومانية قلعة مسادا التي احتفظ بها متمردون يهود بعد سقوط القدس. ويروي يوسيفوس أن المدافعين اختاروا الموت الجماعي بدل الأسر. وتؤكد الآثار أعمال الحصار الروماني والدمار، بينما يناقش المؤرخون تفاصيل رواية الوفيات الأخيرة.","context":"الحصار الروماني موثق أثريًا بقوة؛ أما وصف القرار والموت الجماعي فيعتمد أساسًا على يوسيفوس.","aftermath":"شكل سقوط مسادا نهاية أحد آخر مراكز المقاومة المتبقية بعد الثورة الكبرى.","sourceStatus":"أدلة أثرية قوية جدًا على الحصار؛ رواية الموت النهائي تعتمد على يوسيفوس"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-115-kitos-war-diaspora-revolt-46"]={"title":"حرب كيتوس / ثورة الشتات","location":"شرق الإمبراطورية الرومانية","story":"اندلعت ثورات يهودية في عدة ولايات رومانية شرقية في عهد تراجان وقُمعت بعنف.","context":"وقعت الثورات في سياق حروب تراجان الشرقية وشملت أيضًا عنفًا طائفيًا شديدًا. وأعداد الضحايا القديمة غير موثوقة.","aftermath":"ألحق القمع أضرارًا جسيمة بعدة مجتمعات يهودية في الشتات وغير وضعها في بعض مناطق شرق الإمبراطورية.","sourceStatus":"الأحداث موثقة جيدًا؛ أعداد الضحايا غير مؤكدة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-116-trajanic-revolt-spreads-through-jewish-diaspora-47"]={"title":"انتشار الثورة في عهد تراجان عبر الشتات اليهودي","location":"مصر وبرقة وقبرص وبلاد الرافدين","story":"خلال حروب تراجان الشرقية اندلعت انتفاضات يهودية كبيرة وعنف طائفي في عدة مناطق من العالم الروماني. وتكبد المتمردون اليهود والقوات الرومانية والسكان المحليون خسائر كبيرة. وتُعامل أعداد الضحايا الهائلة في المصادر القديمة بحذر شديد.","context":"يُعرض الحدث مع الانتباه إلى حدود وانحيازات المصادر القديمة، خاصة فيما يتعلق بأعداد الضحايا والدوافع.","aftermath":"انتشرت الانتفاضات عبر عدة ولايات وأدت إلى رد عسكري روماني قاسٍ.","sourceStatus":"مصادر قديمة متعددة؛ حجم الأحداث واضح لكن أعداد الضحايا غير موثوقة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-117-roman-suppression-of-the-diaspora-revolt-48"]={"title":"القمع الروماني لثورة الشتات","location":"برقة / مصر / قبرص / بلاد الرافدين","story":"امتدت حرب كيتوس، أو ثورة الشتات، عبر عدة ولايات رومانية شرقية. وتصف المصادر القديمة قتلًا واسعًا نفذه المتمردون اليهود وخصومهم. وفي النهاية قمعت القوات الرومانية الثورات، مع عواقب مدمرة على عدة مجتمعات يهودية.","context":"يحدد الحدث العنف من أطراف متعددة ولا يقبل أرقام الضحايا الدرامية في المصادر القديمة على ظاهرها.","aftermath":"تقلصت بعض المجتمعات اليهودية، خاصة في المناطق الأكثر تضررًا، أو فقدت مكانتها بعد القمع.","sourceStatus":"الثورة موثقة جيدًا؛ أعداد الضحايا القديمة غير موثوقة إلى حد كبير"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-132-bar-kokhba-revolt-49"]={"title":"מרד בר כוכבא","location":"יהודה","story":"בר כוכבא הנהיג מרד יהודי גדול נגד רומא. הדיכוי הרומי החריב חלקים נרחבים מיהודה; יש להתייחס בזהירות למספרי הנפגעים במקורות העתיקים.","context":"המרד היה ניסיון גדול נוסף להתנגד לשלטון הרומי לאחר חורבן בית המקדש השני. הסיבות המדויקות והקשר למדיניות הרומית נידונים במחקר.","aftermath":"הדיכוי גרם אבדות, עקירה ושינויים עמוקים במרכזי החיים היהודיים ביהודה.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-135-roman-suppression-after-the-bar-kokhba-revolt-50"]={"title":"הדיכוי הרומי לאחר מרד בר כוכבא","location":"יהודה","story":"לאחר דיכוי מרד בר כוכבא החריבה רומא חלקים נרחבים מיהודה. מקורות עתיקים מתארים אבדות עצומות, שעבוד והרס. ירושלים נוסדה מחדש כמושבה הרומית איליה קפיטולינה, והגישה היהודית לעיר הוגבלה מאוד.","context":"היקף ההרס נתמך במקורות ספרותיים, אפיגרפיים וארכאולוגיים, אך מספרי הנפגעים העתיקים שנויים במחלוקת.","aftermath":"מרכז הכובד של החיים היהודיים בארץ השתנה, והגליל נעשה מרכז חשוב יותר בתקופה שלאחר המרד.","sourceStatus":"ראיות ספרותיות, אפיגרפיות וארכאולוגיות חזקות; מספרי הנפגעים העתיקים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-351-jewish-revolt-against-constantius-gallus-51"]={"title":"מרד יהודי נגד קונסטנטיוס גאלוס","location":"הגליל / ציפורי","story":"מרד יהודי פרץ בארץ ישראל הרומית בתקופת קונסטנטיוס השני ובן דודו גאלוס. המורדים השתלטו או תקפו כמה מרכזים, ובהם ציפורי. כוחות רומיים דיכאו את המרד, ומקורות עתיקים מדווחים על הרס משמעותי.","context":"המרד מתועד היסטורית, אך המקורות הספרותיים ששרדו קצרים ולעיתים סותרים זה את זה.","aftermath":"הדיכוי פגע בכמה מרכזים בגליל והמחיש את המשך המתחים בין קהילות יהודיות לשלטון האימפריאלי.","sourceStatus":"האירוע מתועד היסטורית, אך המקורות הספרותיים קצרים ולעיתים סותרים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-415-expulsion-of-jews-from-alexandria-under-cyril-52"]={"title":"גירוש יהודים מאלכסנדריה תחת קירילוס","location":"אלכסנדריה, מצרים הביזנטית","story":"במהלך עימות אלים בין פלגים נוצרים, יהודים ושלטוניים באלכסנדריה, הוביל הפטריארך קירילוס פעולה נגד הקהילה היהודית לאחר פרוץ אלימות בין־קהילתית. סוקרטס סכולסטיקוס מספר שבתי כנסת נתפסו ויהודים רבים גורשו. היקף הגירוש ומשך השפעתו שנויים במחלוקת.","context":"האירוע התרחש בתוך מאבק עירוני מורכב שכלל כמה קבוצות ומוקדי כוח, ולא כפעולה מבודדת ללא הקשר.","aftermath":"הקהילה היהודית באלכסנדריה נפגעה, אך שאלת היקף הגירוש וקביעותו נותרה שנויה במחלוקת.","sourceStatus":"עדויות ספרותיות מן העת העתיקה המאוחרת; היקף האירוע ורצף ההתרחשויות שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-529-samaritan-revolts-and-jewish-communities-in-byzantine-palestine-53"]={"title":"המרידות השומרוניות והקהילות היהודיות בארץ ישראל הביזנטית","location":"ארץ ישראל","story":"מרידות שומרוניות חוזרות נגד השלטון הביזנטי הביאו למלחמה קשה באזור במאה השישית. קהילות יהודיות חיו באותו מרחב מסוכסך ומופיעות בחלק מן המקורות כמשתתפות או כנפגעות, בהתאם למקום ולאירוע. העימותים החריבו חלקים מן הארץ.","context":"יש להבחין בין המרידות השומרוניות המתועדות היטב לבין טענות נקודתיות על השתתפות יהודית, המשתנות לפי המקור והאירוע.","aftermath":"המלחמות החלישו קהילות ואזורים שונים בארץ ישראל הביזנטית ושינו את המאזן הדמוגרפי והפוליטי.","sourceStatus":"המרידות מתועדות היטב; מידת ההשתתפות היהודית משתנה לפי המקור והאירוע"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-614-sasanian-capture-of-jerusalem-54"]={"title":"כיבוש ירושלים בידי הסאסאנים","location":"ירושלים, ארץ ישראל הביזנטית","story":"כוחות פרסיים סאסאניים כבשו את ירושלים במהלך המלחמה הביזנטית–סאסאנית. קבוצות יהודיות השתתפו בצד הפרסי; תושבים נוצרים סבלו מאלימות נרחבת. מקורות מאוחרים חלוקים מאוד לגבי מספרי הנפגעים ותפקידי המשתתפים.","context":"האירוע מבחין בין עצם הכיבוש, המתועד היטב, לבין פרטי מעשי הטבח ומספרי הנפגעים שבהם נדרשת זהירות.","aftermath":"השלטון הפרסי בירושלים היה קצר יחסית, וביזנטיון שב וכבש את האזור בהמשך.","sourceStatus":"עצם הכיבוש מתועד ברמת ודאות גבוהה; פרטי מעשי הטבח והמספרים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-132-bar-kokhba-revolt-49"]={"title":"ثورة بار كوخبا","location":"يهوذا","story":"قاد بار كوخبا ثورة يهودية كبرى ضد روما. وأدى القمع الروماني إلى دمار واسع في يهوذا؛ وينبغي التعامل بحذر مع أعداد الضحايا في المصادر القديمة.","context":"كانت الثورة محاولة كبرى أخرى لمقاومة الحكم الروماني بعد تدمير الهيكل الثاني. ولا تزال الأسباب الدقيقة وعلاقتها بالسياسة الرومانية موضع بحث.","aftermath":"سبب القمع خسائر وتهجيرًا وتغييرات عميقة في مراكز الحياة اليهودية في يهوذا.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-135-roman-suppression-after-the-bar-kokhba-revolt-50"]={"title":"القمع الروماني بعد ثورة بار كوخبا","location":"يهوذا","story":"بعد هزيمة ثورة بار كوخبا دمرت روما أجزاء واسعة من يهوذا. وتصف المصادر القديمة خسائر هائلة واستعبادًا ودمارًا. وأعيد تأسيس القدس كمستعمرة رومانية باسم إيليا كابيتولينا، وفُرضت قيود شديدة على دخول اليهود إليها.","context":"تدعم المصادر الأدبية والنقوش والآثار حجم الدمار، لكن أعداد الضحايا القديمة موضع نقاش.","aftermath":"تحول مركز ثقل الحياة اليهودية في البلاد، وأصبح الجليل أكثر أهمية في الفترة التالية للثورة.","sourceStatus":"أدلة أدبية ونقشية وأثرية قوية؛ أعداد الضحايا القديمة موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-351-jewish-revolt-against-constantius-gallus-51"]={"title":"ثورة يهودية ضد قسطنطيوس غالوس","location":"الجليل / صفورية","story":"اندلعت ثورة يهودية في فلسطين الرومانية في عهد قسطنطيوس الثاني وابن عمه غالوس. وسيطر المتمردون على عدة مراكز أو هاجموها، ومنها صفورية. وقمعت القوات الرومانية الانتفاضة، وتذكر المصادر القديمة دمارًا كبيرًا.","context":"الثورة مثبتة تاريخيًا، لكن الروايات الأدبية الباقية موجزة وأحيانًا متناقضة.","aftermath":"أضر القمع بعدة مراكز في الجليل وأظهر استمرار التوتر بين المجتمعات اليهودية والسلطة الإمبراطورية.","sourceStatus":"الحدث مثبت تاريخيًا لكن الروايات الأدبية الباقية موجزة وأحيانًا متناقضة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-415-expulsion-of-jews-from-alexandria-under-cyril-52"]={"title":"طرد اليهود من الإسكندرية في عهد كيرلس","location":"الإسكندرية، مصر البيزنطية","story":"خلال صراع عنيف بين فصائل مسيحية ويهودية وإمبراطورية في الإسكندرية، قاد البطريرك كيرلس إجراءً ضد المجتمع اليهودي بعد اندلاع عنف طائفي. ويذكر سقراط السكولاستيكي أن المعابد اليهودية صودرت وأن كثيرًا من اليهود طُردوا. وحجم الطرد واستمراره موضع نقاش.","context":"وقع الحدث ضمن صراع حضري معقد ضم جماعات ومراكز قوة متعددة، لا كعمل معزول بلا سياق.","aftermath":"تضرر المجتمع اليهودي في الإسكندرية، لكن مدى الطرد ودوامه ما يزالان موضع نقاش.","sourceStatus":"أدلة أدبية من أواخر العصور القديمة؛ حجم الحدث وتسلسله موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-529-samaritan-revolts-and-jewish-communities-in-byzantine-palestine-53"]={"title":"الثورات السامرية والمجتمعات اليهودية في فلسطين البيزنطية","location":"فلسطين","story":"أدت الثورات السامرية المتكررة ضد الحكم البيزنطي إلى حروب شديدة في فلسطين في القرن السادس. وعاشت المجتمعات اليهودية في المشهد المتنازع عليه نفسه، وتظهر في بعض الروايات كمشاركة أو متضررة بحسب المكان والحادثة. ودمرت الصراعات أجزاء من المنطقة.","context":"ينبغي التمييز بين الثورات السامرية الموثقة جيدًا وبين الادعاءات الخاصة بالمشاركة اليهودية التي تختلف حسب المصدر والحادثة.","aftermath":"أضعفت الحروب مجتمعات ومناطق مختلفة في فلسطين البيزنطية وغيرت التوازن السكاني والسياسي.","sourceStatus":"الثورات موثقة جيدًا؛ المشاركة اليهودية المحددة تختلف بحسب المصدر والحادثة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-614-sasanian-capture-of-jerusalem-54"]={"title":"الاستيلاء الساساني على القدس","location":"القدس، فلسطين البيزنطية","story":"استولت القوات الفارسية الساسانية على القدس خلال الحرب البيزنطية الساسانية. وشاركت جماعات يهودية إلى جانب الفرس، بينما تعرض سكان مسيحيون لعنف واسع. وتختلف الروايات اللاحقة كثيرًا بشأن أعداد الضحايا وأدوار المشاركين.","context":"يميز الحدث بين حقيقة الفتح الموثقة جيدًا وبين تفاصيل المذابح وأعداد الضحايا التي تتطلب الحذر.","aftermath":"كان الحكم الفارسي للقدس قصيرًا نسبيًا، واستعادت بيزنطة المنطقة لاحقًا.","sourceStatus":"الفتح الأساسي ثابت بدرجة عالية؛ تفاصيل المذابح والأعداد موضع خلاف"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-622-muhammad-s-hijra-to-medina-55"]={"title":"ההיג'רה של מוחמד למדינה","location":"מדינה, חצי האי ערב","story":"מוחמד (בערך 570–632 לספירה) היגר ממכה למדינה בשנת 622. במדינה חיו שבטים יהודיים לצד קבוצות ערביות. אירוע זה יוצר את המסגרת הפוליטית לעימותים מאוחרים יותר המתועדים בציר הזמן.","context":"סמן זה מבחין בין שינוי פוליטי ומעמד קהילתי לבין אירועים ישירים של אלימות.","aftermath":"היחסים בין הקהילה המוסלמית החדשה לבין הקבוצות השונות במדינה השתנו בשנים הבאות וכללו בריתות, מחלוקות ועימותים.","sourceStatus":"ההיג'רה היא אירוע היסטורי מבוסס; פרטים רבים על ההסכמים הקהילתיים שרדו במקורות ספרותיים אסלאמיים מאוחרים יותר"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-624-banu-qaynuqa-conflict-56"]={"title":"העימות עם בני קינוקאע","location":"מדינה","story":"מסורות ספרותיות אסלאמיות מוקדמות מתארות עימות בין קהילתו של מוחמד במדינה לבין בני קינוקאע, ולאחריו גירוש הקבוצה.","context":"האירוע מוכר בעיקר ממקורות אסלאמיים ספרותיים שנכתבו מאוחר יותר, ולכן פרטים, מניעים ורצף האירועים נידונים במחקר.","aftermath":"בני קינוקאע גורשו ממדינה, והמאזן הפוליטי בין הקבוצות בעיר השתנה.","sourceStatus":"מקורות ספרותיים מאוחרים יותר; הפרטים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-625-banu-nadir-conflict-57"]={"title":"העימות עם בני נדיר","location":"מדינה","story":"מקורות אסלאמיים מוקדמים מתארים עימות בין מוחמד לבין בני נדיר ואת גירושם ממדינה.","context":"האירוע מוכר בעיקר ממסורת ספרותית אסלאמית מאוחרת יותר, ולכן יש להבחין בין גרעין האירוע לבין פרטים סיפוריים.","aftermath":"בני נדיר עזבו את מדינה ורבים מהם עברו למרכזים אחרים, ובהם ח'ייבר.","sourceStatus":"מקורות ספרותיים מאוחרים יותר; הפרטים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-627-banu-qurayza-episode-58"]={"title":"פרשת בני קוריט'ה","location":"מדינה","story":"המסורת האסלאמית מתארת את כניעת בני קוריט'ה לאחר קרב השוחה ואת הוצאתם להורג של רבים מן הגברים הבוגרים; הפרטים ומספר ההרוגים שנויים במחלוקת.","context":"האירוע נשען בעיקר על מקורות ספרותיים אסלאמיים מאוחרים. עצם העימות מקובל באופן רחב, אך היקף ההוצאות להורג והפרטים המדויקים נידונים במחקר.","aftermath":"הקהילה חדלה להתקיים כקבוצה פוליטית עצמאית במדינה, והשליטה של קהילתו של מוחמד בעיר התחזקה.","sourceStatus":"מקורות ספרותיים מאוחרים יותר; המספרים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-628-khaybar-campaign-59"]={"title":"מסע ח'ייבר","location":"ח'ייבר, חצי האי ערב","story":"כוחותיו של מוחמד הביסו את קהילות נווה המדבר היהודיות בח'ייבר; הסכמים אפשרו לרבים מן התושבים להישאר תחת תנאים פוליטיים וכלכליים חדשים.","context":"האירוע הצבאי הרחב מבוסס, בעוד פרטים רבים של הסיפור נשענים על מקורות אסלאמיים ספרותיים.","aftermath":"קהילות יהודיות המשיכו להתקיים בח'ייבר לתקופה תחת הסדרי שלטון חדשים.","sourceStatus":"האירוע הרחב מבוסס; פרטי הסיפור נגזרים ממקורות אסלאמיים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-629-byzantine-restoration-and-reported-anti-jewish-reprisals-60"]={"title":"השבת השלטון הביזנטי ודיווחים על פעולות תגמול נגד יהודים","location":"ירושלים / ארץ ישראל הביזנטית","story":"לאחר שהקיסר הרקליוס השיב את השליטה הביזנטית, מסורות מאוחרות מתארות רדיפות והרג של יהודים שהואשמו בשיתוף פעולה עם הפרסים. קיומן של הגבלות מחודשות סביר, אך סיפורים על טבח שיטתי ברחבי האימפריה או על שבועה מסוימת של הרקליוס הם מאוחרים ושנויים במחלוקת.","context":"האירוע מבחין בין ראיות חזקות יחסית להגבלות מחודשות לבין סיפורי טבח מאוחרים וחלשים יותר מבחינה היסטורית.","aftermath":"התקופה הביזנטית המחודשת הייתה קצרה; בתוך שנים ספורות השתלטו כוחות מוסלמיים על ירושלים והאזור.","sourceStatus":"הראיות להגבלות חזקות יותר מן המסורות המאוחרות על טבח"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-622-muhammad-s-hijra-to-medina-55"]={"title":"هجرة محمد إلى المدينة","location":"المدينة، شبه الجزيرة العربية","story":"هاجر محمد (نحو 570–632م) من مكة إلى المدينة سنة 622. وضمت المدينة قبائل يهودية إلى جانب جماعات عربية. ويؤسس هذا الحدث للسياق السياسي للصراعات اللاحقة الموثقة في الخط الزمني.","context":"يفصل هذا المؤشر بين التغيير السياسي والوضع الجماعي وبين أحداث العنف المباشرة.","aftermath":"تغيرت العلاقات بين المجتمع المسلم الجديد والجماعات المختلفة في المدينة خلال السنوات التالية وشملت تحالفات وخلافات وصراعات.","sourceStatus":"الهجرة حدث تاريخي ثابت؛ كثير من تفاصيل الاتفاقات المجتمعية بقيت في مصادر أدبية إسلامية لاحقة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-624-banu-qaynuqa-conflict-56"]={"title":"الصراع مع بني قينقاع","location":"المدينة","story":"تصف التقاليد الأدبية الإسلامية المبكرة صراعًا بين مجتمع محمد في المدينة وبني قينقاع، أعقبه طرد الجماعة.","context":"يُعرف الحدث أساسًا من مصادر أدبية إسلامية دُوّنت لاحقًا، ولذلك تبقى التفاصيل والدوافع وتسلسل الأحداث موضع بحث.","aftermath":"طُرد بنو قينقاع من المدينة وتغير ميزان القوى السياسي بين جماعاتها.","sourceStatus":"مصادر أدبية لاحقة؛ التفاصيل موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-625-banu-nadir-conflict-57"]={"title":"الصراع مع بني النضير","location":"المدينة","story":"تصف المصادر الإسلامية المبكرة صراع محمد مع بني النضير وطردهم من المدينة.","context":"يُعرف الحدث أساسًا من تقاليد أدبية إسلامية لاحقة، ولذلك ينبغي التمييز بين جوهر الحدث والتفاصيل السردية.","aftermath":"غادر بنو النضير المدينة وانتقل كثير منهم إلى مراكز أخرى منها خيبر.","sourceStatus":"مصادر أدبية لاحقة؛ التفاصيل موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-627-banu-qurayza-episode-58"]={"title":"حادثة بني قريظة","location":"المدينة","story":"تصف التقاليد الإسلامية استسلام بني قريظة بعد معركة الخندق وإعدام عدد كبير من الرجال البالغين؛ والتفاصيل والأعداد موضع نقاش.","context":"يعتمد الحدث أساسًا على مصادر أدبية إسلامية لاحقة. ويُقبل جوهر الصراع على نطاق واسع، لكن حجم الإعدامات والتفاصيل الدقيقة موضع بحث.","aftermath":"انتهى وجود الجماعة كقوة سياسية مستقلة في المدينة وتعززت سيطرة مجتمع محمد على المدينة.","sourceStatus":"مصادر أدبية لاحقة؛ الأعداد موضع خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-628-khaybar-campaign-59"]={"title":"حملة خيبر","location":"خيبر، شبه الجزيرة العربية","story":"هزمت قوات محمد مجتمعات الواحات اليهودية في خيبر، وسمحت اتفاقات لكثير من السكان بالبقاء في ظل شروط سياسية واقتصادية جديدة.","context":"الحدث العسكري العام ثابت، بينما تعتمد تفاصيل كثيرة من الرواية على مصادر أدبية إسلامية.","aftermath":"استمرت مجتمعات يهودية في خيبر فترة من الزمن في ظل ترتيبات حكم جديدة.","sourceStatus":"الحدث العام ثابت؛ التفاصيل السردية مستمدة من مصادر إسلامية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-629-byzantine-restoration-and-reported-anti-jewish-reprisals-60"]={"title":"استعادة الحكم البيزنطي وتقارير الانتقام من اليهود","location":"القدس / فلسطين البيزنطية","story":"بعد أن استعاد الإمبراطور هرقل السيطرة البيزنطية، تصف تقاليد لاحقة اضطهادًا وقتلًا لليهود المتهمين بالتعاون مع الفرس. ووجود قيود متجددة أمر مرجح، لكن روايات مذبحة منهجية على مستوى الإمبراطورية أو قسم محدد لهرقل متأخرة ومتنازع عليها.","context":"يميز الحدث بين الأدلة الأقوى نسبيًا على تجدد القيود وبين روايات المذابح اللاحقة والأضعف تاريخيًا.","aftermath":"كانت استعادة الحكم البيزنطي قصيرة؛ ففي غضون سنوات سيطرت قوات مسلمة على القدس والمنطقة.","sourceStatus":"الأدلة على القيود أقوى من روايات المذابح اللاحقة"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-638-muslim-conquest-of-jerusalem-61"]={"title":"הכיבוש המוסלמי של ירושלים","location":"ירושלים","story":"ירושלים עברה מן השלטון הביזנטי לשלטון מוסלמי מוקדם במהלך הכיבושים הערביים. מסורות מאוחרות קושרות את הממשל החדש לחידוש גישה או התיישבות יהודית לאחר ההגבלות הביזנטיות, אך הפרטים משתנים בין המקורות.","context":"סמן זה מבחין בין שינוי שלטוני ומעמד משפטי לבין אירוע ישיר של אלימות.","aftermath":"החיים היהודיים תחת השלטון המוסלמי השתנו לפי תקופה ושליט; ירושלים שבה להיות נגישה יותר ליהודים לפי חלק מן המקורות.","sourceStatus":"הכיבוש הוא אירוע היסטורי מבוסס; סיפורי הכניעה המפורטים והמדיניות הקהילתית המוקדמת משתנים בין מקורות מאוחרים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-717-jewish-life-under-early-islamic-rule-and-dhimmi-status-62"]={"title":"החיים היהודיים תחת השלטון האסלאמי המוקדם ומעמד הד'ימי","location":"השטחים האסלאמיים המוקדמים","story":"במהלך המאות הראשונות של השלטון האסלאמי חיו בדרך כלל קהילות יהודיות ונוצריות כאוכלוסיות לא־מוסלמיות מוגנות אך כפופות מבחינה משפטית. מיסים, הגבלות והיישום המקומי השתנו מאוד בין שליטים, מקומות ותקופות.","context":"סמן זה מתאר מסגרת משפטית ופוליטית רחבה ואינו מציג אותה כאירוע יחיד של אלימות או כמצב אחיד בכל העולם המוסלמי.","aftermath":"קהילות יהודיות התקיימו ואף שגשגו בחלק מן המרכזים, בעוד שבמקומות ובתקופות אחרות הוטלו עליהן מגבלות חמורות יותר.","sourceStatus":"המסגרת המשפטית־היסטורית הרחבה מבוססת; האכיפה והכללים הספציפיים השתנו במידה רבה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1011-persecution-under-al-hakim-63"]={"title":"רדיפות תחת אל־חאכם","location":"הח'ליפות הפאטמית","story":"בתקופת הח'ליף הפאטמי אל־חאכם הוטלו על נוצרים ויהודים צעדים מפלים וכופים, ובהם הגבלות ופגיעה בבתי תפילה. עוצמת המדיניות והכרונולוגיה שלה השתנו במהלך שלטונו.","context":"האירוע מבחין בין הרדיפה המתועדת היטב לבין סיפורים מאוחרים או הכללות שאינן נתמכות באותה מידה.","aftermath":"ההגבלות השתנו לאורך שלטונו של אל־חאכם וחלקן בוטלו או התרככו בהמשך.","sourceStatus":"רמת ודאות גבוהה לגבי הרדיפה; לא מדובר בטבח יחיד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1066-granada-massacre-64"]={"title":"טבח גרנדה","location":"גרנדה, אל־אנדלוס","story":"המון תקף את הקהילה היהודית בגרנדה והרג את הווזיר היהודי יוסף אבן נגרלה; מקורות מימי הביניים מתארים הרג נרחב בקרב יהודי העיר.","context":"האירוע מתועד כפרץ אלימות אנטי־יהודית משמעותי, אך יש להתייחס בזהירות להערכות מספריות מימי הביניים.","aftermath":"הקהילה היהודית בגרנדה נפגעה קשות, והאירוע נעשה לאחת הדוגמאות הבולטות לאלימות נגד יהודים באל־אנדלוס.","sourceStatus":"האירוע מבוסס; ההערכות המספריות מימי הביניים אינן ודאיות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1095-pope-urban-ii-calls-the-first-crusade-65"]={"title":"האפיפיור אורבנוס השני קורא למסע הצלב הראשון","location":"קלרמון, צרפת","story":"האפיפיור אורבנוס השני קרא למסע צבאי לעבר מזרח הים התיכון. הקריאה לא הופנתה באופן רשמי נגד יהודי אירופה, אך גיוס הצלבנים לווה בשנה שלאחר מכן בהתקפות קשות נגד קהילות יהודיות בחבל הריין.","context":"סמן זה מפריד בין הקריאה הפוליטית־דתית למסע הצלב לבין האלימות נגד יהודים שהתרחשה לאחר מכן.","aftermath":"ההתגייסות למסע הצלב יצרה תנועות חמושות שחלקן תקפו קהילות יהודיות באירופה עוד לפני יציאתן למזרח.","sourceStatus":"הקריאה למסע הצלב מתועדת היטב; הגרסאות ששרדו לנאומו של אורבנוס נכתבו לאחר האירוע"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-638-muslim-conquest-of-jerusalem-61"]={"title":"الفتح الإسلامي للقدس","location":"القدس","story":"انتقلت القدس من الحكم البيزنطي إلى الحكم الإسلامي المبكر خلال الفتوحات العربية. وتربط تقاليد لاحقة الإدارة الجديدة بتجدد وصول اليهود أو استيطانهم بعد القيود البيزنطية، لكن التفاصيل تختلف بين المصادر.","context":"يفصل هذا المؤشر بين تغير الحكم والوضع القانوني وبين حدث مباشر من العنف.","aftermath":"اختلفت الحياة اليهودية تحت الحكم الإسلامي بحسب الفترة والحاكم؛ وتشير بعض المصادر إلى أن القدس أصبحت أكثر إتاحة لليهود.","sourceStatus":"الفتح حدث تاريخي ثابت؛ روايات الاستسلام التفصيلية والسياسات المجتمعية المبكرة تختلف بين المصادر اللاحقة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-717-jewish-life-under-early-islamic-rule-and-dhimmi-status-62"]={"title":"الحياة اليهودية تحت الحكم الإسلامي المبكر ووضع أهل الذمة","location":"الأراضي الإسلامية المبكرة","story":"خلال القرون الإسلامية الأولى عاش اليهود والمسيحيون عمومًا كسكان غير مسلمين محميين لكنهم أدنى قانونيًا. واختلفت الضرائب والقيود والممارسة المحلية كثيرًا بين الحكام والأماكن والفترات.","context":"يصف هذا المؤشر إطارًا قانونيًا وسياسيًا واسعًا ولا يقدمه كحادثة عنف واحدة أو كحالة موحدة في جميع أنحاء العالم الإسلامي.","aftermath":"استمرت مجتمعات يهودية وازدهرت في بعض المراكز، بينما واجهت في أماكن وفترات أخرى قيودًا أشد.","sourceStatus":"الإطار القانوني التاريخي العام ثابت؛ التطبيق والقواعد المحددة اختلفت بدرجة كبيرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1011-persecution-under-al-hakim-63"]={"title":"الاضطهاد في عهد الحاكم بأمر الله","location":"الخلافة الفاطمية","story":"في عهد الخليفة الفاطمي الحاكم بأمر الله فُرضت إجراءات تمييزية وقسرية على المسيحيين واليهود، شملت قيودًا وإضرارًا بدور العبادة. واختلفت شدة السياسات وتسلسلها الزمني خلال حكمه.","context":"يميز الحدث بين الاضطهاد الموثق جيدًا وبين الروايات اللاحقة أو التعميمات التي لا تدعمها الأدلة بالقدر نفسه.","aftermath":"تغيرت القيود خلال عهد الحاكم وأُلغي أو خُفف بعضها لاحقًا.","sourceStatus":"ثقة عالية في وقوع الاضطهاد؛ لم يكن مذبحة واحدة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1066-granada-massacre-64"]={"title":"مذبحة غرناطة","location":"غرناطة، الأندلس","story":"هاجم حشد المجتمع اليهودي في غرناطة وقتل الوزير اليهودي يوسف بن نغريلة؛ وتصف مصادر العصور الوسطى قتلًا واسعًا بين يهود المدينة.","context":"الحدث موثق بوصفه انفجارًا كبيرًا للعنف المعادي لليهود، لكن التقديرات العددية في مصادر العصور الوسطى تتطلب الحذر.","aftermath":"تضرر المجتمع اليهودي في غرناطة بشدة وأصبح الحدث من أبرز أمثلة العنف ضد اليهود في الأندلس.","sourceStatus":"الحدث ثابت؛ التقديرات العددية في العصور الوسطى غير مؤكدة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1095-pope-urban-ii-calls-the-first-crusade-65"]={"title":"البابا أوربان الثاني يدعو إلى الحملة الصليبية الأولى","location":"كليرمون، فرنسا","story":"دعا البابا أوربان الثاني إلى حملة مسلحة نحو شرق البحر المتوسط. ولم تكن الدعوة موجهة رسميًا ضد يهود أوروبا، لكن تعبئة الصليبيين أعقبها في العام التالي هجمات شديدة على المجتمعات اليهودية في الراين.","context":"يفصل هذا المؤشر بين الدعوة السياسية والدينية للحملة الصليبية وبين العنف ضد اليهود الذي وقع بعدها.","aftermath":"أنتجت التعبئة الصليبية جماعات مسلحة هاجم بعضها المجتمعات اليهودية في أوروبا قبل توجهها شرقًا.","sourceStatus":"الدعوة إلى الحملة موثقة جيدًا؛ النسخ الباقية من خطاب أوربان كُتبت بعد الحدث"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1096-speyer-massacre-66"]={"title":"טבח שפייר","location":"שפייר, האימפריה הרומית הקדושה","story":"כאשר אלימות מסע הצלב הראשון התפשטה בחבל הריין, תוקפים פגעו בקהילה היהודית בשפייר. הבישוף הגן על יהודים רבים, אך מספר יהודים נרצחו.","context":"האירוע מתועד היטב בכרוניקות מימי הביניים; פרטים ומספרים מדויקים דורשים זהירות.","aftermath":"ההתקפה בשפייר הייתה חלק מגל רחב יותר שפגע בקהילות יהודיות לאורך הריין.","sourceStatus":"רמת ודאות גבוהה; כרוניקות מימי הביניים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1096-worms-massacre-67"]={"title":"טבח וורמס","location":"וורמס, האימפריה הרומית הקדושה","story":"צלבנים ומשתתפים מקומיים תקפו יהודים בוורמס במהלך מסע הצלב הראשון. יהודים רבים נהרגו למרות ניסיונות למצוא מחסה תחת הגנת הבישוף.","context":"האירוע הוא חלק מגל האלימות האנטי־יהודית בחבל הריין בזמן גיוס מסע הצלב הראשון.","aftermath":"הקהילה בוורמס ספגה אבדות כבדות, וגל ההתקפות המשיך לקהילות אחרות באזור.","sourceStatus":"רמת ודאות גבוהה; כרוניקות מימי הביניים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1096-mainz-massacre-68"]={"title":"טבח מיינץ","location":"מיינץ, האימפריה הרומית הקדושה","story":"הקהילה היהודית במיינץ הותקפה במהלך מסע הצלב הראשון למרות שחבריה ביקשו מקלט אצל הארכיבישוף. מקורות מימי הביניים מתארים הרג המוני והתאבדויות תחת איום של המרה בכפייה.","context":"גרעין האירוע מתועד היטב, אך מספרי ההרוגים המדויקים משתנים בין הכרוניקות.","aftermath":"הקהילה במיינץ נהרסה במידה רבה והאירוע נעשה סמל מרכזי בזיכרון היהודי של גזירות תתנ״ו.","sourceStatus":"רמת ודאות גבוהה; כרוניקות מימי הביניים; המספרים המדויקים משתנים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1096-rhineland-massacres-during-the-first-crusade-69"]={"title":"טבחי חבל הריין במהלך מסע הצלב הראשון","location":"וורמס, מיינץ, קלן וחבל הריין","story":"קבוצות צלבנים והמונים מקומיים תקפו קהילות יהודיות כאשר מסע הצלב הראשון נע מזרחה.","context":"ההתקפות לא היו יעד רשמי של מסע הצלב שעליו הכריז האפיפיור, אך הן צמחו מתוך גיוס צלבני, קנאות דתית, אינטרסים מקומיים ועוינות אנטי־יהודית.","aftermath":"קהילות רבות נפגעו קשות, והאירועים הותירו חותם עמוק בזיכרון ובכתיבה היהודית האשכנזית.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1099-crusader-capture-of-jerusalem-70"]={"title":"כיבוש ירושלים בידי הצלבנים","location":"ירושלים","story":"כוחות מסע הצלב הראשון כבשו את ירושלים ביולי 1099 וביצעו טבח בתושבים מוסלמים ויהודים. תושבים יהודים היו בין ההרוגים במהלך הכיבוש.","context":"עצם הכיבוש והטבח מתועדים היטב ממקורות שונים, אך מספרי הנפגעים המדויקים שנמסרו בכרוניקות שנויים במחלוקת.","aftermath":"ירושלים הפכה לבירת ממלכת ירושלים הצלבנית, והאוכלוסיות המוסלמית והיהודית בעיר נפגעו קשות.","sourceStatus":"רמת ודאות גבוהה מאוד לגבי הכיבוש והטבח; המספרים המדויקים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1096-speyer-massacre-66"]={"title":"مذبحة شباير","location":"شباير، الإمبراطورية الرومانية المقدسة","story":"مع انتشار عنف الحملة الصليبية الأولى في الراين استهدف مهاجمون المجتمع اليهودي في شباير. وحمى الأسقف كثيرًا من اليهود، لكن عددًا منهم قُتل.","context":"الحدث موثق جيدًا في سجلات العصور الوسطى؛ وتتطلب التفاصيل والأعداد الدقيقة الحذر.","aftermath":"كان الهجوم في شباير جزءًا من موجة أوسع استهدفت المجتمعات اليهودية على طول الراين.","sourceStatus":"ثقة عالية؛ سجلات العصور الوسطى"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1096-worms-massacre-67"]={"title":"مذبحة فورمس","location":"فورمس، الإمبراطورية الرومانية المقدسة","story":"هاجم صليبيون ومشاركون محليون اليهود في فورمس خلال الحملة الصليبية الأولى. وقُتل كثير من اليهود رغم محاولات الاحتماء بحماية الأسقف.","context":"الحدث جزء من موجة العنف المعادي لليهود في الراين أثناء تعبئة الحملة الصليبية الأولى.","aftermath":"تكبد مجتمع فورمس خسائر فادحة واستمرت موجة الهجمات إلى مجتمعات أخرى في المنطقة.","sourceStatus":"ثقة عالية؛ سجلات العصور الوسطى"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1096-mainz-massacre-68"]={"title":"مذبحة ماينتس","location":"ماينتس، الإمبراطورية الرومانية المقدسة","story":"تعرض المجتمع اليهودي في ماينتس للهجوم خلال الحملة الصليبية الأولى رغم لجوئه إلى رئيس الأساقفة. وتصف مصادر العصور الوسطى قتلًا جماعيًا وانتحارًا تحت تهديد التحول القسري.","context":"جوهر الحدث موثق جيدًا، لكن الأعداد الدقيقة للقتلى تختلف بين السجلات.","aftermath":"دُمر مجتمع ماينتس إلى حد كبير وأصبح الحدث من أبرز رموز ذكرى اضطهادات سنة 1096 في التاريخ اليهودي الأشكنازي.","sourceStatus":"ثقة عالية؛ سجلات العصور الوسطى؛ الأعداد الدقيقة تختلف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1096-rhineland-massacres-during-the-first-crusade-69"]={"title":"مذابح الراين خلال الحملة الصليبية الأولى","location":"فورمس وماينتس وكولونيا ومنطقة الراين","story":"هاجمت جماعات صليبية وحشود محلية المجتمعات اليهودية مع تحرك الحملة الصليبية الأولى شرقًا.","context":"لم تكن الهجمات هدفًا رسميًا للحملة التي دعا إليها البابا، لكنها نشأت وسط التعبئة الصليبية والحماسة الدينية والمصالح المحلية والعداء لليهود.","aftermath":"تضررت مجتمعات كثيرة بشدة وتركت الأحداث أثرًا عميقًا في الذاكرة والكتابة اليهودية الأشكنازية.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1099-crusader-capture-of-jerusalem-70"]={"title":"استيلاء الصليبيين على القدس","location":"القدس","story":"استولت قوات الحملة الصليبية الأولى على القدس في يوليو 1099 وذبحت سكانًا مسلمين ويهودًا. وكان سكان يهود بين الذين قُتلوا أثناء الفتح.","context":"الفتح والمذبحة موثقان جيدًا في مصادر متعددة، لكن الأعداد الدقيقة للضحايا الواردة في السجلات موضع خلاف.","aftermath":"أصبحت القدس عاصمة مملكة القدس الصليبية وتضرر سكانها المسلمون واليهود بشدة.","sourceStatus":"ثقة عالية جدًا في الفتح والمذبحة؛ الأعداد الدقيقة موضع خلاف"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-638-muslim-conquest-of-jerusalem-61"]={"title":"הכיבוש המוסלמי של ירושלים","location":"ירושלים","story":"ירושלים עברה משלטון ביזנטי לשלטון מוסלמי מוקדם במהלך הכיבושים הערביים. מסורות מאוחרות מקשרות את הממשל החדש לחידוש גישה או התיישבות יהודית לאחר ההגבלות הביזנטיות, אך הפרטים שונים בין המקורות.","context":"סמן זה מבחין בין שינוי שלטוני ומעמד משפטי לבין אירוע ישיר של אלימות.","aftermath":"החיים היהודיים תחת השלטון המוסלמי השתנו לפי תקופה ושליט וכללו הן אפשרויות מחודשות להתיישבות והן מגבלות משפטיות.","sourceStatus":"הכיבוש מבוסס היטב היסטורית; סיפורי הכניעה המפורטים והמדיניות הקהילתית המוקדמת משתנים במקורות מאוחרים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-717-jewish-life-under-early-islamic-rule-and-dhimmi-status-62"]={"title":"חיים יהודיים תחת השלטון המוסלמי המוקדם ומעמד הד'ימי","location":"שטחי האסלאם המוקדם","story":"במהלך המאות הראשונות לשלטון האסלאמי חיו בדרך כלל קהילות יהודיות ונוצריות כאוכלוסיות לא־מוסלמיות מוגנות אך כפופות מבחינה משפטית. מיסים, הגבלות ואופן האכיפה השתנו מאוד בין שליטים, מקומות ותקופות.","context":"זהו תיאור של מסגרת משפטית־פוליטית רחבה, ולא של מצב אחיד בכל העולם המוסלמי או של אירוע אלים יחיד.","aftermath":"קהילות יהודיות המשיכו להתפתח במרכזים רבים תחת שלטון מוסלמי, כאשר רמת הביטחון, האוטונומיה והמגבלות השתנתה ממקום למקום.","sourceStatus":"המסגרת המשפטית־היסטורית הרחבה מבוססת; האכיפה והכללים המסוימים השתנו במידה רבה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1011-persecution-under-al-hakim-63"]={"title":"רדיפות תחת אל־חאכם","location":"הח'ליפות הפאטמית","story":"תחת הח'ליף הפאטמי אל־חאכם הוטלו צעדים מפלים וכופים על נוצרים ויהודים, ובהם הגבלות והרס בתי תפילה. עוצמת המדיניות והכרונולוגיה שלה השתנו במהלך שלטונו.","context":"האירוע מתאר תקופת רדיפה ומדיניות מפלה, ולא טבח יחיד. יש להבחין בין הצעדים המתועדים לבין סיפורים מאוחרים יותר.","aftermath":"המדיניות השתנתה בהמשך, וחלק מן ההגבלות בוטלו או התרככו לאחר תקופתו.","sourceStatus":"רמת ודאות גבוהה לגבי הרדיפות; לא מדובר בטבח יחיד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1066-granada-massacre-64"]={"title":"טבח גרנדה","location":"גרנדה, אל־אנדלוס","story":"המון תקף את הקהילה היהודית בגרנדה והרג את הווזיר היהודי יוסף אבן נגרילה; מקורות מימי הביניים מתארים הרג נרחב.","context":"האירוע התרחש בתוך מתחים פוליטיים וחברתיים בגרנדה. עצם הטבח מבוסס, אך מספרי ההרוגים במקורות מימי הביניים אינם ודאיים.","aftermath":"הקהילה היהודית בגרנדה נפגעה קשות והאירוע נעשה אחת הדוגמאות הבולטות לאלימות אנטי־יהודית באל־אנדלוס.","sourceStatus":"האירוע מבוסס; האומדנים המספריים מימי הביניים אינם ודאיים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1095-pope-urban-ii-calls-the-first-crusade-65"]={"title":"האפיפיור אורבנוס השני קורא למסע הצלב הראשון","location":"קלרמון, צרפת","story":"האפיפיור אורבנוס השני קרא למסע מזוין לעבר מזרח הים התיכון. הקריאה לא הופנתה רשמית נגד יהודי אירופה, אך גיוס הצלבנים לווה זמן קצר לאחר מכן בהתקפות אנטי־יהודיות קשות בחבל הריין בשנת 1096.","context":"סמן זה מפריד בין הקריאה הפוליטית־דתית למסע הצלב לבין האלימות נגד יהודים שבאה בעקבות גיוס קבוצות צלבניות מסוימות.","aftermath":"בשנת 1096 תקפו קבוצות צלבנים וקהלים מקומיים קהילות יהודיות במספר ערים בחבל הריין.","sourceStatus":"הקריאה למסע הצלב מתועדת היטב; הגרסאות ששרדו לנאומו של אורבנוס נכתבו לאחר האירוע"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-638-muslim-conquest-of-jerusalem-61"]={"title":"الفتح الإسلامي للقدس","location":"القدس","story":"انتقلت القدس من الحكم البيزنطي إلى الحكم الإسلامي المبكر خلال الفتوحات العربية. وتربط تقاليد لاحقة الإدارة الجديدة بتجدد دخول اليهود أو استيطانهم بعد القيود البيزنطية، لكن التفاصيل تختلف بين المصادر.","context":"يفصل هذا المؤشر بين تغير الحكم والوضع القانوني وبين أحداث العنف المباشرة.","aftermath":"تباينت الحياة اليهودية تحت الحكم الإسلامي بحسب الفترة والحاكم، وشملت فرصًا متجددة للاستيطان إلى جانب قيود قانونية.","sourceStatus":"الفتح ثابت تاريخيًا؛ روايات الاستسلام التفصيلية والسياسات الجماعية المبكرة تختلف في المصادر اللاحقة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-717-jewish-life-under-early-islamic-rule-and-dhimmi-status-62"]={"title":"الحياة اليهودية تحت الحكم الإسلامي المبكر ووضع أهل الذمة","location":"الأراضي الإسلامية المبكرة","story":"خلال القرون الإسلامية الأولى عاشت المجتمعات اليهودية والمسيحية عمومًا كسكان غير مسلمين محميين لكن في وضع قانوني أدنى. وتفاوتت الضرائب والقيود والممارسة المحلية كثيرًا باختلاف الحكام والأماكن والفترات.","context":"هذا وصف لإطار قانوني وسياسي واسع، وليس لحالة موحدة في كل العالم الإسلامي أو لحادثة عنف واحدة.","aftermath":"استمرت المجتمعات اليهودية في التطور في مراكز عديدة تحت الحكم الإسلامي، مع اختلاف الأمن والاستقلال والقيود من مكان إلى آخر.","sourceStatus":"الإطار القانوني التاريخي العام ثابت؛ التطبيق والقواعد المحددة اختلفت بدرجة كبيرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1011-persecution-under-al-hakim-63"]={"title":"الاضطهاد في عهد الحاكم بأمر الله","location":"الخلافة الفاطمية","story":"فرض الخليفة الفاطمي الحاكم بأمر الله إجراءات تمييزية وقسرية على المسيحيين واليهود، شملت قيودًا وتدمير دور عبادة. وتفاوتت شدة السياسات وتسلسلها خلال عهده.","context":"يصف الحدث فترة اضطهاد وسياسات تمييزية، وليس مذبحة واحدة. وينبغي التمييز بين الإجراءات الموثقة والروايات اللاحقة.","aftermath":"تغيرت السياسات لاحقًا، وأُلغيت أو خُففت بعض القيود بعد عهده.","sourceStatus":"ثقة عالية في وقوع الاضطهاد؛ لم يكن مذبحة واحدة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1066-granada-massacre-64"]={"title":"مذبحة غرناطة","location":"غرناطة، الأندلس","story":"هاجم حشد المجتمع اليهودي في غرناطة وقتل الوزير اليهودي يوسف بن نغريلة؛ وتصف مصادر العصور الوسطى قتلًا واسعًا.","context":"وقع الحدث وسط توترات سياسية واجتماعية في غرناطة. والمذبحة نفسها ثابتة، لكن أعداد القتلى في مصادر العصور الوسطى غير مؤكدة.","aftermath":"تضرر المجتمع اليهودي في غرناطة بشدة وأصبح الحدث من أبرز أمثلة العنف المعادي لليهود في الأندلس.","sourceStatus":"الحدث ثابت؛ التقديرات العددية في العصور الوسطى غير مؤكدة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1095-pope-urban-ii-calls-the-first-crusade-65"]={"title":"البابا أوربان الثاني يدعو إلى الحملة الصليبية الأولى","location":"كليرمون، فرنسا","story":"دعا البابا أوربان الثاني إلى حملة مسلحة نحو شرق البحر المتوسط. ولم تكن الدعوة موجهة رسميًا ضد يهود أوروبا، لكن التعبئة الصليبية أعقبها سريعًا عنف شديد ضد اليهود في الراين سنة 1096.","context":"يفصل هذا المؤشر بين الدعوة السياسية والدينية للحملة الصليبية وبين العنف ضد اليهود الذي رافق تعبئة بعض الجماعات الصليبية.","aftermath":"في سنة 1096 هاجمت جماعات صليبية وحشود محلية مجتمعات يهودية في عدة مدن على نهر الراين.","sourceStatus":"الدعوة إلى الحملة موثقة جيدًا؛ النسخ الباقية من خطاب أوربان كُتبت بعد الحدث"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1096-speyer-massacre-66"]={"title":"טבח שפייר","location":"שפייר, האימפריה הרומית הקדושה","story":"כאשר האלימות סביב מסע הצלב הראשון התפשטה בחבל הריין, תוקפים פגעו בקהילה היהודית בשפייר. הבישוף הגן על יהודים רבים, אך מספר יהודים נרצחו.","context":"האירוע הוא חלק מגל האלימות האנטי־יהודית של 1096. עצם ההתקפה מתועדת היטב, אך יש לנקוט זהירות בפרטים ובמספרים שבכרוניקות מימי הביניים.","aftermath":"הגנת הבישוף הצילה רבים מבני הקהילה, אך ההתקפה סימנה את תחילת גל הרדיפות בחבל הריין.","sourceStatus":"רמת ודאות גבוהה; כרוניקות מימי הביניים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1096-worms-massacre-67"]={"title":"טבח וורמס","location":"וורמס, האימפריה הרומית הקדושה","story":"צלבנים ומשתתפים מקומיים תקפו יהודים בוורמס במהלך מסע הצלב הראשון. יהודים רבים נהרגו למרות ניסיונות למצוא מחסה תחת הגנת הבישוף.","context":"האירוע מתועד בכרוניקות יהודיות ונוצריות מימי הביניים כחלק מגל האלימות בחבל הריין.","aftermath":"הקהילה ספגה אבדות כבדות והאלימות המשיכה במהרה לקהילות נוספות באזור.","sourceStatus":"רמת ודאות גבוהה; כרוניקות מימי הביניים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1096-mainz-massacre-68"]={"title":"טבח מיינץ","location":"מיינץ, האימפריה הרומית הקדושה","story":"הקהילה היהודית במיינץ הותקפה במהלך מסע הצלב הראשון אף שחבריה ביקשו מחסה אצל הארכיבישוף. מקורות מימי הביניים מתארים הרג המוני והתאבדויות תחת איום של המרה בכפייה.","context":"עצם הטבח מתועד היטב; המספרים המדויקים ופרטים מסוימים משתנים בין הכרוניקות.","aftermath":"מיינץ, אחד המרכזים היהודיים החשובים בחבל הריין, נפגע קשות והאירוע נחרת בזיכרון היהודי של גזירות תתנ״ו.","sourceStatus":"רמת ודאות גבוהה; כרוניקות מימי הביניים; המספרים המדויקים משתנים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1096-rhineland-massacres-during-the-first-crusade-69"]={"title":"טבחי חבל הריין במהלך מסע הצלב הראשון","location":"וורמס, מיינץ, קלן וחבל הריין","story":"קבוצות צלבנים והמונים מקומיים תקפו קהילות יהודיות כאשר מסע הצלב הראשון נע מזרחה.","context":"האלימות לא הייתה יעד רשמי של מסע הצלב שהוכרז בקלרמון, אך קבוצות צלבנים מסוימות הפנו את הלהט הדתי והאלימות נגד יהודים מקומיים.","aftermath":"קהילות רבות נפגעו, נהרסו או התפזרו, והאירועים נעשו נקודת ציון מרכזית בהיסטוריה של רדיפות יהודי אירופה.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1099-crusader-capture-of-jerusalem-70"]={"title":"כיבוש ירושלים בידי הצלבנים","location":"ירושלים","story":"כוחות מסע הצלב הראשון כבשו את ירושלים ביולי 1099 וטבחו בתושבים מוסלמים ויהודים. תושבים יהודים היו בין ההרוגים במהלך הכיבוש.","context":"הכיבוש והטבח מתועדים היטב במקורות מכמה מסורות; המספרים המדויקים של ההרוגים שנויים במחלוקת.","aftermath":"הצלבנים הקימו את ממלכת ירושלים הלטינית, והאוכלוסיות המוסלמיות והיהודיות בעיר נפגעו קשות מן הכיבוש.","sourceStatus":"רמת ודאות גבוהה מאוד לגבי הכיבוש והטבח; המספרים המדויקים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1096-speyer-massacre-66"]={"title":"مذبحة شباير","location":"شباير، الإمبراطورية الرومانية المقدسة","story":"مع انتشار عنف الحملة الصليبية الأولى في الراين، استهدف مهاجمون المجتمع اليهودي في شباير. وحمى الأسقف كثيرًا من اليهود، لكن عددًا منهم قُتل.","context":"الحادثة جزء من موجة العنف المعادي لليهود سنة 1096. والهجوم نفسه موثق جيدًا، مع ضرورة الحذر في التفاصيل والأرقام الواردة في سجلات العصور الوسطى.","aftermath":"أنقذت حماية الأسقف كثيرًا من أفراد المجتمع، لكن الهجوم كان بداية موجة الاضطهاد في الراين.","sourceStatus":"ثقة عالية؛ سجلات من العصور الوسطى"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1096-worms-massacre-67"]={"title":"مذبحة فورمس","location":"فورمس، الإمبراطورية الرومانية المقدسة","story":"هاجم صليبيون ومشاركون محليون اليهود في فورمس خلال الحملة الصليبية الأولى. وقُتل كثير من اليهود رغم محاولات الاحتماء بحماية الأسقف.","context":"توثق سجلات يهودية ومسيحية من العصور الوسطى الحدث ضمن موجة العنف في الراين.","aftermath":"تكبد المجتمع خسائر كبيرة وانتقل العنف سريعًا إلى مجتمعات أخرى في المنطقة.","sourceStatus":"ثقة عالية؛ سجلات من العصور الوسطى"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1096-mainz-massacre-68"]={"title":"مذبحة ماينتس","location":"ماينتس، الإمبراطورية الرومانية المقدسة","story":"تعرض المجتمع اليهودي في ماينتس للهجوم خلال الحملة الصليبية الأولى رغم لجوئه إلى رئيس الأساقفة. وتصف مصادر العصور الوسطى قتلًا جماعيًا وانتحارًا تحت تهديد التحول الديني القسري.","context":"المذبحة نفسها موثقة جيدًا؛ وتختلف الأعداد الدقيقة وبعض التفاصيل بين السجلات.","aftermath":"تضررت ماينتس، وهي من أهم المراكز اليهودية في الراين، بشدة وأصبح الحدث جزءًا مركزيًا من ذاكرة اضطهادات سنة 1096.","sourceStatus":"ثقة عالية؛ سجلات من العصور الوسطى؛ الأعداد الدقيقة تختلف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1096-rhineland-massacres-during-the-first-crusade-69"]={"title":"مذابح الراين خلال الحملة الصليبية الأولى","location":"فورمس وماينتس وكولونيا ومنطقة الراين","story":"هاجمت جماعات صليبية وحشود محلية مجتمعات يهودية بينما كانت الحملة الصليبية الأولى تتجه شرقًا.","context":"لم يكن العنف ضد اليهود هدفًا رسميًا للحملة التي أُعلنت في كليرمون، لكن بعض الجماعات الصليبية وجهت الحماسة الدينية والعنف نحو اليهود المحليين.","aftermath":"تضررت أو دُمرت أو تشتتت مجتمعات عديدة، وأصبحت الأحداث محطة كبرى في تاريخ اضطهاد يهود أوروبا.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1099-crusader-capture-of-jerusalem-70"]={"title":"استيلاء الصليبيين على القدس","location":"القدس","story":"استولت قوات الحملة الصليبية الأولى على القدس في يوليو 1099 وقتلت سكانًا مسلمين ويهودًا. وكان سكان يهود بين الذين قُتلوا أثناء الفتح.","context":"الفتح والمذبحة موثقان جيدًا في مصادر من تقاليد متعددة؛ أما الأعداد الدقيقة للقتلى فموضع خلاف.","aftermath":"أسس الصليبيون مملكة القدس اللاتينية، وتضرر السكان المسلمون واليهود في المدينة بشدة من الفتح.","sourceStatus":"ثقة عالية جدًا في الفتح والمذبحة؛ الأعداد الدقيقة موضع خلاف"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1144-norwich-accusation-and-the-emergence-of-the-blood-libel-71"]={"title":"האשמת נוריץ' והופעת עלילת הדם","location":"נוריץ', אנגליה","story":"לאחר מותו של ויליאם מנוריץ' הואשמו יהודים באופן כוזב ברצח פולחני. ההאשמה נעשתה דגם משפיע לעלילת הדם בימי הביניים — הטענה המפוברקת שיהודים רוצחים ילדים נוצרים לצרכים דתיים. האשמות דומות הובילו בהמשך לרדיפות ולאלימות ברחבי אירופה.","context":"סמן זה מבחין בין הרדיפה ההיסטורית המתועדת לבין ההאשמה הכוזבת ששימשה להצדקתה.","aftermath":"האירוע תרם להתפשטות עלילת הדם ולגלים מאוחרים יותר של רדיפות, הגבלות ואלימות נגד קהילות יהודיות.","sourceStatus":"הופעת ההאשמה מתועדת היטב; טענת הרצח הפולחני עצמה הייתה כוזבת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1146-second-crusade-violence-and-almohad-persecution-72"]={"title":"אלימות מסע הצלב השני ורדיפות האלמוואחידון","location":"מערב אירופה / צפון אפריקה / איבריה","story":"אמצע המאה ה־12 הביא אלימות אנטי־יהודית הקשורה למסע הצלב השני באירופה, ובמקביל מדיניות כפייה של שלטון האלמוואחידון בצפון אפריקה ובאיבריה.","context":"מדובר בשני הקשרים אזוריים שונים שהתרחשו בתקופה דומה: אלימות צלבנית באירופה ומדיניות דתית כופה תחת האלמוואחידון.","aftermath":"קהילות יהודיות באזורים שונים חוו הרג, לחץ להמרת דת, עקירה והגירה.","sourceStatus":"רמת ודאות גבוהה לגבי הדפוס הרחב"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1171-blois-blood-libel-executions-73"]={"title":"הוצאות להורג בעקבות עלילת הדם בבלואה","location":"בלואה, צרפת","story":"עשרות יהודים נשרפו למוות לאחר האשמת שווא ברצח פולחני, באחד המקרים המוקדמים והבולטים של רדיפה המבוססת על עלילת דם.","context":"ההליך וההוצאות להורג מתועדים היסטורית; ההאשמה שיהודים ביצעו רצח פולחני הייתה כוזבת.","aftermath":"האירוע חיזק את התפשטות עלילות הדם והפחד מפני רדיפות דומות בקהילות יהודיות אחרות.","sourceStatus":"רמת ודאות גבוהה; פרטים מדויקים נשענים על מקורות מימי הביניים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1189-london-coronation-riots-74"]={"title":"מהומות ההכתרה בלונדון","location":"לונדון, אנגליה","story":"אלימות נגד יהודים פרצה סביב הכתרת ריצ'רד הראשון בשנת 1189. בחודשים שלאחר מכן התפשטו התקפות מעבר ללונדון וסייעו ליצור את הרקע לטבח ביורק.","context":"המהומות התרחשו בתוך אווירה של עוינות דתית, חובות ומתחים חברתיים; אין לייחס את פעולות ההמון לכלל האוכלוסייה הנוצרית.","aftermath":"האלימות התפשטה לערים נוספות באנגליה והגיעה לשיאה ביורק בשנת 1190.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1190-york-massacre-at-clifford-s-tower-75"]={"title":"טבח יורק במגדל קליפורד","location":"יורק, אנגליה","story":"כ־150 מבני הקהילה היהודית ביורק נצורו בטירה המלכותית. רבים הרגו את בני משפחותיהם ואת עצמם במקום לעמוד בפני המרה בכפייה או רצח; ניצולים שיצאו מן המבצר נהרגו בידי התוקפים.","context":"האירוע מתועד בכמה כרוניקות וברשומות מנהליות, אם כי יש לנקוט זהירות בפרטי הסיפור ובמספר המדויק.","aftermath":"הקהילה היהודית ביורק הושמדה למעשה באירוע, והוא נעשה אחד מסמלי האלימות האנטי־יהודית באנגליה של ימי הביניים.","sourceStatus":"רמת ודאות גבוהה מאוד; כרוניקות מרובות ורשומות מנהליות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1235-fulda-blood-libel-accusations-76"]={"title":"עלילת הדם בפולדה","location":"פולדה, האימפריה הרומית הקדושה","story":"לאחר מותם של ילדים נוצרים בפולדה הואשמו יהודים מקומיים ברצח פולחני. ההאשמה תרמה לאלימות ונעשתה אחד ממקרי עלילת הדם הבולטים שחזרו מאוחר יותר ברחבי אירופה.","context":"ההאשמה והרדיפה מתועדות היסטורית; הטענה לרצח פולחני הייתה כוזבת.","aftermath":"המקרה תרם להמשך הפצת עלילות הדם ולהגברת הסיכון לקהילות יהודיות באירופה.","sourceStatus":"ההאשמה והרדיפה מתועדות; טענת הרצח הפולחני הייתה כוזבת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1236-anjou-and-poitou-attacks-on-jewish-communities-77"]={"title":"התקפות על קהילות יהודיות באנז'ו ובפואטו","location":"מערב צרפת","story":"אלימות בעלת אופי צלבני במערב צרפת פגעה בקהילות יהודיות באנז'ו ובפואטו. מקורות מימי הביניים מתארים הרג ולחצים להמרת דת בכפייה.","context":"האירועים מוכרים ממקורות ומחקר של ימי הביניים, אך המספרים המדויקים משתנים.","aftermath":"הקהילות שנפגעו חוו אבדות, המרות בכפייה ועקירה.","sourceStatus":"מתועד במחקר ימי הביניים; המספרים משתנים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1255-lincoln-blood-libel-case-78"]={"title":"פרשת עלילת הדם בלינקולן","location":"לינקולן, אנגליה","story":"לאחר מותו של ילד נוצרי שנודע כ'יו הקטן מלינקולן', הואשמו יהודים באופן כוזב ברצח פולחני. שמונה־עשר יהודים הוצאו להורג לאחר הליכים שקיבלו תמיכה מן הכתר.","context":"ההליך המשפטי והרדיפה מתועדים; ההאשמה ברצח פולחני הייתה כוזבת.","aftermath":"המקרה חיזק את עלילת הדם באנגליה והוסיף ללחץ המשפטי והחברתי על יהודי הממלכה.","sourceStatus":"רמת ודאות גבוהה; ההאשמה עצמה הייתה כוזבת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1286-munich-blood-libel-persecution-79"]={"title":"רדיפת עלילת הדם במינכן","location":"מינכן, בוואריה","story":"עלילת דם במינכן נעשתה חלק מן הדפוס המתרחב של ימי הביניים שבו טענות כוזבות על רצח פולחני חשפו קהילות יהודיות לרדיפה ולאלימות.","context":"סמן זה מבחין בין הרדיפה המתועדת לבין טענת הרצח הפולחני הכוזבת ששימשה נגדה.","aftermath":"המקרה הצטרף למסורת מתרחבת של האשמות שווא שסיכנה קהילות יהודיות באירופה.","sourceStatus":"ההאשמה מימי הביניים מתועדת; טענת הרצח הפולחני הייתה כוזבת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1290-expulsion-of-jews-from-england-80"]={"title":"גירוש יהודי אנגליה","location":"אנגליה","story":"אדוארד הראשון הורה בשנת 1290 על גירוש היהודים מאנגליה לאחר עשרות שנים של מיסוי מפלה, הגבלות ואלימות. החיים הקהילתיים היהודיים באנגליה הופסקו רשמית למשך מאות שנים.","context":"הגירוש היה מדיניות מדינה ולא אירוע טבח יחיד, והוא הגיע לאחר תקופה ממושכת של הגבלות ולחץ כלכלי ומשפטי.","aftermath":"הנוכחות היהודית החוקית באנגליה הסתיימה עד להתיישבות מחודשת הדרגתית במאה ה־17.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1298-rintfleisch-massacres-81"]={"title":"טבחי רינטפלייש","location":"פרנקוניה ובוואריה","story":"גל טבח אנטי־יהודי התפשט בקהילות רבות בגרמניה תחת תנועת רינטפלייש.","context":"האלימות התפשטה בין ערים ויישובים רבים; מספרי ההרוגים הכוללים משתנים בין המקורות.","aftermath":"קהילות יהודיות רבות נהרסו או נפגעו קשות והניצולים נעקרו בחלק מן המקומות.","sourceStatus":"רמת ודאות גבוהה; המספרים משתנים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1320-shepherds-crusade-attacks-82"]={"title":"התקפות מסע הצלב של הרועים","location":"צרפת וצפון איבריה","story":"קבוצות הקשורות למסע הצלב של הרועים תקפו קהילות יהודיות בחלקים מצרפת ומצפון חצי האי האיברי.","context":"האלימות הייתה גל אזורי של התקפות מצד קבוצות נעות, ולא מדיניות אחידה של כל שלטונות האזור.","aftermath":"קהילות רבות ספגו הרג, המרות כפויות ועקירה.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1336-armleder-massacres-83"]={"title":"טבחי ארמלדר","location":"ארצות גרמניה","story":"כנופיות חמושות תקפו קהילות יהודיות בחלקים מארצות גרמניה במהלך שנות ה־1330.","context":"האירועים היו חלק מגלי אלימות מקומיים ואזוריים נגד יהודים בימי הביניים המאוחרים.","aftermath":"מספר קהילות נפגעו או נהרסו והאלימות תרמה לחוסר הביטחון המתמשך של יהודי האזור.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1348-black-death-massacres-84"]={"title":"טבחי המוות השחור","location":"מרכז ומערב אירופה","story":"יהודים הואשמו באופן כוזב בגרימת המגפה באמצעות הרעלת בארות, והאשמות אלה הציתו טבח והרס של קהילות ברחבי אירופה.","context":"המגפה נגרמה ממחלה, לא מהרעלת בארות בידי יהודים. ההאשמה הייתה תאוריית קשר ששימשה להצדקת רדיפה.","aftermath":"קהילות יהודיות רבות הושמדו, גורשו או נעקרו, גם במקומות שבהם הרשויות ניסו להגן עליהן.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1349-strasbourg-massacre-during-the-black-death-85"]={"title":"טבח שטרסבורג בזמן המוות השחור","location":"שטרסבורג, האימפריה הרומית הקדושה","story":"במהלך רדיפות המוות השחור שרפו שלטונות ותושבים בשטרסבורג מספר גדול של יהודים לאחר האשמות שווא שיהודים הרעילו בארות וגרמו למגפה.","context":"הטבח מתועד היטב; האשמת הרעלת הבארות הייתה כוזבת ומספר ההרוגים המדויק משתנה בין המקורות.","aftermath":"הקהילה היהודית בעיר נפגעה אנושות והאירוע נעשה אחד הטבחים הידועים של תקופת המוות השחור.","sourceStatus":"רמת ודאות גבוהה מאוד לגבי הטבח; המספר המדויק משתנה"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1144-norwich-accusation-and-the-emergence-of-the-blood-libel-71"]={"title":"اتهام نورويتش وظهور فرية الدم","location":"نورويتش، إنجلترا","story":"بعد وفاة وليام من نورويتش اتُهم اليهود زورًا بالقتل الطقسي. وأصبح الاتهام نموذجًا مؤثرًا لفرية الدم في العصور الوسطى، وهي الادعاء الملفق بأن اليهود يقتلون أطفالًا مسيحيين لأغراض دينية. وأدت اتهامات مماثلة لاحقًا إلى اضطهاد وعنف في أنحاء أوروبا.","context":"يميز هذا المؤشر بين الاضطهاد التاريخي الموثق وبين الاتهام الكاذب المستخدم لتبريره.","aftermath":"ساهم الحدث في انتشار فرية الدم وفي موجات لاحقة من الاضطهاد والقيود والعنف ضد المجتمعات اليهودية.","sourceStatus":"ظهور الاتهام موثق جيدًا؛ ادعاء القتل الطقسي نفسه كان كاذبًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1146-second-crusade-violence-and-almohad-persecution-72"]={"title":"عنف الحملة الصليبية الثانية واضطهاد الموحدين","location":"أوروبا الغربية / شمال أفريقيا / أيبيريا","story":"شهد منتصف القرن الثاني عشر عنفًا معاديًا لليهود مرتبطًا بالحملة الصليبية الثانية في أوروبا، وبالتوازي سياسات قسرية للموحدين في شمال أفريقيا وأيبيريا.","context":"هذان سياقان إقليميان مختلفان وقعا في فترة متقاربة: عنف صليبي في أوروبا وسياسة دينية قسرية تحت حكم الموحدين.","aftermath":"واجهت مجتمعات يهودية في مناطق مختلفة القتل والضغط للتحول الديني والتهجير والهجرة.","sourceStatus":"ثقة عالية في النمط العام"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1171-blois-blood-libel-executions-73"]={"title":"إعدامات بلوا بسبب فرية الدم","location":"بلوا، فرنسا","story":"أُحرق عشرات اليهود بعد اتهام كاذب بالقتل الطقسي، في إحدى القضايا المبكرة البارزة للاضطهاد القائم على فرية الدم.","context":"الإجراءات والإعدامات موثقة تاريخيًا؛ أما الادعاء بأن اليهود ارتكبوا قتلًا طقسيًا فكان كاذبًا.","aftermath":"عزز الحدث انتشار فرية الدم والخوف من اضطهادات مشابهة في مجتمعات يهودية أخرى.","sourceStatus":"ثقة عالية؛ التفاصيل الدقيقة من مصادر العصور الوسطى"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1189-london-coronation-riots-74"]={"title":"أعمال شغب تتويج لندن","location":"لندن، إنجلترا","story":"اندلع عنف ضد اليهود حول تتويج ريتشارد الأول سنة 1189. وانتشرت الهجمات خارج لندن خلال الأشهر التالية ومهدت للمذبحة في يورك.","context":"وقعت الاضطرابات وسط عداء ديني وديون وتوترات اجتماعية؛ ولا ينبغي نسب أعمال الحشود إلى المجتمع المسيحي بأكمله.","aftermath":"انتشر العنف إلى مدن إنجليزية أخرى وبلغ ذروته في يورك سنة 1190.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1190-york-massacre-at-clifford-s-tower-75"]={"title":"مذبحة يورك في برج كليفورد","location":"يورك، إنجلترا","story":"حُوصر نحو 150 من أفراد المجتمع اليهودي في يورك داخل القلعة الملكية. وقتل كثيرون أسرهم وأنفسهم بدل مواجهة التحول القسري أو القتل؛ وقُتل ناجون خرجوا من القلعة على يد المهاجمين.","context":"توثق الحادثة عدة سجلات ووثائق إدارية، مع ضرورة الحذر في بعض التفاصيل والعدد الدقيق.","aftermath":"دُمر المجتمع اليهودي في يورك فعليًا في الحادثة وأصبحت من أبرز رموز العنف المعادي لليهود في إنجلترا الوسيطة.","sourceStatus":"ثقة عالية جدًا؛ سجلات متعددة ووثائق إدارية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1235-fulda-blood-libel-accusations-76"]={"title":"اتهامات فرية الدم في فولدا","location":"فولدا، الإمبراطورية الرومانية المقدسة","story":"بعد وفاة أطفال مسيحيين في فولدا اتُهم اليهود المحليون بالقتل الطقسي. وساهم الاتهام في العنف وأصبح من أبرز قضايا فرية الدم التي تكررت لاحقًا في أوروبا.","context":"الاتهام والاضطهاد موثقان تاريخيًا؛ أما ادعاء القتل الطقسي فكان كاذبًا.","aftermath":"ساهمت القضية في استمرار نشر فرية الدم وزيادة الخطر على المجتمعات اليهودية في أوروبا.","sourceStatus":"الاتهام والاضطهاد موثقان؛ ادعاء القتل الطقسي كان كاذبًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1236-anjou-and-poitou-attacks-on-jewish-communities-77"]={"title":"هجمات أنجو وبواتو على المجتمعات اليهودية","location":"غرب فرنسا","story":"استهدف عنف ذو طابع صليبي في غرب فرنسا مجتمعات يهودية في أنجو وبواتو. وتصف مصادر العصور الوسطى عمليات قتل وضغوطًا للتحول الديني القسري.","context":"الأحداث معروفة من مصادر ودراسات العصور الوسطى، لكن الأعداد الدقيقة تختلف.","aftermath":"واجهت المجتمعات المتضررة خسائر وتحولات قسرية وتهجيرًا.","sourceStatus":"موثق في دراسات العصور الوسطى؛ الأعداد تختلف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1255-lincoln-blood-libel-case-78"]={"title":"قضية فرية الدم في لنكولن","location":"لنكولن، إنجلترا","story":"بعد وفاة طفل مسيحي عُرف باسم هيو الصغير من لنكولن، اتُهم اليهود زورًا بالقتل الطقسي. وأُعدم ثمانية عشر يهوديًا بعد إجراءات شجعها التاج.","context":"الإجراءات القضائية والاضطهاد موثقان؛ اتهام القتل الطقسي كان كاذبًا.","aftermath":"عززت القضية فرية الدم في إنجلترا وأضافت إلى الضغط القانوني والاجتماعي على يهود المملكة.","sourceStatus":"ثقة عالية؛ الاتهام نفسه كان كاذبًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1286-munich-blood-libel-persecution-79"]={"title":"اضطهاد فرية الدم في ميونيخ","location":"ميونيخ، بافاريا","story":"أصبحت فرية دم في ميونيخ جزءًا من نمط متوسع في العصور الوسطى عرّضت فيه ادعاءات القتل الطقسي الكاذبة المجتمعات اليهودية للاضطهاد والعنف.","context":"يميز هذا المؤشر بين الاضطهاد الموثق وبين ادعاء القتل الطقسي الكاذب المستخدم ضده.","aftermath":"انضمت القضية إلى تقليد متوسع من الاتهامات الكاذبة التي عرضت المجتمعات اليهودية الأوروبية للخطر.","sourceStatus":"الاتهام الوسيط موثق؛ ادعاء القتل الطقسي كان كاذبًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1290-expulsion-of-jews-from-england-80"]={"title":"طرد اليهود من إنجلترا","location":"إنجلترا","story":"أمر إدوارد الأول بطرد اليهود من إنجلترا سنة 1290 بعد عقود من الضرائب التمييزية والقيود والعنف. وانتهت الحياة الجماعية اليهودية الرسمية في إنجلترا لقرون.","context":"كان الطرد سياسة دولة لا مذبحة منفردة، وجاء بعد فترة طويلة من القيود والضغط الاقتصادي والقانوني.","aftermath":"انتهى الوجود اليهودي القانوني في إنجلترا حتى عودة الاستيطان تدريجيًا في القرن السابع عشر.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1298-rintfleisch-massacres-81"]={"title":"مذابح رينتفلايش","location":"فرانكونيا وبافاريا","story":"انتشرت موجة من المذابح المعادية لليهود عبر مجتمعات ألمانية عديدة تحت حركة رينتفلايش.","context":"امتد العنف بين مدن وبلدات كثيرة؛ وتختلف أعداد القتلى الإجمالية بين المصادر.","aftermath":"دُمرت أو تضررت بشدة مجتمعات يهودية عديدة وهُجر الناجون في بعض المناطق.","sourceStatus":"ثقة عالية؛ الأعداد تختلف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1320-shepherds-crusade-attacks-82"]={"title":"هجمات حملة الرعاة الصليبية","location":"فرنسا وشمال أيبيريا","story":"هاجمت جماعات مرتبطة بحملة الرعاة الصليبية مجتمعات يهودية في أجزاء من فرنسا وشمال شبه الجزيرة الأيبيرية.","context":"كان العنف موجة إقليمية من هجمات جماعات متنقلة، لا سياسة موحدة لجميع سلطات المنطقة.","aftermath":"تعرضت مجتمعات عديدة للقتل والتحول القسري والتهجير.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1336-armleder-massacres-83"]={"title":"مذابح أرملدر","location":"الأراضي الألمانية","story":"هاجمت جماعات مسلحة مجتمعات يهودية في أجزاء من الأراضي الألمانية خلال ثلاثينيات القرن الرابع عشر.","context":"كانت الأحداث جزءًا من موجات عنف محلية وإقليمية ضد اليهود في أواخر العصور الوسطى.","aftermath":"تضررت أو دُمرت عدة مجتمعات وساهم العنف في استمرار انعدام الأمن لدى يهود المنطقة.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1348-black-death-massacres-84"]={"title":"مذابح الموت الأسود","location":"وسط وغرب أوروبا","story":"اتُهم اليهود زورًا بالتسبب في الطاعون عبر تسميم الآبار، فأشعلت هذه الاتهامات مذابح وتدمير مجتمعات في أنحاء أوروبا.","context":"كان الطاعون مرضًا ولم ينتج عن تسميم اليهود للآبار. وكان الاتهام نظرية مؤامرة استُخدمت لتبرير الاضطهاد.","aftermath":"دُمرت أو طُردت أو هُجرت مجتمعات يهودية كثيرة، حتى في أماكن حاولت فيها السلطات حمايتها.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1349-strasbourg-massacre-during-the-black-death-85"]={"title":"مذبحة ستراسبورغ أثناء الموت الأسود","location":"ستراسبورغ، الإمبراطورية الرومانية المقدسة","story":"خلال اضطهادات الموت الأسود أحرق مسؤولو وسكان ستراسبورغ عددًا كبيرًا من اليهود بعد اتهامات كاذبة بأن اليهود سمموا الآبار وتسببوا في الطاعون.","context":"المذبحة موثقة جيدًا؛ اتهام تسميم الآبار كان كاذبًا ويختلف العدد الدقيق للقتلى بين المصادر.","aftermath":"تضرر المجتمع اليهودي في المدينة بصورة كارثية وأصبحت الحادثة من أشهر مذابح فترة الموت الأسود.","sourceStatus":"ثقة عالية جدًا في المذبحة؛ العدد الدقيق يختلف"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1391-anti-jewish-massacres-in-iberia-86"]={"title":"טבחי יהודים בחצי האי האיברי","location":"קסטיליה ואראגון","story":"גל אלימות עירונית שטף קהילות יהודיות בספרד, הרג יהודים ודחף רבים אחרים להמרת דת בכפייה.","context":"האירועים היו גל רחב של אלימות קהילתית ולא תקרית יחידה, והתרחשו בתוך מתחים דתיים, חברתיים ופוליטיים.","aftermath":"הקהילות היהודיות נפגעו קשות, ומספר גדול של יהודים נעשו נוצרים חדשים בעקבות כפייה ולחץ.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1421-vienna-gesera-87"]={"title":"גזירת וינה","location":"דוכסות אוסטריה","story":"יהודי אוסטריה נעצרו, רכושם הוחרם, ורבים גורשו או הוצאו להורג במהלך גזירת וינה.","context":"האירוע היה רדיפה בחסות השלטון שכללה החרמת רכוש, גירוש והוצאות להורג.","aftermath":"הקהילה היהודית בווינה ובאזורים נוספים באוסטריה נהרסה או גורשה במידה רבה.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1475-trent-blood-libel-persecution-88"]={"title":"רדיפת עלילת הדם בטרנטו","location":"טרנטו, נסיכות־הבישופות של טרנטו","story":"לאחר היעלמות ילד נוצרי הואשמו יהודים מקומיים ברצח פולחני, עונו והוצאו להורג. טענת הרצח הפולחני הייתה כוזבת ונעשתה אחת מעלילות הדם המשפיעות באירופה.","context":"האירוע מבחין בין הרדיפה וההוצאות להורג המתועדות היטב לבין עלילת הרצח הפולחני הכוזבת.","aftermath":"הפרשה חיזקה את הפצת עלילת הדם והובילה לרדיפות נוספות נגד יהודים.","sourceStatus":"רמת ודאות גבוהה; טענת הרצח הפולחני הייתה כוזבת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1478-spanish-inquisition-begins-89"]={"title":"תחילת האינקוויזיציה הספרדית","location":"ספרד","story":"האינקוויזיציה הספרדית רדפה חשודים בכפירה, ובהם יהודים מומרים שנחשדו בקיום יהדות בסתר; נעשה שימוש בחקירות, עינויים והוצאות להורג.","context":"האינקוויזיציה כוונה רשמית לנוצרים ולנוצרים חדשים שנחשדו בכפירה, ולא ליהודים שנותרו יהודים, אך היא השפיעה עמוקות על משפחות ממוצא יהודי.","aftermath":"הרדיפה הגבירה פחד, פיקוח והגירה בקרב נוצרים חדשים וסייעה ליצור את הרקע לגירוש היהודים מספרד.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1492-expulsion-of-jews-from-spain-90"]={"title":"גירוש יהודי ספרד","location":"ספרד","story":"צו אלהמברה הורה ליהודים שנותרו יהודים להתנצר או לעזוב את ספרד, וגרם לעקירה המונית ולמצוקה קשה.","context":"הגירוש היה מדיניות מדינה של המלוכה הספרדית, ולא אירוע טבח יחיד.","aftermath":"יהודים רבים עברו לפורטוגל, לצפון אפריקה, לאימפריה העות'מאנית ולמקומות אחרים, והשפיעו על התפתחות התפוצה הספרדית.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1497-forced-conversion-of-jews-in-portugal-91"]={"title":"המרת דת בכפייה של יהודי פורטוגל","location":"ממלכת פורטוגל","story":"לאחר שיהודים רבים שגורשו מספרד נכנסו לפורטוגל, הורה המלך מנואל הראשון ליהודים לעזוב את ממלכתו. בפועל מנעו השלטונות מרובם לצאת וכפו הטבלה המונית בשנת 1497, וכך נוצרה אוכלוסייה גדולה של נוצרים חדשים.","context":"האירוע היה מדיניות מדינה של המרה בכפייה ולא בחירה דתית חופשית.","aftermath":"קהילות יהודיות גלויות בפורטוגל נעלמו כמעט לחלוטין, בעוד נוצרים חדשים רבים המשיכו להתמודד עם חשד ורדיפה.","sourceStatus":"מדיניות המדינה וההמרה בכפייה מתועדות היטב; אומדני מספר הנפגעים משתנים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1510-brandenburg-host-desecration-persecution-92"]={"title":"רדיפת חילול לחם הקודש בברנדנבורג","location":"ברנדנבורג, האימפריה הרומית הקדושה","story":"יהודים בברנדנבורג הואשמו בפרשת חילול לחם הקודש, והדבר הוביל להוצאות להורג ולגירוש. האשמות כאלה טענו באופן כוזב שיהודים פגעו בלחם הקודש הנוצרי ושימשו שוב ושוב עילה לרדיפה.","context":"ההליך והעונשים היו היסטוריים; הטענה העל־טבעית על חילול לחם הקודש הייתה עלילה דתית.","aftermath":"הקהילה נפגעה מהוצאות להורג וגירוש, והאירוע הצטרף לדפוס אירופי של רדיפות המבוססות על האשמות דתיות כוזבות.","sourceStatus":"ההליך וההוצאות להורג היסטוריים; האשמת חילול לחם הקודש הייתה עלילה דתית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1648-khmelnytsky-uprising-massacres-93"]={"title":"טבחי מרד חמלניצקי","location":"האיחוד הפולני–ליטאי / אוקראינה","story":"במהלך מרד חמלניצקי היו קהילות יהודיות בין האוכלוסיות שסבלו מהרג והרס נרחבים. אומדני ההרוגים ההיסטוריים משתנים מאוד.","context":"האלימות התרחשה בתוך מלחמה רחבה שכללה קוזאקים, האיחוד הפולני–ליטאי וקבוצות נוספות. אין להתייחס לאומדני נפגעים מסורתיים כאל מספרים ודאיים.","aftermath":"קהילות יהודיות רבות נהרסו או נעקרו והאירועים הותירו חותם עמוק בזיכרון היהודי של מזרח אירופה.","sourceStatus":"רמת ודאות גבוהה לגבי גל הטבח; המספרים הכוללים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1648-nemyriv-massacre-during-the-khmelnytsky-uprising-94"]={"title":"טבח נמירוב במהלך מרד חמלניצקי","location":"נמירוב, האיחוד הפולני–ליטאי","story":"במהלך מרד חמלניצקי כבשו כוחות קוזאקים ובעלי ברית את נמירוב והרגו תושבים יהודים רבים וכן יריבים אחרים. כרוניקות יהודיות זכרו את האירוע כאחד האסונות הגדולים של 1648.","context":"הטבח מתועד בכרוניקות בנות התקופה וסמוכות לה; מספרי הנפגעים המדויקים שנויים במחלוקת.","aftermath":"הקהילה היהודית בנמירוב נפגעה באופן קטסטרופלי והאירוע נעשה חלק מרכזי מזיכרון גזירות ת״ח–ת״ט.","sourceStatus":"הטבח מתועד היטב; מספרי הנפגעים המדויקים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1648-tulchyn-massacre-during-the-khmelnytsky-uprising-95"]={"title":"טבח טולצ'ין במהלך מרד חמלניצקי","location":"טולצ'ין, האיחוד הפולני–ליטאי","story":"בטולצ'ין התנגדו בתחילה יהודים ומגינים פולנים לכוחות הצרים. מקורות יהודיים בני התקופה מתארים בגידה ולאחריה הרג המוני. האירוע הוא חלק מן החורבן הרחב של קהילות יהודיות בשנים 1648–1649.","context":"האירוע מתועד בכרוניקות יהודיות; מספרים מדויקים וחלק מפרטי הסיפור נותרים בלתי ודאיים.","aftermath":"הקהילה נפגעה קשות והטבח הצטרף לגל החורבן הרחב של המרד.","sourceStatus":"האירוע מתועד בכרוניקות יהודיות; מספרים מדויקים וחלק מן הפרטים אינם ודאיים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1768-uman-massacre-during-the-koliivshchyna-uprising-96"]={"title":"טבח אומן במהלך מרד הקולייבשצ'ינה","location":"אומן, האיחוד הפולני–ליטאי","story":"מורדי ההיידמקים כבשו את אומן במהלך מרד הקולייבשצ'ינה והרגו מספר גדול של יהודים, אצילים פולנים, אנשי כמורה ותושבים אחרים. מקורות מאוחרים נותנים אומדנים שונים מאוד, ולכן אין להציג מספר מסורתי אחד כוודאי.","context":"הטבח התרחש כחלק ממרד חברתי, פוליטי ודתי רחב יותר שפגע בכמה אוכלוסיות.","aftermath":"האירוע הותיר הרס כבד באומן ונעשה חלק מן הזיכרון ההיסטורי של הקהילות שנפגעו.","sourceStatus":"הטבח היסטורי; אומדני הנפגעים משתנים מאוד במקורות מאוחרים"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1391-anti-jewish-massacres-in-iberia-86"]={"title":"مذابح معادية لليهود في أيبيريا","location":"قشتالة وأراغون","story":"اجتاحت موجة من العنف الحضري المجتمعات اليهودية في إسبانيا، فقتلت يهودًا ودفعت كثيرين آخرين إلى التحول الديني القسري.","context":"كانت الأحداث موجة واسعة من العنف المجتمعي وليست حادثة واحدة، ووقعت وسط توترات دينية واجتماعية وسياسية.","aftermath":"تضررت المجتمعات اليهودية بشدة وأصبح عدد كبير من اليهود مسيحيين جددًا نتيجة الإكراه والضغط.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1421-vienna-gesera-87"]={"title":"اضطهاد فيينا","location":"دوقية النمسا","story":"اعتُقل يهود النمسا وصودرت ممتلكاتهم وطُرد أو أُعدم كثيرون خلال اضطهاد فيينا.","context":"كان الحدث اضطهادًا برعاية السلطة شمل مصادرة الممتلكات والطرد والإعدامات.","aftermath":"دُمر أو طُرد جزء كبير من المجتمع اليهودي في فيينا ومناطق أخرى من النمسا.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1475-trent-blood-libel-persecution-88"]={"title":"اضطهاد فرية الدم في ترينت","location":"ترينت، أسقفية ترينت","story":"بعد اختفاء طفل مسيحي اتُهم اليهود المحليون بالقتل الطقسي وعُذبوا وأُعدموا. وكان ادعاء القتل الطقسي كاذبًا وأصبح من أكثر فريات الدم تأثيرًا في أوروبا.","context":"يميز الحدث بين الاضطهاد والإعدامات الموثقة جيدًا وبين فرية القتل الطقسي الكاذبة.","aftermath":"عززت القضية انتشار فرية الدم وأدت إلى مزيد من الاضطهاد ضد اليهود.","sourceStatus":"ثقة عالية؛ ادعاء القتل الطقسي كان كاذبًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1478-spanish-inquisition-begins-89"]={"title":"بداية محاكم التفتيش الإسبانية","location":"إسبانيا","story":"استهدفت محاكم التفتيش الإسبانية المشتبه بهم بالهرطقة، ومنهم يهود تحولوا إلى المسيحية واتُهموا بممارسة اليهودية سرًا؛ واستخدمت التحقيق والتعذيب والإعدام.","context":"استهدفت المحاكم رسميًا المسيحيين والمسيحيين الجدد المشتبه في هرطقتهم، لا اليهود الذين ظلوا يهودًا، لكنها أثرت بعمق في عائلات من أصول يهودية.","aftermath":"زاد الاضطهاد الخوف والمراقبة والهجرة بين المسيحيين الجدد وساهم في خلق السياق لطرد اليهود من إسبانيا.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1492-expulsion-of-jews-from-spain-90"]={"title":"طرد اليهود من إسبانيا","location":"إسبانيا","story":"أمر مرسوم الحمراء اليهود المتمسكين باليهودية بالتحول إلى المسيحية أو مغادرة إسبانيا، مما أدى إلى تهجير جماعي ومعاناة شديدة.","context":"كان الطرد سياسة دولة من الملكية الإسبانية وليس مذبحة منفردة.","aftermath":"انتقل كثير من اليهود إلى البرتغال وشمال أفريقيا والإمبراطورية العثمانية ومناطق أخرى، وأسهموا في نشوء الشتات السفاردي.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1497-forced-conversion-of-jews-in-portugal-91"]={"title":"التحول القسري ليهود البرتغال","location":"مملكة البرتغال","story":"بعد دخول كثير من اليهود المطرودين من إسبانيا إلى البرتغال أمر الملك مانويل الأول اليهود بمغادرة المملكة. لكن السلطات منعت معظمهم عمليًا من الرحيل وفرضت تعميدًا جماعيًا سنة 1497، مما أنشأ عددًا كبيرًا من المسيحيين الجدد.","context":"كان الحدث سياسة دولة للتحول القسري لا اختيارًا دينيًا حرًا.","aftermath":"اختفت تقريبًا المجتمعات اليهودية العلنية في البرتغال، بينما ظل كثير من المسيحيين الجدد عرضة للشك والاضطهاد.","sourceStatus":"سياسة الدولة والتحول القسري موثقان جيدًا؛ تقديرات عدد المتضررين تختلف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1510-brandenburg-host-desecration-persecution-92"]={"title":"اضطهاد تدنيس القربان في براندنبورغ","location":"براندنبورغ، الإمبراطورية الرومانية المقدسة","story":"اتُهم يهود في براندنبورغ في قضية تدنيس القربان، مما أدى إلى إعدامات وطرد. وكانت مثل هذه الاتهامات تزعم كذبًا أن اليهود يسيئون إلى خبز القربان المسيحي واستُخدمت مرارًا ذريعة للاضطهاد.","context":"كانت المحاكمة والعقوبات تاريخية؛ أما الادعاء الخارق بشأن تدنيس القربان فكان فرية دينية.","aftermath":"تضرر المجتمع بالإعدامات والطرد وانضمت الحادثة إلى نمط أوروبي من الاضطهاد المبني على اتهامات دينية كاذبة.","sourceStatus":"المحاكمة والإعدامات تاريخية؛ اتهام تدنيس القربان كان فرية دينية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1648-khmelnytsky-uprising-massacres-93"]={"title":"مذابح انتفاضة خميلنيتسكي","location":"الكومنولث البولندي الليتواني / أوكرانيا","story":"خلال انتفاضة خميلنيتسكي كانت المجتمعات اليهودية من بين السكان الذين تعرضوا لقتل ودمار واسع. وتختلف تقديرات الوفيات التاريخية بدرجة كبيرة.","context":"وقع العنف داخل حرب أوسع ضمت القوزاق والكومنولث البولندي الليتواني وجماعات أخرى. ولا ينبغي التعامل مع تقديرات الضحايا التقليدية كأرقام مؤكدة.","aftermath":"دُمرت أو هُجرت مجتمعات يهودية كثيرة وتركت الأحداث أثرًا عميقًا في الذاكرة اليهودية لشرق أوروبا.","sourceStatus":"ثقة عالية في موجة المذابح؛ الأعداد الإجمالية موضع خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1648-nemyriv-massacre-during-the-khmelnytsky-uprising-94"]={"title":"مذبحة نميروف خلال انتفاضة خميلنيتسكي","location":"نميروف، الكومنولث البولندي الليتواني","story":"خلال انتفاضة خميلنيتسكي استولت قوات قوزاق وحلفاؤها على نميروف وقتلت كثيرًا من السكان اليهود وغيرهم من الخصوم. وذكرت السجلات اليهودية الحادثة بوصفها من كوارث سنة 1648 الكبرى.","context":"المذبحة موثقة في سجلات معاصرة وقريبة من العصر؛ الأعداد الدقيقة للضحايا موضع خلاف.","aftermath":"تعرض المجتمع اليهودي في نميروف لدمار كارثي وأصبحت الحادثة جزءًا مركزيًا من ذاكرة أحداث 1648–1649.","sourceStatus":"المذبحة موثقة جيدًا؛ الأعداد الدقيقة للضحايا موضع خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1648-tulchyn-massacre-during-the-khmelnytsky-uprising-95"]={"title":"مذبحة تولتشين خلال انتفاضة خميلنيتسكي","location":"تولتشين، الكومنولث البولندي الليتواني","story":"في تولتشين قاوم اليهود والمدافعون البولنديون في البداية القوات المحاصرة. وتصف روايات يهودية معاصرة خيانة أعقبها قتل جماعي. والحادثة جزء من الدمار الأوسع للمجتمعات اليهودية في 1648–1649.","context":"الحادثة موثقة في سجلات يهودية؛ وتبقى الأعداد الدقيقة وبعض التفاصيل السردية غير مؤكدة.","aftermath":"تضرر المجتمع بشدة وانضمت المذبحة إلى موجة الدمار الأوسع للانتفاضة.","sourceStatus":"الحادثة موثقة في سجلات يهودية؛ الأعداد الدقيقة وبعض التفاصيل غير مؤكدة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1768-uman-massacre-during-the-koliivshchyna-uprising-96"]={"title":"مذبحة أومان خلال انتفاضة كولييفشتشينا","location":"أومان، الكومنولث البولندي الليتواني","story":"استولى متمردو الهايداماك على أومان خلال انتفاضة كولييفشتشينا وقتلوا أعدادًا كبيرة من اليهود والنبلاء البولنديين ورجال الدين وسكان آخرين. وتعطي الروايات اللاحقة تقديرات متفاوتة جدًا، لذلك لا ينبغي تقديم رقم تقليدي واحد على أنه مؤكد.","context":"وقعت المذبحة ضمن انتفاضة اجتماعية وسياسية ودينية أوسع أضرت بعدة جماعات سكانية.","aftermath":"تركت الحادثة دمارًا كبيرًا في أومان وأصبحت جزءًا من الذاكرة التاريخية للمجتمعات المتضررة.","sourceStatus":"المذبحة تاريخية؛ تقديرات الضحايا تختلف كثيرًا في المصادر اللاحقة"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1819-hep-hep-riots-97"]={"title":"מהומות הֶפּ־הֶפּ","location":"המדינות הגרמניות","story":"מהומות אנטי־יהודיות שהחלו בווירצבורג התפשטו לערים גרמניות אחדות בתקופה של ויכוח על אמנציפציה ליהודים. המונים תקפו בתים, עסקים ויחידים יהודים תוך קריאת הסיסמה שממנה קיבלו המהומות את שמן.","context":"האירוע התרחש בתוך מתחים פוליטיים, כלכליים וחברתיים סביב מעמדם האזרחי של יהודים.","aftermath":"המהומות ערערו את ביטחון הקהילות והמחישו את ההתנגדות הציבורית לאמנציפציה יהודית בחלק מן המדינות הגרמניות.","sourceStatus":"מתועד היטב ברשומות בנות התקופה; המניעים שילבו דעות קדומות אנטי־יהודיות עם מתחים פוליטיים וכלכליים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1821-odessa-anti-jewish-riot-98"]={"title":"מהומה אנטי־יהודית באודסה","location":"אודסה, האימפריה הרוסית","story":"מהומה אנטי־יהודית באודסה בשנת 1821 מזוהה לעיתים כאחד האירועים הראשונים שכונו לימים פוגרום.","context":"האירוע היה מקומי ויש להבחין בינו לבין גלי הפוגרומים הרחבים יותר של סוף המאה ה־19.","aftermath":"האלימות קדמה לגלים מאוחרים יותר של פוגרומים באודסה וברחבי האימפריה הרוסית.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1834-safed-looting-and-attacks-on-the-jewish-community-99"]={"title":"ביזה והתקפות על הקהילה היהודית בצפת","location":"צפת, ארץ ישראל העות'מאנית","story":"במהלך המהומות האזוריות הקשורות למרד 1834 בארץ ישראל הותקפה הקהילה היהודית בצפת ונבזזה בהיקף נרחב. בתים ובתי כנסת ניזוקו ותושבים הותקפו ונעקרו.","context":"האירוע התרחש בתוך מרד אזורי רחב יותר; המקורות מסכימים על ההתקפות והביזה אך שונים בפרטים ובמספרי הנפגעים.","aftermath":"הקהילה סבלה אובדן רכוש, פציעות ועקירה ונדרשה לתהליך שיקום.","sourceStatus":"ההתקפות והביזה מתועדות; המקורות שונים בפרטים ובמספרי הנפגעים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1840-damascus-affair-100"]={"title":"עלילת דמשק","location":"דמשק, סוריה העות'מאנית","story":"לאחר היעלמות נזיר קתולי ומשרתו הואשמו יהודים מדמשק באופן כוזב ברצח פולחני. כמה מהם נכלאו ועונו. פעילות יהודית בינלאומית סייעה להביא לשחרורם והפכה את הפרשה לנקודת מפנה בהתארגנות הפוליטית היהודית המודרנית.","context":"המעצרים והעינויים מתועדים היטב; האשמת הרצח הפולחני הייתה עלילת דם כוזבת.","aftermath":"הפרשה עוררה התערבות יהודית ודיפלומטית בינלאומית וחיזקה רשתות של סולידריות יהודית חוצת גבולות.","sourceStatus":"המעצרים והעינויים מתועדים היטב; האשמת הרצח הפולחני הייתה כוזבת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1859-odessa-anti-jewish-riot-of-1859-101"]={"title":"המהומה האנטי־יהודית באודסה בשנת 1859","location":"אודסה, האימפריה הרוסית","story":"אלימות אנטי־יהודית פרצה באודסה סביב חג הפסחא. מלחים יוונים ויוונים מקומיים בלטו בין התוקפים. עוינות דתית השתלבה בתחרות כלכלית גוברת בנמל הים השחור.","context":"סמן זה מבחין בין ההקשר המקומי לבין פוגרומים מאוחרים יותר ואינו מניח שלכל מקרי האלימות היו אותם מבצעים או גורמים.","aftermath":"האלימות תרמה לשינוי עמדות יהודיות כלפי ביטחון, ארגון קהילתי ואמנציפציה.","sourceStatus":"מתועד היטב; חוקרים מדגישים מתחים יווניים־יהודיים מקומיים ותחרות כלכלית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1871-odessa-pogrom-of-1871-102"]={"title":"פוגרום אודסה של 1871","location":"אודסה, האימפריה הרוסית","story":"כמה ימים של אלימות אנטי־יהודית באודסה גרמו נזק לבתים ולעסקים יהודיים. יוונים השתתפו באופן בולט, וגם רוסים הצטרפו להתקפות. חוקרים רואים ב־1871 מבשר חשוב לעידן הפוגרומים הרחב שבא לאחר מכן.","context":"האירוע שילב מתחים דתיים, אתניים וכלכליים מקומיים ואינו זהה בהכרח לגלי הפוגרומים המאוחרים יותר.","aftermath":"האלימות תרמה להתארגנות, להגנה עצמית ולשינוי עמדות כלפי ביטחון ואמנציפציה.","sourceStatus":"מתועד היטב בדוחות רשמיים ובמחקר היסטורי; המניעים כללו מתחים דתיים, אתניים וכלכליים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1881-russian-empire-pogrom-wave-103"]={"title":"גל הפוגרומים באימפריה הרוסית","location":"האימפריה הרוסית","story":"לאחר רצח הצאר אלכסנדר השני שטף גל נרחב של מהומות אנטי־יהודיות אזורים בדרום ובמערב האימפריה הרוסית בשנים 1881–1884.","context":"האלימות התרחשה בתוך משבר פוליטי וחברתי רחב; מידת האחריות והתגובה של הרשויות השתנתה בין מקומות.","aftermath":"הפוגרומים תרמו להגירה יהודית המונית, להתארגנות פוליטית ולהתפתחות תנועות הגנה עצמית.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1882-may-laws-intensify-restrictions-on-russian-jews-104"]={"title":"חוקי מאי מחמירים את ההגבלות על יהודי רוסיה","location":"האימפריה הרוסית","story":"בעקבות גל הפוגרומים של 1881 הטילה הממשלה הקיסרית תקנות זמניות שנודעו כחוקי מאי, שהגבילו את המקומות שבהם יהודים רבים יכלו להתיישב ולעסוק במסחר. אלה היו צעדי מדינה מפלים ולא התקפה אלימה.","context":"סמן זה מפריד בין רדיפה משפטית של המדינה לבין אלימות פוגרומית ישירה.","aftermath":"ההגבלות העמיקו לחץ כלכלי וחברתי ותרמו להגירה ולשינוי פוליטי בקרב יהודי האימפריה.","sourceStatus":"החקיקה הקיסרית מתועדת בוודאות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1903-kishinev-pogrom-105"]={"title":"פוגרום קישינב","location":"קישינב, האימפריה הרוסית","story":"שלושה ימים של אלימות אנטי־יהודית הרגו קרוב לחמישים יהודים, פצעו מאות והביאו להרס או ביזה של מאות בתים ועסקים.","context":"הפוגרום עורר תשומת לב בינלאומית והמחיש את הסכנה של הסתה אנטישמית ותגובה שלטונית בלתי מספקת.","aftermath":"האירוע האיץ הגירה, פעילות פוליטית והקמת קבוצות הגנה עצמית יהודיות.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1905-odessa-pogrom-106"]={"title":"פוגרום אודסה","location":"אודסה, האימפריה הרוסית","story":"במהלך המהפכה של 1905 חוותה אודסה אחד הפוגרומים הקטלניים של אותה שנה, עם הרג, פציעות והרס נרחבים.","context":"האלימות התרחשה בתוך אי־יציבות מהפכנית ופוליטית רחבה; אומדני הנפגעים משתנים.","aftermath":"הפוגרום העמיק את תחושת חוסר הביטחון והגביר הגירה, ארגון פוליטי והגנה עצמית.","sourceStatus":"רמת ודאות גבוהה; אומדני הנפגעים משתנים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1918-civil-war-pogroms-in-ukraine-and-neighboring-regions-107"]={"title":"פוגרומי מלחמת האזרחים באוקראינה ובאזורים סמוכים","location":"אוקראינה / בלארוס / גליציה","story":"במהלך מלחמות האזרחים שלאחר 1917 ביצעו כוחות ממספר מחנות פוליטיים וצבאיים פוגרומים שבהם נהרגו עשרות אלפי יהודים.","context":"האלימות בוצעה בידי כוחות שונים ולא ניתן לייחס אותה למחנה יחיד; האומדנים המצטברים משתנים במחקר.","aftermath":"הפוגרומים גרמו להרג המוני, עקירה וטראומה והאיצו שינויים פוליטיים והגירה בקרב יהודי האזור.","sourceStatus":"רמת ודאות גבוהה מאוד; האומדנים המצטברים משתנים"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1819-hep-hep-riots-97"]={"title":"أعمال شغب هِب-هِب","location":"الولايات الألمانية","story":"بدأت أعمال شغب معادية لليهود في فورتسبورغ وانتشرت إلى عدة مدن ألمانية خلال نقاش حول تحرير اليهود مدنيًا. وهاجمت الحشود منازل ومتاجر وأفرادًا يهودًا وهي تردد الهتاف الذي أخذت منه الاضطرابات اسمها.","context":"وقعت الأحداث وسط توترات سياسية واقتصادية واجتماعية بشأن الوضع المدني لليهود.","aftermath":"زعزعت الاضطرابات أمن المجتمعات وأظهرت المعارضة الشعبية لتحرير اليهود في أجزاء من الولايات الألمانية.","sourceStatus":"موثق جيدًا في سجلات معاصرة؛ جمعت الدوافع بين التحامل المعادي لليهود والتوترات السياسية والاقتصادية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1821-odessa-anti-jewish-riot-98"]={"title":"أعمال شغب معادية لليهود في أوديسا","location":"أوديسا، الإمبراطورية الروسية","story":"تُعرّف أعمال الشغب المعادية لليهود في أوديسا سنة 1821 أحيانًا بأنها من أوائل الحوادث التي سُمّيت لاحقًا بوغروم.","context":"كانت الحادثة محلية وينبغي تمييزها عن موجات البوغروم الأوسع في أواخر القرن التاسع عشر.","aftermath":"سبقت هذه الأعمال موجات لاحقة من البوغروم في أوديسا وعبر الإمبراطورية الروسية.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1834-safed-looting-and-attacks-on-the-jewish-community-99"]={"title":"نهب وهجمات على المجتمع اليهودي في صفد","location":"صفد، فلسطين العثمانية","story":"خلال الاضطرابات الإقليمية المرتبطة بثورة 1834 في فلسطين تعرض المجتمع اليهودي في صفد للهجوم والنهب على نطاق واسع. وتضررت المنازل والمعابد واعتُدي على السكان وهُجروا.","context":"وقع الحدث ضمن تمرد إقليمي أوسع؛ تتفق المصادر على الهجمات والنهب لكنها تختلف في التفاصيل وأعداد الضحايا.","aftermath":"عانى المجتمع خسارة الممتلكات والإصابات والتهجير واضطر إلى إعادة البناء.","sourceStatus":"الهجمات والنهب موثقان؛ تختلف الروايات في التفاصيل وأعداد الضحايا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1840-damascus-affair-100"]={"title":"قضية دمشق","location":"دمشق، سوريا العثمانية","story":"بعد اختفاء راهب كاثوليكي وخادمه اتُهم أفراد من المجتمع اليهودي في دمشق زورًا بالقتل الطقسي. وسُجن عدد منهم وعُذب. وساعد التحرك اليهودي الدولي في إطلاق سراحهم وجعل القضية نقطة تحول في التنظيم السياسي اليهودي الحديث.","context":"الاعتقالات والتعذيب موثقان جيدًا؛ اتهام القتل الطقسي كان فرية دم كاذبة.","aftermath":"أثارت القضية تدخلًا يهوديًا ودبلوماسيًا دوليًا وعززت شبكات التضامن اليهودي عبر الحدود.","sourceStatus":"الاعتقالات والتعذيب موثقان جيدًا؛ اتهام القتل الطقسي كان كاذبًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1859-odessa-anti-jewish-riot-of-1859-101"]={"title":"أعمال الشغب المعادية لليهود في أوديسا سنة 1859","location":"أوديسا، الإمبراطورية الروسية","story":"اندلع عنف معادٍ لليهود في أوديسا حول عيد الفصح. وكان البحارة اليونانيون واليونانيون المحليون بارزين بين المهاجمين. وامتزج العداء الديني بالمنافسة الاقتصادية المتزايدة في ميناء البحر الأسود.","context":"يميز هذا المؤشر السياق المحلي عن البوغرومات اللاحقة ولا يفترض أن جميع أعمال العنف كان لها المنفذون أو الأسباب نفسها.","aftermath":"ساهم العنف في تغير المواقف اليهودية تجاه الأمن والتنظيم المجتمعي والتحرر المدني.","sourceStatus":"موثق جيدًا؛ يؤكد المؤرخون التوترات اليونانية اليهودية المحلية والمنافسة الاقتصادية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1871-odessa-pogrom-of-1871-102"]={"title":"بوغروم أوديسا سنة 1871","location":"أوديسا، الإمبراطورية الروسية","story":"ألحقت عدة أيام من العنف المعادي لليهود في أوديسا أضرارًا بمنازل ومتاجر يهودية. وشارك اليونانيون بصورة بارزة، وانضم روس أيضًا إلى الهجمات. ويعد المؤرخون سنة 1871 مقدمة مهمة لعصر البوغرومات الأوسع الذي تلاها.","context":"جمعت الحادثة توترات دينية وعرقية واقتصادية محلية ولا تتطابق بالضرورة مع موجات البوغروم اللاحقة.","aftermath":"ساهم العنف في التنظيم والدفاع الذاتي وتغير المواقف تجاه الأمن والتحرر المدني.","sourceStatus":"موثق جيدًا في تقارير رسمية ودراسات تاريخية؛ شملت الدوافع توترات دينية وعرقية واقتصادية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1881-russian-empire-pogrom-wave-103"]={"title":"موجة البوغرومات في الإمبراطورية الروسية","location":"الإمبراطورية الروسية","story":"بعد اغتيال القيصر ألكسندر الثاني اجتاحت أعمال شغب واسعة معادية لليهود مناطق جنوبية وغربية من الإمبراطورية الروسية بين 1881 و1884.","context":"وقعت أعمال العنف وسط أزمة سياسية واجتماعية واسعة؛ واختلف دور السلطات واستجابتها بحسب المكان.","aftermath":"ساهمت البوغرومات في هجرة يهودية واسعة وتنظيم سياسي وتطور حركات الدفاع الذاتي.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1882-may-laws-intensify-restrictions-on-russian-jews-104"]={"title":"قوانين مايو تشدد القيود على يهود روسيا","location":"الإمبراطورية الروسية","story":"في أعقاب موجة بوغرومات 1881 فرضت الحكومة الإمبراطورية لوائح مؤقتة عُرفت بقوانين مايو، قيدت الأماكن التي يستطيع كثير من اليهود السكن والعمل التجاري فيها. وكانت إجراءات دولة تمييزية لا هجومًا عنيفًا.","context":"يفصل هذا المؤشر بين الاضطهاد القانوني للدولة وبين عنف البوغروم المباشر.","aftermath":"عمقت القيود الضغط الاقتصادي والاجتماعي وساهمت في الهجرة والتغير السياسي بين يهود الإمبراطورية.","sourceStatus":"التشريع الإمبراطوري موثق بصورة مؤكدة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1903-kishinev-pogrom-105"]={"title":"بوغروم كيشيناو","location":"كيشيناو، الإمبراطورية الروسية","story":"قتلت ثلاثة أيام من العنف المعادي لليهود قرابة خمسين يهوديًا وجرحت المئات ودمرت أو نهبت مئات المنازل والمتاجر.","context":"جذب البوغروم اهتمامًا دوليًا وأظهر خطر التحريض المعادي للسامية والاستجابة الحكومية غير الكافية.","aftermath":"سرّعت الحادثة الهجرة والنشاط السياسي وتأسيس مجموعات الدفاع الذاتي اليهودية.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1905-odessa-pogrom-106"]={"title":"بوغروم أوديسا","location":"أوديسا، الإمبراطورية الروسية","story":"خلال اضطرابات ثورة 1905 شهدت أوديسا أحد أكثر بوغرومات تلك السنة دموية، مع قتل وإصابات ودمار واسع.","context":"وقع العنف وسط عدم استقرار ثوري وسياسي واسع؛ وتختلف تقديرات الضحايا.","aftermath":"عمق البوغروم الشعور بانعدام الأمن وزاد الهجرة والتنظيم السياسي والدفاع الذاتي.","sourceStatus":"ثقة عالية؛ تقديرات الضحايا تختلف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1918-civil-war-pogroms-in-ukraine-and-neighboring-regions-107"]={"title":"بوغرومات الحرب الأهلية في أوكرانيا والمناطق المجاورة","location":"أوكرانيا / بيلاروس / غاليسيا","story":"خلال الحروب الأهلية التي أعقبت 1917 نفذت قوات من عدة معسكرات سياسية وعسكرية بوغرومات قتلت عشرات الآلاف من اليهود.","context":"نفذت أعمال العنف قوات مختلفة ولا يمكن نسبها إلى معسكر واحد؛ وتختلف التقديرات الإجمالية في الدراسات.","aftermath":"سببت البوغرومات قتلًا جماعيًا وتهجيرًا وصدمة وسرعت التحولات السياسية والهجرة بين يهود المنطقة.","sourceStatus":"ثقة عالية جدًا؛ التقديرات الإجمالية تختلف"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1920-nebi-musa-riots-108"]={"title":"מהומות נבי מוסא","location":"ירושלים","story":"אלימות במהלך חגיגות נבי מוסא כללה התקפות על הקהילה היהודית בירושלים על רקע החרפת המתחים הפוליטיים הערביים–יהודיים בתקופת המנדט הבריטי.","context":"האירוע היה חלק מן העימות הפוליטי והקהילתי המתפתח בארץ בתקופת המנדט.","aftermath":"המהומות העמיקו את חוסר האמון והובילו לשינויים בהתארגנות הביטחונית היהודית.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1921-jaffa-riots-109"]={"title":"מהומות יפו","location":"יפו והסביבה","story":"אלימות ערבית–יהודית ביפו ובאזורים סמוכים גרמה להרוגים ולפצועים בשתי הקהילות והעמיקה את המתחים בתקופת המנדט.","context":"האלימות התרחשה בתוך מתחים לאומיים, פוליטיים וחברתיים גוברים בין ערבים ליהודים.","aftermath":"האירועים החריפו את ההפרדה והחששות הביטחוניים והובילו לתגובות מצד שלטונות המנדט.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1929-hebron-massacre-and-1929-palestine-riots-110"]={"title":"טבח חברון ומהומות תרפ״ט","location":"חברון וארץ ישראל המנדטורית","story":"במהלך אלימות נרחבת ב־1929 הרגו תוקפים ערבים 67 יהודים בחברון. יהודים הותקפו גם במקומות אחרים, בעוד ערבים נהרגו בעימותים ובידי כוחות בריטיים.","context":"הטבח בחברון היה חלק מגל אלימות רחב יותר, ולכן יש להבחין בין האירוע המקומי לבין כלל נפגעי מהומות 1929.","aftermath":"הקהילה היהודית העתיקה בחברון פונתה לאחר הטבח והאלימות העמיקה את הסכסוך בתקופת המנדט.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1929-safed-massacre-during-the-1929-riots-111"]={"title":"טבח צפת במהלך מהומות תרפ״ט","location":"צפת, ארץ ישראל המנדטורית","story":"במהלך מהומות 1929 תקפו ערבים תושבים יהודים בצפת, הרגו יהודים ושרפו ובזזו בתים יהודיים.","context":"זהו אירוע מזוהה בתוך גל האלימות הרחב של 1929, המיוצג גם באירועים אחרים בציר הזמן.","aftermath":"הקהילה היהודית בצפת ספגה הרוגים, פציעות ונזק לרכוש והמתחים באזור החריפו.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1933-nazi-seizure-of-power-begins-systematic-persecution-of-german-jews-112"]={"title":"עליית הנאצים לשלטון מתחילה רדיפה שיטתית של יהודי גרמניה","location":"גרמניה","story":"לאחר שאדולף היטלר נעשה קנצלר ב־30 בינואר 1933, המשטר הנאצי הפך במהירות אידאולוגיה אנטישמית למדיניות ממשלתית. יהודים סבלו מאיומים, תקיפות, הדרה ממוסדות ציבור ומערכת מתרחבת של חוקים מפלים.","context":"סמן זה עוקב אחר ההסלמה מאידאולוגיה אנטישמית למדיניות מדינה, הדרה משפטית, נישול כלכלי ואלימות גלויה יותר ויותר.","aftermath":"הצעדים בידדו, רוששו וסיכנו בהדרגה את הקהילות היהודיות וסייעו ליצור את המסגרת המוסדית לרדיפה הקיצונית ולרצח ההמוני שבאו בהמשך.","sourceStatus":"מתועד בהרחבה ברשומות גרמניות, בדיווחים בני התקופה ובארכיוני השואה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1933-nationwide-nazi-boycott-of-jewish-businesses-113"]={"title":"חרם נאצי ארצי על עסקים יהודיים","location":"גרמניה","story":"ב־1 באפריל 1933 ארגנה המפלגה הנאצית חרם ארצי על עסקים בבעלות יהודית ועל בעלי מקצוע יהודים. אנשי SA עמדו מחוץ לחנויות ולמשרדים כדי להפחיד לקוחות. אף שהחרם הרשמי נמשך יום אחד, הוא סימן תחילת מסע לאומי להוצאת יהודים מן החיים הכלכליים בגרמניה.","context":"החרם היה שלב מוקדם בהפיכת האנטישמיות למדיניות ממוסדת של הדרה כלכלית.","aftermath":"הצעדים הכלכליים נגד יהודים התרחבו בשנים הבאות והובילו לנישול שיטתי יותר.","sourceStatus":"מתועד בהרחבה; החרם אורגן בידי רשויות המפלגה הנאצית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1933-civil-service-law-excludes-jews-from-government-employment-114"]={"title":"חוק שירות המדינה מדיר יהודים ממשרות ממשלתיות","location":"גרמניה","story":"החוק לשיקום שירות המדינה המקצועי מ־7 באפריל סילק יהודים רבים ומתנגדים פוליטיים ממשרות ממשלתיות. זה היה אחד הצעדים המשפטיים הגדולים הראשונים להדרה שיטתית של יהודים מן החיים הציבוריים בגרמניה.","context":"החקיקה ממחישה את המעבר המהיר מאפליה פוליטית לחוק מדינה מחייב.","aftermath":"ההדרה התרחבה בהמשך למקצועות ולמוסדות נוספים וסייעה לבודד את יהודי גרמניה.","sourceStatus":"החקיקה ויישומה מתועדים ישירות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1935-nuremberg-laws-strip-jews-of-rights-and-impose-racial-definitions-115"]={"title":"חוקי נירנברג שוללים זכויות מיהודים ומטילים הגדרות גזעיות","location":"נירנברג / גרמניה הנאצית","story":"חוקי נירנברג שללו מיהודי גרמניה אזרחות מלאה ואסרו נישואין ויחסי מין בין יהודים לבין מי שסווגו כבעלי דם גרמני או קרוב לו. הרשויות הנאציות הגדירו זהות יהודית לפי מוצא גזעי ולא לפי אמונה אישית.","context":"החוקים הפכו את האפליה הגזעית לעיקרון משפטי מרכזי של המדינה הנאצית.","aftermath":"הם העמיקו את בידוד היהודים והכשירו צעדי נישול, גירוש ורדיפה נוספים.","sourceStatus":"חקיקה נאצית ופרקטיקה מנהלית מתועדות בהרחבה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1936-1936-1939-arab-revolt-attacks-on-jewish-civilians-116"]={"title":"המרד הערבי 1936–1939: התקפות על אזרחים יהודים","location":"ארץ ישראל המנדטורית","story":"המרד הערבי נגד השלטון הבריטי וההגירה היהודית ההמונית כלל התקפות על אזרחים ויישובים יהודיים, לצד דיכוי בריטי ותגובות חמושות יהודיות.","context":"האירוע היה חלק ממרד רחב נגד הבריטים ומסכסוך לאומי מתעצם; אלימות בוצעה במסגרות שונות בידי כמה צדדים.","aftermath":"המרד שינה את מדיניות בריטניה, את ההתארגנות הצבאית היהודית ואת היחסים בין הקהילות לקראת סוף המנדט.","sourceStatus":"רמת ודאות גבוהה מאוד; אירועים בודדים דורשים מקורות נפרדים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1937-escalating-exclusion-and-aryanization-of-jewish-economic-life-117"]={"title":"החרפת ההדרה וה״אריזציה״ של החיים הכלכליים היהודיים","location":"גרמניה","story":"מ־1937 ועד 1939 אילצה המדיניות הנאצית יותר ויותר יהודים לצאת ממקצועות ומעסקים והעבירה רכוש בבעלות יהודית לבעלות לא־יהודית בתנאי כפייה. התהליך, שכונה אריזציה, רושש משפחות יהודיות ובודד אותן עוד יותר.","context":"הנישול הכלכלי היה חלק מן ההסלמה השיטתית של רדיפת יהודי גרמניה.","aftermath":"המדיניות צמצמה את יכולת הקיום הכלכלית של יהודים והגבירה את הלחץ להגר.","sourceStatus":"מתועד בהרחבה בצווים נאציים, ברשומות רכוש ובמחקר השואה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1938-kristallnacht-november-pogrom-118"]={"title":"ליל הבדולח / פוגרום נובמבר","location":"גרמניה ואוסטריה","story":"מנהיגי הנאצים שחררו גל אלימות אנטי־יהודית ארצי: בתי כנסת נשרפו, עסקים ובתים נהרסו, יהודים נרצחו וכ־26,000 גברים יהודים נכלאו במחנות ריכוז.","context":"הפוגרום סימן מעבר בולט מרדיפה משפטית וכלכלית לאלימות המונית מאורגנת בידי המשטר.","aftermath":"האירוע האיץ הגירה, נישול וכליאה והיה שלב מרכזי בדרך לרדיפה הקטלנית בזמן המלחמה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1939-german-invasion-of-poland-and-persecution-of-polish-jews-119"]={"title":"פלישת גרמניה לפולין ורדיפת יהודי פולין","location":"פולין הכבושה","story":"גרמניה פלשה לפולין ב־1 בספטמבר 1939. כוחות גרמניים ורשויות הכיבוש החלו מיד להשפיל יהודים, לכפות עבודת כפייה, לשדוד, לעקור ולהפעיל אלימות. האוכלוסייה היהודית הגדולה של פולין עברה תחת שלטון נאצי.","context":"זהו שלב מרכזי בכרונולוגיית השואה שבו הרדיפה הנאצית התרחבה עם הכיבוש למיליוני יהודים נוספים.","aftermath":"הכיבוש הוביל לריכוז יהודים, גטאות, גירושים ובהמשך לרצח המוני שיטתי.","sourceStatus":"מתועד בהרחבה ברשומות גרמניות, בעדויות ראייה ובארכיוני השואה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1940-nazi-ghettos-isolate-jewish-communities-in-occupied-poland-120"]={"title":"הגטאות הנאציים מבודדים קהילות יהודיות בפולין הכבושה","location":"פולין הכבושה בידי גרמניה","story":"הרשויות הגרמניות אילצו יהודים לעבור לרבעים עירוניים סגורים או מוגבלים שנודעו כגטאות. גטאות כמו לודז' וורשה סבלו מצפיפות קיצונית, רעב, מחלות ועבודת כפייה, ובהמשך שימשו נקודות ריכוז לגירוש למרכזי הרג.","context":"הגטאות היו חלק ממערכת רדיפה שהתקדמה מבידוד וניצול אל גירוש ורצח המוני.","aftermath":"מאות אלפים מתו מתנאי החיים או גורשו בהמשך למרכזי הרג.","sourceStatus":"מתועד בהרחבה ברשומות מנהל גרמניות, תצלומים, יומנים ועדויות ניצולים"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1920-nebi-musa-riots-108"]={"title":"اضطرابات النبي موسى","location":"القدس","story":"شمل العنف خلال موسم النبي موسى هجمات على المجتمع اليهودي في القدس وسط تصاعد التوتر السياسي العربي اليهودي في عهد الانتداب البريطاني.","context":"كانت الحادثة جزءًا من الصراع السياسي والمجتمعي المتنامي في فلسطين خلال الانتداب.","aftermath":"عمقت الاضطرابات انعدام الثقة وأدت إلى تغييرات في التنظيم الأمني اليهودي.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1921-jaffa-riots-109"]={"title":"اضطرابات يافا","location":"يافا والمنطقة المحيطة","story":"أدى العنف العربي اليهودي في يافا والمناطق المجاورة إلى قتلى وجرحى من المجتمعين وعمق توترات عهد الانتداب.","context":"وقع العنف وسط تصاعد التوترات القومية والسياسية والاجتماعية بين العرب واليهود.","aftermath":"فاقمت الأحداث الانقسام والمخاوف الأمنية وأدت إلى ردود من سلطات الانتداب.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1929-hebron-massacre-and-1929-palestine-riots-110"]={"title":"مذبحة الخليل واضطرابات فلسطين سنة 1929","location":"الخليل وفلسطين الانتدابية","story":"خلال أعمال العنف الواسعة سنة 1929 قتل مهاجمون عرب 67 يهوديًا في الخليل. كما تعرض يهود لهجمات في أماكن أخرى، بينما قُتل عرب في اشتباكات وعلى يد القوات البريطانية.","context":"كانت مذبحة الخليل جزءًا من موجة عنف أوسع، ولذلك ينبغي التمييز بين الحادثة المحلية ومجمل ضحايا اضطرابات 1929.","aftermath":"أُخلي المجتمع اليهودي القديم في الخليل بعد المذبحة وعمق العنف الصراع في عهد الانتداب.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1929-safed-massacre-during-the-1929-riots-111"]={"title":"مذبحة صفد خلال اضطرابات 1929","location":"صفد، فلسطين الانتدابية","story":"خلال اضطرابات 1929 هاجم عرب سكانًا يهودًا في صفد وقتلوا يهودًا وأحرقوا ونهبوا منازل يهودية.","context":"هذه حادثة محددة داخل موجة العنف الأوسع لسنة 1929 والممثلة أيضًا في أحداث أخرى في الخط الزمني.","aftermath":"تكبد المجتمع اليهودي في صفد قتلى وإصابات وأضرارًا بالممتلكات وتصاعد التوتر في المنطقة.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1933-nazi-seizure-of-power-begins-systematic-persecution-of-german-jews-112"]={"title":"استيلاء النازيين على السلطة يبدأ الاضطهاد المنهجي ليهود ألمانيا","location":"ألمانيا","story":"بعد أن أصبح أدولف هتلر مستشارًا في 30 يناير 1933 حوّل النظام النازي الأيديولوجيا المعادية للسامية بسرعة إلى سياسة حكومية. وواجه اليهود الترهيب والاعتداء والاستبعاد من المؤسسات العامة ونظامًا متوسعًا من القوانين التمييزية.","context":"يتتبع هذا المؤشر التصعيد من الأيديولوجيا المعادية للسامية إلى سياسة الدولة والإقصاء القانوني ونزع الملكية الاقتصادية والعنف المتزايد.","aftermath":"عزلت هذه الإجراءات المجتمعات اليهودية وأفقرتها وعرضتها للخطر تدريجيًا وساعدت في إنشاء الإطار المؤسسي للاضطهاد الأشد والقتل الجماعي لاحقًا.","sourceStatus":"موثق على نطاق واسع في السجلات الألمانية والتقارير المعاصرة وأرشيفات الهولوكوست"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1933-nationwide-nazi-boycott-of-jewish-businesses-113"]={"title":"مقاطعة نازية وطنية للأعمال اليهودية","location":"ألمانيا","story":"في 1 أبريل 1933 نظم الحزب النازي مقاطعة وطنية للمتاجر المملوكة لليهود وللمهنيين اليهود. ووقف أفراد قوات العاصفة خارج المتاجر والمكاتب لترهيب الزبائن. ورغم أن المقاطعة الرسمية استمرت يومًا واحدًا، فإنها دشنت حملة وطنية لإخراج اليهود من الحياة الاقتصادية الألمانية.","context":"كانت المقاطعة مرحلة مبكرة في تحويل معاداة السامية إلى سياسة مؤسسية للإقصاء الاقتصادي.","aftermath":"توسعت الإجراءات الاقتصادية ضد اليهود في السنوات التالية وأدت إلى نزع ملكية أكثر منهجية.","sourceStatus":"موثق على نطاق واسع؛ نظمت سلطات الحزب النازي المقاطعة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1933-civil-service-law-excludes-jews-from-government-employment-114"]={"title":"قانون الخدمة المدنية يستبعد اليهود من الوظائف الحكومية","location":"ألمانيا","story":"أزال قانون استعادة الخدمة المدنية المهنية الصادر في 7 أبريل كثيرًا من اليهود والمعارضين السياسيين من الوظائف الحكومية. وكان من أوائل الخطوات القانونية الكبرى للإقصاء المنهجي لليهود من الحياة العامة الألمانية.","context":"يوضح التشريع الانتقال السريع من التمييز السياسي إلى قانون دولة ملزم.","aftermath":"امتد الإقصاء لاحقًا إلى مهن ومؤسسات أخرى وساعد في عزل يهود ألمانيا.","sourceStatus":"التشريع وتطبيقه موثقان مباشرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1935-nuremberg-laws-strip-jews-of-rights-and-impose-racial-definitions-115"]={"title":"قوانين نورمبرغ تسلب اليهود حقوقهم وتفرض تعريفات عرقية","location":"نورمبرغ / ألمانيا النازية","story":"حرمت قوانين نورمبرغ يهود ألمانيا من المواطنة الكاملة وحظرت الزواج والعلاقات الجنسية بين اليهود ومن صُنّفوا من الدم الألماني أو القريب منه. وحددت السلطات النازية الهوية اليهودية وفق الأصل العرقي لا الاعتقاد الديني الشخصي.","context":"حولت القوانين التمييز العرقي إلى مبدأ قانوني مركزي للدولة النازية.","aftermath":"عمقت عزلة اليهود ومهدت لمزيد من نزع الملكية والطرد والاضطهاد.","sourceStatus":"تشريعات نازية وممارسة إدارية موثقة على نطاق واسع"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1936-1936-1939-arab-revolt-attacks-on-jewish-civilians-116"]={"title":"الثورة العربية 1936–1939: هجمات على المدنيين اليهود","location":"فلسطين الانتدابية","story":"شملت الثورة العربية ضد الحكم البريطاني والهجرة اليهودية الواسعة هجمات على مدنيين ومجتمعات يهودية، إلى جانب مكافحة التمرد البريطانية وردود مسلحة يهودية.","context":"كانت الحادثة جزءًا من تمرد واسع ضد البريطانيين ومن صراع قومي متصاعد؛ ووقع العنف في سياقات مختلفة ومن عدة أطراف.","aftermath":"غيرت الثورة السياسة البريطانية والتنظيم العسكري اليهودي والعلاقات بين المجتمعات قبيل نهاية الانتداب.","sourceStatus":"ثقة عالية جدًا؛ الحوادث الفردية تحتاج مصادر منفصلة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1937-escalating-exclusion-and-aryanization-of-jewish-economic-life-117"]={"title":"تصاعد إقصاء و«أرينة» الحياة الاقتصادية اليهودية","location":"ألمانيا","story":"من 1937 إلى 1939 أجبرت السياسة النازية اليهود بصورة متزايدة على الخروج من المهن والأعمال ونقلت الممتلكات اليهودية إلى ملكية غير يهودية بشروط قسرية. وأفقرت هذه العملية، المعروفة بالأرينة، الأسر اليهودية وعزلتها أكثر عن المجتمع الألماني.","context":"كان نزع الملكية الاقتصادية جزءًا من التصعيد المنهجي لاضطهاد يهود ألمانيا.","aftermath":"قلصت السياسة قدرة اليهود على البقاء اقتصاديًا وزادت الضغط للهجرة.","sourceStatus":"موثق على نطاق واسع بالمراسيم النازية وسجلات الملكية ودراسات الهولوكوست"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1938-kristallnacht-november-pogrom-118"]={"title":"ليلة الكريستال / بوغروم نوفمبر","location":"ألمانيا والنمسا","story":"أطلق قادة النازيين عنفًا وطنيًا ضد اليهود: أُحرقت المعابد ودُمرت المتاجر والمنازل وقُتل يهود وسُجن نحو 26 ألف رجل يهودي في معسكرات الاعتقال.","context":"مثل البوغروم انتقالًا بارزًا من الاضطهاد القانوني والاقتصادي إلى عنف جماعي منظم من النظام.","aftermath":"سرّع الحدث الهجرة ونزع الملكية والسجن وكان مرحلة رئيسية نحو الاضطهاد القاتل في زمن الحرب.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1939-german-invasion-of-poland-and-persecution-of-polish-jews-119"]={"title":"الغزو الألماني لبولندا واضطهاد يهود بولندا","location":"بولندا المحتلة","story":"غزت ألمانيا بولندا في 1 سبتمبر 1939. وبدأت القوات الألمانية وسلطات الاحتلال فورًا بإذلال اليهود وفرض العمل القسري والسرقة والتهجير والعنف. وخضع العدد الكبير من يهود بولندا للحكم النازي.","context":"كانت هذه مرحلة مركزية في تسلسل الهولوكوست، إذ وسع الاحتلال الاضطهاد النازي ليشمل ملايين اليهود الآخرين.","aftermath":"أدى الاحتلال إلى تجميع اليهود في الغيتوات والترحيل ثم القتل الجماعي المنهجي.","sourceStatus":"موثق على نطاق واسع في السجلات الألمانية وشهادات العيان وأرشيفات الهولوكوست"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1940-nazi-ghettos-isolate-jewish-communities-in-occupied-poland-120"]={"title":"الغيتوات النازية تعزل المجتمعات اليهودية في بولندا المحتلة","location":"بولندا المحتلة ألمانيًا","story":"أجبرت السلطات الألمانية اليهود على الانتقال إلى أحياء حضرية مغلقة أو مقيدة عُرفت بالغيتوات. وعانت غيتوات مثل لودج ووارسو من اكتظاظ شديد وجوع ومرض وعمل قسري، ثم استُخدمت نقاط تجميع للترحيل إلى مراكز القتل.","context":"كانت الغيتوات جزءًا من نظام اضطهاد تقدم من العزل والاستغلال إلى الترحيل والقتل الجماعي.","aftermath":"مات مئات الآلاف من ظروف الحياة أو رُحلوا لاحقًا إلى مراكز القتل.","sourceStatus":"موثق على نطاق واسع في السجلات الإدارية الألمانية والصور واليوميات وشهادات الناجين"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-farhud-121"]={"title":"הפרהוד","location":"בגדאד, עיראק","story":"ב־1–2 ביוני 1941 פרצה בבגדאד אלימות אנטי־יהודית שכללה הרג ופציעת יהודים, ביזה והרס נרחבים.","context":"הפרהוד התרחש בתוך משבר פוליטי בעיראק בזמן מלחמת העולם השנייה, לאחר קריסת המשטר הפרו־צירי של רשיד עלי.","aftermath":"האירוע ערער עמוקות את תחושת הביטחון של יהודי עיראק ונעשה נקודת ציון בזיכרון הקהילה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-ia-i-pogrom-122"]={"title":"פוגרום יאשי","location":"יאשי, רומניה","story":"רשויות ויחידות צבא רומניות, בסיוע חיילים גרמנים בחלק מן המקרים, רצחו לפחות 8,000 יהודים במהלך פוגרום יוני 1941 וברכבות המוות הקשורות אליו.","context":"האירוע היה חלק מרדיפת ורצח יהודי רומניה בתקופת השואה ובוצע במעורבות מרכזית של הרשויות הרומניות.","aftermath":"אלפי יהודים נרצחו והקהילה נפגעה באופן קטסטרופלי.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-lviv-pogrom-123"]={"title":"פוגרום לבוב","location":"לבוב, אוקראינה הכבושה בידי גרמניה","story":"לאחר הכיבוש הגרמני של לבוב השתתפו כוחות גרמניים, פעילים לאומנים אוקראינים, אנשי מיליציה ואזרחים מקומיים בהשפלה, הכאה ורצח של יהודים.","context":"האירוע התרחש בימים הראשונים של הכיבוש הגרמני ובתוך הסלמה מהירה של אלימות אנטי־יהודית.","aftermath":"הפוגרום היה חלק מתחילת ההשמדה ההמונית של יהודי האזור תחת הכיבוש הנאצי.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-jedwabne-massacre-124"]={"title":"טבח ידוובנה","location":"ידוובנה, פולין הכבושה בידי גרמניה","story":"מאות מתושבי ידוובנה היהודים נרצחו ביולי 1941 בידי שכנים פולנים בנוכחות משטרה גרמנית; שאלות על מידת היוזמה וההכוונה הגרמנית ממשיכות להיחקר.","context":"האחריות הישירה של מבצעים מקומיים מתועדת, לצד נוכחות ושליטה גרמנית באזור; היבטים של היוזמה הגרמנית נותרו נושא למחקר.","aftermath":"הקהילה היהודית המקומית הושמדה כמעט לחלוטין.","sourceStatus":"רמת ודאות גבוהה מאוד; היבטים מסוימים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-ponary-mass-killings-begin-125"]={"title":"תחילת הרציחות ההמוניות בפונאר","location":"ליד וילנה, ליטא","story":"יחידות אס־אס ומשטרה גרמניות, בסיוע משתפי פעולה ליטאים, רצחו בפונאר יהודים מווילנה ומהסביבה. בסופו של דבר נרצחו באתר עשרות אלפי יהודים.","context":"פונאר היה אתר מרכזי של רצח בירי בתקופת השואה במזרח אירופה.","aftermath":"הרציחות השמידו חלק גדול מן האוכלוסייה היהודית של וילנה והאזור.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-che-mno-killing-center-begins-mass-murder-126"]={"title":"מרכז ההרג חלמנו מתחיל ברצח המוני","location":"חלמנו, פולין הכבושה בידי גרמניה","story":"הרצח ההמוני בחלמנו החל בדצמבר 1941 באמצעות משאיות גז. גרמניה הנאצית רצחה שם לפחות 152,000 יהודים.","context":"חלמנו היה מרכז ההרג הנאצי הראשון שבו נעשה שימוש שיטתי בגז לצורך רצח המוני.","aftermath":"המרכז שימש להשמדת קהילות יהודיות, במיוחד מאזור ורטגאו וגטו לודז'.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-holocaust-mass-shootings-and-extermination-127"]={"title":"השואה: ירי המוני והשמדה","location":"אירופה הכבושה בידי גרמניה","story":"גרמניה הנאצית ובעלות בריתה ומשתפי הפעולה עמה רצחו באופן שיטתי כשישה מיליון יהודים אירופים באמצעות ירי, מרכזי הרג, גטאות, הרעבה, עבודת כפייה ושיטות נוספות.","context":"זהו אירוע־על בציר הזמן; אירועים נפרדים מתעדים אתרי הרג, גירושים, פוגרומים ומעשי התנגדות ספציפיים.","aftermath":"השואה החריבה קהילות יהודיות ברחבי אירופה והותירה השלכות דמוגרפיות, פוליטיות ותרבותיות עמוקות.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-rumbula-massacre-128"]={"title":"טבח רומבולה","location":"ליד ריגה, לטביה הכבושה בידי גרמניה","story":"אנשי אס־אס ומשטרה גרמנים וכוחות עזר לטביים רצחו בסוף 1941 כ־25,000 יהודים מגטו ריגה וכ־1,000 יהודים מגרמניה ביער רומבולה.","context":"הטבח היה אחד ממבצעי הירי ההמוני הגדולים בשואה לפני התרחבות מרכזי ההרג.","aftermath":"רוב תושבי גטו ריגה שנכללו באקציה נרצחו בתוך ימים ספורים.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-babi-yar-massacre-129"]={"title":"טבח באבי יאר","location":"קייב, אוקראינה הכבושה בידי גרמניה","story":"ב־29–30 בספטמבר 1941 רצחו אנשי איינזצגרופה C ומשתפי פעולה 33,771 גברים, נשים וילדים יהודים בגיא באבי יאר.","context":"הרצח התרחש לאחר כיבוש קייב והיה דוגמה מרכזית לשיטת ההשמדה בירי המוני.","aftermath":"האתר המשיך לשמש את הנאצים לרצח קבוצות נוספות במהלך הכיבוש.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-operation-barbarossa-and-einsatzgruppen-mass-shootings-130"]={"title":"מבצע ברברוסה והירי ההמוני של האיינזצגרופן","location":"השטחים הסובייטיים הכבושים בידי גרמניה","story":"לאחר פלישת גרמניה לברית המועצות ביוני 1941 ביצעו יחידות הרג ניידות, בסיוע כוחות גרמניים נוספים וכוחות עזר מקומיים במקומות שונים, ירי המוני ביהודים ובקבוצות יעד אחרות. קהילות יהודיות שלמות נרצחו סמוך לבתיהן.","context":"הפלישה סימנה הסלמה מכרעת מרדיפה וגטאות לרצח המוני שיטתי בשטחי ברית המועצות הכבושים.","aftermath":"הירי ההמוני רצח מאות אלפי יהודים והיה מרכיב מרכזי בהתפתחות השואה.","sourceStatus":"מתועד בהרחבה בדוחות מבצעיים גרמניים, רשומות מלחמה, קברי אחים ועדויות ניצולים ועדים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-kamianets-podilskyi-massacre-131"]={"title":"טבח קמניץ־פודולסקי","location":"קמניץ־פודולסקי, אוקראינה הסובייטית הכבושה","story":"בסוף אוגוסט 1941 רצחו כוחות אס־אס ומשטרה גרמניים, בסיוע כוחות תחת פיקוד גרמני, עשרות אלפי יהודים ליד קמניץ־פודולסקי. רבים מן הקורבנות גורשו קודם משטח בשליטה הונגרית; גם יהודים אוקראינים מקומיים נרצחו.","context":"הטבח היה אחד ממבצעי הרצח ההמוני הגדולים הראשונים לאחר מבצע ברברוסה.","aftermath":"האירוע הדגים את המעבר המהיר לרצח המוני של אוכלוסיות יהודיות שלמות.","sourceStatus":"מתועד בהרחבה; כ־23,600 יהודים דווחו כנרצחים באקציה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-odessa-massacre-under-romanian-occupation-132"]={"title":"טבח אודסה תחת הכיבוש הרומני","location":"אודסה והאזור הסובב, אוקראינה הכבושה","story":"לאחר שכוחות רומניים וגרמניים כבשו את אודסה ביצעו הרשויות הרומניות פעולות תגמול המוניות נגד יהודים בעקבות פיצוץ במטה הצבאי הרומני. יהודים נורו, נתלו, נשרפו במבנים וגורשו לאתרי הרג ולמחנות בטרנסניסטריה שבשליטת רומניה.","context":"האירוע היה חלק מרדיפת ורצח היהודים תחת הממשל הרומני באזור.","aftermath":"הרציחות והגירושים השמידו חלק ניכר מן הקהילה היהודית המקומית.","sourceStatus":"התפקיד הרומני והרצח ההמוני מתועדים בהרחבה; מספרי הנפגעים משתנים לפי התחום הגאוגרפי והכרונולוגי הנכלל"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-farhud-121"]={"title":"الفرهود","location":"بغداد، العراق","story":"في 1–2 يونيو 1941 اندلع عنف معادٍ لليهود في بغداد أدى إلى قتل وجرح يهود ونهب ودمار واسع.","context":"وقع الفرهود وسط أزمة سياسية عراقية خلال الحرب العالمية الثانية بعد انهيار نظام رشيد عالي الموالي للمحور.","aftermath":"زعزع الحدث بشدة شعور يهود العراق بالأمان وأصبح محطة مركزية في ذاكرة المجتمع.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-ia-i-pogrom-122"]={"title":"بوغروم ياش","location":"ياش، رومانيا","story":"قتلت السلطات والوحدات العسكرية الرومانية، بمساعدة جنود ألمان في بعض الحالات، ما لا يقل عن 8,000 يهودي خلال بوغروم يونيو 1941 وقطارات الموت المرتبطة به.","context":"كان الحدث جزءًا من اضطهاد وقتل يهود رومانيا في الهولوكوست ونُفذ بمشاركة مركزية من السلطات الرومانية.","aftermath":"قُتل آلاف اليهود وتعرض المجتمع لكارثة واسعة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-lviv-pogrom-123"]={"title":"بوغروم لفيف","location":"لفيف، أوكرانيا المحتلة ألمانيًا","story":"بعد الاحتلال الألماني للمدينة شاركت قوات ألمانية ونشطاء قوميون أوكرانيون وأفراد ميليشيا ومدنيون محليون في إذلال اليهود وضربهم وقتلهم.","context":"وقع الحدث في الأيام الأولى للاحتلال الألماني وسط تصاعد سريع للعنف المعادي لليهود.","aftermath":"كان البوغروم جزءًا من بداية الإبادة الجماعية ليهود المنطقة تحت الاحتلال النازي.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-jedwabne-massacre-124"]={"title":"مذبحة يدفابنه","location":"يدفابنه، بولندا المحتلة ألمانيًا","story":"قُتل مئات السكان اليهود في يدفابنه في يوليو 1941 على يد جيران بولنديين بحضور الشرطة الألمانية؛ وما زالت جوانب التحريض والتوجيه الألماني موضع بحث تاريخي.","context":"المسؤولية المباشرة للمنفذين المحليين موثقة إلى جانب الوجود والسيطرة الألمانية في المنطقة؛ بعض جوانب المبادرة الألمانية ما تزال موضع بحث.","aftermath":"دُمر المجتمع اليهودي المحلي تقريبًا بالكامل.","sourceStatus":"ثقة عالية جدًا؛ بعض الجوانب موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-ponary-mass-killings-begin-125"]={"title":"بدء القتل الجماعي في بوناري","location":"قرب فيلنا، ليتوانيا","story":"قتلت وحدات الإس إس والشرطة الألمانية بمساعدة متعاونين ليتوانيين يهودًا من فيلنا والمناطق المحيطة في بوناري. وفي النهاية قُتل في الموقع عشرات الآلاف من اليهود.","context":"كان بوناري موقعًا رئيسيًا للقتل بالرصاص خلال الهولوكوست في شرق أوروبا.","aftermath":"أدت عمليات القتل إلى إبادة جزء كبير من السكان اليهود في فيلنا والمنطقة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-che-mno-killing-center-begins-mass-murder-126"]={"title":"مركز خيلمنو للقتل يبدأ القتل الجماعي","location":"خيلمنو، بولندا المحتلة ألمانيًا","story":"بدأ القتل الجماعي في خيلمنو في ديسمبر 1941 باستخدام شاحنات الغاز. وقتلت ألمانيا النازية هناك ما لا يقل عن 152 ألف يهودي.","context":"كان خيلمنو أول مركز قتل نازي استُخدم فيه الغاز بصورة منهجية للقتل الجماعي.","aftermath":"استُخدم المركز لإبادة مجتمعات يهودية، خاصة من منطقة فارتغاو وغيتو لودج.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-holocaust-mass-shootings-and-extermination-127"]={"title":"الهولوكوست: إطلاق النار الجماعي والإبادة","location":"أوروبا المحتلة ألمانيًا","story":"قتلت ألمانيا النازية وحلفاؤها والمتعاونون معها بصورة منهجية نحو ستة ملايين يهودي أوروبي عبر إطلاق النار ومراكز القتل والغيتوات والتجويع والعمل القسري ووسائل أخرى.","context":"هذا حدث شامل في الخط الزمني؛ وتوثق أحداث منفصلة مواقع قتل وترحيل وبوغرومات وأعمال مقاومة محددة.","aftermath":"دمر الهولوكوست المجتمعات اليهودية في أنحاء أوروبا وترك آثارًا ديموغرافية وسياسية وثقافية عميقة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-rumbula-massacre-128"]={"title":"مذبحة رومبولا","location":"قرب ريغا، لاتفيا المحتلة ألمانيًا","story":"قتل أفراد الإس إس والشرطة الألمان وقوات مساعدة لاتفية نحو 25 ألف يهودي من غيتو ريغا ونحو ألف يهودي ألماني في غابة رومبولا أواخر 1941.","context":"كانت المذبحة من أكبر عمليات القتل الجماعي بالرصاص في الهولوكوست قبل توسع مراكز القتل.","aftermath":"قُتل معظم سكان غيتو ريغا المستهدفين خلال أيام قليلة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-babi-yar-massacre-129"]={"title":"مذبحة بابي يار","location":"كييف، أوكرانيا المحتلة ألمانيًا","story":"في 29–30 سبتمبر 1941 قتل أفراد أينزاتسغروبه C ومتعاونون 33,771 رجلًا وامرأة وطفلًا يهوديًا في وادي بابي يار.","context":"وقع القتل بعد احتلال كييف وكان مثالًا رئيسيًا على الإبادة بإطلاق النار الجماعي.","aftermath":"واصل النازيون استخدام الموقع لقتل جماعات أخرى خلال الاحتلال.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-operation-barbarossa-and-einsatzgruppen-mass-shootings-130"]={"title":"عملية بارباروسا وإطلاق النار الجماعي للأينزاتسغروبن","location":"الأراضي السوفيتية المحتلة ألمانيًا","story":"بعد غزو ألمانيا للاتحاد السوفيتي في يونيو 1941 نفذت وحدات قتل متنقلة، بدعم قوات ألمانية أخرى ومساعدين محليين في مواقع مختلفة، عمليات إطلاق نار جماعي ضد اليهود وجماعات مستهدفة أخرى. وقُتلت مجتمعات يهودية كاملة قرب منازلها.","context":"مثل الغزو تصعيدًا حاسمًا من الاضطهاد والغيتوات إلى القتل الجماعي المنهجي في الأراضي السوفيتية المحتلة.","aftermath":"قتلت عمليات إطلاق النار مئات الآلاف من اليهود وكانت عنصرًا مركزيًا في تطور الهولوكوست.","sourceStatus":"موثق على نطاق واسع بالتقارير العملياتية الألمانية وسجلات الحرب والمقابر الجماعية وشهادات الناجين والشهود"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-kamianets-podilskyi-massacre-131"]={"title":"مذبحة كاميانيتس بوديلسكي","location":"كاميانيتس بوديلسكي، أوكرانيا السوفيتية المحتلة","story":"في أواخر أغسطس 1941 قتلت قوات الإس إس والشرطة الألمانية، بمشاركة قوات تحت القيادة الألمانية، عشرات الآلاف من اليهود قرب كاميانيتس بوديلسكي. وكان كثير من الضحايا قد رُحلوا من أراضٍ خاضعة للسيطرة المجرية، كما قُتل يهود أوكرانيون محليون.","context":"كانت المذبحة من أوائل عمليات القتل الجماعي الكبرى بعد عملية بارباروسا.","aftermath":"أظهر الحدث الانتقال السريع إلى قتل جماعي لمجتمعات يهودية كاملة.","sourceStatus":"موثق على نطاق واسع؛ أُبلغ عن مقتل نحو 23,600 يهودي في العملية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-odessa-massacre-under-romanian-occupation-132"]={"title":"مذبحة أوديسا تحت الاحتلال الروماني","location":"أوديسا والمنطقة المحيطة، أوكرانيا المحتلة","story":"بعد استيلاء القوات الرومانية والألمانية على أوديسا نفذت السلطات الرومانية أعمال انتقام جماعية ضد اليهود إثر انفجار في مقر عسكري روماني. وأُطلق النار على اليهود وشُنقوا وأُحرقوا في مبانٍ ورُحلوا إلى مواقع قتل ومعسكرات في ترانسنيستريا الخاضعة لرومانيا.","context":"كان الحدث جزءًا من اضطهاد وقتل اليهود تحت الإدارة الرومانية في المنطقة.","aftermath":"دمرت عمليات القتل والترحيل جزءًا كبيرًا من المجتمع اليهودي المحلي.","sourceStatus":"الدور الروماني والقتل الجماعي موثقان على نطاق واسع؛ تختلف أعداد الضحايا بحسب النطاق الجغرافي والزمني المحتسب"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-belzec-killing-center-133"]={"title":"מרכז ההרג בלז'ץ","location":"בלז'ץ, פולין הכבושה בידי גרמניה","story":"בלז'ץ הפך למרכז הרג במסגרת מבצע ריינהרד. כ־435,000 יהודים נרצחו בו, רובם המכריע בתאי גזים.","context":"בלז'ץ היה אחד משלושת מרכזי ההרג המרכזיים של מבצע ריינהרד להשמדת יהודי הגנרלגוברנמן.","aftermath":"כמעט כל המגורשים שנשלחו לבלז'ץ נרצחו, והמחנה פורק לאחר סיום פעולות ההרג העיקריות.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-sobibor-killing-center-134"]={"title":"מרכז ההרג סוביבור","location":"סוביבור, פולין הכבושה בידי גרמניה","story":"סוביבור הוקם כמרכז הרג במסגרת מבצע ריינהרד. לפחות 167,000 יהודים נרצחו בו.","context":"המחנה נועד בעיקר לרצח המוני של יהודים שגורשו מאזורים שונים באירופה הכבושה.","aftermath":"לאחר מרד האסירים ב־1943 פירקו הגרמנים את המחנה וניסו לטשטש את עקבותיו.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-treblinka-ii-killing-center-135"]={"title":"מרכז ההרג טרבלינקה II","location":"טרבלינקה, פולין הכבושה בידי גרמניה","story":"טרבלינקה II פעל כמרכז הרג במסגרת מבצע ריינהרד. אנשי המשטר הנאצי רצחו בו לפי ההערכות כ־925,000 יהודים.","context":"טרבלינקה היה אחד מאתרי הרצח ההמוני הקטלניים ביותר של השואה.","aftermath":"לאחר מרד אסירים ב־1943 פורק האתר ונעשו ניסיונות להסוות את תפקידו.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-auschwitz-birkenau-mass-murder-of-jews-136"]={"title":"הרצח ההמוני של יהודים באושוויץ־בירקנאו","location":"אושוויץ־בירקנאו, פולין הכבושה בידי גרמניה","story":"אושוויץ־בירקנאו נעשה מתחם הריכוז וההרג הגדול ביותר של גרמניה הנאצית. כמיליון יהודים נרצחו במתחם אושוויץ.","context":"האתר שילב מחנה ריכוז, עבודת כפייה ומערכת רצח המוני, בעיקר באמצעות תאי גזים.","aftermath":"אושוויץ נעשה אחד הסמלים המרכזיים של השואה ושל רצח יהודי אירופה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-great-action-deportation-of-warsaw-jews-to-treblinka-137"]={"title":"האקציה הגדולה: גירוש יהודי ורשה לטרבלינקה","location":"ורשה, פולין הכבושה בידי גרמניה","story":"מיולי עד ספטמבר 1942 גירשו הרשויות הגרמניות כ־265,000 יהודים מגטו ורשה לטרבלינקה ורצחו כ־35,000 יהודים בגטו במהלך המבצע.","context":"הגירוש היה חלק ממבצע ריינהרד ומחיסול הקהילות היהודיות בפולין הכבושה.","aftermath":"רוב אוכלוסיית הגטו גורשה ונרצחה; הנותרים התארגנו בהמשך להתנגדות חמושה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-operation-reinhard-138"]={"title":"מבצע ריינהרד","location":"פולין הכבושה בידי גרמניה","story":"מבצע ריינהרד היה התוכנית הנאצית לרצח יהודי הגנרלגוברנמן בפולין הכבושה. מרכזי ההרג העיקריים היו בלז'ץ, סוביבור וטרבלינקה, לצד גירושים וירי המוני.","context":"האירוע הוא מסגרת־על; מרכזי ההרג והגירושים המרכזיים מיוצגים גם כאירועים נפרדים בציר הזמן.","aftermath":"המבצע השמיד את רוב הקהילות היהודיות באזור והיה מרכיב מרכזי בפתרון הסופי.","sourceStatus":"מתועד בהרחבה; סמנים נפרדים מספקים אומדני קורבנות ספציפיים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1943-warsaw-ghetto-uprising-139"]={"title":"מרד גטו ורשה","location":"ורשה, פולין הכבושה בידי גרמניה","story":"לוחמים יהודים התנגדו למבצע הגירוש הגרמני הסופי שהחל ב־19 באפריל 1943. לפחות 7,000 יהודים מתו בלחימה או במקומות מסתור בזמן שהכוחות הגרמניים החריבו את הגטו.","context":"המרד היה פעולת התנגדות יהודית מזוינת נגד חיסול הגטו וגירוש תושביו.","aftermath":"המרד דוכא והגטו נהרס, אך הוא נעשה סמל מרכזי להתנגדות יהודית בשואה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1943-operation-harvest-festival-140"]={"title":"מבצע חג הקציר","location":"מחוז לובלין, פולין הכבושה בידי גרמניה","story":"אנשי אס־אס ומשטרה גרמנים רצחו עשרות אלפי עובדי כפייה יהודים במחוז לובלין במהלך מבצע חג הקציר בנובמבר 1943.","context":"המבצע נועד לחסל את האוכלוסייה היהודית שנותרה במחנות עבודת הכפייה המרכזיים באזור לובלין.","aftermath":"זה היה אחד ממבצעי הירי ההמוני הגדולים ביותר שביצעו הגרמנים נגד יהודים ביום ובפרק זמן קצר.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1943-bia-ystok-ghetto-uprising-141"]={"title":"מרד גטו ביאליסטוק","location":"ביאליסטוק, פולין הכבושה","story":"כאשר הכוחות הגרמניים החלו בחיסול הסופי של גטו ביאליסטוק באוגוסט 1943, פתחו לוחמי המחתרת היהודית במרד חמוש. ההתנגדות הוכרעה ורוב היהודים שנותרו גורשו למרכזי הרג ולמחנות.","context":"המרד היה ניסיון התנגדות מאורגן מול חיסול הגטו וגירוש תושביו.","aftermath":"רוב הקהילה שנותרה גורשה או נרצחה לאחר דיכוי ההתנגדות.","sourceStatus":"מתועד היטב ברשומות גרמניות, בדיווחי מחתרת ובעדויות ניצולים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1943-sobibor-uprising-and-mass-escape-142"]={"title":"מרד סוביבור והבריחה ההמונית","location":"מרכז ההרג סוביבור, פולין הכבושה","story":"ב־14 באוקטובר 1943 ארגנו אסירים יהודים בסוביבור מרד, הרגו כמה אנשי אס־אס ושומרים וניסו בריחה המונית. מאות פרצו מן המחנה; מספר קטן יותר שרד את המלחמה.","context":"המרד היה אחת מפעולות ההתנגדות הגדולות בתוך מרכז הרג נאצי.","aftermath":"המרד תרם להחלטה הגרמנית לפרק את מרכז ההרג ולטשטש את עקבותיו.","sourceStatus":"מתועד בהרחבה בעדויות ניצולים, ברשומות גרמניות ובחקירות שלאחר המלחמה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1943-treblinka-prisoner-uprising-143"]={"title":"מרד האסירים בטרבלינקה","location":"טרבלינקה II, פולין הכבושה","story":"ב־2 באוגוסט 1943 תפסו אסירים במרכז ההרג טרבלינקה נשק, הציתו חלקים מן המחנה וניסו בריחה המונית. מאות עברו את גדר המחנה, אך רבים ניצודו ונרצחו; מספר קטן יותר שרד את המלחמה.","context":"המרד היה התנגדות מאורגנת של אסירים בתוך אחד ממרכזי ההרג המרכזיים של מבצע ריינהרד.","aftermath":"המרד פגע במחנה והיה בין הגורמים שקדמו לפירוקו בידי הגרמנים.","sourceStatus":"המרד מתועד בהרחבה בעדויות ניצולים, ברשומות גרמניות ובמחקר שלאחר המלחמה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1944-deportation-of-hungarian-jews-to-auschwitz-birkenau-144"]={"title":"גירוש יהודי הונגריה לאושוויץ־בירקנאו","location":"הונגריה → אושוויץ־בירקנאו","story":"לאחר שגרמניה כבשה את הונגריה במרץ 1944 ריכזו וגירשו הרשויות ההונגריות, בשיתוף אנשי אס־אס גרמנים, יהודים במהירות. בין מאי ליולי גורשו כ־440,000 יהודים, רובם לאושוויץ־בירקנאו, ושם נרצח רובם.","context":"הגירושים היו מן המבצעים המהירים והגדולים ביותר של השלב האחרון בשואה.","aftermath":"בתוך שבועות ספורים הושמד חלק עצום מיהדות הונגריה שמחוץ לבודפשט.","sourceStatus":"מתועד בהרחבה ברשומות גירוש, תיעוד גרמני והונגרי, תצלומים ועדויות ניצולים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1944-auschwitz-sonderkommando-revolt-145"]={"title":"מרד הזונדרקומנדו באושוויץ","location":"אושוויץ־בירקנאו, פולין הכבושה","story":"ב־7 באוקטובר 1944 מרדו אסירי זונדרקומנדו יהודים באושוויץ־בירקנאו. הם תקפו שומרי אס־אס ופגעו בקרמטוריום IV באמצעות חומרי נפץ שהוברחו בידי אסירות יהודיות שעבדו במפעל סמוך.","context":"המרד היה ניסיון התנגדות של אסירים שנכפו לעבוד במתקני הרצח והשרפה.","aftermath":"המרד דוכא והמשתתפים הוצאו להורג, אך הקרמטוריום ניזוק והאירוע נעשה סמל להתנגדות בתוך אושוויץ.","sourceStatus":"מתועד בהרחבה ברשומות המחנה ובעדויות ניצולים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1944-liquidation-of-the-d-ghetto-146"]={"title":"חיסול גטו לודז'","location":"לודז', פולין הכבושה","story":"ב־1944 חיסלו הרשויות הגרמניות את גטו לודז', מן הגטאות הגדולים והממושכים בפולין הכבושה. רוב היהודים שנותרו גורשו לאושוויץ־בירקנאו, לאחר שגירושים קודמים שלחו עשרות אלפים לחלמנו.","context":"החיסול היה השלב האחרון בפירוק אחת הקהילות היהודיות הגדולות שנותרו בגטאות.","aftermath":"רוב תושבי הגטו שנותרו גורשו למרכזי הרג ורק מיעוט שרד.","sourceStatus":"החיסול והגירושים מתועדים בהרחבה ברשומות גרמניות, בתיעוד הגטו ובעדויות ניצולים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1945-death-marches-during-the-collapse-of-nazi-germany-147"]={"title":"צעדות המוות בזמן קריסת גרמניה הנאצית","location":"מרכז ומזרח אירופה","story":"כאשר צבאות בעלות הברית התקרבו למחנות הריכוז, פינו אנשי האס־אס אסירים לעומק גרמניה. אסירים, ובהם יהודים רבים, אולצו לצעוד ולהיטלטל בתנאי חורף קשים; שומרים רצחו מי שלא יכלו להמשיך ורבים אחרים מתו מחשיפה, רעב ותשישות.","context":"הפינויים נועדו להעביר אסירים הרחק מהצבאות המתקדמים והפכו לשלב קטלני נוסף בחודשי המלחמה האחרונים.","aftermath":"עשרות אלפי אסירים מתו בצעדות ובפינויים לפני שחרור המחנות וסיום המלחמה.","sourceStatus":"מתועד בהרחבה בפינויים רבים; המספרים הכוללים משתנים משום שהתרחשו צעדות רבות ונפרדות"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-belzec-killing-center-133"]={"title":"مركز القتل بيلجيتس","location":"بيلجيتس، بولندا المحتلة ألمانيًا","story":"أصبح بيلجيتس مركز قتل ضمن عملية راينهارد. وقُتل فيه نحو 435 ألف يهودي، غالبيتهم الساحقة في غرف الغاز.","context":"كان بيلجيتس أحد مراكز القتل الثلاثة الرئيسية لعملية راينهارد الهادفة إلى إبادة يهود الحكومة العامة.","aftermath":"قُتل تقريبًا جميع المرحلين إلى بيلجيتس وفُكك المعسكر بعد انتهاء عمليات القتل الرئيسية.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-sobibor-killing-center-134"]={"title":"مركز القتل سوبيبور","location":"سوبيبور، بولندا المحتلة ألمانيًا","story":"أُنشئ سوبيبور كمركز قتل ضمن عملية راينهارد. وقُتل فيه ما لا يقل عن 167 ألف يهودي.","context":"خُصص المعسكر أساسًا للقتل الجماعي لليهود المرحلين من مناطق مختلفة من أوروبا المحتلة.","aftermath":"بعد انتفاضة السجناء سنة 1943 فكك الألمان المعسكر وحاولوا إخفاء آثاره.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-treblinka-ii-killing-center-135"]={"title":"مركز القتل تريبلينكا الثاني","location":"تريبلينكا، بولندا المحتلة ألمانيًا","story":"عمل تريبلينكا الثاني كمركز قتل ضمن عملية راينهارد. وقتل النازيون فيه ما يقدر بنحو 925 ألف يهودي.","context":"كان تريبلينكا من أكثر مواقع القتل الجماعي فتكًا في الهولوكوست.","aftermath":"بعد انتفاضة السجناء سنة 1943 فُكك الموقع وجرت محاولات لإخفاء دوره.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-auschwitz-birkenau-mass-murder-of-jews-136"]={"title":"القتل الجماعي لليهود في أوشفيتز-بيركيناو","location":"أوشفيتز-بيركيناو، بولندا المحتلة ألمانيًا","story":"أصبح أوشفيتز-بيركيناو أكبر مجمع نازي للاعتقال والقتل. وقُتل نحو مليون يهودي في مجمع أوشفيتز.","context":"جمع الموقع بين معسكر اعتقال والعمل القسري ونظام للقتل الجماعي، خصوصًا بغرف الغاز.","aftermath":"أصبح أوشفيتز أحد أبرز رموز الهولوكوست وقتل يهود أوروبا.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-great-action-deportation-of-warsaw-jews-to-treblinka-137"]={"title":"العملية الكبرى: ترحيل يهود وارسو إلى تريبلينكا","location":"وارسو، بولندا المحتلة ألمانيًا","story":"من يوليو إلى سبتمبر 1942 رحلت السلطات الألمانية نحو 265 ألف يهودي من غيتو وارسو إلى تريبلينكا وقتلت نحو 35 ألف يهودي داخل الغيتو خلال العملية.","context":"كان الترحيل جزءًا من عملية راينهارد ومن تدمير المجتمعات اليهودية في بولندا المحتلة.","aftermath":"رُحل وقُتل معظم سكان الغيتو، ونظم من تبقى لاحقًا مقاومة مسلحة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-operation-reinhard-138"]={"title":"عملية راينهارد","location":"بولندا المحتلة ألمانيًا","story":"كانت عملية راينهارد البرنامج النازي لقتل يهود الحكومة العامة في بولندا المحتلة. وكانت مراكز القتل الرئيسية بيلجيتس وسوبيبور وتريبلينكا، إلى جانب الترحيل وإطلاق النار الجماعي.","context":"هذا حدث شامل؛ وتمثل مراكز القتل وعمليات الترحيل الرئيسية أيضًا كأحداث منفصلة في الخط الزمني.","aftermath":"أبادت العملية معظم المجتمعات اليهودية في المنطقة وكانت عنصرًا مركزيًا في الحل النهائي.","sourceStatus":"موثق على نطاق واسع؛ توفر مؤشرات منفصلة تقديرات أكثر تحديدًا للضحايا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1943-warsaw-ghetto-uprising-139"]={"title":"انتفاضة غيتو وارسو","location":"وارسو، بولندا المحتلة ألمانيًا","story":"قاوم مقاتلون يهود عملية الترحيل الألمانية النهائية التي بدأت في 19 أبريل 1943. ومات ما لا يقل عن 7,000 يهودي في القتال أو المخابئ بينما دمرت القوات الألمانية الغيتو.","context":"كانت الانتفاضة مقاومة يهودية مسلحة لتصفية الغيتو وترحيل سكانه.","aftermath":"قُمعت الانتفاضة ودُمر الغيتو، لكنها أصبحت رمزًا مركزيًا للمقاومة اليهودية في الهولوكوست.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1943-operation-harvest-festival-140"]={"title":"عملية مهرجان الحصاد","location":"منطقة لوبلين، بولندا المحتلة ألمانيًا","story":"قتل أفراد الإس إس والشرطة الألمانية عشرات الآلاف من عمال السخرة اليهود في منطقة لوبلين خلال عملية مهرجان الحصاد في نوفمبر 1943.","context":"هدفت العملية إلى تصفية السكان اليهود الباقين في معسكرات العمل القسري الرئيسية في منطقة لوبلين.","aftermath":"كانت من أكبر عمليات إطلاق النار الجماعي التي نفذها الألمان ضد اليهود في يوم واحد وفترة قصيرة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1943-bia-ystok-ghetto-uprising-141"]={"title":"انتفاضة غيتو بياليستوك","location":"بياليستوك، بولندا المحتلة","story":"عندما بدأت القوات الألمانية التصفية النهائية لغيتو بياليستوك في أغسطس 1943 أطلق مقاتلو المقاومة اليهودية انتفاضة مسلحة. وهُزمت المقاومة ورُحل معظم اليهود الباقين إلى مراكز القتل والمعسكرات.","context":"كانت الانتفاضة محاولة مقاومة منظمة ضد تصفية الغيتو وترحيل سكانه.","aftermath":"رُحل أو قُتل معظم من بقي من المجتمع بعد قمع المقاومة.","sourceStatus":"موثق جيدًا في السجلات الألمانية وتقارير المقاومة وشهادات الناجين"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1943-sobibor-uprising-and-mass-escape-142"]={"title":"انتفاضة سوبيبور والهروب الجماعي","location":"مركز القتل سوبيبور، بولندا المحتلة","story":"في 14 أكتوبر 1943 نظم سجناء يهود في سوبيبور انتفاضة وقتلوا عدة أفراد من الإس إس والحراس وحاولوا الهرب جماعيًا. وخرج المئات من المعسكر؛ ونجا عدد أقل من الحرب.","context":"كانت الانتفاضة من أكبر أعمال المقاومة داخل مركز قتل نازي.","aftermath":"ساهمت الانتفاضة في قرار الألمان تفكيك مركز القتل وإخفاء آثاره.","sourceStatus":"موثق على نطاق واسع بشهادات الناجين والسجلات الألمانية وتحقيقات ما بعد الحرب"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1943-treblinka-prisoner-uprising-143"]={"title":"انتفاضة سجناء تريبلينكا","location":"تريبلينكا الثاني، بولندا المحتلة","story":"في 2 أغسطس 1943 استولى سجناء في مركز قتل تريبلينكا على أسلحة وأشعلوا أجزاء من المعسكر وحاولوا هروبًا جماعيًا. وعبر المئات محيط المعسكر، لكن كثيرين طوردوا وقُتلوا؛ ونجا عدد أقل من الحرب.","context":"كانت الانتفاضة مقاومة منظمة من السجناء داخل أحد مراكز القتل الرئيسية لعملية راينهارد.","aftermath":"ألحقت الانتفاضة أضرارًا بالمعسكر وكانت من التطورات التي سبقت تفكيكه على يد الألمان.","sourceStatus":"موثق على نطاق واسع بشهادات الناجين والسجلات الألمانية وأبحاث ما بعد الحرب"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1944-deportation-of-hungarian-jews-to-auschwitz-birkenau-144"]={"title":"ترحيل يهود المجر إلى أوشفيتز-بيركيناو","location":"المجر ← أوشفيتز-بيركيناو","story":"بعد احتلال ألمانيا للمجر في مارس 1944 جمعت السلطات المجرية، بالتعاون مع مسؤولي الإس إس الألمان، اليهود ورحلتهم بسرعة. وبين مايو ويوليو رُحل نحو 440 ألف يهودي، معظمهم إلى أوشفيتز-بيركيناو حيث قُتل غالبيتهم.","context":"كانت عمليات الترحيل من أسرع وأكبر عمليات المرحلة الأخيرة من الهولوكوست.","aftermath":"خلال أسابيع دُمر جزء هائل من يهود المجر خارج بودابست.","sourceStatus":"موثق على نطاق واسع بسجلات الترحيل والوثائق الألمانية والمجرية والصور وشهادات الناجين"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1944-auschwitz-sonderkommando-revolt-145"]={"title":"تمرد السوندركوماندو في أوشفيتز","location":"أوشفيتز-بيركيناو، بولندا المحتلة","story":"في 7 أكتوبر 1944 تمرد سجناء يهود من السوندركوماندو في أوشفيتز-بيركيناو. وهاجموا حراس الإس إس وألحقوا أضرارًا بالمحرقة الرابعة بمتفجرات هربتها سجينات يهوديات يعملن في مصنع قريب.","context":"كان التمرد محاولة مقاومة من سجناء أُجبروا على العمل في منشآت القتل والحرق.","aftermath":"قُمع التمرد وأُعدم المشاركون، لكن المحرقة تضررت وأصبح الحدث رمزًا للمقاومة داخل أوشفيتز.","sourceStatus":"موثق على نطاق واسع في سجلات المعسكر وشهادات الناجين"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1944-liquidation-of-the-d-ghetto-146"]={"title":"تصفية غيتو لودج","location":"لودج، بولندا المحتلة","story":"في 1944 صفّت السلطات الألمانية غيتو لودج، أحد أكبر وأطول الغيتوات بقاءً في بولندا المحتلة. ورُحل معظم اليهود الباقين إلى أوشفيتز-بيركيناو، بعد أن أرسلت ترحيلات سابقة عشرات الآلاف إلى خيلمنو.","context":"كانت التصفية المرحلة الأخيرة في تفكيك أحد أكبر المجتمعات اليهودية المتبقية في الغيتوات.","aftermath":"رُحل معظم السكان الباقين إلى مراكز القتل ولم ينجُ إلا عدد قليل.","sourceStatus":"التصفية والترحيلات موثقة على نطاق واسع في السجلات الألمانية ووثائق الغيتو وشهادات الناجين"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1945-death-marches-during-the-collapse-of-nazi-germany-147"]={"title":"مسيرات الموت أثناء انهيار ألمانيا النازية","location":"وسط وشرق أوروبا","story":"مع اقتراب جيوش الحلفاء من معسكرات الاعتقال أخلى الإس إس السجناء نحو داخل ألمانيا. وأُجبر السجناء، ومنهم أعداد كبيرة من اليهود، على المسير والنقل في ظروف شتوية قاسية؛ وقتل الحراس من لم يستطيعوا المتابعة ومات آخرون من البرد والجوع والإرهاق.","context":"هدفت عمليات الإخلاء إلى نقل السجناء بعيدًا عن الجيوش المتقدمة وأصبحت مرحلة قاتلة إضافية في الأشهر الأخيرة للحرب.","aftermath":"مات عشرات الآلاف من السجناء في المسيرات والإجلاء قبل تحرير المعسكرات ونهاية الحرب.","sourceStatus":"موثق على نطاق واسع عبر عمليات إخلاء عديدة؛ تختلف الأعداد الإجمالية لأن مسيرات منفصلة كثيرة وقعت"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1946-kielce-pogrom-148"]={"title":"פוגרום קיילצה","location":"קיילצה, פולין","story":"המון, שאליו הצטרפו כמה שוטרים וחיילים, רצח ניצולי שואה יהודים ויהודים אחרים בקיילצה; לפחות 42 יהודים נרצחו.","context":"האירוע היה אלימות אנטי־יהודית לאחר השואה והמחיש את הסכנה שנמשכה עבור ניצולים שחזרו או ניסו לבנות מחדש את חייהם.","aftermath":"הפוגרום האיץ את יציאתם של יהודים רבים מפולין לאחר המלחמה והעמיק את תחושת חוסר הביטחון.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1946-king-david-hotel-bombing-149"]={"title":"פיצוץ מלון המלך דוד","location":"ירושלים, ארץ ישראל המנדטורית","story":"ב־22 ביולי 1946 פוצץ ארגון האצ״ל את האגף הדרומי של מלון המלך דוד בירושלים, שבו שכנו משרדי הממשל והצבא הבריטיים. 91 בני אדם נהרגו, ובהם ערבים, בריטים, יהודים ואחרים.","context":"הפיגוע היה חלק מן המאבק של ארגוני המחתרת היהודיים נגד שלטון המנדט הבריטי.","aftermath":"הפיצוץ החריף את העימות עם בריטניה והפך לאחד האירועים השנויים במחלוקת של תקופת המנדט.","sourceStatus":"הפיגוע, מבצעיו ומספר ההרוגים מתועדים בהרחבה; קיימת מחלוקת על האזהרות ועל תגובת הבריטים לפני הפיצוץ"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1947-fajja-bus-attacks-150"]={"title":"התקפות האוטובוסים ליד פג'ה","location":"ליד פתח תקווה, ארץ ישראל המנדטורית","story":"ב־30 בנובמבר 1947, יום לאחר הצבעת האו״ם על החלוקה, תקפו חמושים ערבים אוטובוסים יהודיים. ההתקפות היו בין האירועים הפותחים של שלב מלחמת האזרחים בסכסוך 1947–1949.","context":"האירוע התרחש מיד לאחר החלטת החלוקה ובתוך הסלמה מהירה של אלימות בין הקהילות.","aftermath":"ההתקפות סימנו את המעבר לעימות מזוין רחב יותר בארץ ישראל המנדטורית.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1947-1947-1949-palestine-war-arab-israeli-war-151"]={"title":"מלחמת 1947–1949 בארץ ישראל / מלחמת ערב–ישראל","location":"ארץ ישראל המנדטורית / ישראל","story":"הלחימה החלה לאחר הצבעת האו״ם על החלוקה; לאחר הכרזת העצמאות של ישראל במאי 1948 נכנסו צבאות ערביים שכנים למלחמה. אזרחים ולוחמים יהודים וערבים ספגו אבדות כבדות ועקירה.","context":"המלחמה כללה תחילה מלחמת אזרחים בין כוחות יהודיים וערביים ובהמשך מלחמה בין־מדינתית.","aftermath":"המלחמה הקימה את מדינת ישראל, שינתה גבולות, יצרה משברי פליטים ועקירה והותירה סכסוכים טריטוריאליים ופוליטיים בלתי פתורים.","sourceStatus":"רמת ודאות גבוהה מאוד; נרטיבים וחלק מן הנתונים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1947-un-partition-plan-and-outbreak-of-civil-war-in-mandatory-palestine-152"]={"title":"תוכנית החלוקה של האו״ם ופרוץ מלחמת האזרחים בארץ ישראל המנדטורית","location":"ארץ ישראל המנדטורית","story":"ב־29 בנובמבר 1947 המליצה העצרת הכללית של האו״ם לחלק את הארץ למדינה ערבית ולמדינה יהודית, עם משטר בינלאומי לירושלים. הנהגת הסוכנות היהודית קיבלה את החלוקה כבסיס למדינה; מנהיגים ערבים דחו אותה. הלחימה בין כוחות ערביים פלסטיניים לכוחות יהודיים החריפה כמעט מיד.","context":"החלטה 181 הייתה המלצה בינלאומית לחלוקה והפכה לנקודת מפנה פוליטית ומלחמתית.","aftermath":"האלימות התרחבה במהירות והובילה למלחמת 1948, להקמת ישראל ולעקירה רחבת היקף.","sourceStatus":"החלטה 181 וההסלמה שאחריה מתועדות בהרחבה; פרשנויות לגבי אחריות, כוונות והוגנות התוכנית נותרו שנויות במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-hadassah-medical-convoy-massacre-153"]={"title":"טבח שיירת הדסה","location":"ירושלים","story":"באפריל 1948 ארב כוח ערבי לשיירה שהובילה אנשי רפואה ואספקה לבית החולים הדסה ולאוניברסיטה העברית בהר הצופים; 78 יהודים נהרגו.","context":"האירוע התרחש בתוך הקרבות והמצור סביב ירושלים במהלך מלחמת האזרחים של 1947–1948.","aftermath":"הטבח העמיק את האלימות והפגיעה בשירותים רפואיים ובגישה להר הצופים.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-deir-yassin-massacre-154"]={"title":"טבח דיר יאסין","location":"דיר יאסין, ליד ירושלים","story":"ב־9 באפריל 1948 תקפו לוחמי האצ״ל ולח״י את הכפר הערבי הפלסטיני דיר יאסין. יותר ממאה מתושבי הכפר, ובהם אזרחים, נהרגו. הטבח הפך לסמל מרכזי של הסבל הפלסטיני ותרם לפחד במהלך מלחמת 1948.","context":"האירוע היה חלק ממלחמת האזרחים וחשוב להציגו לצד התקפות על יהודים ואירועי עקירה פלסטיניים באותה תקופה.","aftermath":"החדשות על הטבח תרמו לפחד ולבריחה במקומות אחרים והאירוע נותר מרכזי בזיכרון הפלסטיני.","sourceStatus":"ההתקפה והרג אזרחים מתועדים היטב; המספר המדויק וחלק מפרטי הקרב נדונו במחקר, והערכות מודרניות מציבות בדרך כלל את מספר ההרוגים סביב 100–110"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-kfar-etzion-massacre-155"]={"title":"טבח כפר עציון","location":"כפר עציון, דרומית לירושלים","story":"ב־13 במאי 1948 נפל כפר עציון לידי הלגיון הערבי וכוחות ערביים מקומיים לאחר לחימה ממושכת. מספר גדול של מגינים ותושבים יהודים נהרגו לאחר קריסת ההגנה ורק מעטים שרדו. יתר יישובי גוש עציון נכנעו למחרת.","context":"האירוע התרחש בשלב האחרון של מלחמת האזרחים, ערב סיום המנדט הבריטי.","aftermath":"נפילת הגוש נעשתה סמל מרכזי בזיכרון הישראלי של מלחמת 1948.","sourceStatus":"נפילת כפר עציון וההרג ההמוני מתועדים היטב; המקורות שונים לגבי הנסיבות המדויקות של מות יחידים לאחר הכניעה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-declaration-of-the-state-of-israel-156"]={"title":"הכרזת מדינת ישראל","location":"תל אביב","story":"ב־14 במאי 1948 הכריז דוד בן־גוריון על הקמת מדינת ישראל עם סיום המנדט הבריטי. ההכרזה הפכה את מלחמת האזרחים המתמשכת לעימות בין־מדינתי כאשר צבאות ערביים שכנים נכנסו לשטח המנדט לשעבר.","context":"האירוע היה נקודת מעבר מרכזית מהיישוב היהודי למדינה ריבונית בתוך מלחמה פעילה.","aftermath":"ישראל קמה כמדינה, והמלחמה התרחבה מיד עם התערבות צבאות ערב.","sourceStatus":"ההכרזה והמעבר הצבאי המיידי מתועדים ישירות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-arab-armies-enter-palestine-and-the-first-arab-israeli-war-expands-157"]={"title":"צבאות ערב נכנסים לארץ והמלחמה הערבית–ישראלית הראשונה מתרחבת","location":"ישראל / שטח ארץ ישראל המנדטורית לשעבר","story":"החל ב־15 במאי נכנסו צבאות מצרים, עבר הירדן, סוריה, עיראק ולבנון למלחמה בעקבות הכרזת העצמאות של ישראל. המלחמה כללה כעת את המדינה הישראלית החדשה, כוחות ערביים פלסטיניים ומספר מדינות ערביות שכנות.","context":"לממשלות ערב השונות היו מטרות צבאיות ופוליטיות שונות, ולכן אין לתאר את ההתערבות כאסטרטגיה אחידה לחלוטין.","aftermath":"העימות התרחב למלחמה בין־מדינתית שהסתיימה בהסכמי שביתת הנשק של 1949.","sourceStatus":"התערבות צבאות ערב השכנים מתועדת בהרחבה; המטרות והחישובים הפוליטיים השתנו בין הממשלות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-fall-of-the-jewish-quarter-of-jerusalem-s-old-city-158"]={"title":"נפילת הרובע היהודי בעיר העתיקה בירושלים","location":"ירושלים","story":"לאחר מצור ולחימה נכנע הרובע היהודי בעיר העתיקה ללגיון הערבי של עבר הירדן ב־28 במאי 1948. התושבים היהודים פונו מן הרובע והמגינים שנותרו בחיים נשבו. בתי כנסת ואתרים יהודיים נוספים ניזוקו או נהרסו לאחר מכן בתקופת השלטון הירדני.","context":"האירוע היה חלק מן המאבק על ירושלים במלחמת 1948.","aftermath":"העיר העתיקה נותרה בשליטה ירדנית עד 1967 ותושביה היהודים של הרובע לא יכלו לשוב בתקופה זו.","sourceStatus":"הכניעה והפינוי מתועדים היטב; תיאורי ההרס המאוחר משתנים לפי האתר והמקור"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-lydda-and-ramle-fighting-killings-and-palestinian-expulsion-159"]={"title":"לוד ורמלה: לחימה, הרג וגירוש פלסטינים","location":"לוד ורמלה","story":"כוחות ישראליים כבשו את לוד ורמלה ביולי 1948 במסגרת מבצע דני. אזרחים נהרגו במהלך הלחימה בלוד, ולאחר מכן רוב האוכלוסייה הערבית הפלסטינית של שתי הערים גורשה או נאלצה לברוח מזרחה. האירוע מרכזי בוויכוח ההיסטורי על משבר הפליטים הפלסטינים.","context":"האירוע מדגים שגם פעולות צבאיות ישראליות וגירוש פלסטינים הם חלק הכרחי מן התמונה המלאה של מלחמת 1948.","aftermath":"עשרות אלפי פלסטינים נעקרו והערים עברו לשליטה ישראלית.","sourceStatus":"הכיבוש והעקירה ההמונית מתועדים היטב; היסטוריונים חלוקים לגבי היבטים של הפקודות, מספרי ההרוגים והמנגנונים המדויקים של הגירוש"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-palestinian-refugee-and-displacement-crisis-160"]={"title":"משבר הפליטים והעקירה הפלסטיני","location":"פלסטין / מדינות ערב השכנות","story":"במהלך מלחמת 1947–1949 מאות אלפי ערבים פלסטינים ברחו או גורשו מבתיהם בשטח שהפך לישראל. הסיבות השתנו לפי מקום ושלב במלחמה וכללו גירוש ישיר, בריחה מקרבות, פחד מהתקפה והתמוטטות החברה הפלסטינית. ישראל מנעה בדרך כלל מרוב הפליטים לשוב לאחר המלחמה.","context":"העקירה ההמונית אינה שנויה במחלוקת, אך המשקל היחסי של הסיבות והאחריות במקומות מסוימים נותר נושא מרכזי למחלוקת היסטורית ופוליטית.","aftermath":"משבר הפליטים נעשה אחת הסוגיות המרכזיות והמתמשכות בסכסוך הישראלי–פלסטיני.","sourceStatus":"העקירה רחבת ההיקף אינה שנויה במחלוקת; מאזן הסיבות והאחריות ביישובים מסוימים נותר אחד הנושאים השנויים ביותר במחלוקת בתולדות הסכסוך"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-assassination-of-un-mediator-folke-bernadotte-161"]={"title":"רצח מתווך האו״ם פולקה ברנדוט","location":"ירושלים","story":"ב־17 בספטמבר 1948 נרצח בירושלים מתווך האו״ם הרוזן פולקה ברנדוט בידי חברי לח״י, ארגון מחתרת יהודי. ברנדוט מונה לתווך במלחמה הערבית–ישראלית והציע הסדרים בנושאי גבולות, ירושלים ופליטים.","context":"האירוע מתעד אלימות פוליטית שביצע ארגון יהודי ואינו מוצג כאירוע שבו יהודים היו הקורבנות.","aftermath":"הרצח עורר גינוי בינלאומי והאיץ צעדים ישראליים נגד לח״י.","sourceStatus":"הרצח ואחריות לח״י מתועדים היטב ברשומות האו״ם ובמקורות היסטוריים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1949-1949-armistice-agreements-end-major-fighting-162"]={"title":"הסכמי שביתת הנשק של 1949 מסיימים את הלחימה העיקרית","location":"ישראל ומדינות ערב השכנות","story":"ישראל חתמה ב־1949 על הסכמי שביתת נשק נפרדים עם מצרים, לבנון, ירדן וסוריה. ההסכמים סיימו את הלחימה הבין־מדינתית העיקרית אך לא יצרו הסכמי שלום כוללים. קווי שביתת הנשק נעשו הגבולות המעשיים עד מלחמת 1967.","context":"ההסכמים סיימו את השלב הצבאי העיקרי של מלחמת 1948 בלי לפתור את הסכסוך הרחב.","aftermath":"הגבולות, סוגיית הפליטים ומעמד ירושלים נותרו בלתי פתורים והמשיכו לעצב את הסכסוכים הבאים.","sourceStatus":"ההסכמים וקווי שביתת הנשק מתועדים ישירות ברשומות האו״ם"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1946-kielce-pogrom-148"]={"title":"بوغروم كيلتسه","location":"كيلتسه، بولندا","story":"قتل حشد انضم إليه بعض أفراد الشرطة والجنود ناجين يهودًا من الهولوكوست ويهودًا آخرين في كيلتسه؛ وقُتل ما لا يقل عن 42 يهوديًا.","context":"كان الحدث عنفًا معاديًا لليهود بعد الهولوكوست وأظهر استمرار الخطر على الناجين العائدين أو الساعين لإعادة بناء حياتهم.","aftermath":"سرّع البوغروم خروج كثير من اليهود من بولندا بعد الحرب وعمق الشعور بانعدام الأمن.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1946-king-david-hotel-bombing-149"]={"title":"تفجير فندق الملك داود","location":"القدس، فلسطين الانتدابية","story":"في 22 يوليو 1946 فجر تنظيم الإرغون اليهودي الجناح الجنوبي من فندق الملك داود في القدس، حيث كانت توجد مكاتب إدارية وعسكرية بريطانية. قُتل 91 شخصًا بينهم عرب وبريطانيون ويهود وآخرون.","context":"كان التفجير جزءًا من صراع التنظيمات السرية اليهودية ضد حكم الانتداب البريطاني.","aftermath":"صعّد التفجير المواجهة مع بريطانيا وأصبح من أكثر أحداث عهد الانتداب إثارة للجدل.","sourceStatus":"الهجوم ومنفذوه وعدد القتلى موثقون على نطاق واسع؛ يستمر الخلاف حول التحذيرات والاستجابة البريطانية قبل الانفجار"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1947-fajja-bus-attacks-150"]={"title":"هجمات حافلات فجة","location":"قرب بتاح تكفا، فلسطين الانتدابية","story":"في 30 نوفمبر 1947، بعد يوم من تصويت الأمم المتحدة على التقسيم، هاجم مسلحون عرب حافلات يهودية، وكانت الهجمات من الوقائع الافتتاحية لمرحلة الحرب الأهلية في صراع 1947–1949.","context":"وقعت الحادثة مباشرة بعد قرار التقسيم وسط تصاعد سريع للعنف بين المجتمعين.","aftermath":"أشارت الهجمات إلى الانتقال نحو صراع مسلح أوسع في فلسطين الانتدابية.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1947-1947-1949-palestine-war-arab-israeli-war-151"]={"title":"حرب فلسطين 1947–1949 / الحرب العربية الإسرائيلية","location":"فلسطين الانتدابية / إسرائيل","story":"اندلع القتال بعد تصويت الأمم المتحدة على التقسيم؛ وبعد إعلان إسرائيل استقلالها في مايو 1948 دخلت جيوش عربية مجاورة الحرب. وتكبد المدنيون والمقاتلون اليهود والعرب خسائر كبيرة وتهجيرًا.","context":"شملت الحرب أولًا حربًا أهلية بين قوات يهودية وعربية ثم تحولت إلى حرب بين دول.","aftermath":"أنشأت الحرب دولة إسرائيل وغيرت الحدود وخلقت أزمات لجوء وتهجير وتركت نزاعات إقليمية وسياسية دون حل.","sourceStatus":"ثقة عالية جدًا؛ السرديات وبعض الأرقام موضع خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1947-un-partition-plan-and-outbreak-of-civil-war-in-mandatory-palestine-152"]={"title":"خطة الأمم المتحدة للتقسيم واندلاع الحرب الأهلية في فلسطين الانتدابية","location":"فلسطين الانتدابية","story":"في 29 نوفمبر 1947 أوصت الجمعية العامة للأمم المتحدة بتقسيم فلسطين إلى دولتين عربية ويهودية مع نظام دولي للقدس. قبل قادة الوكالة اليهودية التقسيم أساسًا لإقامة دولة، ورفضه القادة العرب. وتصاعد القتال بين القوات العربية الفلسطينية واليهودية فورًا تقريبًا.","context":"كان القرار 181 توصية دولية بالتقسيم وأصبح نقطة تحول سياسية وعسكرية.","aftermath":"اتسع العنف بسرعة وقاد إلى حرب 1948 وقيام إسرائيل وتهجير واسع.","sourceStatus":"قرار 181 والتصعيد اللاحق موثقان على نطاق واسع؛ تبقى تفسيرات المسؤولية والنوايا وعدالة الخطة موضع خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-hadassah-medical-convoy-massacre-153"]={"title":"مذبحة قافلة هداسا الطبية","location":"القدس","story":"في أبريل 1948 نصب مسلحون عرب كمينًا لقافلة تقل عاملين طبيين وإمدادات إلى مستشفى هداسا والجامعة العبرية على جبل المشارف؛ وقُتل 78 يهوديًا.","context":"وقعت الحادثة ضمن القتال والحصار حول القدس أثناء مرحلة الحرب الأهلية من صراع 1947–1948.","aftermath":"عمقت المذبحة العنف وأثرت في الخدمات الطبية والوصول إلى جبل المشارف.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-deir-yassin-massacre-154"]={"title":"مذبحة دير ياسين","location":"دير ياسين، قرب القدس","story":"في 9 أبريل 1948 هاجم مقاتلو الإرغون وليحي قرية دير ياسين العربية الفلسطينية. وقُتل أكثر من مئة من سكان القرية، بينهم مدنيون. وأصبحت المذبحة رمزًا رئيسيًا للمعاناة الفلسطينية وأسهمت في الخوف خلال حرب 1948.","context":"كانت الحادثة جزءًا من الحرب الأهلية، ومن الضروري عرضها إلى جانب الهجمات على اليهود ووقائع التهجير الفلسطيني في الفترة نفسها.","aftermath":"ساهمت أخبار المذبحة في الخوف والفرار في أماكن أخرى وظلت مركزية في الذاكرة الفلسطينية.","sourceStatus":"الهجوم وقتل المدنيين موثقان بقوة؛ نوقش العدد الدقيق وبعض تفاصيل المعركة، وتضع الدراسات الحديثة عدد القتلى عادة في حدود 100–110"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-kfar-etzion-massacre-155"]={"title":"مذبحة كفار عتصيون","location":"كفار عتصيون، جنوب القدس","story":"في 13 مايو 1948 سقطت كفار عتصيون أمام الفيلق العربي وقوات عربية محلية بعد قتال طويل. وقُتل عدد كبير من المدافعين والسكان اليهود بعد انهيار الدفاعات ولم ينجُ إلا قليلون. واستسلمت بقية مستوطنات كتلة عتصيون في اليوم التالي.","context":"وقعت الحادثة في المرحلة الأخيرة من الحرب الأهلية عشية انتهاء الانتداب البريطاني.","aftermath":"أصبح سقوط الكتلة رمزًا مهمًا في الذاكرة الإسرائيلية لحرب 1948.","sourceStatus":"سقوط كفار عتصيون والقتل الجماعي موثقان جيدًا؛ تختلف الروايات حول الظروف الدقيقة لبعض الوفيات بعد الاستسلام"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-declaration-of-the-state-of-israel-156"]={"title":"إعلان دولة إسرائيل","location":"تل أبيب","story":"في 14 مايو 1948 أعلن دافيد بن غوريون قيام دولة إسرائيل مع انتهاء الانتداب البريطاني. وحول الإعلان الحرب الأهلية الجارية إلى صراع بين دول عندما دخلت جيوش عربية مجاورة أراضي الانتداب السابق.","context":"كان الحدث نقطة انتقال رئيسية من المجتمع اليهودي المنظم في فلسطين إلى دولة ذات سيادة وسط حرب قائمة.","aftermath":"قامت إسرائيل كدولة واتسعت الحرب فور تدخل الجيوش العربية.","sourceStatus":"الإعلان والتحول العسكري المباشر موثقان بصورة مباشرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-arab-armies-enter-palestine-and-the-first-arab-israeli-war-expands-157"]={"title":"الجيوش العربية تدخل فلسطين وتتسع الحرب العربية الإسرائيلية الأولى","location":"إسرائيل / أراضي فلسطين الانتدابية السابقة","story":"ابتداءً من 15 مايو دخلت جيوش مصر وشرق الأردن وسوريا والعراق ولبنان الحرب بعد إعلان استقلال إسرائيل. وأصبح الصراع يشمل الدولة الإسرائيلية الجديدة والقوات العربية الفلسطينية وعدة دول عربية مجاورة.","context":"كانت للحكومات العربية المختلفة أهداف عسكرية وسياسية متباينة، لذلك لا ينبغي تصوير التدخل كاستراتيجية موحدة بالكامل.","aftermath":"اتسع الصراع إلى حرب بين دول انتهت باتفاقيات الهدنة سنة 1949.","sourceStatus":"تدخل الجيوش العربية المجاورة موثق على نطاق واسع؛ اختلفت الأهداف والحسابات السياسية بين الحكومات"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-fall-of-the-jewish-quarter-of-jerusalem-s-old-city-158"]={"title":"سقوط الحي اليهودي في البلدة القديمة بالقدس","location":"القدس","story":"بعد حصار وقتال استسلم الحي اليهودي في البلدة القديمة للفيلق العربي التابع لشرق الأردن في 28 مايو 1948. وأُجلي السكان اليهود وأصبح المدافعون الناجون أسرى حرب. وتضررت أو دُمرت لاحقًا معابد ومواقع يهودية أخرى خلال الحكم الأردني.","context":"كانت الحادثة جزءًا من الصراع على القدس في حرب 1948.","aftermath":"بقيت البلدة القديمة تحت السيطرة الأردنية حتى 1967 ولم يتمكن سكان الحي اليهود من العودة خلال تلك الفترة.","sourceStatus":"الاستسلام والإجلاء موثقان جيدًا؛ تختلف أوصاف الدمار اللاحق بحسب الموقع والمصدر"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-lydda-and-ramle-fighting-killings-and-palestinian-expulsion-159"]={"title":"اللد والرملة: قتال وقتل وطرد فلسطينيين","location":"اللد والرملة","story":"استولت القوات الإسرائيلية على اللد والرملة في يوليو 1948 خلال عملية داني. وقُتل مدنيون أثناء القتال في اللد، ثم طُرد أو أُجبر معظم السكان العرب الفلسطينيين في المدينتين على الفرار شرقًا. وتبقى الحادثة مركزية في النقاش التاريخي حول أزمة اللاجئين الفلسطينيين.","context":"توضح الحادثة أن العمليات العسكرية الإسرائيلية وتهجير الفلسطينيين جزء ضروري من الصورة الكاملة لحرب 1948.","aftermath":"هُجر عشرات الآلاف من الفلسطينيين وانتقلت المدينتان إلى السيطرة الإسرائيلية.","sourceStatus":"الاستيلاء والتهجير الجماعي موثقان بقوة؛ يناقش المؤرخون جوانب الأوامر وأعداد القتلى والآليات الدقيقة للطرد"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-palestinian-refugee-and-displacement-crisis-160"]={"title":"أزمة اللاجئين والتهجير الفلسطيني","location":"فلسطين / الدول العربية المجاورة","story":"خلال حرب 1947–1949 فر أو طُرد مئات الآلاف من العرب الفلسطينيين من منازلهم في الأراضي التي أصبحت إسرائيل. واختلفت الأسباب بحسب المكان ومرحلة الحرب وشملت الطرد المباشر والفرار من القتال والخوف من الهجوم وانهيار المجتمع الفلسطيني. ومنعت إسرائيل عمومًا معظم اللاجئين من العودة بعد الحرب.","context":"التهجير واسع النطاق غير محل نزاع، لكن الوزن النسبي للأسباب والمسؤولية في مواقع محددة ما يزال موضوعًا رئيسيًا للخلاف التاريخي والسياسي.","aftermath":"أصبحت أزمة اللاجئين إحدى القضايا المركزية والدائمة في الصراع الإسرائيلي الفلسطيني.","sourceStatus":"التهجير واسع النطاق غير محل نزاع؛ يظل توازن الأسباب والمسؤولية في مناطق بعينها من أكثر موضوعات تاريخ الصراع إثارة للجدل"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-assassination-of-un-mediator-folke-bernadotte-161"]={"title":"اغتيال وسيط الأمم المتحدة فولكه برنادوت","location":"القدس","story":"في 17 سبتمبر 1948 اغتال أعضاء من ليحي، وهو تنظيم مسلح يهودي، وسيط الأمم المتحدة الكونت فولكه برنادوت في القدس. وكان قد عُين للتوسط في الحرب العربية الإسرائيلية واقترح ترتيبات للحدود والقدس واللاجئين.","context":"يوثق الحدث عنفًا سياسيًا نفذه تنظيم يهودي ولا يُعرض كحادثة كان اليهود فيها الضحايا.","aftermath":"أثار الاغتيال إدانة دولية وسرّع إجراءات إسرائيلية ضد ليحي.","sourceStatus":"الاغتيال ومسؤولية ليحي موثقان بقوة في سجلات الأمم المتحدة والمصادر التاريخية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1949-1949-armistice-agreements-end-major-fighting-162"]={"title":"اتفاقيات هدنة 1949 تنهي القتال الرئيسي","location":"إسرائيل والدول العربية المجاورة","story":"وقعت إسرائيل اتفاقيات هدنة منفصلة مع مصر ولبنان والأردن وسوريا سنة 1949. وأنهت الاتفاقيات القتال الرئيسي بين الدول لكنها لم تنشئ معاهدات سلام شاملة. وأصبحت خطوط الهدنة الحدود العملية حتى حرب 1967.","context":"أنهت الاتفاقيات المرحلة العسكرية الرئيسية من حرب 1948 دون حل الصراع الأوسع.","aftermath":"ظلت الحدود وقضية اللاجئين ووضع القدس دون حل واستمرت في تشكيل النزاعات اللاحقة.","sourceStatus":"الاتفاقيات وخطوط الهدنة موثقة مباشرة في سجلات الأمم المتحدة"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1951-post-armistice-infiltration-and-border-violence-164"]={"title":"הסתננות ואלימות בגבולות לאחר שביתת הנשק","location":"ישראל וקווי שביתת הנשק הסמוכים","story":"לאחר הסכמי שביתת הנשק של 1949 נותרו גבולות ישראל בלתי יציבים. פליטים פלסטינים ומסתננים אחרים חצו את הקווים מסיבות שונות, ובהן חזרה לבתים קודמים, השבת רכוש, הברחות והתקפות מזוינות. ישראלים נהרגו בחלק מן החדירות, וגם אכיפת הגבול ופעולות תגמול ישראליות הרגו פלסטינים.","context":"הסמן מבחין בין הסתננות פלסטינית והתקפות מזוינות, פעולות תגמול ישראליות, אלימות נגד אזרחים ומתחים בין־מדינתיים, בלי לייחס כל אירוע לגורם יחיד.","aftermath":"התקפות ופעולות תגמול חוזרות הקשיחו את הגבולות, הגבירו את התחרות הצבאית האזורית ותרמו להסלמה לקראת מלחמת סיני ב־1956 ובהמשך מלחמת ששת הימים.","sourceStatus":"דפוס ההסתננות והאלימות בגבול מתועד היטב; המניעים ושיעור המעברים החמושים לעומת הלא־חמושים השתנו מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1953-qibya-raid-165"]={"title":"פעולת קיביה","location":"קיביה, הגדה המערבית הירדנית","story":"ב־14–15 באוקטובר 1953 ביצעו כוחות ישראליים פעולת תגמול בכפר קיביה לאחר התקפות קודמות בתוך ישראל. בתים פוצצו ועשרות אזרחים ערבים פלסטינים נהרגו. מועצת הביטחון של האו״ם גינתה בחריפות את הפעולה.","context":"האירוע היה חלק ממעגל חדירות ופעולות תגמול לאחר 1949.","aftermath":"הפעולה החריפה את המתיחות בגבול ואת הביקורת הבינלאומית על מדיניות התגמול הישראלית.","sourceStatus":"הפשיטה ומות האזרחים מתועדים היטב; החלטה 101 של מועצת הביטחון הגדירה אותה פעולת תגמול של כוחות ישראליים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1954-ma-ale-akrabim-bus-massacre-166"]={"title":"טבח מעלה עקרבים","location":"הנגב, ישראל","story":"חמושים ארבו לאוטובוס נוסעים ישראלי במעלה עקרבים במרץ 1954, הרגו נוסעים והותירו רק מעטים בחיים.","context":"זהו אירוע מזוהה בתוך ההיסטוריה הרחבה של אלימות נגד מטרות יהודיות וישראליות.","aftermath":"הטבח העמיק את תחושת חוסר הביטחון ואת הלחץ לתגובה צבאית בתקופה של מתיחות גבול.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1955-patish-wedding-attack-167"]={"title":"התקפת החתונה בפטיש","location":"פטיש, ישראל","story":"תוקפים השליכו רימונים ופתחו באש על חגיגת חתונה צפופה במרץ 1955, הרגו צעירה ופצעו 18 בני אדם.","context":"האירוע היה התקפה מזוהה על אזרחים בתוך תקופה רחבה של אלימות גבול.","aftermath":"ההתקפה תרמה להסלמת החששות הביטחוניים ולמעגל התגובות באזור הגבול.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1955-gaza-raid-and-escalation-of-israel-egypt-border-conflict-168"]={"title":"פעולת עזה והסלמת הסכסוך בגבול ישראל–מצרים","location":"רצועת עזה","story":"בפברואר 1955 פשטו כוחות ישראליים על מתקן צבאי מצרי בעזה לאחר תקריות גבול מתמשכות. הפעולה הרגה חיילים מצרים וסייעה להאיץ מעגל עימות בין מצרים לישראל. בהמשך הרחיבה מצרים את ארגון ותמיכת פשיטות הפדאיון הפלסטיניות.","context":"האירוע היה חלק ממעגל הגבול שלאחר 1949 שבו חדירות, התקפות ופעולות תגמול הזינו זו את זו.","aftermath":"ההסלמה תרמה למשבר הביטחוני והצבאי שהוביל למלחמת סיני ב־1956.","sourceStatus":"הפשיטה וההסלמה שאחריה מתועדות היטב; היסטוריונים חלוקים לגבי משקלה בין הגורמים לשינוי במדיניות הצבאית המצרית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1956-kfar-chabad-synagogue-attack-169"]={"title":"התקפת בית הכנסת בכפר חב״ד","location":"כפר חב״ד, ישראל","story":"חמושים פתחו באש בבית כנסת שבו שהו ילדים ובני נוער באפריל 1956, הרגו שלושה ילדים ומדריך צעיר ופצעו אחרים.","context":"זהו אירוע מזוהה בתוך תקופה רחבה יותר של אלימות גבול.","aftermath":"ההתקפה העמיקה את תחושת האיום על יישובים אזרחיים בישראל.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1956-ramat-rachel-shooting-170"]={"title":"הירי ברמת רחל","location":"רמת רחל, ישראל","story":"ירי מעמדה ירדנית הרג ארבעה ארכאולוגים ופצע שישה־עשר בני אדם ברמת רחל בספטמבר 1956.","context":"האירוע התרחש בתוך מתיחות מתמשכת לאורך קווי שביתת הנשק.","aftermath":"הירי הוסיף להסלמה האזורית בחודשים שקדמו למלחמת סיני.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1956-suez-crisis-sinai-war-171"]={"title":"משבר סואץ / מלחמת סיני","location":"מצרים / סיני / ישראל","story":"ישראל פלשה לחצי האי סיני בתיאום עם ההתערבות הבריטית־צרפתית לאחר שמצרים הלאימה את תעלת סואץ.","context":"המלחמה שילבה סכסוך ישראלי–מצרי עם מאבק בריטי וצרפתי על תעלת סואץ והשפעה אזורית.","aftermath":"לחץ בינלאומי אילץ את ישראל, בריטניה וצרפת לסגת ושינה את מאזן הכוחות והדיפלומטיה באזור.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1956-fedayeen-raids-and-israeli-reprisals-before-the-sinai-war-172"]={"title":"פשיטות פדאיון ופעולות תגמול ישראליות לפני מלחמת סיני","location":"ישראל, רצועת עזה והגבולות הסמוכים","story":"באמצע שנות ה־1950 ביצעו פדאיון פלסטינים, במיוחד מרצועת עזה שבשליטה מצרית, פשיטות והתקפות בתוך ישראל. ישראל הגיבה בפעולות תגמול צבאיות גדולות יותר ויותר. המעגל הרג אזרחים וחיילים משני הצדדים ותרם למשבר שקדם למלחמת 1956.","context":"הסמן מציג יחד את ההתקפות הפלסטיניות ואת התגובות הצבאיות הישראליות בלי להציג צד אחד בלבד כמקור האלימות.","aftermath":"מעגל הפשיטות והתגמול הקשיח גבולות והגביר את ההסלמה הצבאית בין ישראל למצרים.","sourceStatus":"הדפוס מתועד בהרחבה; אירועים בודדים נבדלו במבצעים, במטרות ובמספרי הנפגעים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1956-kafr-qasim-massacre-173"]={"title":"טבח כפר קאסם","location":"כפר קאסם, ישראל","story":"ב־29 באוקטובר 1956 הרגו שוטרי משמר הגבול הישראלי 48 אזרחים ערבים ישראלים ועובר אחד לאחר שתושבים חזרו לביתם בלי לדעת ששעת העוצר הוקדמה. בתי משפט בישראל הרשיעו בהמשך כמה מאנשי היחידה, והפרשה נעשתה תקדים מרכזי בדין הישראלי בנוגע לפקודה בלתי חוקית בעליל.","context":"האירוע מתעד הרג אזרחים ערבים בידי כוחות ישראליים בתוך תקופת מתיחות ומלחמה.","aftermath":"המשפטים שלאחר הטבח עיצבו עיקרון משפטי ישראלי חשוב בנוגע לחובת חיילים ושוטרים לסרב לפקודה בלתי חוקית בעליל.","sourceStatus":"ההרוגים, נסיבות האירוע והמשפטים הישראליים מתועדים היטב"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1956-coordinated-israeli-british-and-french-attack-on-egypt-174"]={"title":"המתקפה המתואמת של ישראל, בריטניה וצרפת על מצרים","location":"חצי האי סיני ותעלת סואץ","story":"ב־29 באוקטובר 1956 פלשה ישראל לסיני במסגרת תוכנית חשאית שתואמה עם בריטניה וצרפת. לאחר מכן התערבו בריטניה וצרפת סביב תעלת סואץ. לחץ בינלאומי, במיוחד מצד ארצות הברית והאו״ם, אילץ לבסוף את הכוחות התוקפים לסגת.","context":"האירוע מבהיר שמלחמת סיני הייתה גם מבצע מתואם בין שלוש מדינות ולא רק עימות גבול ישראלי–מצרי.","aftermath":"הנסיגה תחת לחץ בינלאומי החלישה את בריטניה וצרפת באזור והשפיעה על ההסדרים הביטחוניים סביב ישראל ומצרים.","sourceStatus":"התיאום החשאי בסוור והרצף הצבאי מתועדים בהרחבה בארכיונים דיפלומטיים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1964-creation-of-the-palestine-liberation-organization-175"]={"title":"הקמת הארגון לשחרור פלסטין","location":"ירושלים / מסגרת הליגה הערבית","story":"הארגון לשחרור פלסטין הוקם ב־1964 כארגון גג פוליטי שטען לייצוג העם הפלסטיני. הקמתו שיקפה התמסדות גוברת של הלאומיות הפלסטינית; ארגונים חמושים כגון פת״ח התפתחו בנפרד ובהמשך נעשו דומיננטיים באש״ף.","context":"הקמת אש״ף הייתה שלב מרכזי בהתפתחות מוסדות פוליטיים פלסטיניים בתוך הסכסוך האזורי.","aftermath":"אש״ף נעשה בהמשך המסגרת הפוליטית הפלסטינית המרכזית ושינה את היחסים בין התנועה הלאומית הפלסטינית למדינות ערב.","sourceStatus":"הקמת אש״ף ב־1964 מתועדת היטב; תוכניתו הפוליטית ויחסיו עם ממשלות ערב השתנו לאורך הזמן"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1965-fatah-begins-armed-operations-against-israel-176"]={"title":"פת״ח מתחיל בפעולות חמושות נגד ישראל","location":"ישראל והמדינות השכנות","story":"פת״ח הכריז בתחילת 1965 על תחילת המאבק המזוין וביצע ניסיונות חבלה וחדירה נגד ישראל. הארגון נעשה בהמשך הפלג הדומיננטי באש״ף.","context":"האירוע מסמן את התרחבות הפעילות הפלסטינית החמושה המאורגנת לפני מלחמת ששת הימים.","aftermath":"פעולות פת״ח והתגובות להן תרמו למתיחות הגבולית והפוליטית באזור.","sourceStatus":"תחילת הפעילות החמושה הפומבית של פת״ח ב־1965 מתועדת היטב; המקורות חלוקים לגבי הצלחת המבצעים הראשונים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1966-samu-raid-177"]={"title":"פעולת סמוע","location":"סמוע, הגדה המערבית הירדנית","story":"בנובמבר 1966 פתחה ישראל בפעולת תגמול גדולה נגד הכפר סמוע לאחר שמוקש הרג חיילים ישראלים. הפעולה הובילה לקרב עם כוחות ירדניים ולהרס נרחב בכפר והחריפה מאוד את המתיחות בין ישראל לירדן לפני מלחמת ששת הימים.","context":"הפעולה הייתה חלק ממעגל התקפות ותגמול אך בלטה בהיקפה ובהשלכותיה הדיפלומטיות.","aftermath":"הפשיטה פגעה ביחסי ישראל–ירדן ותרמה לסביבה האזורית המתוחה שלפני מלחמת 1967.","sourceStatus":"המבצע והקרב מתועדים היטב ברשומות דיפלומטיות וצבאיות; הערכות השפעתו האסטרטגית שונות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1967-six-day-war-178"]={"title":"מלחמת ששת הימים","location":"ישראל / מצרים / ירדן / סוריה","story":"ישראל נלחמה במצרים, ירדן וסוריה ביוני 1967 וכבשה את חצי האי סיני, רצועת עזה, הגדה המערבית, מזרח ירושלים ורמת הגולן.","context":"המלחמה פרצה לאחר תקופה של הסלמה אזורית, גיוס כוחות, סגירת מצרי טיראן ומתיחות בין ישראל למדינות ערב.","aftermath":"המלחמה שינתה באופן דרמטי את השליטה הטריטוריאלית והעמידה מיליוני פלסטינים תחת שליטה ישראלית, והשלכותיה ממשיכות לעצב את הסכסוך.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1967-israeli-occupation-begins-in-the-west-bank-east-jerusalem-and-gaza-179"]={"title":"תחילת השליטה הישראלית בגדה המערבית, מזרח ירושלים ורצועת עזה","location":"הגדה המערבית, מזרח ירושלים ורצועת עזה","story":"ניצחון ישראל במלחמת ששת הימים הביא את הגדה המערבית, מזרח ירושלים ורצועת עזה לשליטה ישראלית, לצד סיני ורמת הגולן. מעמד השטחים והפלסטינים החיים בהם נעשה מרכזי בסכסוך. ישראל סיפחה בהמשך את מזרח ירושלים, מהלך שאינו מוכר בידי רוב מדינות העולם.","context":"הסמן מציב את השליטה הטריטוריאלית והחוויה הפלסטינית לצד מלחמות מדינות ערב והתקפות על ישראלים באותה כרונולוגיה.","aftermath":"השליטה בשטחים שינתה את הסכסוך הישראלי–פלסטיני והפכה את שאלות הגבולות, ההתנחלויות, הביטחון והמדינה הפלסטינית למרכזיות.","sourceStatus":"כיבוש השטחים והשליטה בהם מתועדים היטב; הטענות המשפטיות והפוליטיות לגבי שטחים מסוימים נותרו שנויות במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1967-un-security-council-resolution-242-establishes-land-for-peace-framework-180"]={"title":"החלטה 242 של מועצת הביטחון יוצרת מסגרת של שטחים תמורת שלום","location":"האומות המאוחדות","story":"ב־22 בנובמבר 1967 אימצה מועצת הביטחון פה אחד את החלטה 242. היא קראה לנסיגת כוחות ישראליים משטחים שנכבשו בעימות האחרון, לסיום מצב הלוחמה ולהכרה בריבונותה ובזכותה של כל מדינה באזור לחיות בגבולות בטוחים ומוכרים.","context":"ההחלטה נעשתה בסיס מרכזי לדיפלומטיה הערבית–ישראלית שלאחר מלחמת ששת הימים.","aftermath":"עקרונות ההחלטה השפיעו על משאים ומתנים והסכמי שלום מאוחרים, בעוד ניסוח סעיף הנסיגה המשיך לעורר מחלוקת פרשנית.","sourceStatus":"נוסח ההחלטה מתועד ישירות; הבדלים בפרשנות לשפת הנסיגה נעשו מחלוקת דיפלומטית מתמשכת"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1951-post-armistice-infiltration-and-border-violence-164"]={"title":"التسلل والعنف الحدودي بعد الهدنة","location":"إسرائيل وخطوط الهدنة المجاورة","story":"بعد اتفاقيات هدنة 1949 ظلت حدود إسرائيل غير مستقرة. وعبر لاجئون فلسطينيون ومتسللون آخرون خطوط الهدنة لأسباب متنوعة منها العودة إلى منازل سابقة واستعادة الممتلكات والتهريب والهجمات المسلحة. وقُتل إسرائيليون في بعض عمليات التسلل، كما قتلت إجراءات الحدود وعمليات الانتقام الإسرائيلية فلسطينيين.","context":"يميز هذا المؤشر بين التسلل والهجمات الفلسطينية المسلحة والعمليات الانتقامية الإسرائيلية والعنف ضد المدنيين والتوترات بين الدول بدل إرجاع كل حادثة إلى سبب واحد.","aftermath":"شددت الهجمات والعمليات الانتقامية المتكررة الحدود وزادت المنافسة العسكرية الإقليمية وأسهمت في التصعيد نحو حرب سيناء سنة 1956 ثم حرب الأيام الستة.","sourceStatus":"نمط التسلل والعنف الحدودي موثق جيدًا؛ اختلفت الدوافع ونسبة العبور المسلح وغير المسلح بدرجة كبيرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1953-qibya-raid-165"]={"title":"غارة قبية","location":"قبية، الضفة الغربية الأردنية","story":"في 14–15 أكتوبر 1953 نفذت قوات إسرائيلية غارة انتقامية على قرية قبية بعد هجمات سابقة داخل إسرائيل. وهُدمت منازل وقُتل عشرات المدنيين العرب الفلسطينيين. وأدان مجلس الأمن العملية بشدة.","context":"كانت الحادثة جزءًا من دورة التسلل والعمليات الانتقامية بعد 1949.","aftermath":"فاقمت العملية توتر الحدود والانتقاد الدولي لسياسة الانتقام الإسرائيلية.","sourceStatus":"الغارة ومقتل المدنيين موثقان بقوة؛ وصف قرار مجلس الأمن 101 العملية بأنها عمل انتقامي نفذته قوات مسلحة إسرائيلية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1954-ma-ale-akrabim-bus-massacre-166"]={"title":"مذبحة حافلة معاليه عكربيم","location":"النقب، إسرائيل","story":"نصب مسلحون كمينًا لحافلة ركاب إسرائيلية في معاليه عكربيم في مارس 1954 وقتلوا ركابًا ولم يتركوا إلا عددًا قليلًا من الناجين.","context":"هذه واقعة محددة ضمن التاريخ الأوسع للعنف ضد أهداف يهودية وإسرائيلية.","aftermath":"عمقت المذبحة الشعور بانعدام الأمن والضغط من أجل رد عسكري خلال فترة توتر حدودي.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1955-patish-wedding-attack-167"]={"title":"هجوم حفل زفاف باتيش","location":"باتيش، إسرائيل","story":"ألقى مهاجمون قنابل يدوية وفتحوا النار على حفل زفاف مزدحم في مارس 1955، فقتلوا شابة وجرحوا 18 شخصًا.","context":"كانت الحادثة هجومًا محددًا على مدنيين ضمن فترة أوسع من العنف الحدودي.","aftermath":"ساهم الهجوم في تصاعد المخاوف الأمنية ودورة الردود على الحدود.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1955-gaza-raid-and-escalation-of-israel-egypt-border-conflict-168"]={"title":"غارة غزة وتصاعد صراع الحدود بين إسرائيل ومصر","location":"قطاع غزة","story":"في فبراير 1955 أغارت قوات إسرائيلية على منشأة عسكرية مصرية في غزة بعد حوادث حدودية متواصلة. وقتلت العملية جنودًا مصريين وساعدت في تسريع دورة المواجهة بين مصر وإسرائيل. ثم وسعت مصر تنظيم ودعم غارات الفدائيين الفلسطينيين.","context":"كانت الحادثة جزءًا من دورة ما بعد 1949 التي غذت فيها عمليات التسلل والهجمات والانتقام بعضها بعضًا.","aftermath":"ساهم التصعيد في الأزمة الأمنية والعسكرية التي قادت إلى حرب سيناء سنة 1956.","sourceStatus":"الغارة والتصعيد اللاحق موثقان جيدًا؛ يختلف المؤرخون في وزن الغارة بين أسباب تغير السياسة العسكرية المصرية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1956-kfar-chabad-synagogue-attack-169"]={"title":"هجوم كنيس كفار حباد","location":"كفار حباد، إسرائيل","story":"فتح مسلحون النار على كنيس كان فيه أطفال ومراهقون في أبريل 1956، فقتلوا ثلاثة أطفال ومرشدًا شابًا وأصابوا آخرين.","context":"هذه واقعة محددة ضمن فترة أوسع من العنف الحدودي.","aftermath":"عمق الهجوم الشعور بالتهديد للمجتمعات المدنية الإسرائيلية.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1956-ramat-rachel-shooting-170"]={"title":"إطلاق النار في رمات راحيل","location":"رمات راحيل، إسرائيل","story":"أدى إطلاق نار من موقع أردني إلى مقتل أربعة علماء آثار وجرح ستة عشر شخصًا في رمات راحيل في سبتمبر 1956.","context":"وقعت الحادثة وسط توتر مستمر على خطوط الهدنة.","aftermath":"أضاف إطلاق النار إلى التصعيد الإقليمي في الأشهر السابقة لحرب سيناء.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1956-suez-crisis-sinai-war-171"]={"title":"أزمة السويس / حرب سيناء","location":"مصر / سيناء / إسرائيل","story":"غزت إسرائيل شبه جزيرة سيناء بالتنسيق مع التدخل البريطاني الفرنسي بعد تأميم مصر لقناة السويس.","context":"جمعت الحرب بين الصراع الإسرائيلي المصري وصراع بريطانيا وفرنسا على قناة السويس والنفوذ الإقليمي.","aftermath":"أجبر الضغط الدولي إسرائيل وبريطانيا وفرنسا على الانسحاب وغير ميزان القوى والدبلوماسية الإقليمية.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1956-fedayeen-raids-and-israeli-reprisals-before-the-sinai-war-172"]={"title":"غارات الفدائيين والعمليات الانتقامية الإسرائيلية قبل حرب سيناء","location":"إسرائيل وقطاع غزة والحدود المجاورة","story":"في منتصف الخمسينيات نفذ فدائيون فلسطينيون، خصوصًا من غزة الخاضعة لمصر، غارات وهجمات داخل إسرائيل. وردت إسرائيل بعمليات انتقامية عسكرية متزايدة الحجم. وقتلت الدورة مدنيين وجنودًا من الجانبين وأسهمت في الأزمة السابقة لحرب 1956.","context":"يعرض المؤشر الهجمات الفلسطينية والردود العسكرية الإسرائيلية معًا بدل تقديم طرف واحد فقط كمصدر للعنف.","aftermath":"شددت دورة الغارات والانتقام الحدود وزادت التصعيد العسكري بين إسرائيل ومصر.","sourceStatus":"الدورة موثقة على نطاق واسع؛ اختلفت الحوادث الفردية في المنفذين والأهداف والضحايا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1956-kafr-qasim-massacre-173"]={"title":"مذبحة كفر قاسم","location":"كفر قاسم، إسرائيل","story":"في 29 أكتوبر 1956 قتل أفراد من حرس الحدود الإسرائيلي 48 مواطنًا عربيًا إسرائيليًا وجنينًا واحدًا بعد عودة القرويين إلى منازلهم دون علمهم بتقديم موعد حظر التجول. وأدانت محاكم إسرائيلية لاحقًا عدة أفراد من الوحدة، وأصبحت القضية سابقة في القانون الإسرائيلي بشأن الأوامر غير القانونية بشكل واضح.","context":"يوثق الحدث قتل مدنيين عرب على يد قوات إسرائيلية في فترة توتر وحرب.","aftermath":"شكلت المحاكمات اللاحقة مبدأ قانونيًا إسرائيليًا مهمًا بشأن واجب الجنود والشرطة رفض أمر غير قانوني بشكل واضح.","sourceStatus":"عمليات القتل والضحايا والمحاكمات الإسرائيلية اللاحقة موثقة بقوة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1956-coordinated-israeli-british-and-french-attack-on-egypt-174"]={"title":"الهجوم الإسرائيلي البريطاني الفرنسي المنسق على مصر","location":"شبه جزيرة سيناء وقناة السويس","story":"في 29 أكتوبر 1956 غزت إسرائيل سيناء بموجب خطة سرية منسقة مع بريطانيا وفرنسا. ثم تدخلت بريطانيا وفرنسا حول قناة السويس. وأجبر الضغط الدولي، خصوصًا من الولايات المتحدة والأمم المتحدة، القوى المهاجمة في النهاية على الانسحاب.","context":"يوضح الحدث أن حرب سيناء كانت أيضًا عملية منسقة بين ثلاث دول وليست مجرد نزاع حدودي إسرائيلي مصري.","aftermath":"أضعف الانسحاب تحت الضغط الدولي بريطانيا وفرنسا إقليميًا وأثر في الترتيبات الأمنية بين إسرائيل ومصر.","sourceStatus":"تنسيق سيفر السري والتسلسل العسكري موثقان على نطاق واسع في الأرشيفات الدبلوماسية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1964-creation-of-the-palestine-liberation-organization-175"]={"title":"إنشاء منظمة التحرير الفلسطينية","location":"القدس / إطار جامعة الدول العربية","story":"أُنشئت منظمة التحرير الفلسطينية سنة 1964 كمنظمة سياسية جامعة تدعي تمثيل الشعب الفلسطيني. وعكس تأسيسها تزايد مؤسسات القومية الفلسطينية؛ وتطورت منظمات مسلحة مثل فتح بصورة منفصلة ثم أصبحت مهيمنة داخل المنظمة.","context":"كان إنشاء منظمة التحرير مرحلة مركزية في تطور المؤسسات السياسية الفلسطينية ضمن الصراع الإقليمي.","aftermath":"أصبحت المنظمة لاحقًا الإطار السياسي الفلسطيني الرئيسي وغيرت العلاقة بين الحركة الوطنية الفلسطينية والدول العربية.","sourceStatus":"إنشاء المنظمة سنة 1964 موثق بقوة؛ تغير برنامجها السياسي وعلاقتها بالحكومات العربية مع الزمن"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1965-fatah-begins-armed-operations-against-israel-176"]={"title":"فتح تبدأ عمليات مسلحة ضد إسرائيل","location":"إسرائيل والدول المجاورة","story":"أعلنت فتح بداية كفاحها المسلح في مطلع 1965 ونفذت محاولات تخريب وتسلل ضد إسرائيل. وأصبحت لاحقًا الفصيل المهيمن في منظمة التحرير الفلسطينية.","context":"تمثل الحادثة توسع النشاط الفلسطيني المسلح المنظم قبل حرب الأيام الستة.","aftermath":"ساهمت عمليات فتح والردود عليها في توتر الحدود والسياسة الإقليمية.","sourceStatus":"الإطلاق العلني للعمليات المسلحة سنة 1965 موثق جيدًا؛ تختلف الروايات حول النجاح العملياتي للهجمات الأولى"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1966-samu-raid-177"]={"title":"غارة السموع","location":"السموع، الضفة الغربية الأردنية","story":"في نوفمبر 1966 شنت إسرائيل غارة انتقامية كبيرة على قرية السموع بعد حادث لغم قتل جنودًا إسرائيليين. وأدت الغارة إلى قتال مع القوات الأردنية ودمار كبير في القرية وفاقمت بشدة التوتر الإسرائيلي الأردني قبل حرب الأيام الستة.","context":"كانت العملية جزءًا من دورة الهجمات والانتقام لكنها برزت بحجمها وعواقبها الدبلوماسية.","aftermath":"أضرت الغارة بالعلاقات الإسرائيلية الأردنية وأسهمت في البيئة الإقليمية المتوترة قبل حرب 1967.","sourceStatus":"العملية والمعركة موثقتان جيدًا في السجلات الدبلوماسية والعسكرية؛ تختلف تقديرات أثرها الاستراتيجي"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1967-six-day-war-178"]={"title":"حرب الأيام الستة","location":"إسرائيل / مصر / الأردن / سوريا","story":"حاربت إسرائيل مصر والأردن وسوريا في يونيو 1967 واستولت على سيناء وقطاع غزة والضفة الغربية والقدس الشرقية وهضبة الجولان.","context":"اندلعت الحرب بعد فترة من التصعيد الإقليمي وحشد القوات وإغلاق مضائق تيران والتوتر بين إسرائيل والدول العربية.","aftermath":"غيرت الحرب السيطرة الإقليمية بصورة جذرية ووضعت ملايين الفلسطينيين تحت السيطرة الإسرائيلية، ولا تزال آثارها تشكل الصراع.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1967-israeli-occupation-begins-in-the-west-bank-east-jerusalem-and-gaza-179"]={"title":"بدء السيطرة الإسرائيلية على الضفة الغربية والقدس الشرقية وغزة","location":"الضفة الغربية والقدس الشرقية وقطاع غزة","story":"أدى انتصار إسرائيل في حرب الأيام الستة إلى وضع الضفة الغربية والقدس الشرقية وقطاع غزة تحت السيطرة الإسرائيلية، إلى جانب سيناء والجولان. وأصبح وضع هذه الأراضي والفلسطينيين فيها محوريًا في الصراع. وضمت إسرائيل القدس الشرقية لاحقًا، وهي خطوة لا تعترف بها معظم دول العالم.","context":"يضع المؤشر السيطرة الإقليمية والتجربة الفلسطينية إلى جانب حروب الدول العربية والهجمات على الإسرائيليين ضمن التسلسل نفسه.","aftermath":"غيرت السيطرة على الأراضي الصراع الإسرائيلي الفلسطيني وجعلت الحدود والمستوطنات والأمن والدولة الفلسطينية قضايا مركزية.","sourceStatus":"الاستيلاء والسيطرة اللاحقة موثقان بقوة؛ تبقى المطالب القانونية والسياسية بشأن أراض معينة موضع نزاع"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1967-un-security-council-resolution-242-establishes-land-for-peace-framework-180"]={"title":"قرار مجلس الأمن 242 يؤسس إطار الأرض مقابل السلام","location":"الأمم المتحدة","story":"في 22 نوفمبر 1967 اعتمد مجلس الأمن بالإجماع القرار 242. ودعا إلى انسحاب القوات الإسرائيلية من أراضٍ احتُلت في النزاع الأخير، وإنهاء حالة الحرب، والاعتراف بسيادة كل دولة في المنطقة وحقها في العيش ضمن حدود آمنة ومعترف بها.","context":"أصبح القرار أساسًا رئيسيًا للدبلوماسية العربية الإسرائيلية بعد حرب الأيام الستة.","aftermath":"أثرت مبادئه في مفاوضات ومعاهدات سلام لاحقة، بينما ظل تفسير صياغة الانسحاب موضع خلاف.","sourceStatus":"نص القرار موثق مباشرة؛ أصبحت الاختلافات حول تفسير لغة الانسحاب نزاعًا دبلوماسيًا دائمًا"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1968-el-al-flight-253-attack-in-athens-181"]={"title":"התקפה על טיסת אל על 253 באתונה","location":"אתונה, יוון","story":"חמושים פלסטינים תקפו מטוס אל על בנמל התעופה באתונה בדצמבר 1968, הרגו נוסע ישראלי ופצעו אחרים.","context":"זהו אירוע מזוהה בתוך ההיסטוריה הרחבה של אלימות נגד מטרות יהודיות או ישראליות.","aftermath":"ההתקפה הייתה חלק מהתרחבות הפעילות הפלסטינית החמושה לזירה הבינלאומית.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1968-battle-of-karameh-182"]={"title":"קרב כראמה","location":"כראמה, ירדן","story":"כוחות ישראליים תקפו בסיסי גרילה פלסטיניים באזור כראמה לאחר סדרת התקפות פת״ח, ובהן פיצוץ מוקש שהרג ישראלים. כוחות ירדניים ולוחמים פלסטינים התנגדו לפשיטה. ישראל גרמה אבדות אך גם ספגה אבדות משמעותיות, ופת״ח הציג את הקרב כניצחון פוליטי וסמלי.","context":"הסמן מציב יחד פעילות פלסטינית חמושה, פעולה צבאית ישראלית והתערבות צבא ירדן, בלי לצמצם את האירוע לנרטיב של צד אחד.","aftermath":"הקרב חיזק את מעמד פת״ח בעולם הערבי אך גם החריף את המתיחות בין הארגונים הפלסטיניים לממלכה הירדנית.","sourceStatus":"הקרב מתועד היטב; נרטיבים ישראליים, ירדניים ופלסטיניים מדגישים תוצאות צבאיות ופוליטיות שונות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1969-war-of-attrition-along-the-suez-canal-183"]={"title":"מלחמת ההתשה לאורך תעלת סואץ","location":"תעלת סואץ / חזית סיני","story":"מצרים וישראל ניהלו מלחמת התשה הולכת ומחריפה לאחר מלחמת ששת הימים. חילופי ארטילריה, תקיפות אוויריות ופעולות קומנדו גרמו לאבדות צבאיות ואזרחיות. כוח אדם וציוד סובייטיים נעשו מעורבים יותר לצד מצרים לפני כניסת הפסקת אש בתמיכת ארצות הברית לתוקף ב־1970.","context":"העימות היה המשך ישיר של הסכסוך על תוצאות 1967 ושל הניסיון המצרי לשנות את המצב לאורך תעלת סואץ.","aftermath":"הפסקת האש סיימה את הלחימה הישירה בשלב זה, אך הסוגיות הטריטוריאליות והצבאיות נותרו והובילו בהמשך למלחמת 1973.","sourceStatus":"העימות ומעורבות המעצמות מתועדים בהרחבה ברשומות דיפלומטיות וצבאיות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1970-avivim-school-bus-massacre-184"]={"title":"טבח אוטובוס ילדי אביבים","location":"אביבים, ישראל","story":"חמושים ירו על אוטובוס בית ספר ישראלי סמוך לגבול לבנון במאי 1970, הרגו ילדים ומבוגרים ופצעו אחרים.","context":"זהו אירוע מזוהה של תקיפה נגד אזרחים ישראלים בתוך הסכסוך הרחב.","aftermath":"הטבח החריף את המתיחות בגבול ישראל–לבנון ואת החשש מפני חדירות והתקפות על אזרחים.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1970-black-september-conflict-in-jordan-185"]={"title":"עימות ספטמבר השחור בירדן","location":"ירדן","story":"המתיחות בין המלוכה הירדנית לארגונים הפלסטיניים החמושים התפתחה ללחימה רחבה בספטמבר 1970. כוחות ירדן פעלו נגד ארגוני אש״ף, נגרמו אבדות כבדות ולבסוף נדחקה הנוכחות החמושה העיקרית של אש״ף מירדן ללבנון.","context":"האירוע היה עימות בין המדינה הירדנית לארגונים הפלסטיניים ולא עימות ישראלי–פלסטיני ישיר.","aftermath":"העברת מרכז הכובד של אש״ף ללבנון השפיעה עמוקות על הפוליטיקה והאלימות בלבנון בשנות ה־1970 וה־1980.","sourceStatus":"העימות וגירוש אש״ף מירדן מתועדים היטב; אומדני הנפגעים משתנים במידה רבה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1972-lod-airport-massacre-186"]={"title":"טבח נמל התעופה לוד","location":"נמל התעופה לוד, ישראל","story":"חמושים מן הצבא האדום היפני, שפעלו עם ארגון פלסטיני חמוש, תקפו נוסעים בנמל התעופה לוד במאי 1972.","context":"האירוע היה חלק מהתרחבות הטרור והפעילות החמושה הפלסטינית ובעלות בריתה לזירה הבינלאומית.","aftermath":"הטבח הגביר את הדגש הישראלי והבינלאומי על אבטחת תעופה ומאבק בטרור.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1972-munich-olympics-attack-187"]={"title":"התקפת אולימפיאדת מינכן","location":"מינכן, מערב גרמניה","story":"חברי ארגון ספטמבר השחור לקחו בני ערובה ממשלחת ישראל לאולימפיאדה; אחד־עשר ספורטאים ומאמנים ישראלים נהרגו במהלך ההתקפה וניסיון החילוץ הכושל.","context":"האירוע היה מתקפת טרור בינלאומית נגד המשלחת האולימפית הישראלית.","aftermath":"הטבח הוביל לשינויים נרחבים באבטחת אירועי ספורט ולפעולות ישראליות נגד גורמים שנקשרו לארגון.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1973-yom-kippur-october-war-188"]={"title":"מלחמת יום הכיפורים / מלחמת אוקטובר","location":"ישראל / מצרים / סוריה","story":"מצרים וסוריה פתחו במתקפת פתע על עמדות ישראליות ב־6 באוקטובר 1973 ופתחו מלחמה אזורית גדולה.","context":"המלחמה נבעה במידה רבה מן הקיפאון שלאחר 1967 וממאמצי מצרים וסוריה להשיב שטחים שאיבדו במלחמת ששת הימים.","aftermath":"המלחמה גרמה לאבדות כבדות, זעזעה את הפוליטיקה הישראלית והאזורית וסייעה לפתוח מסלול דיפלומטי שהוביל בהמשך להסכם השלום בין מצרים לישראל.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1973-israel-crosses-the-suez-canal-and-encircles-egypt-s-third-army-189"]={"title":"ישראל חוצה את תעלת סואץ ומכתרת את הארמייה השלישית של מצרים","location":"מצרים / תעלת סואץ","story":"בשלב המאוחר של מלחמת אוקטובר 1973 חצו כוחות ישראליים לגדה המערבית של תעלת סואץ וכיתרו את הארמייה השלישית המצרית. המהפך בשדה הקרב החריף את הדיפלומטיה האמריקאית–סובייטית וסייע לדחוף להפסקת אש.","context":"האירוע היה שלב מכריע במלחמה לאחר ההצלחות המצריות הראשונות במעבר התעלה.","aftermath":"הכיתור והלחץ הבינלאומי תרמו להסדרי הפסקת האש ולהמשך הדיפלומטיה בין מצרים לישראל.","sourceStatus":"החצייה והכיתור מתועדים היטב ברשומות צבאיות ודיפלומטיות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1974-kiryat-shmona-massacre-190"]={"title":"טבח קריית שמונה","location":"קריית שמונה, ישראל","story":"חמושים פלסטינים חדרו לקריית שמונה באפריל 1974 ורצחו אזרחים, ובהם ילדים.","context":"זהו אירוע מזוהה של אלימות נגד אזרחים ישראלים בתוך תקופה רחבה יותר של עימות.","aftermath":"הטבח הגביר את הלחץ הביטחוני בגבול הצפון ואת התגובה הישראלית לפעילות חמושה מלבנון.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1974-ma-alot-massacre-191"]={"title":"טבח מעלות","location":"מעלות, ישראל","story":"שלושה חמושים פלסטינים תפסו תלמידי בית ספר ובני ערובה נוספים במאי 1974. במהלך ניסיון החילוץ ירו התוקפים בילדים והשליכו רימונים; בני ערובה רבים נהרגו.","context":"האירוע היה מתקפה מכוונת על בני ערובה אזרחיים והפך לאחד מאירועי הטרור הבולטים בישראל בשנות ה־1970.","aftermath":"הטבח השפיע על מדיניות הביטחון והתגובה הישראלית לאירועי בני ערובה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1975-savoy-hotel-attack-192"]={"title":"התקפת מלון סבוי","location":"תל אביב, ישראל","story":"חמושי פת״ח השתלטו על מלון סבוי במרץ 1975. שמונה בני ערובה ושלושה חיילים ישראלים נהרגו במהלך האירוע ופעולת החילוץ.","context":"האירוע היה פעולת טרור ובני ערובה בתוך המאבק הפלסטיני החמוש נגד ישראל.","aftermath":"ההתקפה חיזקה את הדגש הישראלי על תגובה מהירה לאירועי חדירה ובני ערובה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1976-entebbe-hijacking-and-hostage-crisis-193"]={"title":"חטיפת אנטבה ומשבר בני הערובה","location":"אנטבה, אוגנדה","story":"חמושים הקשורים לחזית העממית לשחרור פלסטין וחמושים גרמנים חטפו מטוס אייר פראנס והסיטו אותו לאנטבה. נוסעים ישראלים ויהודים הופרדו מרבים מבני הערובה האחרים לפני מבצע חילוץ של קומנדו ישראלי.","context":"האירוע שילב חטיפת מטוס בינלאומית, הפרדה של בני ערובה יהודים וישראלים ומבצע חילוץ ישראלי במדינה זרה.","aftermath":"רוב בני הערובה חולצו במבצע הישראלי, שהפך לאחד ממבצעי החילוץ הידועים בעולם.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1978-coastal-road-massacre-194"]={"title":"טבח כביש החוף","location":"ישראל","story":"חמושים פלסטינים תקפו אזרחים שנסעו בכביש החוף בישראל, הרגו עשרות והובילו לתגובה צבאית ישראלית גדולה בלבנון.","context":"הטבח היה מתקפה על אזרחים והתרחש בתוך הסלמה של פעילות אש״ף מלבנון ותגובות ישראליות.","aftermath":"ישראל פתחה לאחר מכן במבצע ליטני בדרום לבנון, והעימות בגבול הצפון העמיק.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1978-camp-david-accords-195"]={"title":"הסכמי קמפ דייוויד","location":"קמפ דייוויד, מרילנד, ארצות הברית","story":"נשיא מצרים אנואר סאדאת וראש ממשלת ישראל מנחם בגין, בתיווך נשיא ארצות הברית ג'ימי קרטר, הגיעו להסכמי קמפ דייוויד בספטמבר 1978. ההסכמים יצרו מסגרת להסכם שלום מצרי–ישראלי ולמשא ומתן על ממשל עצמי פלסטיני.","context":"ההסכמים סימנו מעבר משמעותי ממלחמה ישירה בין מצרים לישראל למסלול של משא ומתן מדיני.","aftermath":"הם הובילו להסכם השלום של 1979, בעוד מסגרת האוטונומיה הפלסטינית לא יושמה כפי שתוכננה במקור.","sourceStatus":"ההסכמים מתועדים ישירות; סעיפי האוטונומיה הפלסטינית לא יושמו כפי שנחזו במקור"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1979-egypt-israel-peace-treaty-196"]={"title":"הסכם השלום בין מצרים לישראל","location":"וושינגטון הבירה / מצרים וישראל","story":"מצרים וישראל חתמו על הסכם שלום ב־26 במרץ 1979. ישראל הסכימה לסגת מחצי האי סיני, ומצרים נעשתה המדינה הערבית הראשונה שהכירה רשמית בישראל. ההסכם שינה באופן יסודי את המאזן האסטרטגי של הסכסוך הערבי–ישראלי.","context":"ההסכם היה תוצאה של תהליך מדיני שהחל לאחר מלחמת 1973 והתקדם דרך קמפ דייוויד.","aftermath":"הנסיגה הישראלית מסיני בוצעה בשלבים והשלום בין שתי המדינות נעשה עוגן מרכזי בסדר האזורי.","sourceStatus":"ההסכם והנסיגה הישראלית המדורגת מסיני מתועדים ישירות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1980-paris-synagogue-bombing-197"]={"title":"הפיגוע בבית הכנסת בפריז","location":"פריז, צרפת","story":"מטען חבלה התפוצץ מחוץ לבית הכנסת ברחוב קופרניק בפריז באוקטובר 1980, הרג ארבעה בני אדם ופצע עשרות.","context":"זהו אירוע מזוהה של אלימות נגד יעד יהודי מחוץ לישראל.","aftermath":"הפיגוע עורר זעזוע בצרפת והגביר את תשומת הלב לאנטישמיות ולטרור נגד מוסדות יהודיים באירופה.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1982-1982-lebanon-war-198"]={"title":"מלחמת לבנון 1982","location":"לבנון / ישראל","story":"ישראל פלשה ללבנון על רקע העימות עם אש״ף והתקפות חוצות גבול. במלחמה השתתפו כוחות ישראליים, פלסטיניים, לבנוניים וסוריים והיא גרמה סבל נרחב לאזרחים.","context":"המלחמה התרחשה בתוך מלחמת האזרחים בלבנון והסכסוך הישראלי–פלסטיני והייתה מורכבת ממספר רב של צדדים ומטרות.","aftermath":"המלחמה הובילה לפינוי אש״ף מביירות, להמשך נוכחות ישראלית בלבנון ולהשלכות ארוכות טווח על הפוליטיקה והביטחון באזור.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1982-great-synagogue-of-rome-attack-199"]={"title":"ההתקפה על בית הכנסת הגדול ברומא","location":"רומא, איטליה","story":"חמושים תקפו מתפללים שיצאו מבית הכנסת הגדול ברומא באוקטובר 1982, הרגו ילד בן שנתיים ופצעו עשרות.","context":"זהו אירוע מזוהה של אלימות נגד קהילה יהודית מחוץ לישראל.","aftermath":"ההתקפה הגבירה את החשש מפני טרור אנטי־יהודי באירופה ואת אמצעי האבטחה סביב מוסדות יהודיים.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1982-siege-of-beirut-and-plo-evacuation-200"]={"title":"המצור על ביירות ופינוי אש״ף","location":"ביירות, לבנון","story":"במהלך פלישת ישראל ללבנון ב־1982 כיתרו כוחות ישראליים את מערב ביירות, שבה התבסס אש״ף. הפגזות ולחימה כבדות גרמו לאבדות צבאיות ואזרחיות. הסדר בתיווך אמריקאי הוביל לבסוף לפינוי לוחמי אש״ף מביירות למספר מדינות ערביות.","context":"המצור היה שלב מרכזי במלחמת לבנון וכלל לחימה באזור עירוני מאוכלס בצפיפות.","aftermath":"פינוי אש״ף שינה את מרכז פעילותו האזורי אך לא סיים את הסכסוך בלבנון או בין ישראל לפלסטינים.","sourceStatus":"המצור ופינוי אש״ף מתועדים בהרחבה; אומדני הנפגעים והערכות המידתיות נותרו שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1982-sabra-and-shatila-massacre-201"]={"title":"טבח סברה ושתילה","location":"ביירות, לבנון","story":"בספטמבר 1982 נכנסו אנשי מיליציית הפלנגות הנוצרית הלבנונית למחנות הפליטים סברה ושתילה וטבחו באזרחים פלסטינים ולבנונים בזמן שכוחות ישראליים שלטו באזור הסובב. ועדת כהן הישראלית קבעה בהמשך כי בכירים ישראלים נשאו באחריות עקיפה משום שלא צפו ולא מנעו את סכנת הטבח.","context":"האירוע מתעד טבח שביצעה מיליציה לבנונית ואת שאלת האחריות הישראלית הנובעת משליטתה הצבאית בסביבה.","aftermath":"הטבח עורר מחאה רחבה בישראל ובעולם והוביל למסקנות אישיות ומוסדיות של ועדת כהן.","sourceStatus":"הטבח בידי כוחות הפלנגות הלבנוניים מתועד היטב. אומדני הקורבנות משתנים. ועדת כהן קבעה אחריות עקיפה, לא אחריות כמבצעים ישירים, של בכירים ישראלים"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1968-el-al-flight-253-attack-in-athens-181"]={"title":"هجوم رحلة إل عال 253 في أثينا","location":"أثينا، اليونان","story":"هاجم مسلحون فلسطينيون طائرة إل عال في مطار أثينا في ديسمبر 1968، فقتلوا راكبًا إسرائيليًا وأصابوا آخرين.","context":"هذه حادثة محددة ضمن التاريخ الأوسع للعنف ضد أهداف يهودية أو إسرائيلية.","aftermath":"كان الهجوم جزءًا من توسع النشاط الفلسطيني المسلح إلى الساحة الدولية.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1968-battle-of-karameh-182"]={"title":"معركة الكرامة","location":"الكرامة، الأردن","story":"هاجمت القوات الإسرائيلية قواعد للمقاتلين الفلسطينيين حول الكرامة بعد سلسلة من هجمات فتح، منها انفجار لغم قتل إسرائيليين. وقاومت القوات الأردنية والمقاتلون الفلسطينيون الغارة. أوقعت إسرائيل خسائر لكنها تكبدت أيضًا خسائر مهمة، وقدمت فتح المعركة كنصر سياسي ورمزي.","context":"يضع المؤشر النشاط الفلسطيني المسلح والعمل العسكري الإسرائيلي وتدخل الجيش الأردني في تسلسل واحد دون اختزال الحدث في رواية طرف واحد.","aftermath":"عززت المعركة مكانة فتح في العالم العربي لكنها زادت أيضًا التوتر بين التنظيمات الفلسطينية والملكية الأردنية.","sourceStatus":"المعركة موثقة جيدًا؛ تركز الروايات الإسرائيلية والأردنية والفلسطينية على نتائج عسكرية وسياسية مختلفة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1969-war-of-attrition-along-the-suez-canal-183"]={"title":"حرب الاستنزاف على طول قناة السويس","location":"قناة السويس / جبهة سيناء","story":"خاضت مصر وإسرائيل حرب استنزاف متصاعدة بعد حرب الأيام الستة. وأدت المدفعية والغارات الجوية وعمليات الكوماندوز إلى خسائر عسكرية ومدنية. وازداد تدخل الأفراد والمعدات السوفيتية إلى جانب مصر قبل دخول وقف إطلاق نار بدعم أمريكي حيز التنفيذ سنة 1970.","context":"كان الصراع استمرارًا مباشرًا للخلاف على نتائج 1967 ولمحاولة مصر تغيير الوضع على قناة السويس.","aftermath":"أنهى وقف النار القتال المباشر في هذه المرحلة، لكن القضايا الإقليمية والعسكرية بقيت وقادت لاحقًا إلى حرب 1973.","sourceStatus":"الصراع وتدخل القوى الكبرى موثقان على نطاق واسع في السجلات الدبلوماسية والعسكرية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1970-avivim-school-bus-massacre-184"]={"title":"مذبحة حافلة مدرسة أفيفيم","location":"أفيفيم، إسرائيل","story":"أطلق مسلحون النار على حافلة مدرسية إسرائيلية قرب الحدود اللبنانية في مايو 1970، فقتلوا أطفالًا وبالغين وأصابوا آخرين.","context":"هذه حادثة محددة لهجوم على مدنيين إسرائيليين ضمن الصراع الأوسع.","aftermath":"فاقمت المذبحة التوتر على الحدود الإسرائيلية اللبنانية والمخاوف من التسلل والهجمات على المدنيين.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1970-black-september-conflict-in-jordan-185"]={"title":"صراع أيلول الأسود في الأردن","location":"الأردن","story":"انفجرت التوترات بين الملكية الأردنية والتنظيمات الفلسطينية المسلحة إلى قتال واسع في سبتمبر 1970. وتحركت القوات الأردنية ضد منظمات منظمة التحرير، ما أدى إلى خسائر كبيرة وفي النهاية إخراج الوجود المسلح الرئيسي للمنظمة من الأردن إلى لبنان.","context":"كان الحدث صراعًا بين الدولة الأردنية والتنظيمات الفلسطينية وليس مواجهة إسرائيلية فلسطينية مباشرة.","aftermath":"أثر انتقال مركز ثقل منظمة التحرير إلى لبنان بعمق في السياسة والعنف اللبنانيين خلال السبعينيات والثمانينيات.","sourceStatus":"الصراع وإخراج منظمة التحرير من الأردن موثقان جيدًا؛ تختلف تقديرات الضحايا بدرجة كبيرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1972-lod-airport-massacre-186"]={"title":"مذبحة مطار اللد","location":"مطار اللد، إسرائيل","story":"هاجم مسلحون من الجيش الأحمر الياباني، يعملون مع تنظيم فلسطيني مسلح، ركابًا في مطار اللد في مايو 1972.","context":"كان الحدث جزءًا من توسع الإرهاب والنشاط الفلسطيني المسلح وحلفائه إلى الساحة الدولية.","aftermath":"زادت المذبحة التركيز الإسرائيلي والدولي على أمن الطيران ومكافحة الإرهاب.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1972-munich-olympics-attack-187"]={"title":"هجوم أولمبياد ميونيخ","location":"ميونيخ، ألمانيا الغربية","story":"احتجز أعضاء من منظمة أيلول الأسود أفرادًا من الفريق الأولمبي الإسرائيلي رهائن؛ وقُتل أحد عشر رياضيًا ومدربًا إسرائيليًا خلال الهجوم ومحاولة الإنقاذ الفاشلة.","context":"كان الحدث هجومًا إرهابيًا دوليًا ضد الوفد الأولمبي الإسرائيلي.","aftermath":"أدت المذبحة إلى تغييرات واسعة في أمن الفعاليات الرياضية وإلى عمليات إسرائيلية ضد أشخاص مرتبطين بالتنظيم.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1973-yom-kippur-october-war-188"]={"title":"حرب يوم الغفران / حرب أكتوبر","location":"إسرائيل / مصر / سوريا","story":"شنت مصر وسوريا هجومًا مفاجئًا على المواقع الإسرائيلية في 6 أكتوبر 1973، لتبدأ حرب إقليمية كبرى.","context":"نشأت الحرب إلى حد كبير من الجمود بعد 1967 ومن مساعي مصر وسوريا لاستعادة أراضٍ فقدتاها في حرب الأيام الستة.","aftermath":"سببت الحرب خسائر كبيرة وهزت السياسة الإسرائيلية والإقليمية وساعدت في فتح مسار دبلوماسي قاد لاحقًا إلى السلام المصري الإسرائيلي.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1973-israel-crosses-the-suez-canal-and-encircles-egypt-s-third-army-189"]={"title":"إسرائيل تعبر قناة السويس وتحاصر الجيش المصري الثالث","location":"مصر / قناة السويس","story":"في المرحلة المتأخرة من حرب أكتوبر 1973 عبرت القوات الإسرائيلية إلى الضفة الغربية للقناة وحاصرت الجيش المصري الثالث. وكثف انقلاب الوضع الميداني الدبلوماسية الأمريكية السوفيتية وساعد في الدفع نحو وقف إطلاق النار.","context":"كان الحدث مرحلة حاسمة في الحرب بعد النجاحات المصرية الأولى في عبور القناة.","aftermath":"ساهم الحصار والضغط الدولي في ترتيبات وقف النار واستمرار الدبلوماسية بين مصر وإسرائيل.","sourceStatus":"العبور والحصار موثقان بقوة في السجلات العسكرية والدبلوماسية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1974-kiryat-shmona-massacre-190"]={"title":"مذبحة كريات شمونة","location":"كريات شمونة، إسرائيل","story":"تسلل مسلحون فلسطينيون إلى كريات شمونة في أبريل 1974 وقتلوا مدنيين، بينهم أطفال.","context":"هذه حادثة محددة من العنف ضد مدنيين إسرائيليين ضمن فترة صراع أوسع.","aftermath":"زادت المذبحة الضغط الأمني على الحدود الشمالية والرد الإسرائيلي على النشاط المسلح من لبنان.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1974-ma-alot-massacre-191"]={"title":"مذبحة معالوت","location":"معالوت، إسرائيل","story":"احتجز ثلاثة مسلحين فلسطينيين تلاميذ مدرسة ورهائن آخرين في مايو 1974. وخلال محاولة الإنقاذ أطلق المهاجمون النار على الأطفال وألقوا قنابل يدوية، فقُتل عدد كبير من الرهائن.","context":"كان الحدث هجومًا متعمدًا على رهائن مدنيين وأصبح من أبرز الهجمات الإرهابية في إسرائيل في السبعينيات.","aftermath":"أثرت المذبحة في سياسة الأمن والاستجابة الإسرائيلية لأزمات الرهائن.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1975-savoy-hotel-attack-192"]={"title":"هجوم فندق سافوي","location":"تل أبيب، إسرائيل","story":"سيطر مسلحو فتح على فندق سافوي في مارس 1975. وقُتل ثمانية رهائن وثلاثة جنود إسرائيليين خلال الحادث وعملية الإنقاذ.","context":"كان الحدث عملية إرهابية واحتجاز رهائن ضمن الكفاح الفلسطيني المسلح ضد إسرائيل.","aftermath":"عزز الهجوم التركيز الإسرائيلي على الاستجابة السريعة لعمليات التسلل والرهائن.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1976-entebbe-hijacking-and-hostage-crisis-193"]={"title":"اختطاف عنتيبي وأزمة الرهائن","location":"عنتيبي، أوغندا","story":"اختطف مسلحون مرتبطون بالجبهة الشعبية لتحرير فلسطين ومسلحون ألمان طائرة إير فرانس وحولوها إلى عنتيبي. وفُصل الركاب الإسرائيليون واليهود عن كثير من الرهائن الآخرين قبل عملية إنقاذ نفذتها قوات كوماندوز إسرائيلية.","context":"جمع الحدث بين خطف طائرة دولية وفصل رهائن يهود وإسرائيليين وعملية إنقاذ إسرائيلية في دولة أجنبية.","aftermath":"أُنقذ معظم الرهائن في العملية الإسرائيلية التي أصبحت من أشهر عمليات الإنقاذ في العالم.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1978-coastal-road-massacre-194"]={"title":"مذبحة الطريق الساحلي","location":"إسرائيل","story":"هاجم مسلحون فلسطينيون مدنيين مسافرين على الطريق الساحلي في إسرائيل، فقتلوا العشرات وأثاروا ردًا عسكريًا إسرائيليًا كبيرًا في لبنان.","context":"كانت المذبحة هجومًا على المدنيين ووقعت وسط تصاعد نشاط منظمة التحرير من لبنان والردود الإسرائيلية.","aftermath":"أطلقت إسرائيل بعدها عملية الليطاني في جنوب لبنان وتعمق الصراع على الحدود الشمالية.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1978-camp-david-accords-195"]={"title":"اتفاقيات كامب ديفيد","location":"كامب ديفيد، ماريلاند، الولايات المتحدة","story":"توصل الرئيس المصري أنور السادات ورئيس الوزراء الإسرائيلي مناحيم بيغن، بوساطة الرئيس الأمريكي جيمي كارتر، إلى اتفاقيات كامب ديفيد في سبتمبر 1978. وأنشأت الاتفاقيات إطارًا لمعاهدة سلام مصرية إسرائيلية ولمفاوضات بشأن الحكم الذاتي الفلسطيني.","context":"مثلت الاتفاقيات انتقالًا مهمًا من الحرب المباشرة بين مصر وإسرائيل إلى مسار تفاوض سياسي.","aftermath":"قادت إلى معاهدة السلام سنة 1979، بينما لم يُنفذ إطار الحكم الذاتي الفلسطيني كما كان متصورًا أصلًا.","sourceStatus":"الاتفاقيات موثقة مباشرة؛ لم تُنفذ أحكام الحكم الذاتي الفلسطيني كما تصورت أصلًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1979-egypt-israel-peace-treaty-196"]={"title":"معاهدة السلام المصرية الإسرائيلية","location":"واشنطن العاصمة / مصر وإسرائيل","story":"وقعت مصر وإسرائيل معاهدة سلام في 26 مارس 1979. ووافقت إسرائيل على الانسحاب من سيناء وأصبحت مصر أول دولة عربية تعترف رسميًا بإسرائيل. وغيرت المعاهدة بصورة أساسية الميزان الاستراتيجي للصراع العربي الإسرائيلي.","context":"كانت المعاهدة نتيجة مسار دبلوماسي بدأ بعد حرب 1973 وتقدم عبر كامب ديفيد.","aftermath":"نُفذ الانسحاب الإسرائيلي من سيناء على مراحل وأصبح السلام بين البلدين ركيزة أساسية للنظام الإقليمي.","sourceStatus":"المعاهدة والانسحاب الإسرائيلي المرحلي من سيناء موثقان مباشرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1980-paris-synagogue-bombing-197"]={"title":"تفجير كنيس باريس","location":"باريس، فرنسا","story":"انفجرت قنبلة خارج كنيس شارع كوبرنيك في باريس في أكتوبر 1980، فقتلت أربعة أشخاص وأصابت العشرات.","context":"هذه حادثة محددة من العنف ضد هدف يهودي خارج إسرائيل.","aftermath":"أثار التفجير صدمة في فرنسا وزاد الاهتمام بمعاداة السامية والإرهاب ضد المؤسسات اليهودية في أوروبا.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1982-1982-lebanon-war-198"]={"title":"حرب لبنان 1982","location":"لبنان / إسرائيل","story":"غزت إسرائيل لبنان وسط الصراع مع منظمة التحرير والهجمات عبر الحدود. وشاركت في الحرب قوات إسرائيلية وفلسطينية ولبنانية وسورية وتسببت في معاناة واسعة للمدنيين.","context":"وقعت الحرب داخل الحرب الأهلية اللبنانية والصراع الإسرائيلي الفلسطيني وكانت متعددة الأطراف والأهداف.","aftermath":"أدت إلى خروج منظمة التحرير من بيروت واستمرار الوجود الإسرائيلي في لبنان وعواقب طويلة المدى على السياسة والأمن الإقليميين.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1982-great-synagogue-of-rome-attack-199"]={"title":"الهجوم على الكنيس الكبير في روما","location":"روما، إيطاليا","story":"هاجم مسلحون مصلين يغادرون الكنيس الكبير في روما في أكتوبر 1982، فقتلوا طفلًا عمره عامان وجرحوا العشرات.","context":"هذه حادثة محددة من العنف ضد مجتمع يهودي خارج إسرائيل.","aftermath":"زاد الهجوم المخاوف من الإرهاب المعادي لليهود في أوروبا والإجراءات الأمنية حول المؤسسات اليهودية.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1982-siege-of-beirut-and-plo-evacuation-200"]={"title":"حصار بيروت وإجلاء منظمة التحرير الفلسطينية","location":"بيروت، لبنان","story":"خلال الغزو الإسرائيلي للبنان سنة 1982 حاصرت القوات الإسرائيلية غرب بيروت حيث كانت منظمة التحرير متمركزة. وأدت عمليات القصف والقتال الشديد إلى خسائر عسكرية ومدنية. وفي النهاية قاد ترتيب بوساطة أمريكية إلى إجلاء مقاتلي المنظمة من بيروت إلى عدة دول عربية.","context":"كان الحصار مرحلة مركزية في حرب لبنان وشمل قتالًا داخل منطقة حضرية كثيفة السكان.","aftermath":"غيّر خروج منظمة التحرير مركز نشاطها الإقليمي لكنه لم ينهِ الصراع في لبنان أو الصراع الإسرائيلي الفلسطيني.","sourceStatus":"الحصار وإجلاء منظمة التحرير موثقان على نطاق واسع؛ تبقى تقديرات الضحايا وتقييمات التناسب موضع خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1982-sabra-and-shatila-massacre-201"]={"title":"مذبحة صبرا وشاتيلا","location":"بيروت، لبنان","story":"في سبتمبر 1982 دخل مسلحو ميليشيا الكتائب المسيحية اللبنانية مخيمي صبرا وشاتيلا وقتلوا مدنيين فلسطينيين ولبنانيين بينما كانت القوات الإسرائيلية تسيطر على المنطقة المحيطة. وخلصت لجنة كاهان الإسرائيلية لاحقًا إلى أن مسؤولين إسرائيليين تحملوا مسؤولية غير مباشرة لعدم توقع خطر وقوع مذبحة ومنعه.","context":"يوثق الحدث مذبحة نفذتها ميليشيا لبنانية ومسألة المسؤولية الإسرائيلية الناشئة عن السيطرة العسكرية على المنطقة المحيطة.","aftermath":"أثارت المذبحة احتجاجات واسعة في إسرائيل والعالم وأدت إلى استنتاجات شخصية ومؤسسية للجنة كاهان.","sourceStatus":"المذبحة على يد قوات الكتائب اللبنانية موثقة بقوة. تختلف تقديرات الضحايا. ووجدت لجنة كاهان مسؤولية إسرائيلية غير مباشرة لا مسؤولية مباشرة عن التنفيذ"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1985-rome-and-vienna-airport-attacks-202"]={"title":"התקפות נמלי התעופה ברומא ובווינה","location":"רומא, איטליה / וינה, אוסטריה","story":"חמושים תקפו דלפקי אל על בנמלי התעופה ברומא ובווינה בדצמבר 1985, הרגו ופצעו נוסעים.","context":"זהו אירוע מזוהה של אלימות נגד מטרות ישראליות ויהודיות בזירה הבינלאומית.","aftermath":"ההתקפות הגבירו את אמצעי האבטחה סביב תעופה ישראלית ויעדים יהודיים באירופה.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1985-israel-withdraws-from-most-of-lebanon-and-establishes-a-security-zone-203"]={"title":"ישראל נסוגה מרוב לבנון ומקימה רצועת ביטחון","location":"דרום לבנון","story":"עד 1985 נסוגה ישראל מרוב לבנון אך הותירה כוחות ברצועת ביטחון שהכריזה בדרום, בשיתוף עם צבא דרום לבנון. הלחימה עם ארגונים לבנוניים חמושים, ובהדרגה בעיקר חזבאללה, נמשכה שנים.","context":"הסמן מקשר בין מלחמת לבנון, התפתחות חזבאללה והמשך המעורבות הישראלית בדרום לבנון.","aftermath":"הנוכחות ברצועת הביטחון נמשכה עד הנסיגה הישראלית בשנת 2000 וגבתה אבדות משני הצדדים.","sourceStatus":"הנסיגה ותקופת רצועת הביטחון מתועדות היטב; הערכות הצורך הצבאי והשפעות הנוכחות נותרו שנויות במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1987-first-intifada-204"]={"title":"האינתיפאדה הראשונה","location":"הגדה המערבית / עזה / ישראל","story":"התקוממות פלסטינית נגד השליטה הישראלית כללה הפגנות, מהומות, התקפות ותגובות צבאיות ישראליות, וגרמה למותם של פלסטינים וישראלים.","context":"האינתיפאדה צמחה מתוך מציאות של עשרים שנות שליטה ישראלית בשטחים ומתחים פוליטיים, חברתיים וכלכליים.","aftermath":"ההתקוממות שינתה את הפוליטיקה הפלסטינית והישראלית ותרמה לתנאים שהובילו לתהליך מדריד ואוסלו.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1987-hamas-emerges-during-the-first-intifada-205"]={"title":"חמאס מתפתח במהלך האינתיפאדה הראשונה","location":"רצועת עזה והגדה המערבית","story":"חמאס צמח ב־1987 במהלך האינתיפאדה הראשונה מתוך רשתות הקשורות לאחים המוסלמים הפלסטינים. הוא שילב פעילות חברתית ודתית עם התנגדות חמושה לישראל ובהמשך נעשה יריב מרכזי של תנועת פת״ח הלאומית־חילונית.","context":"הקמת חמאס הוסיפה זרם אסלאמיסטי מאורגן למאבק הלאומי הפלסטיני.","aftermath":"חמאס נעשה בהמשך כוח פוליטי וצבאי מרכזי והשפיע עמוקות על תהליך השלום ועל הפוליטיקה הפלסטינית.","sourceStatus":"צמיחת חמאס במהלך האינתיפאדה הראשונה מתועדת היטב; הארגון, שיטותיו ותפקידו הפוליטי השתנו מאוד בעשורים הבאים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1991-madrid-peace-conference-206"]={"title":"ועידת השלום במדריד","location":"מדריד, ספרד","story":"ישראל, מדינות ערב שכנות ומשלחת ירדנית־פלסטינית משותפת נפגשו בוועידת מדריד באוקטובר 1991. הוועידה לא יצרה הסדר סופי אך פתחה משא ומתן ישיר דו־צדדי ורב־צדדי וסייעה ליצור את המסלול הדיפלומטי שקדם לאוסלו.","context":"הוועידה סימנה מעבר חשוב מעימות אזורי ממושך למשא ומתן ישיר ורשמי.","aftermath":"השיחות שנפתחו במדריד סייעו ליצור תנאים למסלולי שלום מאוחרים יותר, ובהם אוסלו והשלום עם ירדן.","sourceStatus":"הוועידה והמשלחות המשתתפות מתועדות ישירות ברשומות דיפלומטיות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1992-israeli-embassy-bombing-in-buenos-aires-207"]={"title":"הפיגוע בשגרירות ישראל בבואנוס איירס","location":"בואנוס איירס, ארגנטינה","story":"פיגוע התאבדות החריב את שגרירות ישראל בבואנוס איירס במרץ 1992, הרג 29 בני אדם ופצע מאות.","context":"זהו אירוע מזוהה של טרור נגד יעד ישראלי מחוץ לישראל.","aftermath":"הפיגוע נעשה אחד מאירועי הטרור הקטלניים ביותר בארגנטינה והקדים בשנתיים את הפיגוע במרכז AMIA.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1993-oslo-accord-and-mutual-israel-plo-recognition-208"]={"title":"הסכם אוסלו והכרה הדדית בין ישראל לאש״ף","location":"אוסלו / וושינגטון הבירה","story":"משא ומתן חשאי בין ישראל לאש״ף הוביל להצהרת העקרונות של 1993. ישראל הכירה באש״ף כנציג העם הפלסטיני, ואש״ף הכיר בזכותה של ישראל להתקיים בשלום והתחייב לוותר על טרור. ההסכם תכנן ממשל עצמי פלסטיני ומשא ומתן מאוחר יותר על סוגיות הקבע.","context":"אוסלו היה פריצת דרך של הכרה הדדית אך דחה את הסוגיות הקשות ביותר לשלב עתידי.","aftermath":"ההסכם יצר את הרשות הפלסטינית ותהליך מדיני חדש, אך גבולות, ירושלים, פליטים, התנחלויות וסוגיות קבע אחרות נותרו בלתי פתורים.","sourceStatus":"ההסכם וההכרה ההדדית מתועדים ישירות; אוסלו השאיר גבולות, ירושלים, פליטים, התנחלויות וסוגיות קבע אחרות בלתי פתורים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1994-amia-bombing-209"]={"title":"הפיגוע בבניין AMIA","location":"בואנוס איירס, ארגנטינה","story":"פיצוץ החריב את מרכז הקהילה היהודית AMIA, הרג 85 בני אדם ופצע מאות.","context":"הפיגוע היה מתקפת טרור רחבת היקף נגד מוסד יהודי מרכזי בארגנטינה.","aftermath":"החקירה והמאבק המשפטי והפוליטי סביב האחריות לפיגוע נמשכו במשך עשרות שנים.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1994-tel-aviv-bus-5-bombing-210"]={"title":"הפיגוע בקו 5 בתל אביב","location":"תל אביב, ישראל","story":"מחבל מתאבד של חמאס פוצץ עצמו באוטובוס עירוני בתל אביב באוקטובר 1994 והרג 22 בני אדם.","context":"הפיגוע התרחש בתקופת אוסלו והמחיש את התנגדות חמאס לתהליך המדיני באמצעות טרור נגד אזרחים.","aftermath":"ההתקפה הגבירה פחד ציבורי והתנגדות פוליטית לתהליך השלום.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1994-cave-of-the-patriarchs-massacre-211"]={"title":"טבח מערת המכפלה","location":"חברון, הגדה המערבית","story":"ב־25 בפברואר 1994 פתח ברוך גולדשטיין, קיצוני יהודי ישראלי, באש על מתפללים מוסלמים במסגד אברהימי/מערת המכפלה בחברון, הרג 29 פלסטינים ופצע רבים נוספים לפני שנהרג. הטבח החריף את המתיחות הישראלית–פלסטינית במהלך תהליך אוסלו.","context":"האירוע מתעד במפורש טרור יהודי קיצוני נגד אזרחים פלסטינים בתקופת תהליך השלום.","aftermath":"הטבח הוביל לגינוי רחב, צעדי ביטחון חדשים והעמיק את חוסר האמון והאלימות.","sourceStatus":"זהות המבצע, המקום והרג 29 המתפללים הפלסטינים מתועדים היטב"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1994-israel-jordan-peace-treaty-212"]={"title":"הסכם השלום בין ישראל לירדן","location":"גבול הערבה / ואדי ערבה","story":"ישראל וירדן חתמו על הסכם שלום באוקטובר 1994, סיימו רשמית את מצב המלחמה ביניהן וכוננו יחסים דיפלומטיים. ירדן הייתה המדינה הערבית השנייה, אחרי מצרים, שחתמה על הסכם שלום עם ישראל.","context":"ההסכם התקדם במקביל לתהליך אוסלו והראה אפשרות להסדרים מדיניים אזוריים.","aftermath":"השלום יצר מסגרת קבועה ליחסים, ביטחון גבול ושיתוף פעולה בין ישראל לירדן.","sourceStatus":"ההסכם וההכרה הדיפלומטית מתועדים ישירות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1995-oslo-ii-divides-west-bank-administrative-control-213"]={"title":"אוסלו ב׳ מחלק את השליטה המנהלית בגדה המערבית","location":"הגדה המערבית","story":"הסכם הביניים הישראלי–פלסטיני מ־1995, הידוע כאוסלו ב׳, חילק את הגדה המערבית לשטחי A, B ו־C עם הסדרים שונים של סמכות אזרחית פלסטינית ושליטה ביטחונית או מנהלית ישראלית. המסגרת נועדה להיות זמנית עד למשא ומתן על הסדר קבע.","context":"החלוקה הייתה מנגנון ביניים ולא הסדר גבולות סופי.","aftermath":"חלוקת A/B/C נשארה בעלת חשיבות מעשית ופוליטית הרבה מעבר לתקופת הביניים שתוכננה.","sourceStatus":"ההסכם והחלוקות המנהליות מתועדים ישירות; השלכותיהם המשפטיות והפוליטיות המאוחרות נותרו שנויות במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1995-assassination-of-yitzhak-rabin-214"]={"title":"רצח יצחק רבין","location":"תל אביב, ישראל","story":"ב־4 בנובמבר 1995 נרצח ראש ממשלת ישראל יצחק רבין לאחר עצרת שלום בידי יגאל עמיר, קיצוני יהודי ישראלי שהתנגד להסכמי אוסלו. הרצח זעזע את החברה הישראלית ופגע בתנופה הפוליטית של תהליך השלום.","context":"האירוע מתעד אלימות פוליטית יהודית קיצונית נגד מנהיג ישראלי בגלל מדיניות שלום.","aftermath":"הרצח שינה את הפוליטיקה הישראלית והפך לסמל של סכנת הסתה וקיצוניות פוליטית פנימית.","sourceStatus":"הרצח, המבצע והמניע האנטי־אוסלו מתועדים היטב"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1996-jerusalem-bus-18-bombings-215"]={"title":"הפיגועים בקו 18 בירושלים","location":"ירושלים, ישראל","story":"שני פיגועי התאבדות בקו 18 בירושלים בשנת 1996 הרגו עשרות אזרחים במהלך גל התקפות של חמאס.","context":"הפיגועים היו חלק ממסע טרור שפגע קשות בתחושת הביטחון הציבורית בתקופת אוסלו.","aftermath":"ההתקפות הגבירו התנגדות לתהליך השלום והשפיעו על האקלים הפוליטי בישראל.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1996-hamas-suicide-bombing-campaign-undermines-oslo-process-216"]={"title":"מסע פיגועי ההתאבדות של חמאס מערער את תהליך אוסלו","location":"ירושלים, תל אביב וערים ישראליות נוספות","story":"סדרת פיגועי התאבדות של חמאס ב־1996 הרגה אזרחים ישראלים והגבירה פחד והתנגדות פוליטית לתהליך אוסלו. ההתקפות באו לאחר פיגועים קודמים של חמאס ובתוך מעגל רחב יותר של אלימות ישראלית–פלסטינית.","context":"המסע ממחיש כיצד ארגונים שהתנגדו לאוסלו השתמשו בטרור נגד אזרחים בזמן שהמשא ומתן המדיני נמשך.","aftermath":"הפיגועים החלישו את התמיכה הציבורית בתהליך והחריפו את המשבר הפוליטי בין הצדדים.","sourceStatus":"ההתקפות ואחריות חמאס לפיגועים מרכזיים מתועדות בהרחבה; אירועים בודדים מיוצגים בנפרד בציר הזמן לפי הצורך"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1998-wye-river-memorandum-217"]={"title":"מזכר ואי ריבר","location":"מרילנד, ארצות הברית","story":"ראש ממשלת ישראל בנימין נתניהו ויו״ר אש״ף יאסר ערפאת ניהלו משא ומתן על מזכר ואי ריבר בתיווך אמריקאי. הוא קרא לפריסות ישראליות נוספות מחלקים בגדה המערבית ולהתחייבויות ביטחוניות פלסטיניות, אך מחלוקות על היישום עצרו במהרה את התהליך.","context":"המזכר היה ניסיון להחיות את יישום אוסלו לאחר שנים של אלימות וחוסר אמון.","aftermath":"חלק מן ההתחייבויות יושמו אך התהליך נתקע ולא פתר את סוגיות הקבע.","sourceStatus":"ההסכם והמחלוקות המאוחרות על יישומו מתועדים ישירות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2000-second-intifada-218"]={"title":"האינתיפאדה השנייה","location":"ישראל / הגדה המערבית / עזה","story":"האינתיפאדה השנייה כללה פיגועי התאבדות והתקפות אחרות נגד ישראלים לצד פעולות צבאיות ישראליות גדולות; אלפי פלסטינים וישראלים נהרגו.","context":"ההתקוממות פרצה לאחר כישלון מאמצי השלום ובתוך מתחים חריפים סביב ירושלים, הכיבוש, ההתנחלויות, ביטחון וסוגיות לאומיות אחרות.","aftermath":"האלימות הרסה במידה רבה את האמון שנבנה בתקופת אוסלו והובילה לשינויים עמוקים במדיניות הביטחון, בתנועה ובפוליטיקה משני הצדדים.","sourceStatus":"רמת ודאות גבוהה מאוד; המספרים הכוללים תלויים בהגדרות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2000-israel-withdraws-from-southern-lebanon-219"]={"title":"ישראל נסוגה מדרום לבנון","location":"דרום לבנון","story":"במאי 2000 נסוגה ישראל מדרום לבנון וסיימה את נוכחות רצועת הביטחון שנמשכה מאז שנות ה־1980. חזבאללה הציג את הנסיגה כניצחון, בעוד מחלוקות על אזור הגבול והתקפות מאוחרות נמשכו.","context":"הנסיגה סיימה פרק ארוך של נוכחות צבאית ישראלית ישירה בדרום לבנון אך לא את העימות עם חזבאללה.","aftermath":"הגבול נותר מתוח, ומחלוקות ובהמשך חטיפות ותקיפות תרמו למלחמת לבנון השנייה ב־2006.","sourceStatus":"הנסיגה מתועדת היטב; המחלוקות סביב חוות שבעא ומשמעות הנסיגה נמשכו"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2000-camp-david-summit-fails-to-reach-final-israeli-palestinian-agreement-220"]={"title":"פסגת קמפ דייוויד נכשלת בהשגת הסכם ישראלי–פלסטיני סופי","location":"קמפ דייוויד, מרילנד, ארצות הברית","story":"נשיא ארצות הברית ביל קלינטון כינס ביולי 2000 את ראש ממשלת ישראל אהוד ברק ואת יו״ר אש״ף יאסר ערפאת למשא ומתן על הסדר קבע. הפסגה הסתיימה ללא הסכמה בסוגיות מרכזיות ובהן גבולות, ירושלים והפליטים הפלסטינים.","context":"הפסגה הייתה ניסיון לפתור את סוגיות הקבע שאוסלו דחה, אך הפערים נותרו משמעותיים.","aftermath":"כישלון הפסגה קדם להתפרצות האינתיפאדה השנייה, אף שהסיבות לכישלון ולהסלמה שלאחריו נותרו נושא למחלוקת.","sourceStatus":"הפסגה והסוגיות שלא נפתרו מתועדות היטב. קיימת מחלוקת משמעותית לגבי הסיבות לכישלון וכיצד לחלק את האחריות"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1985-rome-and-vienna-airport-attacks-202"]={"title":"هجمات مطاري روما وفيينا","location":"روما، إيطاليا / فيينا، النمسا","story":"هاجم مسلحون مكاتب تذاكر إل عال في مطاري روما وفيينا في ديسمبر 1985، فقتلوا وأصابوا مسافرين.","context":"هذه حادثة محددة من العنف ضد أهداف إسرائيلية ويهودية في الساحة الدولية.","aftermath":"أدت الهجمات إلى تشديد الأمن حول الطيران الإسرائيلي والأهداف اليهودية في أوروبا.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1985-israel-withdraws-from-most-of-lebanon-and-establishes-a-security-zone-203"]={"title":"إسرائيل تنسحب من معظم لبنان وتقيم منطقة أمنية","location":"جنوب لبنان","story":"بحلول 1985 انسحبت إسرائيل من معظم لبنان لكنها أبقت قوات في منطقة أمنية أعلنتها في الجنوب وعملت مع جيش لبنان الجنوبي. واستمر القتال مع جماعات لبنانية مسلحة، وبصورة متزايدة مع حزب الله، لسنوات.","context":"يربط المؤشر بين حرب لبنان وصعود حزب الله واستمرار التدخل الإسرائيلي في الجنوب.","aftermath":"استمر الوجود في المنطقة الأمنية حتى الانسحاب الإسرائيلي سنة 2000 وتسبب بخسائر على الجانبين.","sourceStatus":"الانسحاب وفترة المنطقة الأمنية موثقان جيدًا؛ تبقى تقييمات الضرورة العسكرية وآثار الوجود موضع خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1987-first-intifada-204"]={"title":"الانتفاضة الأولى","location":"الضفة الغربية / غزة / إسرائيل","story":"شملت انتفاضة فلسطينية ضد السيطرة الإسرائيلية مظاهرات واضطرابات وهجمات وردودًا عسكرية إسرائيلية، وأدت إلى مقتل فلسطينيين وإسرائيليين.","context":"نشأت الانتفاضة من واقع عقدين من السيطرة الإسرائيلية على الأراضي ومن توترات سياسية واجتماعية واقتصادية.","aftermath":"غيرت الانتفاضة السياسة الفلسطينية والإسرائيلية وأسهمت في الظروف التي قادت إلى مساري مدريد وأوسلو.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1987-hamas-emerges-during-the-first-intifada-205"]={"title":"ظهور حماس خلال الانتفاضة الأولى","location":"قطاع غزة والضفة الغربية","story":"ظهرت حماس سنة 1987 خلال الانتفاضة الأولى من شبكات مرتبطة بالإخوان المسلمين الفلسطينيين. وجمعت بين التنظيم الاجتماعي والديني والمعارضة المسلحة لإسرائيل، وأصبحت لاحقًا منافسًا رئيسيًا لحركة فتح القومية العلمانية.","context":"أضاف تأسيس حماس تيارًا إسلاميًا منظمًا إلى الحركة الوطنية الفلسطينية.","aftermath":"أصبحت حماس لاحقًا قوة سياسية وعسكرية رئيسية وأثرت بعمق في عملية السلام والسياسة الفلسطينية.","sourceStatus":"ظهور حماس خلال الانتفاضة الأولى موثق بقوة؛ تغير تنظيمها وأساليبها ودورها السياسي كثيرًا في العقود التالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1991-madrid-peace-conference-206"]={"title":"مؤتمر مدريد للسلام","location":"مدريد، إسبانيا","story":"اجتمعت إسرائيل ودول عربية مجاورة ووفد أردني فلسطيني مشترك في مؤتمر مدريد في أكتوبر 1991. لم ينتج المؤتمر تسوية نهائية لكنه فتح مفاوضات مباشرة ثنائية ومتعددة الأطراف وساعد في إنشاء المسار الدبلوماسي الذي سبق أوسلو.","context":"مثل المؤتمر انتقالًا مهمًا من صراع إقليمي طويل إلى مفاوضات مباشرة ورسمية.","aftermath":"ساعدت المحادثات التي بدأت في مدريد في تهيئة مسارات سلام لاحقة، منها أوسلو والسلام مع الأردن.","sourceStatus":"المؤتمر والوفود المشاركة موثقة مباشرة في السجلات الدبلوماسية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1992-israeli-embassy-bombing-in-buenos-aires-207"]={"title":"تفجير السفارة الإسرائيلية في بوينس آيرس","location":"بوينس آيرس، الأرجنتين","story":"دمر تفجير انتحاري السفارة الإسرائيلية في بوينس آيرس في مارس 1992، فقتل 29 شخصًا وأصاب المئات.","context":"هذه حادثة إرهابية محددة ضد هدف إسرائيلي خارج إسرائيل.","aftermath":"أصبح التفجير من أكثر الهجمات الإرهابية دموية في الأرجنتين وسبق تفجير مركز AMIA بعامين.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1993-oslo-accord-and-mutual-israel-plo-recognition-208"]={"title":"اتفاق أوسلو والاعتراف المتبادل بين إسرائيل ومنظمة التحرير","location":"أوسلو / واشنطن العاصمة","story":"أنتجت مفاوضات إسرائيلية فلسطينية سرية إعلان المبادئ سنة 1993. اعترفت إسرائيل بمنظمة التحرير ممثلًا للشعب الفلسطيني، واعترفت المنظمة بحق إسرائيل في الوجود بسلام وتعهدت بنبذ الإرهاب. وتصور الاتفاق حكمًا ذاتيًا فلسطينيًا ومفاوضات لاحقة حول قضايا الوضع النهائي.","context":"كان أوسلو اختراقًا في الاعتراف المتبادل لكنه أجل أصعب القضايا إلى مرحلة لاحقة.","aftermath":"أنشأ الاتفاق السلطة الفلسطينية ومسارًا سياسيًا جديدًا، لكن الحدود والقدس واللاجئين والمستوطنات وغيرها بقيت دون حل.","sourceStatus":"الاتفاق والاعتراف المتبادل موثقان مباشرة؛ ترك أوسلو الحدود والقدس واللاجئين والمستوطنات وغيرها من قضايا الوضع النهائي دون حل"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1994-amia-bombing-209"]={"title":"تفجير مركز AMIA","location":"بوينس آيرس، الأرجنتين","story":"دمر تفجير مركز AMIA للجالية اليهودية، فقتل 85 شخصًا وأصاب المئات.","context":"كان التفجير هجومًا إرهابيًا واسع النطاق على مؤسسة يهودية مركزية في الأرجنتين.","aftermath":"استمرت التحقيقات والنزاعات القانونية والسياسية حول المسؤولية عن التفجير لعقود.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1994-tel-aviv-bus-5-bombing-210"]={"title":"تفجير حافلة رقم 5 في تل أبيب","location":"تل أبيب، إسرائيل","story":"فجر انتحاري من حماس نفسه في حافلة داخل تل أبيب في أكتوبر 1994، فقتل 22 شخصًا.","context":"وقع الهجوم خلال عملية أوسلو وأظهر معارضة حماس للمسار السياسي باستخدام الإرهاب ضد المدنيين.","aftermath":"زاد الهجوم الخوف العام والمعارضة السياسية لعملية السلام.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1994-cave-of-the-patriarchs-massacre-211"]={"title":"مذبحة الحرم الإبراهيمي","location":"الخليل، الضفة الغربية","story":"في 25 فبراير 1994 فتح باروخ غولدشتاين، وهو متطرف يهودي إسرائيلي، النار على مصلين مسلمين في المسجد الإبراهيمي/الحرم الإبراهيمي في الخليل، فقتل 29 فلسطينيًا وجرح كثيرين قبل مقتله. وفاقمت المذبحة التوتر الإسرائيلي الفلسطيني خلال عملية أوسلو.","context":"يوثق الحدث بوضوح إرهابًا يهوديًا متطرفًا ضد مدنيين فلسطينيين أثناء عملية السلام.","aftermath":"أدت المذبحة إلى إدانة واسعة وإجراءات أمنية جديدة وعمقت انعدام الثقة والعنف.","sourceStatus":"هوية المنفذ والموقع وقتل 29 مصليًا فلسطينيًا موثقة بقوة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1994-israel-jordan-peace-treaty-212"]={"title":"معاهدة السلام الإسرائيلية الأردنية","location":"حدود وادي عربة","story":"وقعت إسرائيل والأردن معاهدة سلام في أكتوبر 1994، منهية رسميًا حالة الحرب ومقيمة علاقات دبلوماسية. وأصبح الأردن ثاني دولة عربية بعد مصر توقع معاهدة سلام مع إسرائيل.","context":"تقدمت المعاهدة بالتوازي مع أوسلو وأظهرت إمكانية التوصل إلى تسويات سياسية إقليمية.","aftermath":"أنشأ السلام إطارًا دائمًا للعلاقات وأمن الحدود والتعاون بين إسرائيل والأردن.","sourceStatus":"المعاهدة والاعتراف الدبلوماسي موثقان مباشرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1995-oslo-ii-divides-west-bank-administrative-control-213"]={"title":"أوسلو الثاني يقسم السيطرة الإدارية في الضفة الغربية","location":"الضفة الغربية","story":"قسم الاتفاق الإسرائيلي الفلسطيني المرحلي لسنة 1995، المعروف بأوسلو الثاني، الضفة الغربية إلى مناطق أ وب وج بترتيبات مختلفة للسلطة المدنية الفلسطينية والسيطرة الأمنية أو الإدارية الإسرائيلية. وكان الإطار مؤقتًا بانتظار مفاوضات الوضع النهائي.","context":"كان التقسيم آلية انتقالية لا تسوية نهائية للحدود.","aftermath":"بقي تقسيم المناطق أ/ب/ج ذا أهمية عملية وسياسية بعد زمن طويل من الفترة الانتقالية المخطط لها.","sourceStatus":"الاتفاق والتقسيمات الإدارية موثقة مباشرة؛ تبقى آثارها القانونية والسياسية اللاحقة موضع نزاع عميق"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1995-assassination-of-yitzhak-rabin-214"]={"title":"اغتيال إسحاق رابين","location":"تل أبيب، إسرائيل","story":"في 4 نوفمبر 1995 اغتال إيغال عمير، وهو متطرف يهودي إسرائيلي معارض لاتفاقيات أوسلو، رئيس الوزراء إسحاق رابين بعد تجمع للسلام. صدم الاغتيال المجتمع الإسرائيلي وأضر بالزخم السياسي لعملية السلام.","context":"يوثق الحدث عنفًا سياسيًا يهوديًا متطرفًا ضد قائد إسرائيلي بسبب سياسة السلام.","aftermath":"غير الاغتيال السياسة الإسرائيلية وأصبح رمزًا لخطر التحريض والتطرف السياسي الداخلي.","sourceStatus":"الاغتيال والمنفذ والدافع المناهض لأوسلو موثقة بقوة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1996-jerusalem-bus-18-bombings-215"]={"title":"تفجيرات حافلة 18 في القدس","location":"القدس، إسرائيل","story":"أدى تفجيران انتحاريان على خط الحافلة 18 في القدس سنة 1996 إلى مقتل عشرات المدنيين خلال موجة هجمات لحماس.","context":"كانت التفجيرات جزءًا من حملة إرهابية أضرت بشدة بالشعور بالأمن العام خلال فترة أوسلو.","aftermath":"زادت الهجمات المعارضة لعملية السلام وأثرت في المناخ السياسي الإسرائيلي.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1996-hamas-suicide-bombing-campaign-undermines-oslo-process-216"]={"title":"حملة تفجيرات حماس الانتحارية تقوض عملية أوسلو","location":"القدس وتل أبيب ومدن إسرائيلية أخرى","story":"قتلت سلسلة تفجيرات انتحارية لحماس سنة 1996 مدنيين إسرائيليين وزادت الخوف والمعارضة السياسية لعملية أوسلو. وجاءت بعد تفجيرات سابقة لحماس وضمن دورة أوسع من العنف الإسرائيلي الفلسطيني.","context":"توضح الحملة كيف استخدمت جهات معارضة لأوسلو الإرهاب ضد المدنيين بينما كانت المفاوضات السياسية مستمرة.","aftermath":"أضعفت التفجيرات الدعم الشعبي للعملية وفاقمت الأزمة السياسية بين الطرفين.","sourceStatus":"الهجمات ومسؤولية حماس عن تفجيرات رئيسية موثقة على نطاق واسع؛ تمثل هجمات فردية بصورة منفصلة في الخط الزمني حيث يلزم"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1998-wye-river-memorandum-217"]={"title":"مذكرة واي ريفر","location":"ماريلاند، الولايات المتحدة","story":"تفاوض رئيس الوزراء الإسرائيلي بنيامين نتنياهو ورئيس منظمة التحرير ياسر عرفات على مذكرة واي ريفر بوساطة أمريكية. ودعت إلى إعادة انتشار إسرائيلية إضافية من أجزاء من الضفة والتزامات أمنية فلسطينية، لكن خلافات التنفيذ عطلت العملية سريعًا.","context":"كانت المذكرة محاولة لإحياء تنفيذ أوسلو بعد سنوات من العنف وانعدام الثقة.","aftermath":"نُفذ بعض الالتزامات لكن العملية تعثرت ولم تحل قضايا الوضع النهائي.","sourceStatus":"الاتفاق وخلافات التنفيذ اللاحقة موثقة مباشرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2000-second-intifada-218"]={"title":"الانتفاضة الثانية","location":"إسرائيل / الضفة الغربية / غزة","story":"جلبت الانتفاضة الثانية تفجيرات انتحارية وهجمات أخرى ضد إسرائيليين إلى جانب عمليات عسكرية إسرائيلية كبيرة؛ وقُتل آلاف الفلسطينيين والإسرائيليين.","context":"اندلعت الانتفاضة بعد تعثر جهود السلام وسط توترات حادة بشأن القدس والاحتلال والمستوطنات والأمن وقضايا وطنية أخرى.","aftermath":"دمر العنف إلى حد كبير الثقة التي بُنيت خلال أوسلو وأدى إلى تغيرات عميقة في سياسات الأمن والحركة والسياسة لدى الطرفين.","sourceStatus":"ثقة عالية جدًا؛ تعتمد المجاميع على التعريفات"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2000-israel-withdraws-from-southern-lebanon-219"]={"title":"إسرائيل تنسحب من جنوب لبنان","location":"جنوب لبنان","story":"في مايو 2000 سحبت إسرائيل قواتها من جنوب لبنان منهية وجود المنطقة الأمنية المستمر منذ الثمانينيات. وقدم حزب الله الانسحاب كنصر، بينما استمرت النزاعات على منطقة الحدود والهجمات اللاحقة.","context":"أنهى الانسحاب فصلًا طويلًا من الوجود العسكري الإسرائيلي المباشر في جنوب لبنان لكنه لم ينهِ المواجهة مع حزب الله.","aftermath":"بقيت الحدود متوترة وأسهمت النزاعات وعمليات الخطف والهجمات اللاحقة في حرب لبنان الثانية سنة 2006.","sourceStatus":"الانسحاب موثق بقوة؛ استمرت الخلافات حول مزارع شبعا ومعنى الانسحاب"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2000-camp-david-summit-fails-to-reach-final-israeli-palestinian-agreement-220"]={"title":"قمة كامب ديفيد تفشل في التوصل إلى اتفاق إسرائيلي فلسطيني نهائي","location":"كامب ديفيد، ماريلاند، الولايات المتحدة","story":"جمع الرئيس الأمريكي بيل كلينتون رئيس الوزراء الإسرائيلي إيهود باراك ورئيس منظمة التحرير ياسر عرفات في يوليو 2000 لمفاوضات الوضع النهائي. وانتهت القمة دون اتفاق على قضايا رئيسية منها الحدود والقدس واللاجئون الفلسطينيون.","context":"كانت القمة محاولة لحل قضايا الوضع النهائي التي أجلها أوسلو، لكن الفجوات بقيت كبيرة.","aftermath":"سبق فشل القمة اندلاع الانتفاضة الثانية، مع بقاء أسباب الفشل والتصعيد اللاحق محل خلاف.","sourceStatus":"القمة والقضايا غير المحلولة موثقة بقوة. تختلف الروايات كثيرًا حول أسباب فشل المفاوضات وكيفية توزيع المسؤولية"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2001-dolphinarium-discotheque-bombing-221"]={"title":"הפיגוע בדולפינריום","location":"תל אביב, ישראל","story":"מחבל מתאבד תקף צעירים שהמתינו מחוץ למועדון הדולפינריום ביוני 2001; 21 אזרחים ישראלים נהרגו, רובם בני נוער.","context":"הפיגוע היה מתקפה מכוונת על אזרחים במהלך האינתיפאדה השנייה.","aftermath":"הפיגוע העמיק את ההסלמה והלחץ הציבורי בישראל לתגובה ביטחונית חריפה יותר.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2001-sbarro-restaurant-bombing-222"]={"title":"הפיגוע במסעדת סבארו","location":"ירושלים, ישראל","story":"מחבל מתאבד תקף את מסעדת סבארו העמוסה בירושלים באוגוסט 2001 והרג 15 אזרחים.","context":"הפיגוע היה אחת ממתקפות ההתאבדות הבולטות נגד אזרחים באינתיפאדה השנייה.","aftermath":"המתקפה החריפה את מעגל האלימות והעמיקה את חוסר האמון בין הצדדים.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2001-taba-summit-continues-final-status-negotiations-223"]={"title":"פסגת טאבה ממשיכה את המשא ומתן על הסדר הקבע","location":"טאבה, מצרים","story":"נציגים ישראלים ופלסטינים נפגשו בטאבה בינואר 2001 לאחר כישלון פסגת קמפ דייוויד ובעיצומה של האינתיפאדה השנייה. הצדדים דיווחו על צמצום חלק מן הפערים אך לא הגיעו להסכם סופי לפני סיום השיחות.","context":"השיחות הראו שמשא ומתן מדיני נמשך גם בזמן שהאלימות בשטח החריפה.","aftermath":"הפסגה הסתיימה ללא הסכם, והמסלול המדיני נחלש עוד יותר בחודשים הבאים.","sourceStatus":"הפסגה והיעדר הסדר סופי מתועדים היטב; קיימות הערכות שונות לגבי מידת הקרבה להסכמה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2002-passover-massacre-224"]={"title":"טבח ליל הסדר","location":"נתניה, ישראל","story":"מחבל מתאבד תקף ליל סדר במלון פארק בנתניה במהלך האינתיפאדה השנייה, הרג אזרחים ופצע רבים נוספים.","context":"הפיגוע היה מתקפה על אזרחים במהלך חג יהודי והתרחש בשיא גל פיגועי ההתאבדות.","aftermath":"הפיגוע היה גורם מיידי מרכזי בהחלטת ישראל לפתוח במבצע חומת מגן.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2002-operation-defensive-shield-225"]={"title":"מבצע חומת מגן","location":"הגדה המערבית","story":"לאחר גל פיגועי התאבדות פלסטיניים, ובהם טבח ליל הסדר, פתחה ישראל במרץ 2002 במבצע חומת מגן ונכנסה מחדש לערים פלסטיניות מרכזיות בגדה המערבית. התרחשו קרבות, מעצרים ונזק נרחב, ובמיוחד לחימה קשה בג'נין ובשכם.","context":"המבצע היה תגובה צבאית ישראלית רחבת היקף לגל הטרור, אך השפיע גם באופן נרחב על האוכלוסייה הפלסטינית ועל מוסדותיה.","aftermath":"המבצע שינה את מערך הביטחון בגדה וחיזק מחדש את הנוכחות הצבאית הישראלית באזורים שהועברו קודם לשליטה פלסטינית.","sourceStatus":"המבצע והכניסה מחדש למרכזי אוכלוסייה בגדה מתועדים היטב. נרטיבים על נפגעים בקרבות מסוימים, במיוחד בג'נין, היו שנויים במחלוקת חריפה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2002-construction-of-the-west-bank-barrier-begins-226"]={"title":"תחילת בניית גדר ההפרדה בגדה המערבית","location":"הגדה המערבית ואזור מזרח ירושלים","story":"ישראל החלה לבנות מערכת של גדרות וחומות במהלך האינתיפאדה השנייה, בטענה לצורך למנוע ממחבלים מתאבדים ותוקפים אחרים להגיע למרכזי אוכלוסייה בישראל. חלק גדול מהתוואי עובר בתוך הגדה ולא לאורך קו שביתת הנשק של 1949, דבר שיצר קשיי גישה ועקירה לפלסטינים ומחלוקת משפטית בינלאומית.","context":"הגדר שילבה מטרה ביטחונית ישראלית עם השלכות טריטוריאליות והומניטריות משמעותיות על פלסטינים.","aftermath":"ישראל מייחסת לגדר תפקיד בירידה בהתקפות; התוואי והשלכותיו נותרו מוקד למאבקים משפטיים ופוליטיים.","sourceStatus":"הבנייה, התוואי והנימוק הביטחוני מתועדים. ישראל מייחסת לגדר תפקיד בירידה בהתקפות; פלסטינים וגופים בינלאומיים ערערו על חלקים מן התוואי ועל השפעותיו ההומניטריות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2002-arab-peace-initiative-227"]={"title":"יוזמת השלום הערבית","location":"ביירות, לבנון","story":"בפסגת הליגה הערבית בביירות ב־2002 אימצו מדינות ערב יוזמה שהציעה יחסים מנורמלים עם ישראל בתמורה לנסיגה ישראלית מהשטחים שנכבשו ב־1967, פתרון מוסכם לסוגיית הפליטים הפלסטינים והקמת מדינה פלסטינית שבירתה מזרח ירושלים.","context":"היוזמה הציגה מסגרת אזורית להסדר מדיני בזמן שהאינתיפאדה השנייה הייתה בעיצומה.","aftermath":"היוזמה נשארה נקודת ייחוס דיפלומטית וחזרה ואושרה בידי מדינות ערב בשנים מאוחרות יותר.","sourceStatus":"היוזמה ותנאיה המרכזיים מתועדים ישירות ואושרו מחדש בידי מדינות ערב בשנים מאוחרות יותר"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2003-maxim-restaurant-bombing-228"]={"title":"הפיגוע במסעדת מקסים","location":"חיפה, ישראל","story":"מחבלת מתאבדת תקפה את מסעדת מקסים בחיפה באוקטובר 2003 והרגה 21 בני אדם.","context":"הפיגוע היה מתקפה על מקום אזרחי שבו שהו יהודים וערבים והתרחש במהלך האינתיפאדה השנייה.","aftermath":"המתקפה החריפה את תחושת האיום על אזרחים והמשיכה את מעגל הפעולות והתגובות.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2003-quartet-roadmap-for-peace-229"]={"title":"מפת הדרכים לשלום של הקוורטט","location":"ישראל והשטחים הפלסטיניים","story":"ארצות הברית, האיחוד האירופי, האו״ם ורוסיה הציגו מפת דרכים מבוססת ביצועים שנועדה להוביל באמצעות צעדים ביטחוניים ופוליטיים הדדיים להסדר קבע של שתי מדינות. מועצת הביטחון אימצה את מפת הדרכים בהחלטה 1515.","context":"התוכנית ניסתה להחזיר תהליך מדיני מובנה לאחר ההרס של שנות האינתיפאדה השנייה.","aftermath":"היישום נתקע על רקע אלימות מתמשכת ומחלוקות פוליטיות, אך עקרון שתי המדינות נשאר מרכזי בדיפלומטיה הבינלאומית.","sourceStatus":"מפת הדרכים ואישור מועצת הביטחון מתועדים ישירות; היישום נתקע על רקע אלימות ומחלוקות פוליטיות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2005-israel-disengages-from-the-gaza-strip-230"]={"title":"ישראל מתנתקת מרצועת עזה","location":"רצועת עזה וצפון הגדה המערבית","story":"באוגוסט ובספטמבר 2005 פינתה ישראל את כל ההתנחלויות הישראליות בעזה וארבע התנחלויות בצפון הגדה והסיגה את הנוכחות הצבאית הקבועה מתוך הרצועה. כוחות הביטחון של הרשות הפלסטינית נכנסו לאזורי ההתנחלויות שפונו. ישראל המשיכה לשלוט בהיבטים חשובים של הגישה החיצונית לעזה, בעוד מצרים שלטה בצדה של מעבר רפיח במסגרת הסדרים מאוחרים יותר.","context":"ההתנתקות סיימה את ההתנחלויות ואת הנוכחות הצבאית הקבועה בתוך עזה אך לא פתרה את הסכסוך על גבולות, ביטחון, תנועה וריבונות.","aftermath":"ההתנתקות שינתה את מבנה העימות סביב עזה והקדימה את ניצחון חמאס בבחירות והפיצול הפוליטי הפלסטיני.","sourceStatus":"פינוי המתנחלים ונסיגת הנוכחות הקבועה של צה״ל מתועדים ישירות. השאלה המשפטית של מעמד הכיבוש בעזה לאחר ההתנתקות נותרה שנויה במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2006-hamas-wins-palestinian-legislative-election-231"]={"title":"חמאס מנצח בבחירות למועצה המחוקקת הפלסטינית","location":"השטחים הפלסטיניים","story":"חמאס זכה ברוב המושבים בבחירות למועצה המחוקקת הפלסטינית בינואר 2006. התוצאה יצרה משבר פוליטי גדול משום שחמאס לא קיבל את תנאי הקוורטט לוותר על אלימות, להכיר בישראל ולקבל הסכמים ישראליים–פלסטיניים קודמים.","context":"הבחירות העניקו לחמאס לגיטימציה אלקטורלית משמעותית אך גם החריפו את העימות בינו לבין פת״ח ואת המשבר מול ישראל והקהילה הבינלאומית.","aftermath":"המאבק על השלטון תרם לפיצול הפלסטיני בין עזה שבשליטת חמאס לבין הרשות הפלסטינית בגדה.","sourceStatus":"תוצאות הבחירות והמשבר הפוליטי הבינלאומי שאחריהן מתועדים היטב"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2006-gilad-shalit-captured-in-gaza-border-attack-232"]={"title":"גלעד שליט נשבה בהתקפה בגבול עזה","location":"כרם שלום / גבול עזה","story":"ב־25 ביוני 2006 חפרו חמושים פלסטינים מנהרה מעבר לגבול עזה ותקפו מוצב ישראלי, הרגו שני חיילים ישראלים ושבו את רב״ט גלעד שליט. ישראל פתחה בפעולות צבאיות גדולות בעזה. שליט נותר בשבי עד עסקת חילופי שבויים ב־2011.","context":"השבי והתגובה הישראלית הפכו למוקד מרכזי בעימות ישראל–חמאס לאחר ההתנתקות.","aftermath":"המשבר תרם להסלמה צבאית מתמשכת סביב עזה עד לשחרור שליט בעסקת 2011.","sourceStatus":"ההתקפה, ההרוגים, השבי והתקופה שלאחר מכן מתועדים היטב"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2006-second-lebanon-war-233"]={"title":"מלחמת לבנון השנייה","location":"ישראל ולבנון","story":"ב־12 ביולי 2006 חצו לוחמי חזבאללה את הגבול, הרגו חיילים ישראלים ושבו שניים. ישראל הגיבה במערכה אווירית וקרקעית רחבה בלבנון, וחזבאללה ירה אלפי רקטות לצפון ישראל. המלחמה גרמה לאבדות אזרחיות ולעקירה משמעותית בלבנון ובישראל.","context":"המלחמה שילבה מתקפת גבול של חזבאללה, ירי רקטות נרחב ותגובה צבאית ישראלית רחבת היקף.","aftermath":"הפסקת האש לפי החלטה 1701 של מועצת הביטחון סיימה את הלחימה הגדולה, אך חזבאללה וישראל המשיכו להתכונן לעימות עתידי.","sourceStatus":"המתקפה שפתחה את המלחמה, ירי הרקטות והתגובה הצבאית הישראלית מתועדים בהרחבה. הערכות ההתנהלות, המידתיות והתוצאה האסטרטגית נותרו שנויות במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2007-hamas-fatah-fighting-and-hamas-takeover-of-gaza-234"]={"title":"לחימת חמאס–פת״ח והשתלטות חמאס על עזה","location":"רצועת עזה","story":"לאחר חודשים של עימות גובר בין הפלגים הפלסטיניים הביסו כוחות חמאס את כוחות הביטחון המזוהים עם פת״ח והשתלטו על רצועת עזה ביוני 2007. המערכת הפוליטית הפלסטינית התפצלה: חמאס שלט בעזה והרשות הפלסטינית בראשות מחמוד עבאס שלטה בחלקים מהגדה.","context":"זה היה עימות פנים־פלסטיני אלים ולא קרב ישיר בין ישראל לפלסטינים.","aftermath":"הפיצול הפוליטי והגאוגרפי בין עזה לגדה הפך למאפיין מתמשך של הפוליטיקה הפלסטינית ושל הסכסוך.","sourceStatus":"ההשתלטות האלימה והפיצול הפוליטי מתועדים היטב. קיימות מחלוקות לגבי האחריות לקריסת הסדרי חלוקת הכוח הקודמים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2007-israel-tightens-blockade-of-the-gaza-strip-after-hamas-takeover-235"]={"title":"ישראל מחמירה את הסגר על רצועת עזה לאחר השתלטות חמאס","location":"רצועת עזה","story":"לאחר השתלטות חמאס על עזה הטילה ישראל הגבלות מחמירות יותר על תנועת אנשים וסחורות, ומצרים הגבילה גם היא את מעבר רפיח. ישראל נימקה זאת בצורכי ביטחון ובהתקפות מעזה; ארגונים הומניטריים תיעדו השפעות קשות על כלכלת עזה ועל האוכלוסייה האזרחית.","context":"הסגר נועד מבחינת ישראל להגביל יכולות חמאס והברחות נשק, אך השפיע באופן רחב על חיי האזרחים בעזה.","aftermath":"ההגבלות הפכו למרכיב מרכזי ומתמשך בעימות סביב עזה ולנושא של ביקורת ומחלוקת משפטית בינלאומית.","sourceStatus":"ההגבלות לאחר השתלטות חמאס מתועדות בהרחבה. חוקיותן, היקפן, השפעתן ההומניטרית והצדקתן הביטחונית נותרו שנויות במחלוקת חריפה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2007-annapolis-conference-attempts-to-restart-final-status-negotiations-236"]={"title":"ועידת אנאפוליס מנסה לחדש את המשא ומתן על הסדר הקבע","location":"אנאפוליס, מרילנד, ארצות הברית","story":"ראש ממשלת ישראל אהוד אולמרט ונשיא הרשות הפלסטינית מחמוד עבאס נפגשו בחסות ארצות הברית באנאפוליס והתחייבו לחדש משא ומתן שמטרתו הסכם שלום ויישום מפת הדרכים.","context":"הוועידה הייתה ניסיון להחזיר משא ומתן ישיר לאחר שנות האינתיפאדה, ההתנתקות והפיצול הפלסטיני.","aftermath":"המשא ומתן נמשך לאחר הוועידה אך לא הניב הסכם סופי.","sourceStatus":"הוועידה וההבנה המשותפת מתועדות ישירות. המשא ומתן נמשך לאחר מכן אך לא הניב הסכם סופי"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2008-mumbai-chabad-house-attack-237"]={"title":"ההתקפה על בית חב״ד במומבאי","location":"מומבאי, הודו","story":"במהלך מתקפות הטרור המתואמות במומבאי השתלטו מחבלים על מרכז חב״ד בבית נרימן ורצחו בני ערובה במקום.","context":"האירוע היה חלק ממתקפת טרור רחבה על מומבאי ובמקביל תקיפה מכוונת של מוסד יהודי.","aftermath":"ההתקפה הדגישה את הסיכון למוסדות יהודיים גם מחוץ לזירת הסכסוך הישראלי–פלסטיני.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2008-escalating-rocket-fire-and-israeli-strikes-around-gaza-238"]={"title":"הסלמת ירי הרקטות והתקיפות הישראליות סביב עזה","location":"רצועת עזה ודרום ישראל","story":"ארגונים פלסטיניים חמושים ירו רקטות ופצצות מרגמה מעזה לעבר יישובים בישראל, וישראל ביצעה תקיפות אוויריות, פשיטות ופעולות צבאיות אחרות בעזה. הפוגה של שישה חודשים הפחיתה את האלימות לזמן מה ב־2008, אך היא התפרקה על רקע חידוש ההתקפות והפעולות הצבאיות.","context":"הסמן מציג את ירי הרקטות והפעולות הישראליות יחד כחלק ממעגל הסלמה מתמשך.","aftermath":"קריסת ההפוגה הובילה ישירות להסלמה שהפכה למבצע עופרת יצוקה ולמלחמת עזה 2008–2009.","sourceStatus":"ירי הרקטות, התקיפות הישראליות והפוגת 2008 מתועדים היטב. רצף ההפרות והאחריות לקריסת ההפוגה שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2008-operation-cast-lead-2008-09-gaza-war-239"]={"title":"מבצע עופרת יצוקה / מלחמת עזה 2008–2009","location":"רצועת עזה ודרום ישראל","story":"ישראל פתחה במבצע עופרת יצוקה ב־27 בדצמבר 2008 לאחר הסלמה מחודשת בירי רקטות ובפעולות האיבה. המערכה כללה תקיפות אוויריות אינטנסיביות ולאחר מכן מתקפה קרקעית. ארגונים פלסטיניים חמושים המשיכו לירות רקטות לישראל. פלסטינים רבים, ובהם אזרחים, נהרגו, וכן חיילים ואזרחים ישראלים.","context":"המלחמה הייתה שיא של מעגל ממושך של ירי רקטות, סגר, תקיפות ופעולות צבאיות סביב עזה.","aftermath":"המלחמה הסתיימה בהפסקות אש חד־צדדיות אך לא פתרה את העימות הבסיסי בין ישראל לחמאס.","sourceStatus":"המלחמה והפעולות הצבאיות המרכזיות מתועדות בהרחבה. סיווגי הנפגעים, המידתיות והטענות להפרות המשפט הבינלאומי היו ונותרו שנויות במחלוקת"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2001-dolphinarium-discotheque-bombing-221"]={"title":"تفجير ديسكو الدلفيناريوم","location":"تل أبيب، إسرائيل","story":"هاجم انتحاري شبانًا كانوا ينتظرون خارج ملهى الدلفيناريوم في يونيو 2001؛ فقُتل 21 مدنيًا إسرائيليًا، معظمهم من المراهقين.","context":"كان التفجير هجومًا متعمدًا على المدنيين خلال الانتفاضة الثانية.","aftermath":"عمق الهجوم التصعيد والضغط الشعبي في إسرائيل من أجل رد أمني أشد.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2001-sbarro-restaurant-bombing-222"]={"title":"تفجير مطعم سبارو","location":"القدس، إسرائيل","story":"هاجم انتحاري مطعم سبارو المزدحم في القدس في أغسطس 2001، فقتل 15 مدنيًا.","context":"كان التفجير من أبرز الهجمات الانتحارية ضد المدنيين خلال الانتفاضة الثانية.","aftermath":"فاقم الهجوم دورة العنف وعمق انعدام الثقة بين الطرفين.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2001-taba-summit-continues-final-status-negotiations-223"]={"title":"قمة طابا تواصل مفاوضات الوضع النهائي","location":"طابا، مصر","story":"اجتمع مفاوضون إسرائيليون وفلسطينيون في طابا في يناير 2001 بعد فشل قمة كامب ديفيد وفي خضم الانتفاضة الثانية. وأفاد الطرفان بتضييق بعض الفجوات لكنهما لم يتوصلا إلى اتفاق نهائي قبل انتهاء المحادثات.","context":"أظهرت المحادثات أن المسار الدبلوماسي استمر حتى مع تصاعد العنف على الأرض.","aftermath":"انتهت القمة دون اتفاق وضعف المسار السياسي أكثر في الأشهر التالية.","sourceStatus":"القمة وعدم التوصل إلى تسوية نهائية موثقان جيدًا؛ تختلف التقييمات حول مدى اقتراب الطرفين من الاتفاق"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2002-passover-massacre-224"]={"title":"مذبحة عيد الفصح اليهودي","location":"نتانيا، إسرائيل","story":"هاجم انتحاري عشاء عيد الفصح اليهودي في فندق بارك بنتانيا خلال الانتفاضة الثانية، فقتل مدنيين وجرح كثيرين.","context":"كان الهجوم على مدنيين أثناء عيد يهودي ووقع في ذروة موجة التفجيرات الانتحارية.","aftermath":"كان الهجوم عاملًا مباشرًا رئيسيًا في قرار إسرائيل إطلاق عملية السور الواقي.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2002-operation-defensive-shield-225"]={"title":"عملية السور الواقي","location":"الضفة الغربية","story":"بعد موجة من التفجيرات الانتحارية الفلسطينية، ومنها مذبحة عيد الفصح، أطلقت إسرائيل عملية السور الواقي في مارس 2002 وأعادت دخول مدن فلسطينية رئيسية في الضفة. ووقعت معارك واعتقالات وأضرار واسعة، مع قتال شديد خصوصًا في جنين ونابلس.","context":"كانت العملية ردًا عسكريًا إسرائيليًا واسعًا على موجة الإرهاب، لكنها أثرت أيضًا بصورة كبيرة على السكان والمؤسسات الفلسطينية.","aftermath":"غيرت العملية البنية الأمنية في الضفة وعززت الوجود العسكري الإسرائيلي مجددًا في مناطق كانت قد نُقلت سابقًا إلى السيطرة الفلسطينية.","sourceStatus":"العملية وإعادة دخول مراكز سكانية رئيسية موثقتان بقوة. وكانت روايات الضحايا حول بعض المعارك، وخاصة جنين، موضع نزاع شديد"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2002-construction-of-the-west-bank-barrier-begins-226"]={"title":"بدء بناء حاجز الضفة الغربية","location":"الضفة الغربية ومنطقة القدس الشرقية","story":"بدأت إسرائيل بناء منظومة من الأسوار والجدران خلال الانتفاضة الثانية، مبررة ذلك بالحاجة إلى منع الانتحاريين ومهاجمين آخرين من الوصول إلى المراكز السكانية الإسرائيلية. ويمر جزء كبير من المسار داخل الضفة بدل خط هدنة 1949، ما أثار قضايا وصول وتهجير للفلسطينيين وجدلاً قانونيًا دوليًا كبيرًا.","context":"جمع الحاجز بين هدف أمني إسرائيلي وعواقب إقليمية وإنسانية مهمة على الفلسطينيين.","aftermath":"تنسب إسرائيل للحاجز دورًا في خفض الهجمات، بينما ظل مساره وآثاره محور نزاعات قانونية وسياسية.","sourceStatus":"البناء والمسار والمبرر الأمني موثقة. تنسب إسرائيل للحاجز دورًا في خفض الهجمات؛ وطعن فلسطينيون وهيئات دولية في أجزاء من مساره وآثاره الإنسانية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2002-arab-peace-initiative-227"]={"title":"مبادرة السلام العربية","location":"بيروت، لبنان","story":"في قمة جامعة الدول العربية ببيروت سنة 2002 أيدت الدول العربية مبادرة تعرض علاقات طبيعية مع إسرائيل مقابل انسحابها من الأراضي المحتلة سنة 1967، وحل متفق عليه لقضية اللاجئين الفلسطينيين، وإقامة دولة فلسطينية عاصمتها القدس الشرقية.","context":"قدمت المبادرة إطارًا إقليميًا لتسوية سياسية بينما كانت الانتفاضة الثانية مستعرة.","aftermath":"بقيت المبادرة مرجعًا دبلوماسيًا وأعادت الدول العربية تأكيدها في سنوات لاحقة.","sourceStatus":"المبادرة وشروطها الأساسية موثقة مباشرة وأعادت الدول العربية تأكيدها لاحقًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2003-maxim-restaurant-bombing-228"]={"title":"تفجير مطعم مكسيم","location":"حيفا، إسرائيل","story":"هاجمت انتحارية مطعم مكسيم في حيفا في أكتوبر 2003، فقتلت 21 شخصًا.","context":"كان الهجوم على موقع مدني يرتاده يهود وعرب ووقع خلال الانتفاضة الثانية.","aftermath":"فاقم التفجير الشعور بالخطر على المدنيين واستمرار دورة العمليات والردود.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2003-quartet-roadmap-for-peace-229"]={"title":"خريطة الطريق للسلام التي قدمتها اللجنة الرباعية","location":"إسرائيل والأراضي الفلسطينية","story":"قدمت الولايات المتحدة والاتحاد الأوروبي والأمم المتحدة وروسيا خريطة طريق قائمة على الأداء تهدف عبر خطوات أمنية وسياسية متبادلة إلى تسوية دائمة على أساس دولتين. وأيد مجلس الأمن الخطة في القرار 1515.","context":"حاولت الخطة إعادة مسار سياسي منظم بعد الدمار الذي خلفته سنوات الانتفاضة الثانية.","aftermath":"تعثر التنفيذ وسط استمرار العنف والخلافات السياسية، لكن مبدأ الدولتين بقي محوريًا في الدبلوماسية الدولية.","sourceStatus":"خريطة الطريق وتأييد مجلس الأمن موثقان مباشرة؛ تعثر التنفيذ وسط استمرار العنف والخلافات السياسية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2005-israel-disengages-from-the-gaza-strip-230"]={"title":"إسرائيل تنفذ فك الارتباط عن قطاع غزة","location":"قطاع غزة وشمال الضفة الغربية","story":"في أغسطس وسبتمبر 2005 أخلت إسرائيل جميع المستوطنات الإسرائيلية في غزة وأربعًا في شمال الضفة وسحبت وجودها العسكري الدائم من داخل القطاع. ودخلت قوات أمن السلطة الفلسطينية مناطق المستوطنات السابقة. واستمرت إسرائيل في السيطرة على جوانب مهمة من الوصول الخارجي لغزة، بينما سيطرت مصر على جانبها من معبر رفح بموجب ترتيبات لاحقة.","context":"أنهى فك الارتباط المستوطنات والوجود العسكري الدائم داخل غزة لكنه لم يحل النزاع على الحدود والأمن والحركة والسيادة.","aftermath":"غير فك الارتباط بنية الصراع حول غزة وسبق فوز حماس في الانتخابات والانقسام السياسي الفلسطيني.","sourceStatus":"إخلاء المستوطنين وانسحاب الوجود الدائم للجيش الإسرائيلي موثقان مباشرة. وظلت المسألة القانونية لوضع احتلال غزة بعد فك الارتباط محل خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2006-hamas-wins-palestinian-legislative-election-231"]={"title":"حماس تفوز بالانتخابات التشريعية الفلسطينية","location":"الأراضي الفلسطينية","story":"فازت حماس بأغلبية مقاعد المجلس التشريعي الفلسطيني في يناير 2006. وأدت النتيجة إلى أزمة سياسية كبرى لأن حماس لم تقبل شروط اللجنة الرباعية بنبذ العنف والاعتراف بإسرائيل وقبول الاتفاقيات الإسرائيلية الفلسطينية السابقة.","context":"منحت الانتخابات حماس شرعية انتخابية كبيرة لكنها عمقت أيضًا صراعها مع فتح والأزمة مع إسرائيل والمجتمع الدولي.","aftermath":"ساهم الصراع على السلطة في الانقسام الفلسطيني بين غزة التي تسيطر عليها حماس والسلطة الفلسطينية في الضفة.","sourceStatus":"نتيجة الانتخابات والأزمة السياسية الدولية اللاحقة موثقتان بقوة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2006-gilad-shalit-captured-in-gaza-border-attack-232"]={"title":"أسر جلعاد شاليط في هجوم على حدود غزة","location":"كرم أبو سالم / حدود غزة","story":"في 25 يونيو 2006 حفر مسلحون فلسطينيون نفقًا عبر حدود غزة وهاجموا موقعًا عسكريًا إسرائيليًا، فقتلوا جنديين وأسروا العريف جلعاد شاليط. وأطلقت إسرائيل عمليات عسكرية كبيرة في غزة. وبقي شاليط أسيرًا حتى صفقة تبادل سنة 2011.","context":"أصبح الأسر والرد الإسرائيلي محورًا رئيسيًا في مواجهة إسرائيل وحماس بعد فك الارتباط.","aftermath":"ساهمت الأزمة في تصعيد عسكري مستمر حول غزة حتى إطلاق شاليط في صفقة 2011.","sourceStatus":"الهجوم والقتلى والأسر وفترة الاحتجاز اللاحقة موثقة بقوة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2006-second-lebanon-war-233"]={"title":"حرب لبنان الثانية","location":"إسرائيل ولبنان","story":"في 12 يوليو 2006 عبر مقاتلو حزب الله الحدود وقتلوا جنودًا إسرائيليين وأسروا اثنين. وردت إسرائيل بحملة جوية وبرية كبيرة في لبنان، بينما أطلق حزب الله آلاف الصواريخ على شمال إسرائيل. وتسببت الحرب في خسائر مدنية ونزوح كبير في لبنان وإسرائيل.","context":"جمعت الحرب بين هجوم حزب الله عبر الحدود وقصف صاروخي واسع ورد عسكري إسرائيلي كبير.","aftermath":"أنهى وقف إطلاق النار بموجب قرار مجلس الأمن 1701 القتال الرئيسي، لكن حزب الله وإسرائيل واصلا الاستعداد لمواجهة مستقبلية.","sourceStatus":"الهجوم الذي بدأ الحرب وحملة الصواريخ والرد العسكري الإسرائيلي موثقة على نطاق واسع. تبقى تقييمات السلوك والتناسب والنتيجة الاستراتيجية محل خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2007-hamas-fatah-fighting-and-hamas-takeover-of-gaza-234"]={"title":"اقتتال حماس وفتح وسيطرة حماس على غزة","location":"قطاع غزة","story":"بعد أشهر من تصاعد الصراع بين الفصائل الفلسطينية هزمت قوات حماس قوات الأمن المتحالفة مع فتح وسيطرت على قطاع غزة في يونيو 2007. وانقسم النظام السياسي الفلسطيني، فسيطرت حماس على غزة بينما حكمت السلطة الفلسطينية بقيادة محمود عباس أجزاء من الضفة.","context":"كان هذا صراعًا فلسطينيًا داخليًا عنيفًا وليس مواجهة إسرائيلية فلسطينية مباشرة.","aftermath":"أصبح الانقسام السياسي والجغرافي بين غزة والضفة سمة دائمة للسياسة الفلسطينية وللصراع.","sourceStatus":"السيطرة العنيفة والانقسام السياسي موثقان بقوة. تختلف الروايات حول المسؤولية عن انهيار ترتيبات تقاسم السلطة السابقة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2007-israel-tightens-blockade-of-the-gaza-strip-after-hamas-takeover-235"]={"title":"إسرائيل تشدد حصار قطاع غزة بعد سيطرة حماس","location":"قطاع غزة","story":"بعد سيطرة حماس على غزة فرضت إسرائيل قيودًا أشد على حركة الأشخاص والبضائع، كما قيدت مصر معبر رفح. واستشهدت إسرائيل بمخاوف أمنية وهجمات من غزة؛ ووثقت منظمات إنسانية آثارًا كبيرة على اقتصاد غزة وسكانها المدنيين.","context":"استهدف الحصار من وجهة النظر الإسرائيلية تقييد قدرات حماس وتهريب السلاح، لكنه أثر بصورة واسعة في الحياة المدنية في غزة.","aftermath":"أصبحت القيود عنصرًا مركزيًا ودائمًا في الصراع حول غزة وموضوعًا لانتقاد ونزاع قانوني دولي.","sourceStatus":"القيود بعد سيطرة حماس موثقة على نطاق واسع. تبقى قانونيتها ونطاقها وأثرها الإنساني ومبرراتها الأمنية موضع نزاع شديد"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2007-annapolis-conference-attempts-to-restart-final-status-negotiations-236"]={"title":"مؤتمر أنابوليس يحاول استئناف مفاوضات الوضع النهائي","location":"أنابوليس، ماريلاند، الولايات المتحدة","story":"اجتمع رئيس الوزراء الإسرائيلي إيهود أولمرت ورئيس السلطة الفلسطينية محمود عباس برعاية أمريكية في أنابوليس والتزما بتجديد المفاوضات بهدف التوصل إلى اتفاق سلام وتنفيذ خريطة الطريق.","context":"كان المؤتمر محاولة لإعادة المفاوضات المباشرة بعد سنوات الانتفاضة وفك الارتباط والانقسام الفلسطيني.","aftermath":"استمرت المفاوضات بعد المؤتمر لكنها لم تنتج اتفاقًا نهائيًا.","sourceStatus":"المؤتمر والتفاهم المشترك موثقان مباشرة. استمرت المفاوضات بعده لكنها لم تنتج اتفاقًا نهائيًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2008-mumbai-chabad-house-attack-237"]={"title":"الهجوم على بيت حباد في مومباي","location":"مومباي، الهند","story":"خلال هجمات مومباي المنسقة استولى إرهابيون على مركز حباد اليهودي في ناريمان هاوس وقتلوا رهائن داخله.","context":"كان الحدث جزءًا من هجوم إرهابي أوسع على مومباي وفي الوقت نفسه استهدافًا متعمدًا لمؤسسة يهودية.","aftermath":"أبرز الهجوم الخطر على المؤسسات اليهودية حتى خارج ساحة الصراع الإسرائيلي الفلسطيني.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2008-escalating-rocket-fire-and-israeli-strikes-around-gaza-238"]={"title":"تصاعد إطلاق الصواريخ والغارات الإسرائيلية حول غزة","location":"قطاع غزة وجنوب إسرائيل","story":"أطلقت جماعات فلسطينية مسلحة صواريخ وقذائف هاون من غزة نحو بلدات إسرائيلية، بينما نفذت إسرائيل غارات جوية وعمليات توغل وأعمالًا عسكرية أخرى في غزة. وخفضت هدنة لستة أشهر العنف فترة من عام 2008، لكنها انهارت وسط تجدد الهجمات والعمليات العسكرية.","context":"يعرض المؤشر إطلاق الصواريخ والعمليات الإسرائيلية معًا كجزء من دورة تصعيد مستمرة.","aftermath":"أدى انهيار الهدنة مباشرة إلى التصعيد الذي أصبح عملية الرصاص المصبوب وحرب غزة 2008–2009.","sourceStatus":"إطلاق الصواريخ والغارات الإسرائيلية وهدنة 2008 موثقة جيدًا. تسلسل الانتهاكات والمسؤولية عن انهيار الهدنة موضع خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2008-operation-cast-lead-2008-09-gaza-war-239"]={"title":"عملية الرصاص المصبوب / حرب غزة 2008–2009","location":"قطاع غزة وجنوب إسرائيل","story":"بدأت إسرائيل عملية الرصاص المصبوب في 27 ديسمبر 2008 بعد تجدد التصعيد في إطلاق الصواريخ والأعمال العدائية. وشملت الحملة غارات جوية مكثفة ثم هجومًا بريًا. واستمرت الجماعات الفلسطينية المسلحة في إطلاق الصواريخ على إسرائيل. وقُتل عدد كبير من الفلسطينيين، بينهم مدنيون، كما قُتل جنود ومدنيون إسرائيليون.","context":"كانت الحرب ذروة دورة طويلة من إطلاق الصواريخ والحصار والغارات والعمليات العسكرية حول غزة.","aftermath":"انتهت الحرب بوقفات إطلاق نار أحادية الجانب لكنها لم تحل المواجهة الأساسية بين إسرائيل وحماس.","sourceStatus":"الحرب والعمليات العسكرية الرئيسية موثقة على نطاق واسع. كانت تصنيفات الضحايا والتناسب وادعاءات انتهاك القانون الدولي وما تزال موضع نزاع"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2011-gilad-shalit-prisoner-exchange-240"]={"title":"עסקת חילופי השבויים לשחרור גלעד שליט","location":"ישראל / עזה","story":"לאחר יותר מחמש שנות שבי בעזה שוחרר החייל הישראלי גלעד שליט באוקטובר 2011 בתמורה ליותר מאלף אסירים פלסטינים שהוחזקו בידי ישראל. העסקה המחישה את החשיבות הפוליטית של שבויים ואסירים בחברות הישראלית והפלסטינית.","context":"העסקה הייתה אירוע מרכזי ביחסי ישראל–חמאס והדגישה את המחיר ששני הצדדים ייחסו לשבויים ולאסירים.","aftermath":"שחרור שליט סיים את משבר השבי אך לא את העימות בין ישראל לחמאס.","sourceStatus":"השבי, המשא ומתן, העסקה והשחרור מתועדים היטב"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2012-toulouse-jewish-school-attack-241"]={"title":"ההתקפה על בית הספר היהודי בטולוז","location":"טולוז, צרפת","story":"חמוש תקף את בית הספר היהודי אוצר התורה ורצח מורה ושלושה ילדים.","context":"האירוע היה מתקפה אנטישמית מכוונת על מוסד יהודי וילדים יהודים בצרפת.","aftermath":"הרצח עורר זעזוע בצרפת ובקהילות יהודיות והגביר את תשומת הלב לאיום הטרור האנטישמי באירופה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2012-operation-pillar-of-defense-november-gaza-conflict-242"]={"title":"מבצע עמוד ענן / עימות עזה בנובמבר","location":"רצועת עזה וישראל","story":"שמונה ימים של לחימה אינטנסיבית החלו ב־14 בנובמבר 2012 כאשר ישראל הרגה את מפקד הזרוע הצבאית של חמאס אחמד ג'עברי. ישראל ביצעה תקיפות אוויריות נרחבות, וחמאס וארגונים פלסטיניים חמושים אחרים ירו רקטות לעבר מרכזי אוכלוסייה בישראל, כולל אזורי תל אביב וירושלים. הפסקת אש בתיווך מצרי סיימה את ההסלמה.","context":"העימות היה סבב נוסף במאבק בין ישראל לארגונים החמושים בעזה וכלל פגיעה וסיכון לאזרחים משני הצדדים.","aftermath":"הפסקת האש עצרה את הלחימה הגדולה זמנית אך לא פתרה את הסיבות הבסיסיות לעימות.","sourceStatus":"הפעולות הצבאיות והנפגעים האזרחיים משני הצדדים מתועדים בהרחבה. דיווחי האו״ם מתחו ביקורת על ירי רקטות פלסטיני חסר הבחנה ובחנו פגיעה באזרחים מתקיפות ישראליות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2012-palestine-becomes-a-un-non-member-observer-state-243"]={"title":"פלסטין מקבלת מעמד של מדינה משקיפה שאינה חברה באו״ם","location":"האומות המאוחדות, ניו יורק","story":"ב־29 בנובמבר 2012 אימצה העצרת הכללית של האו״ם את החלטה 67/19 והעניקה לפלסטין מעמד של מדינה משקיפה שאינה חברה באו״ם. המהלך לא פתר שאלות של ריבונות, גבולות או הכרה, אך חיזק את יכולתה של פלסטין להשתתף במוסדות בינלאומיים.","context":"המהלך היה הישג דיפלומטי פלסטיני משמעותי במסלול בינלאומי שהתנהל במקביל למשא ומתן ולעימות בשטח.","aftermath":"המעמד הרחיב את אפשרויות הפעולה הפלסטיניות בזירה הבינלאומית, בלי ליצור הסדר קבע עם ישראל.","sourceStatus":"הצבעת העצרת הכללית ושינוי המעמד מתועדים ישירות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2014-jerusalem-synagogue-attack-244"]={"title":"הפיגוע בבית הכנסת בירושלים","location":"ירושלים","story":"שני תוקפים פלסטינים חמושים באקדחים, סכינים וגרזנים תקפו מתפללים בבית כנסת בהר נוף בנובמבר 2014 והרגו מתפללים ושוטר.","context":"הפיגוע היה מתקפה מכוונת על מתפללים יהודים בבית כנסת.","aftermath":"המתקפה החריפה את המתיחות בירושלים ואת החשש מפני התקפות על מקומות תפילה.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2014-kidnapping-and-murder-of-three-israeli-teenagers-245"]={"title":"חטיפתם ורציחתם של שלושה נערים ישראלים","location":"הגדה המערבית","story":"ביוני 2014 נחטפו ונרצחו בגדה המערבית הנערים הישראלים אייל יפרח, גיל־עד שער ונפתלי פרנקל. ישראל פתחה במבצע חיפוש ומעצרים נרחב נגד רשתות חמאס. הרצח והפעולות שבאו בעקבותיו החריפו מאוד את המתיחות הישראלית–פלסטינית.","context":"האירוע היה חוליה מרכזית בשרשרת הסלמה שהובילה בקיץ 2014 לאלימות נוספת ולמלחמת עזה.","aftermath":"החיפושים, המעצרים, רצח מוחמד אבו חדיר וההסלמה בעזה התרחשו ברצף מהיר והעמיקו את המשבר.","sourceStatus":"החטיפה והרצח מתועדים היטב. ישראל ייחסה את ההתקפה לחברי חמאס; הנהגת חמאס חלקה בתחילה על אחריות ארגונית ישירה ובהמשך שיבחה את האחראים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2014-murder-of-palestinian-teenager-mohammed-abu-khdeir-246"]={"title":"רצח הנער הפלסטיני מוחמד אבו חדיר","location":"מזרח ירושלים","story":"ביולי 2014 נחטף ונרצח הנער הפלסטיני מוחמד אבו חדיר בידי יהודים ישראלים כנקמה לאחר רצח שלושת הנערים הישראלים. הרצח הצית מחאות פלסטיניות נרחבות ועימותים עם כוחות הביטחון הישראליים.","context":"האירוע היה מעשה אלימות קיצונית יהודית נגד אזרח פלסטיני והתרחש בתוך שרשרת נקמה והסלמה.","aftermath":"הרצח העמיק את המתיחות והפך לסמל של סכנת אלימות נקם בתוך הסכסוך.","sourceStatus":"החטיפה, הרצח ומניע הנקמה נקבעו בהליכים פליליים בישראל ומתועדים בהרחבה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2014-operation-protective-edge-2014-gaza-war-247"]={"title":"מבצע צוק איתן / מלחמת עזה 2014","location":"רצועת עזה וישראל","story":"לאחר שבועות של הסלמה פתחה ישראל ביולי 2014 במבצע צוק איתן נגד חמאס וארגונים חמושים אחרים בעזה. ישראל ביצעה תקיפות אוויריות ומתקפה קרקעית, בעוד ארגונים פלסטיניים ירו אלפי רקטות ופצצות מרגמה לעבר ישראל והשתמשו במנהרות חוצות גבול. המלחמה גרמה להרס נרחב ולמספר גבוה מאוד של נפגעים פלסטינים, ובהם אזרחים רבים, וכן למות חיילים ואזרחים ישראלים.","context":"המלחמה שילבה ירי רקטות והתקפות של ארגונים חמושים עם מערכה ישראלית רחבת היקף בתוך אזור מאוכלס בצפיפות.","aftermath":"הפסקת האש סיימה את הסבב הגדול אך עזה נותרה תחת סגר, חמאס נותר בשלטון והעימות הבסיסי לא נפתר.","sourceStatus":"המלחמה והפעולות המרכזיות מתועדות בהרחבה. הסיווג המדויק בין לוחמים לאזרחים, המידתיות והטענות להפרות המשפט ההומניטרי הבינלאומי נותרו שנויות במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2015-hyper-cacher-hostage-attack-248"]={"title":"התקפת בני הערובה בהיפר כשר","location":"פריז, צרפת","story":"חמוש תקף מרכול כשר בפריז והרג ארבעה בני ערובה יהודים.","context":"האירוע היה מתקפה אנטישמית מכוונת על יהודים במקום מסחרי יהודי.","aftermath":"ההתקפה, שהתרחשה ימים לאחר מתקפת שארלי הבדו, הגבירה את החשש מטרור אנטישמי בצרפת ובאירופה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2015-duma-arson-attack-kills-palestinian-dawabsheh-family-249"]={"title":"הצתת דומא הורגת את משפחת דוואבשה הפלסטינית","location":"דומא, הגדה המערבית","story":"ביולי 2015 הציתו תוקפים שני בתים פלסטיניים בכפר דומא והשאירו כתובות קיצוניות בעברית. עלי דוואבשה בן 18 חודשים והוריו מתו מפצעיהם; אחיו הצעיר שרד. הרשויות בישראל העמידו לדין קיצונים יהודים בקשר להתקפה.","context":"האירוע היה טרור יהודי קיצוני נגד משפחה פלסטינית אזרחית.","aftermath":"ההתקפה עוררה גינוי רחב והגבירה את תשומת הלב לאלימות קיצונית יהודית בגדה המערבית.","sourceStatus":"ההתקפה, מקרי המוות והמניע הקיצוני מתועדים היטב; בתי משפט בישראל הרשיעו בהמשך נאשם מרכזי"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2015-2015-2016-palestinian-stabbing-shooting-and-vehicle-ramming-wave-250"]={"title":"גל הדקירות, הירי והדריסות הפלסטיני 2015–2016","location":"ישראל, ירושלים והגדה המערבית","story":"החל מסוף 2015 ביצעו פלסטינים רבים פיגועי דקירה, ירי ודריסה נגד אזרחים ואנשי ביטחון ישראלים. כוחות ואזרחים ישראלים הרגו תוקפים רבים, ופלסטינים נהרגו גם בעימותים ובפעולות ביטחון. האלימות כונתה לעיתים 'אינתיפאדת הסכינים', אף שלא הייתה לה המסגרת הריכוזית של התקוממויות קודמות.","context":"הגל כלל התקפות רבות של יחידים לצד תגובות ביטחוניות ישראליות ועימותים רחבים יותר.","aftermath":"האלימות הגבירה את אמצעי הביטחון ואת המתיחות בירושלים ובגדה בלי להתפתח לתהליך מדיני חדש.","sourceStatus":"גל ההתקפות וההרוגים מתועד בהרחבה. המניעים השתנו ורבים מן המבצעים פעלו באופן עצמאי ולא תחת פיקוד ארגוני ישיר"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2016-un-security-council-resolution-2334-on-israeli-settlements-251"]={"title":"החלטה 2334 של מועצת הביטחון בנושא ההתנחלויות הישראליות","location":"האומות המאוחדות","story":"בדצמבר 2016 אימצה מועצת הביטחון את החלטה 2334, שקבעה כי להתנחלויות הישראליות בשטח שנכבש מאז 1967, כולל מזרח ירושלים, אין תוקף משפטי והן מהוות מכשול מרכזי לפתרון שתי המדינות. ישראל דחתה את עמדת ההחלטה.","context":"האירוע מייצג את המחלוקת המשפטית והדיפלומטית הבינלאומית המתמשכת סביב ההתנחלויות והשטחים.","aftermath":"ההחלטה הפכה לנקודת ייחוס מרכזית בדיון הבינלאומי על ההתנחלויות ועל פתרון שתי המדינות.","sourceStatus":"החלטת מועצת הביטחון ודחייתה בידי ישראל מתועדות ישירות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2017-united-states-recognizes-jerusalem-as-israel-s-capital-252"]={"title":"ארצות הברית מכירה בירושלים כבירת ישראל","location":"ירושלים / וושינגטון הבירה","story":"בדצמבר 2017 הכירה ארצות הברית בירושלים כבירת ישראל והודיעה על תוכנית להעביר אליה את שגרירותה. ישראל בירכה על ההחלטה, בעוד ההנהגה הפלסטינית וממשלות רבות התנגדו לה משום שמעמדה הסופי של ירושלים נותר בלתי פתור.","context":"המהלך שינה מדיניות אמריקאית ארוכת שנים והציב את שאלת ירושלים מחדש במרכז המחלוקת הדיפלומטית.","aftermath":"ההכרה קדמה לפתיחת השגרירות האמריקאית בירושלים ב־2018 והעמיקה את הקרע בין ארצות הברית להנהגה הפלסטינית.","sourceStatus":"ההכרה האמריקאית מתועדת ישירות. השלכותיה המשפטיות והדיפלומטיות נותרו שנויות במחלוקת בינלאומית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2018-pittsburgh-synagogue-shooting-253"]={"title":"הירי בבית הכנסת בפיטסבורג","location":"פיטסבורג, ארצות הברית","story":"חמוש תקף מתפללים במתחם בית הכנסת עץ חיים ורצח אחד־עשר בני אדם.","context":"האירוע היה מתקפה אנטישמית מכוונת על קהילה יהודית בזמן תפילה.","aftermath":"הטבח היה המתקפה האנטישמית הקטלנית ביותר נגד יהודים בתולדות ארצות הברית והוביל להתמקדות מחודשת באבטחת מוסדות יהודיים.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2018-gaza-border-protests-and-clashes-254"]={"title":"מחאות ועימותים בגבול עזה","location":"גבול עזה–ישראל","story":"החל במרץ 2018 קיימו פלסטינים הפגנות גדולות ליד גדר המערכת בעזה שכונו צעדת השיבה הגדולה. חלק מהמפגינים התקרבו לגדר או פגעו בה, השליכו אמצעי תבערה או מטענים, בעוד כוחות ישראליים השתמשו באש חיה, גז מדמיע ואמצעים נוספים. פלסטינים רבים נהרגו ונפצעו, ובהם אזרחים.","context":"האירועים שילבו מחאה המונית, ניסיונות חדירה ואלימות מצד חלק מהמשתתפים עם שימוש ישראלי בכוח קטלני לאורך הגבול.","aftermath":"מספר הנפגעים הפלסטינים והוויכוח על כללי הפתיחה באש הפכו לנושא מרכזי של ביקורת וחקירה בינלאומית.","sourceStatus":"המחאות, ניסיונות הפריצה ומספר הנפגעים הפלסטינים הגבוה מתועדים בהרחבה. נחיצות ומידתיות האש החיה הישראלית הפכו לנושא של מחלוקת משפטית בינלאומית משמעותית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2018-united-states-opens-embassy-in-jerusalem-255"]={"title":"ארצות הברית פותחת את שגרירותה בירושלים","location":"ירושלים","story":"ארצות הברית פתחה רשמית את שגרירותה בירושלים במאי 2018, ובכך יישמה את ההכרה שהוכרזה בשנה הקודמת. המהלך התרחש במקביל למחאות עזות בגבול עזה ונדחה בידי ההנהגה הפלסטינית.","context":"פתיחת השגרירות הפכה את שינוי המדיניות האמריקאית למהלך מעשי וסמלי בשטח.","aftermath":"המהלך חיזק את ההכרה האמריקאית בירושלים כבירת ישראל אך לא פתר את המחלוקת הבינלאומית על מעמד העיר.","sourceStatus":"העברת השגרירות והתגובות הבינלאומיות מתועדות ישירות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2019-poway-synagogue-shooting-256"]={"title":"הירי בבית הכנסת בפאוויי","location":"פאוויי, קליפורניה, ארצות הברית","story":"חמוש אנטישמי פתח באש בתוך בית חב״ד בפאוויי ביום האחרון של פסח, הרג מתפללת אחת ופצע שלושה נוספים, ובהם ילדה.","context":"האירוע היה מתקפה אנטישמית על מתפללים יהודים בבית כנסת.","aftermath":"הירי חיזק את החשש מהתגברות אלימות אנטישמית בארצות הברית לאחר פיטסבורג.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2019-halle-synagogue-attack-257"]={"title":"ההתקפה על בית הכנסת בהאלה","location":"האלה, גרמניה","story":"קיצוני חמוש ניסה להיכנס לבית כנסת ביום הכיפורים; לאחר שלא הצליח להיכנס, רצח שני אנשים בקרבת מקום.","context":"האירוע היה ניסיון למתקפה אנטישמית המונית על מתפללים יהודים ביום הקדוש ביותר בלוח השנה היהודי.","aftermath":"הדלת המאובטחת מנעה כניסה לבית הכנסת, והאירוע הגביר את הדיון באבטחת קהילות יהודיות בגרמניה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2020-monsey-hanukkah-stabbing-258"]={"title":"פיגוע הדקירה בחנוכה במונסי","location":"מונסי, ניו יורק, ארצות הברית","story":"במהלך התכנסות חנוכה בביתו של רב דקר תוקף מספר אנשים; אחד הקורבנות מת בהמשך מפצעיו.","context":"האירוע היה מתקפה על יהודים במהלך חגיגה דתית בבית פרטי.","aftermath":"ההתקפה הגבירה את הדאגה מאלימות אנטישמית נגד קהילות יהודיות באזור ניו יורק.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2020-abraham-accords-normalize-israel-s-relations-with-arab-states-259"]={"title":"הסכמי אברהם מנרמלים את יחסי ישראל עם מדינות ערב","location":"ישראל, איחוד האמירויות, בחריין והאזור","story":"ב־2020 הסכמים בתיווך ארצות הברית יצרו או קידמו נורמליזציה בין ישראל לבין איחוד האמירויות, בחריין, מרוקו וסודאן. ההסכמים סימנו שינוי משמעותי בדיפלומטיה הערבית–ישראלית משום שהנורמליזציה התקדמה ללא הסכם שלום ישראלי–פלסטיני קודם.","context":"ההסכמים יצרו מסלול אזורי חדש שהתפתח בנפרד במידה רבה מן הסכסוך הישראלי–פלסטיני הבלתי פתור.","aftermath":"הנורמליזציה הרחיבה קשרים דיפלומטיים, כלכליים וביטחוניים בין ישראל לחלק ממדינות ערב ושינתה את מבנה הדיפלומטיה האזורית.","sourceStatus":"ההסכמים וצעדי הנורמליזציה מתועדים ישירות; היישום ומעמדם של הסדרים דו־צדדיים מסוימים השתנו"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2011-gilad-shalit-prisoner-exchange-240"]={"title":"صفقة تبادل الأسرى لإطلاق جلعاد شاليط","location":"إسرائيل / غزة","story":"بعد أكثر من خمس سنوات في الأسر بغزة أُطلق الجندي الإسرائيلي جلعاد شاليط في أكتوبر 2011 مقابل أكثر من ألف أسير فلسطيني لدى إسرائيل. وأظهرت الصفقة الأهمية السياسية للأسرى والمحتجزين في المجتمعين الإسرائيلي والفلسطيني.","context":"كانت الصفقة حدثًا رئيسيًا في علاقة إسرائيل وحماس وأبرزت القيمة التي يوليها الطرفان للأسرى.","aftermath":"أنهى إطلاق شاليط أزمة أسره لكنه لم ينهِ المواجهة بين إسرائيل وحماس.","sourceStatus":"الأسر والمفاوضات والتبادل والإفراج موثقة بقوة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2012-toulouse-jewish-school-attack-241"]={"title":"الهجوم على المدرسة اليهودية في تولوز","location":"تولوز، فرنسا","story":"هاجم مسلح مدرسة أوزار هاتوراه اليهودية وقتل مدرسًا وثلاثة أطفال.","context":"كان الحدث هجومًا معاديًا للسامية استهدف مؤسسة يهودية وأطفالًا يهودًا في فرنسا.","aftermath":"أثار القتل صدمة في فرنسا والجاليات اليهودية وزاد الاهتمام بخطر الإرهاب المعادي للسامية في أوروبا.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2012-operation-pillar-of-defense-november-gaza-conflict-242"]={"title":"عملية عمود السحاب / صراع غزة في نوفمبر","location":"قطاع غزة وإسرائيل","story":"بدأت ثمانية أيام من القتال المكثف في 14 نوفمبر 2012 عندما قتلت إسرائيل قائد الجناح العسكري لحماس أحمد الجعبري. ونفذت إسرائيل غارات جوية واسعة، بينما أطلقت حماس وجماعات فلسطينية مسلحة أخرى صواريخ نحو مراكز سكانية إسرائيلية، بما فيها منطقتا تل أبيب والقدس. وأنهى وقف إطلاق نار بوساطة مصرية التصعيد.","context":"كان الصراع جولة أخرى من المواجهة بين إسرائيل والجماعات المسلحة في غزة وشمل أذى ومخاطر على المدنيين من الجانبين.","aftermath":"أوقف وقف النار القتال الكبير مؤقتًا لكنه لم يحل أسباب المواجهة الأساسية.","sourceStatus":"العمليات العسكرية والضحايا المدنيون على الجانبين موثقة على نطاق واسع. انتقدت تقارير الأمم المتحدة إطلاق الصواريخ الفلسطينية العشوائي ودرست الضرر المدني من الغارات الإسرائيلية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2012-palestine-becomes-a-un-non-member-observer-state-243"]={"title":"فلسطين تصبح دولة مراقبة غير عضو في الأمم المتحدة","location":"الأمم المتحدة، نيويورك","story":"في 29 نوفمبر 2012 اعتمدت الجمعية العامة القرار 67/19 ومنحت فلسطين صفة دولة مراقبة غير عضو في الأمم المتحدة. لم يحسم القرار قضايا السيادة أو الحدود أو الاعتراف، لكنه عزز قدرة فلسطين على المشاركة في المؤسسات الدولية.","context":"كان التحرك إنجازًا دبلوماسيًا فلسطينيًا مهمًا ضمن مسار دولي سار بالتوازي مع المفاوضات والصراع على الأرض.","aftermath":"وسع الوضع الجديد خيارات العمل الفلسطيني دوليًا دون إنشاء تسوية نهائية مع إسرائيل.","sourceStatus":"تصويت الجمعية العامة وتغيير الوضع موثقان مباشرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2014-jerusalem-synagogue-attack-244"]={"title":"الهجوم على كنيس في القدس","location":"القدس","story":"هاجم فلسطينيان مسلحان بالبنادق والسكاكين والفؤوس مصلين في كنيس بحي هار نوف في نوفمبر 2014، فقتلا مصلين وضابط شرطة.","context":"كان الهجوم استهدافًا متعمدًا لمصلين يهود داخل كنيس.","aftermath":"فاقم الهجوم التوتر في القدس والمخاوف من استهداف أماكن العبادة.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2014-kidnapping-and-murder-of-three-israeli-teenagers-245"]={"title":"اختطاف وقتل ثلاثة مراهقين إسرائيليين","location":"الضفة الغربية","story":"في يونيو 2014 اختُطف وقُتل المراهقون الإسرائيليون إيال يفراح وجلعاد شاعر ونفتالي فرنكل في الضفة الغربية. وأطلقت إسرائيل عملية بحث واعتقالات واسعة ضد شبكات حماس. وأدت عمليات القتل وما تبعها إلى تصعيد حاد في التوتر الإسرائيلي الفلسطيني.","context":"كان الحدث حلقة مركزية في سلسلة تصعيد قادت إلى مزيد من العنف وحرب غزة في صيف 2014.","aftermath":"جرت عمليات البحث والاعتقالات وقتل محمد أبو خضير والتصعيد في غزة في تعاقب سريع وعمقت الأزمة.","sourceStatus":"الاختطاف والقتل موثقان بقوة. نسبت إسرائيل الهجوم إلى أعضاء في حماس؛ ونازعت قيادة حماس أولًا المسؤولية التنظيمية المباشرة ثم أشادت لاحقًا بالمسؤولين"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2014-murder-of-palestinian-teenager-mohammed-abu-khdeir-246"]={"title":"قتل الفتى الفلسطيني محمد أبو خضير","location":"القدس الشرقية","story":"في يوليو 2014 اختُطف الفتى الفلسطيني محمد أبو خضير وقُتل على يد يهود إسرائيليين في هجوم انتقامي بعد قتل المراهقين الإسرائيليين الثلاثة. وأثار قتله احتجاجات فلسطينية واسعة واشتباكات مع قوات الأمن الإسرائيلية.","context":"كان الحدث عنفًا يهوديًا متطرفًا ضد مدني فلسطيني ضمن سلسلة من الانتقام والتصعيد.","aftermath":"عمق القتل التوتر وأصبح رمزًا لخطر العنف الانتقامي داخل الصراع.","sourceStatus":"ثبت الاختطاف والقتل ودافع الانتقام في إجراءات جنائية إسرائيلية وهي موثقة على نطاق واسع"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2014-operation-protective-edge-2014-gaza-war-247"]={"title":"عملية الجرف الصامد / حرب غزة 2014","location":"قطاع غزة وإسرائيل","story":"بعد أسابيع من تصاعد العنف أطلقت إسرائيل عملية الجرف الصامد في يوليو 2014 ضد حماس وجماعات مسلحة أخرى في غزة. ونفذت إسرائيل غارات جوية وهجومًا بريًا، بينما أطلقت الجماعات الفلسطينية آلاف الصواريخ وقذائف الهاون نحو إسرائيل واستخدمت أنفاقًا عابرة للحدود. وتسببت الحرب بدمار واسع وخسائر فلسطينية مرتفعة جدًا، بينها مدنيون كثيرون، إضافة إلى قتلى عسكريين ومدنيين إسرائيليين.","context":"جمعت الحرب بين إطلاق الصواريخ وهجمات الجماعات المسلحة وحملة عسكرية إسرائيلية واسعة داخل منطقة كثيفة السكان.","aftermath":"أنهى وقف النار الجولة الكبرى لكن غزة بقيت تحت الحصار وحماس في السلطة وبقي الصراع الأساسي دون حل.","sourceStatus":"الحرب والعمليات الرئيسية موثقة على نطاق واسع. تبقى التصنيفات الدقيقة للمقاتلين والمدنيين والتناسب وادعاءات انتهاك القانون الإنساني الدولي موضع نزاع"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2015-hyper-cacher-hostage-attack-248"]={"title":"هجوم الرهائن في متجر هايبر كاشير","location":"باريس، فرنسا","story":"هاجم مسلح متجرًا يهوديًا للأطعمة الحلال دينيًا في باريس وقتل أربعة رهائن يهود.","context":"كان الحدث هجومًا معاديًا للسامية استهدف يهودًا في متجر يهودي.","aftermath":"وقع الهجوم بعد أيام من هجوم شارلي إيبدو وزاد المخاوف من الإرهاب المعادي للسامية في فرنسا وأوروبا.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2015-duma-arson-attack-kills-palestinian-dawabsheh-family-249"]={"title":"هجوم إحراق دوما يقتل عائلة دوابشة الفلسطينية","location":"دوما، الضفة الغربية","story":"في يوليو 2015 أضرم مهاجمون النار في منزلين فلسطينيين في قرية دوما وتركوا كتابات عبرية متطرفة. وتوفي علي دوابشة، البالغ 18 شهرًا، ووالداه لاحقًا متأثرين بجراحهم؛ ونجا شقيقه الصغير. وحاكمت السلطات الإسرائيلية متطرفين يهودًا على صلة بالهجوم.","context":"كان الحدث إرهابًا يهوديًا متطرفًا ضد عائلة فلسطينية مدنية.","aftermath":"أثار الهجوم إدانة واسعة وزاد الاهتمام بالعنف اليهودي المتطرف في الضفة الغربية.","sourceStatus":"الهجوم والوفيات والدافع المتطرف موثقة بقوة؛ وأدانت محاكم إسرائيلية لاحقًا متهمًا رئيسيًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2015-2015-2016-palestinian-stabbing-shooting-and-vehicle-ramming-wave-250"]={"title":"موجة الطعن وإطلاق النار والدهس الفلسطينية 2015–2016","location":"إسرائيل والقدس والضفة الغربية","story":"ابتداءً من أواخر 2015 نفذ فلسطينيون عديدون هجمات طعن وإطلاق نار ودهس ضد مدنيين وأفراد أمن إسرائيليين. وقتلت القوات والمدنيون الإسرائيليون مهاجمين كثيرين، كما قُتل فلسطينيون خلال اشتباكات وعمليات أمنية. وسميت الموجة أحيانًا 'انتفاضة السكاكين' رغم افتقارها إلى البنية المركزية للانتفاضات السابقة.","context":"شملت الموجة هجمات فردية كثيرة إلى جانب ردود أمنية إسرائيلية ومواجهات أوسع.","aftermath":"زادت أعمال العنف الإجراءات الأمنية والتوتر في القدس والضفة دون أن تنتج مسارًا سياسيًا جديدًا.","sourceStatus":"موجة الهجمات والوفيات موثقة على نطاق واسع. اختلفت الدوافع وعمل كثير من المنفذين بصورة فردية لا تحت قيادة تنظيمية مباشرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2016-un-security-council-resolution-2334-on-israeli-settlements-251"]={"title":"قرار مجلس الأمن 2334 بشأن المستوطنات الإسرائيلية","location":"الأمم المتحدة","story":"في ديسمبر 2016 اعتمد مجلس الأمن القرار 2334 الذي قال إن المستوطنات الإسرائيلية في الأراضي المحتلة منذ 1967، بما فيها القدس الشرقية، لا تتمتع بشرعية قانونية وتشكل عقبة كبيرة أمام حل الدولتين. ورفضت إسرائيل موقف القرار.","context":"يمثل الحدث النزاع القانوني والدبلوماسي الدولي المستمر حول المستوطنات والأراضي.","aftermath":"أصبح القرار مرجعًا رئيسيًا في النقاش الدولي بشأن المستوطنات وحل الدولتين.","sourceStatus":"قرار مجلس الأمن ورفض إسرائيل له موثقان مباشرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2017-united-states-recognizes-jerusalem-as-israel-s-capital-252"]={"title":"الولايات المتحدة تعترف بالقدس عاصمة لإسرائيل","location":"القدس / واشنطن العاصمة","story":"في ديسمبر 2017 اعترفت الولايات المتحدة بالقدس عاصمة لإسرائيل وأعلنت خططًا لنقل سفارتها إليها. ورحبت إسرائيل بالقرار، بينما عارضته القيادة الفلسطينية وحكومات عديدة لأن الوضع النهائي للقدس بقي دون حل.","context":"غيّر القرار سياسة أمريكية استمرت عقودًا وأعاد مسألة القدس إلى مركز الخلاف الدبلوماسي.","aftermath":"سبق الاعتراف افتتاح السفارة الأمريكية في القدس سنة 2018 وعمق القطيعة بين الولايات المتحدة والقيادة الفلسطينية.","sourceStatus":"الاعتراف الأمريكي موثق مباشرة. تبقى آثاره القانونية والدبلوماسية محل خلاف دولي"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2018-pittsburgh-synagogue-shooting-253"]={"title":"إطلاق النار في كنيس بيتسبرغ","location":"بيتسبرغ، الولايات المتحدة","story":"هاجم مسلح المصلين في مجمع كنيس شجرة الحياة وقتل أحد عشر شخصًا.","context":"كان الحدث هجومًا معاديًا للسامية استهدف جماعة يهودية أثناء الصلاة.","aftermath":"كانت المذبحة أعنف هجوم معادٍ للسامية ضد اليهود في تاريخ الولايات المتحدة وأدت إلى تركيز متجدد على أمن المؤسسات اليهودية.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2018-gaza-border-protests-and-clashes-254"]={"title":"احتجاجات واشتباكات حدود غزة","location":"حدود غزة–إسرائيل","story":"ابتداءً من مارس 2018 نظم فلسطينيون مظاهرات كبيرة قرب السياج المحيط بغزة عُرفت بمسيرة العودة الكبرى. واقترب بعض المتظاهرين من السياج أو ألحقوا به أضرارًا وألقوا مواد حارقة أو متفجرات، بينما استخدمت القوات الإسرائيلية الذخيرة الحية والغاز المسيل للدموع ووسائل أخرى. وقُتل وجُرح عدد كبير من الفلسطينيين، بينهم مدنيون.","context":"جمعت الأحداث بين احتجاج جماهيري ومحاولات اختراق وعنف من بعض المشاركين واستخدام إسرائيلي للقوة المميتة على طول الحدود.","aftermath":"أصبح العدد الكبير من الضحايا الفلسطينيين والجدل حول قواعد إطلاق النار موضوعًا رئيسيًا للنقد والتحقيق الدولي.","sourceStatus":"الاحتجاجات ومحاولات اختراق الحدود والعدد الكبير من الضحايا الفلسطينيين موثقة على نطاق واسع. أصبحت ضرورة وتناسب استخدام إسرائيل للذخيرة الحية موضوع نزاع قانوني دولي كبير"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2018-united-states-opens-embassy-in-jerusalem-255"]={"title":"الولايات المتحدة تفتح سفارتها في القدس","location":"القدس","story":"افتتحت الولايات المتحدة رسميًا سفارتها في القدس في مايو 2018، منفذة الاعتراف المعلن في العام السابق. وتزامن التحرك مع احتجاجات حدودية شديدة في غزة ورفضته القيادة الفلسطينية.","context":"حول افتتاح السفارة تغير السياسة الأمريكية إلى خطوة عملية ورمزية على الأرض.","aftermath":"عزز التحرك الاعتراف الأمريكي بالقدس عاصمة لإسرائيل لكنه لم يحل الخلاف الدولي على وضع المدينة.","sourceStatus":"نقل السفارة وردود الفعل الدولية موثقة مباشرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2019-poway-synagogue-shooting-256"]={"title":"إطلاق النار في كنيس باواي","location":"باواي، كاليفورنيا، الولايات المتحدة","story":"فتح مسلح معادٍ للسامية النار داخل حباد باواي في اليوم الأخير من عيد الفصح اليهودي، فقتل مصلية وأصاب ثلاثة آخرين، بينهم طفلة.","context":"كان الحدث هجومًا معاديًا للسامية على مصلين يهود داخل كنيس.","aftermath":"زاد إطلاق النار المخاوف من تصاعد العنف المعادي للسامية في الولايات المتحدة بعد بيتسبرغ.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2019-halle-synagogue-attack-257"]={"title":"الهجوم على كنيس هاله","location":"هاله، ألمانيا","story":"حاول متطرف مسلح دخول كنيس في يوم الغفران؛ ولما عجز عن الدخول قتل شخصين في الجوار.","context":"كان الحدث محاولة لتنفيذ هجوم جماعي معادٍ للسامية ضد مصلين يهود في أقدس أيام التقويم اليهودي.","aftermath":"منع الباب المحصن دخول المهاجم وزاد الحدث النقاش حول حماية المجتمعات اليهودية في ألمانيا.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2020-monsey-hanukkah-stabbing-258"]={"title":"هجوم الطعن في حانوكا بمونسي","location":"مونسي، نيويورك، الولايات المتحدة","story":"خلال تجمع لحانوكا في منزل حاخام طعن مهاجم عدة أشخاص؛ وتوفي أحد الضحايا لاحقًا متأثرًا بجراحه.","context":"كان الحدث هجومًا على يهود خلال احتفال ديني في منزل خاص.","aftermath":"زاد الهجوم القلق من العنف المعادي للسامية ضد المجتمعات اليهودية في منطقة نيويورك.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2020-abraham-accords-normalize-israel-s-relations-with-arab-states-259"]={"title":"اتفاقيات أبراهام تطبع علاقات إسرائيل مع دول عربية","location":"إسرائيل والإمارات والبحرين والمنطقة","story":"في 2020 أنشأت أو طورت اتفاقيات بوساطة أمريكية التطبيع بين إسرائيل والإمارات العربية المتحدة والبحرين والمغرب والسودان. ومثلت الاتفاقيات تحولًا كبيرًا في الدبلوماسية العربية الإسرائيلية لأن التطبيع تقدم دون تسوية سلام إسرائيلية فلسطينية مسبقة.","context":"أنشأت الاتفاقيات مسارًا إقليميًا جديدًا تطور إلى حد كبير بصورة منفصلة عن الصراع الإسرائيلي الفلسطيني غير المحلول.","aftermath":"وسع التطبيع العلاقات الدبلوماسية والاقتصادية والأمنية بين إسرائيل وبعض الدول العربية وغير بنية الدبلوماسية الإقليمية.","sourceStatus":"الاتفاقيات وخطوات التطبيع موثقة مباشرة؛ اختلف التنفيذ ووضع بعض الترتيبات الثنائية"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2021-may-2021-jerusalem-crisis-and-israel-hamas-war-260"]={"title":"משבר ירושלים ומלחמת ישראל–חמאס במאי 2021","location":"ירושלים, רצועת עזה וישראל","story":"מתחים סביב שייח' ג'ראח, הגבלות בתקופת רמדאן ועימותים באתרים הקדושים בירושלים החריפו במאי 2021. חמאס ירה רקטות לעבר ירושלים וערים ישראליות נוספות; ישראל הגיבה במערכה אווירית אינטנסיבית בעזה. במהלך 11 ימי לחימה נורו אלפי רקטות מעזה ומאות תקיפות ישראליות פגעו ברצועה.","context":"האירוע משלב משבר בירושלים, ירי רקטות של חמאס וארגונים נוספים ותגובה צבאית ישראלית רחבת היקף.","aftermath":"הלחימה הסתיימה בהפסקת אש אך הסוגיות בירושלים, בעזה וביחסי ישראל–חמאס נותרו בלתי פתורות.","sourceStatus":"ההסלמה, ירי הרקטות, התקיפות הישראליות והנפגעים מתועדים בהרחבה. דיווחי האו״ם תיעדו 253 פלסטינים שנהרגו במהלך הלחימה ו־13 בני אדם שנהרגו בישראל, בעוד סיווגי הנפגעים וחוקיות תקיפות מסוימות נותרו במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2021-jewish-arab-communal-violence-in-mixed-israeli-cities-261"]={"title":"אלימות בין יהודים לערבים בערים מעורבות בישראל","location":"לוד, עכו, יפו וערים ישראליות נוספות","story":"במקביל לעימות בעזה במאי 2021 פרצה אלימות קהילתית חמורה בתוך ישראל. המונים יהודים וערבים תקפו בני אדם, בתים, עסקים, כלי רכב ואתרים דתיים במספר ערים מעורבות. האלימות כללה הרג ותקיפות וחשפה מתחים עמוקים בין אזרחים יהודים וערבים.","context":"הסמן מייחס במפורש אלימות לקבוצות יהודיות וערביות כאחד ואינו מציג את האירועים כאלימות חד־צדדית.","aftermath":"האירועים עוררו דיון מחודש ביחסי יהודים–ערבים בתוך ישראל, בשיטור ובפערים חברתיים ופוליטיים.","sourceStatus":"אלימות מצד קבוצות יהודיות וערביות מתועדת בהרחבה. לאירועים בודדים היו מבצעים ונסיבות שונים ואין לצמצמם לייחוס חד־צדדי"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2022-colleyville-synagogue-hostage-crisis-262"]={"title":"משבר בני הערובה בבית הכנסת בקוליוויל","location":"קוליוויל, טקסס, ארצות הברית","story":"אדם חמוש לקח מתפללים כבני ערובה בקהילת בית ישראל בינואר 2022. בני הערובה נמלטו או חולצו לבסוף; התוקף נהרג.","context":"האירוע היה מתקפה על בית כנסת ומתפללים יהודים בארצות הברית.","aftermath":"המשבר הסתיים ללא מות בני הערובה והגביר את תשומת הלב לאבטחת בתי כנסת ומוסדות יהודיים.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2022-west-bank-violence-reaches-highest-palestinian-death-toll-in-years-263"]={"title":"האלימות בגדה מגיעה למספר ההרוגים הפלסטינים הגבוה ביותר זה שנים","location":"הגדה המערבית וישראל","story":"האלימות החריפה מאוד במהלך 2022. התקפות פלסטיניות הרגו ישראלים, בעוד פשיטות מעצר ועימותים חמושים ישראליים, במיוחד באזורי ג'נין ושכם, הרגו מספר הולך וגדל של פלסטינים. גם התקפות מתנחלים נגד פלסטינים גברו. האו״ם תיאר את 2022 כשנה שהייתה בדרכה להיות הקטלנית ביותר לפלסטינים בגדה מאז החל מעקב שיטתי ב־2005.","context":"הסמן מציג יחד התקפות פלסטיניות, פעולות כוחות ישראליים ואלימות מתנחלים, תוך הבחנה בין נסיבות שונות.","aftermath":"ההסלמה נמשכה לתוך 2023 והקדימה מבצעים צבאיים גדולים יותר ועלייה באלימות מצד חמושים ומתנחלים.","sourceStatus":"ההסלמה ומגמת הנפגעים מתועדות בהרחבה במעקב האו״ם. אירועים בודדים כללו אזרחים, חמושים, כוחות ביטחון ומתנחלים בנסיבות שונות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2023-huwara-attack-and-settler-rampage-264"]={"title":"הפיגוע בחווארה והתפרעות המתנחלים","location":"חווארה וכפרים סמוכים בגדה המערבית","story":"ב־26 בפברואר 2023 ירה חמוש פלסטיני למוות בשני אחים ישראלים ליד חווארה. שעות לאחר מכן תקפו מאות מתנחלים ישראלים את חווארה וקהילות פלסטיניות סמוכות והציתו בתים, חנויות וכלי רכב. פלסטיני אחד נהרג ורבים נפצעו.","context":"האירוע מוצג כרצף של פיגוע פלסטיני קטלני ולאחריו אלימות המונית של מתנחלים ישראלים נגד פלסטינים.","aftermath":"האירועים החריפו את המתיחות בגדה והביאו לגינויים ישראליים ובינלאומיים של אלימות המתנחלים.","sourceStatus":"גם רצח שני האחים הישראלים וגם התפרעות המתנחלים שבאה אחריו מתועדים בהרחבה. מנהיגים ישראלים, ובהם הנשיא, גינו את אלימות המתנחלים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2023-large-scale-israeli-operation-in-jenin-refugee-camp-265"]={"title":"מבצע ישראלי רחב היקף במחנה הפליטים ג'נין","location":"ג'נין, הגדה המערבית","story":"ב־3–4 ביולי 2023 פתחו כוחות ישראליים במבצע אווירי וקרקעי גדול בג'נין ובסביבת מחנה הפליטים, במטרה לפגוע בארגונים חמושים ובתשתיות נשק. חמושים פלסטינים החליפו אש עם הכוחות. פלסטינים, ובהם ילדים, נהרגו, רבים נפצעו ונגרם נזק לתשתיות במחנה.","context":"האירוע היה מבצע צבאי ישראלי נגד תשתיות חמושות בתוך אזור עירוני צפוף, עם לחימה ונזק לאזרחים ולתשתיות.","aftermath":"המבצע לא סיים את פעילות הארגונים החמושים בג'נין והעימותים באזור נמשכו.","sourceStatus":"המבצע, התקיפות האוויריות, חילופי האש והנפגעים מתועדים בהרחבה. הרשויות בישראל אמרו שהכוחות פגעו בתשתיות חמושים; ארגונים הומניטריים תיעדו פגיעה באזרחים ובעיות גישה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2023-october-7-hamas-led-attack-on-southern-israel-266"]={"title":"מתקפת 7 באוקטובר בהובלת חמאס על דרום ישראל","location":"דרום ישראל סמוך לרצועת עזה","story":"ב־7 באוקטובר 2023 פתחו חמאס וארגונים פלסטיניים חמושים נוספים במתקפה מתואמת על דרום ישראל תחת ירי רקטות כבד. תוקפים חדרו ליישובים, לפסטיבל מוזיקה ולאתרים צבאיים, הרגו במכוון אזרחים וחיילים וחטפו בני ערובה לעזה. לפי הנתונים הישראליים העדכניים נהרגו כ־1,200 ישראלים ואזרחים זרים ו־251 בני אדם נחטפו.","context":"הסמן מפריד את מתקפת 7 באוקטובר ואת הפגיעה המכוונת באזרחים מן המלחמה הישראלית בעזה שבאה בעקבותיה.","aftermath":"המתקפה הובילה למלחמת עזה רחבת ההיקף, למשבר בני ערובה ולהתרחבות העימות האזורי.","sourceStatus":"המתקפה המתואמת, הרג מכוון של אזרחים ולקיחת בני ערובה מתועדים בהרחבה. ועדת חקירה של האו״ם קבעה שחמאס וארגונים חמושים נוספים ביצעו פשעי מלחמה, ובהם רצח ולקיחת בני ערובה, ומצאה ראיות לאלימות מינית ומגדרית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2023-israel-launches-large-scale-gaza-war-after-october-7-267"]={"title":"ישראל פותחת במלחמה רחבת היקף בעזה לאחר 7 באוקטובר","location":"רצועת עזה","story":"ישראל הגיבה למתקפת 7 באוקטובר במערכה אווירית רחבת היקף ובפלישה קרקעית לעזה, והצהירה שמטרותיה הן פירוק חמאס והשבת החטופים. המערכה גרמה להרס עצום, לעקירה המונית ולמספר גבוה מאוד של הרוגים פלסטינים, ובהם אזרחים, בעוד חיילים ישראלים נהרגו בלחימה וארגונים פלסטיניים חמושים המשיכו לתקוף.","context":"הסמן מציג את המלחמה הישראלית כתגובה נפרדת למתקפת 7 באוקטובר ומאפשר לבחון באופן עצמאי את התנהלותה ואת השפעתה על אזרחי עזה.","aftermath":"המלחמה יצרה משבר הומניטרי עצום, עקירה רחבה, הליכים משפטיים בינלאומיים ומשא ומתן ממושך על הפסקת אש וחטופים.","sourceStatus":"היקף הפעולות הצבאיות, ההרס והעקירה מתועדים בהרחבה. מספרי ההרוגים הפלסטינים מדווחים בידי רשויות הבריאות בעזה ומשמשים בהרחבה את סוכנויות האו״ם, בעוד סיווגי לוחמים וטענות בדבר מידתיות, הרעבה, רצח עם והפרות אחרות נתונים להליכים משפטיים ולמחלוקת חריפה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2023-israel-hezbollah-border-conflict-expands-after-october-7-268"]={"title":"העימות בגבול ישראל–חזבאללה מתרחב לאחר 7 באוקטובר","location":"גבול ישראל–לבנון","story":"זמן קצר לאחר 7 באוקטובר החלו חזבאללה וישראל להחליף אש כמעט מדי יום לאורך גבול לבנון. חזבאללה אמר שהוא פועל לתמיכה בעזה; ישראל תקפה עמדות ומפקדים של חזבאללה. עשרות אלפי אזרחים משני צדי הגבול נעקרו מבתיהם ככל שהעימות החריף.","context":"העימות הפך את מלחמת עזה למשבר אזורי רחב יותר והציב את צפון ישראל ודרום לבנון תחת איום מתמשך.","aftermath":"הלחימה החריפה משמעותית במהלך 2024 והובילה לעימות רחב בהרבה בין ישראל לחזבאללה.","sourceStatus":"חילופי האש המתמשכים והעקירה ההמונית מתועדים בהרחבה. העימות החריף משמעותית במהלך 2024 ושוב בהמשך המלחמה האזורית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2024-iran-and-israel-exchange-direct-attacks-269"]={"title":"איראן וישראל מחליפות תקיפות ישירות","location":"ישראל ואיראן","story":"באפריל 2024 שיגרה איראן מאות כטב״מים וטילים לעבר ישראל לאחר תקיפה ישראלית במתחם דיפלומטי איראני בדמשק שבה נהרגו מפקדים איראנים בכירים. ישראל ובעלות בריתה יירטו את רוב האיומים, ובהמשך ביצעה ישראל תקיפה מוגבלת באיראן. חילופי התקיפות סימנו מעבר חסר תקדים ממלחמת הצללים ארוכת השנים לעימות ישיר בין המדינות.","context":"האירוע הרחיב את העימות האזורי מעבר לזירות השליחים והפך את ישראל ואיראן למשתתפות ישירות בתקיפות זו נגד זו.","aftermath":"חילופי התקיפות יצרו תקדים להסלמה ישירה נוספת בין שתי המדינות.","sourceStatus":"התקיפות והיירוטים מתועדים בהרחבה. התקיפה בדמשק יוחסה באופן נרחב לישראל, אף שישראל לא קיבלה עליה אחריות פומבית באותה עת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2024-israel-hezbollah-war-escalates-in-lebanon-270"]={"title":"מלחמת ישראל–חזבאללה מסלימה בלבנון","location":"לבנון וצפון ישראל","story":"העימות בין ישראל לחזבאללה החריף באופן דרמטי ב־2024 וכלל תקיפות ישראליות ברחבי לבנון, ירי רקטות וטילים של חזבאללה לעבר ישראל, הריגת בכירים בחזבאללה ופעולות קרקעיות ישראליות בדרום לבנון. אוכלוסיות אזרחיות גדולות נעקרו ומספר הנפגעים עלה בחדות.","context":"המלחמה התפתחה מן העימות הגבולי שהחל לאחר 7 באוקטובר לעימות צבאי רחב יותר.","aftermath":"ההסלמה שינתה את מאזן הכוחות בלבנון והובילה בסופו של דבר להסדרי הפסקת אש שבריריים.","sourceStatus":"ההסלמה, התקיפות, הלחימה הקרקעית והעקירה מתועדות בהרחבה. הערכות של תקיפות בודדות והעמידה במשפט ההומניטרי הבינלאומי נותרו שנויות במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2024-icj-advisory-opinion-on-israel-s-occupation-and-settlement-policies-271"]={"title":"חוות הדעת המייעצת של בית הדין הבינלאומי לצדק על הכיבוש ומדיניות ההתנחלויות של ישראל","location":"בית הדין הבינלאומי לצדק, האג","story":"ביולי 2024 פרסם בית הדין הבינלאומי לצדק חוות דעת מייעצת שקבעה כי המשך נוכחותה של ישראל בשטח הפלסטיני הכבוש אינו חוקי והתייחסה להשלכות של מדיניות ההתנחלויות והסיפוח. ישראל דחתה את מסקנות חוות הדעת ומתחה ביקורת על ההליך.","context":"האירוע הוא התפתחות משפטית בינלאומית ולא אירוע צבאי, והוא מוצג בנפרד כדי להבחין בין פסיקה משפטית, מדיניות ואלימות.","aftermath":"חוות הדעת הפכה לנקודת ייחוס מרכזית בדיון המשפטי והדיפלומטי על הכיבוש וההתנחלויות.","sourceStatus":"חוות הדעת היא מסמך סמכותי של בית הדין, אך היא מייעצת ואינה פסק דין המכריע בסכסוך בין מדינות שהסכימו להתדיין בפניו"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2025-gaza-ceasefire-and-hostage-prisoner-exchanges-272"]={"title":"הפסקת האש בעזה וחילופי חטופים–אסירים","location":"רצועת עזה וישראל","story":"הסדרי הפסקת אש במהלך המלחמה שלאחר 7 באוקטובר הובילו לעסקאות שבהן שוחררו חטופים ישראלים שהוחזקו בעזה בתמורה לאסירים ולעצורים פלסטינים. הפסקת אש מאוחרת יותר בתיווך אמריקאי, שהוסכמה באוקטובר 2025, סיימה את הלחימה בהיקף מלא, אף שתקיפות ישראליות נמשכו וסוגיות פוליטיות, הומניטריות וביטחוניות מרכזיות נותרו בלתי פתורות.","context":"ההסדרים שילבו סוגיית חטופים ואסירים עם ניסיון לעצור את המלחמה בלי להגיע להסדר מדיני כולל.","aftermath":"הפסקת האש הפחיתה את היקף הלחימה אך לא יצרה שלום יציב ולא פתרה את שאלת שלטון חמאס, ביטחון ישראל ושיקום עזה.","sourceStatus":"הפסקת האש והחילופים מתועדים. היישום נותר חלקי וההסכם לא יצר הסדר פוליטי כולל ולא הפסיק לחלוטין את האלימות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2026-gaza-after-the-2025-ceasefire-continuing-strikes-and-humanitarian-crisis-273"]={"title":"עזה לאחר הפסקת האש של 2025: תקיפות נמשכות ומשבר הומניטרי","location":"רצועת עזה","story":"עד 2026 הפסקת האש מאוקטובר 2025 סיימה את המלחמה בהיקף מלא אך לא יצרה שלום יציב. תקיפות ישראליות נמשכו, חמאס לא פורק מנשקו ועזה נותרה הרוסה משנות מלחמה. מחסור חמור, תשתיות פגועות ועקירה המשיכו להשפיע על אזרחים.","context":"הסמן מתייחס למצב כאל היסטוריה מתפתחת ולא כאל סיום מוסכם של המלחמה.","aftermath":"המצב ההומניטרי והביטחוני נותר בלתי יציב ותלוי בהמשך יישום הפסקת האש ובהסדרים פוליטיים עתידיים.","sourceStatus":"נכון לאוקטובר 2026. דיווחי רויטרס מצביעים על המשך תקיפות למרות הפסקת האש ועל משברי אנרגיה והומניטריים חמורים בעזה. מאחר שהתנאים ממשיכים להשתנות, יש לראות בסמן זה רשומה מתפתחת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2026-u-s-israel-campaign-against-iran-274"]={"title":"המערכה האמריקאית–ישראלית נגד איראן","location":"איראן והמזרח התיכון הרחב","story":"ב־2026 התרחב העימות האזורי למערכה צבאית ישירה של ארצות הברית וישראל נגד איראן, שתוארה בידי גורמים אמריקאים כמבצע Epic Fury. המלחמה יצרה השלכות אזוריות גדולות והשפיעה על דיפלומטיה, ביטחון אנרגיה ומדינות שכנות.","context":"האירוע מסמן שלב חדש שבו העימות עם איראן הפך ממלחמת צללים וחילופי תקיפות מוגבלים למערכה צבאית ישירה ורחבה יותר.","aftermath":"השלכות המערכה על איראן, ישראל, מדינות המפרץ, לבנון והסדר האזורי עדיין מתפתחות.","sourceStatus":"נכון לאוקטובר 2026. דיווחי רויטרס מאשרים את המערכה האמריקאית–ישראלית נגד איראן. פרטי המבצעים וההשלכות עדיין מתפתחים ויש לעדכנם ככל שיהיו זמינים תיעוד רשמי וארכיוני חזקים יותר"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2026-israel-hezbollah-ceasefire-after-renewed-lebanon-escalation-275"]={"title":"הפסקת אש בין ישראל לחזבאללה לאחר הסלמה מחודשת בלבנון","location":"ישראל ולבנון","story":"לאחר לחימה מחודשת הקשורה לעימות האזורי הרחב הסכימו ישראל וחזבאללה להפסקת אש שעליה הודיעה ארצות הברית ביוני 2026. כוחות ישראליים נותרו בדרום לבנון ותקיפות מוקדמות התרחשו סביב תחילת הפסקת האש, דבר שהדגיש את שבריריות ההסדר.","context":"הפסקת האש הגיעה לאחר שלב נוסף של הסלמה והייתה חלק מן הניסיון לבלום את המלחמה האזורית הרחבה.","aftermath":"עמידות ההסדר, שאלת הנוכחות הצבאית והסדרי הגבול נותרו פתוחים.","sourceStatus":"נכון לאוקטובר 2026. רויטרס דיווחה כי גורם אמריקאי, גורם ישראלי ומקורות בחזבאללה אישרו את הפסקת האש. עמידותה נותרה שאלה מתפתחת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-2026-2026-you-are-here-276"]={"title":"2026 — אתם כאן","location":"ההווה","story":"ציר הזמן מגיע להווה באוקטובר 2026. התיעוד ההיסטורי נשאר פתוח: עזה נמצאת בסביבה שברירית שלאחר מלחמה והפסקת אש, האלימות והעקירה הישראלית–פלסטינית לא נפתרו, והעימות האזורי הרחב הכולל את ישראל, איראן וחזבאללה יצר מלחמות והפסקות אש חדשות.","context":"זהו קצה חי של ציר הזמן ולא מסקנה היסטורית סופית. אירועים בני זמננו מוצגים בזהירות ובהפרדה בין עובדות מתועדות, טענות משפטיות ותוצאות שעדיין מתפתחות.","aftermath":"הפרק הבא עדיין נכתב, ולכן יש לעדכן את הסמן כאשר הסדרי הפסקת אש, חטופים, מלחמות, חקירות והסדרים מדיניים משתנים.","sourceStatus":"זוהי נקודת קצה חיה ולא מסקנה היסטורית סופית. עובדות עכשוויות, מספרי נפגעים, ממצאים משפטיים והסדרים פוליטיים עשויים להשתנות עם הופעת ראיות ורשומות סמכותיות חדשות"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2021-may-2021-jerusalem-crisis-and-israel-hamas-war-260"]={"title":"أزمة القدس وحرب إسرائيل وحماس في مايو 2021","location":"القدس وقطاع غزة وإسرائيل","story":"تصاعدت التوترات بشأن الشيخ جراح وقيود رمضان والاشتباكات في المواقع المقدسة بالقدس بشدة في مايو 2021. وأطلقت حماس صواريخ نحو القدس ومدن إسرائيلية أخرى؛ وردت إسرائيل بحملة جوية مكثفة في غزة. وخلال أحد عشر يومًا أُطلقت آلاف الصواريخ من غزة ونفذت إسرائيل مئات الغارات على القطاع.","context":"يجمع الحدث بين أزمة القدس وإطلاق الصواريخ من حماس وجماعات أخرى والرد العسكري الإسرائيلي الواسع.","aftermath":"انتهى القتال بوقف إطلاق نار لكن قضايا القدس وغزة والعلاقة بين إسرائيل وحماس بقيت دون حل.","sourceStatus":"التصعيد وإطلاق الصواريخ والغارات الإسرائيلية والضحايا موثقة على نطاق واسع. سجلت تقارير الأمم المتحدة مقتل 253 فلسطينيًا خلال الأعمال القتالية و13 شخصًا في إسرائيل، بينما ظلت تصنيفات الضحايا وقانونية ضربات فردية موضع نزاع"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2021-jewish-arab-communal-violence-in-mixed-israeli-cities-261"]={"title":"عنف جماعي يهودي–عربي في المدن الإسرائيلية المختلطة","location":"اللد وعكا ويافا ومدن إسرائيلية أخرى","story":"مع تطور صراع غزة في مايو 2021 اندلع عنف جماعي خطير داخل إسرائيل. وهاجمت حشود يهودية وعربية أشخاصًا ومنازل ومتاجر ومركبات ومواقع دينية في عدة مدن مختلطة. وشمل العنف عمليات قتل واعتداءات وكشف توترات عميقة بين المواطنين اليهود والعرب.","context":"ينسب المؤشر العنف بوضوح إلى جماعات يهودية وعربية معًا ولا يعرض الأحداث كعنف من طرف واحد.","aftermath":"أثارت الأحداث نقاشًا متجددًا حول العلاقات اليهودية العربية داخل إسرائيل والشرطة والفجوات الاجتماعية والسياسية.","sourceStatus":"العنف من جماعات يهودية وعربية موثق على نطاق واسع. كان للحوادث الفردية منفذون وظروف مختلفة ولا ينبغي اختزالها في نسبة أحادية الجانب"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2022-colleyville-synagogue-hostage-crisis-262"]={"title":"أزمة رهائن كنيس كوليفيل","location":"كوليفيل، تكساس، الولايات المتحدة","story":"احتجز رجل مسلح مصلين رهائن في جماعة بيت إسرائيل في يناير 2022. وتمكن الرهائن في النهاية من الفرار أو الإنقاذ؛ وقُتل المهاجم.","context":"كان الحدث هجومًا على كنيس ومصلين يهود في الولايات المتحدة.","aftermath":"انتهت الأزمة دون مقتل الرهائن وزادت الاهتمام بأمن المعابد والمؤسسات اليهودية.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2022-west-bank-violence-reaches-highest-palestinian-death-toll-in-years-263"]={"title":"عنف الضفة الغربية يصل إلى أعلى حصيلة قتلى فلسطينيين منذ سنوات","location":"الضفة الغربية وإسرائيل","story":"تصاعد العنف بشدة خلال 2022. قتلت هجمات فلسطينية إسرائيليين، بينما قتلت مداهمات الاعتقال الإسرائيلية والاشتباكات المسلحة، خصوصًا حول جنين ونابلس، أعدادًا متزايدة من الفلسطينيين. كما زادت هجمات المستوطنين على الفلسطينيين. ووصفت الأمم المتحدة 2022 بأنها في طريقها لأن تكون السنة الأكثر دموية للفلسطينيين في الضفة منذ بدء الرصد المنهجي سنة 2005.","context":"يعرض المؤشر الهجمات الفلسطينية وعمليات القوات الإسرائيلية وعنف المستوطنين معًا مع التمييز بين الظروف المختلفة.","aftermath":"استمر التصعيد في 2023 وسبق عمليات عسكرية أكبر وزيادة عنف المسلحين والمستوطنين.","sourceStatus":"التصعيد واتجاه الضحايا موثقان على نطاق واسع في رصد الأمم المتحدة. شملت الحوادث الفردية مدنيين ومسلحين وقوات أمن ومستوطنين في ظروف مختلفة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2023-huwara-attack-and-settler-rampage-264"]={"title":"هجوم حوارة وهجوم المستوطنين الواسع","location":"حوارة والقرى المحيطة في الضفة الغربية","story":"في 26 فبراير 2023 قتل مسلح فلسطيني شقيقين إسرائيليين قرب حوارة. وبعد ساعات هاجم مئات المستوطنين الإسرائيليين حوارة ومجتمعات فلسطينية مجاورة وأحرقوا منازل ومتاجر ومركبات. وقُتل رجل فلسطيني وأصيب كثيرون.","context":"يُعرض الحدث كتسلسل لهجوم فلسطيني قاتل أعقبه عنف جماعي من مستوطنين إسرائيليين ضد فلسطينيين.","aftermath":"فاقمت الأحداث التوتر في الضفة وأدت إلى إدانات إسرائيلية ودولية لعنف المستوطنين.","sourceStatus":"قتل الشقيقين الإسرائيليين وهجوم المستوطنين اللاحق موثقان على نطاق واسع. وأدان قادة إسرائيليون، بينهم الرئيس، عنف المستوطنين"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2023-large-scale-israeli-operation-in-jenin-refugee-camp-265"]={"title":"عملية إسرائيلية واسعة في مخيم جنين للاجئين","location":"جنين، الضفة الغربية","story":"في 3–4 يوليو 2023 شنت القوات الإسرائيلية عملية جوية وبرية كبيرة في جنين وحول مخيم اللاجئين مستهدفة جماعات مسلحة وبنية أسلحة. وتبادل مسلحون فلسطينيون النار مع القوات. وقُتل فلسطينيون، بينهم أطفال، وأصيب كثيرون وتضررت البنية التحتية في المخيم.","context":"كان الحدث عملية عسكرية إسرائيلية ضد بنية مسلحة داخل منطقة حضرية كثيفة، مع قتال وأضرار للمدنيين والبنية التحتية.","aftermath":"لم تنه العملية نشاط الجماعات المسلحة في جنين واستمرت المواجهات في المنطقة.","sourceStatus":"العملية والغارات الجوية وتبادل النار والضحايا موثقة على نطاق واسع. قالت السلطات الإسرائيلية إن القوات استهدفت بنية للمسلحين؛ ووثقت منظمات إنسانية ضررًا مدنيًا ومشكلات وصول"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2023-october-7-hamas-led-attack-on-southern-israel-266"]={"title":"هجوم 7 أكتوبر بقيادة حماس على جنوب إسرائيل","location":"جنوب إسرائيل قرب قطاع غزة","story":"في 7 أكتوبر 2023 شنت حماس وجماعات فلسطينية مسلحة أخرى هجومًا منسقًا على جنوب إسرائيل تحت غطاء كثيف من الصواريخ. ودخل المهاجمون بلدات ومهرجانًا موسيقيًا ومواقع عسكرية، وقتلوا عمدًا مدنيين وجنودًا وخطفوا رهائن إلى غزة. ووفق الأرقام الإسرائيلية الحالية قُتل نحو 1,200 إسرائيلي وأجنبي وأُخذ 251 شخصًا رهائن.","context":"يفصل المؤشر هجوم 7 أكتوبر والقتل المتعمد للمدنيين عن الحرب الإسرائيلية في غزة التي تلته.","aftermath":"أدى الهجوم إلى حرب غزة الواسعة وأزمة الرهائن واتساع المواجهة الإقليمية.","sourceStatus":"الهجوم المنسق والقتل المتعمد للمدنيين وأخذ الرهائن موثقة على نطاق واسع. خلصت لجنة تحقيق أممية إلى أن حماس وجماعات مسلحة أخرى ارتكبت جرائم حرب، منها القتل وأخذ الرهائن، ووجدت أدلة على عنف جنسي وقائم على النوع الاجتماعي"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2023-israel-launches-large-scale-gaza-war-after-october-7-267"]={"title":"إسرائيل تطلق حربًا واسعة في غزة بعد 7 أكتوبر","location":"قطاع غزة","story":"ردت إسرائيل على هجوم 7 أكتوبر بحملة جوية واسعة وغزو بري لغزة، معلنة أن أهدافها تفكيك حماس وإعادة الرهائن. وتسببت الحملة بدمار هائل ونزوح جماعي وحصيلة فلسطينية مرتفعة جدًا، بينها مدنيون، بينما قُتل جنود إسرائيليون في القتال وواصلت الجماعات الفلسطينية المسلحة هجماتها.","context":"يعرض المؤشر الحرب الإسرائيلية كرد منفصل على هجوم 7 أكتوبر، بما يسمح بتقييم سلوكها وتأثيرها على مدنيي غزة بصورة مستقلة.","aftermath":"خلقت الحرب أزمة إنسانية هائلة ونزوحًا واسعًا وإجراءات قانونية دولية ومفاوضات طويلة بشأن وقف النار والرهائن.","sourceStatus":"حجم العمليات العسكرية والدمار والنزوح موثق على نطاق واسع. أعداد القتلى الفلسطينيين تصدرها سلطات الصحة في غزة وتستخدمها وكالات الأمم المتحدة على نطاق واسع، بينما تبقى تصنيفات المقاتلين وادعاءات التناسب والتجويع والإبادة وغيرها من الانتهاكات موضوع إجراءات قانونية ونزاع شديد"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2023-israel-hezbollah-border-conflict-expands-after-october-7-268"]={"title":"اتساع صراع الحدود بين إسرائيل وحزب الله بعد 7 أكتوبر","location":"الحدود الإسرائيلية اللبنانية","story":"بعد وقت قصير من 7 أكتوبر بدأ حزب الله وإسرائيل تبادل إطلاق النار شبه اليومي عبر حدود لبنان. وقال حزب الله إنه يتحرك دعمًا لغزة؛ وضربت إسرائيل مواقع وقادة للحزب. ونزح عشرات الآلاف من المدنيين على جانبي الحدود مع تصاعد المواجهة.","context":"وسع الصراع حرب غزة إلى أزمة إقليمية أكبر ووضع شمال إسرائيل وجنوب لبنان تحت تهديد مستمر.","aftermath":"تصاعد القتال كثيرًا خلال 2024 وقاد إلى مواجهة أوسع بكثير بين إسرائيل وحزب الله.","sourceStatus":"التبادلات المستمرة والنزوح الجماعي موثقة على نطاق واسع. تصاعد الصراع بصورة كبيرة خلال 2024 ومرة أخرى لاحقًا في الحرب الإقليمية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2024-iran-and-israel-exchange-direct-attacks-269"]={"title":"إيران وإسرائيل تتبادلان هجمات مباشرة","location":"إسرائيل وإيران","story":"في أبريل 2024 أطلقت إيران مئات الطائرات المسيّرة والصواريخ نحو إسرائيل بعد ضربة إسرائيلية على مجمع دبلوماسي إيراني في دمشق قتلت قادة إيرانيين كبارًا. واعترضت إسرائيل وشركاؤها معظم الأسلحة القادمة، ثم نفذت إسرائيل ضربة محدودة داخل إيران. ومثل التبادل انتقالًا غير مسبوق من صراع الظل الطويل إلى هجمات مباشرة بين الدولتين.","context":"وسع الحدث المواجهة الإقليمية إلى ما وراء ساحات الوكلاء وجعل إسرائيل وإيران مشاركتين مباشرة في ضربات متبادلة.","aftermath":"أنشأ تبادل الهجمات سابقة لمزيد من التصعيد المباشر بين الدولتين.","sourceStatus":"الهجمات وعمليات الاعتراض موثقة على نطاق واسع. نُسبت ضربة دمشق على نطاق واسع إلى إسرائيل رغم أنها لم تعلن مسؤوليتها عنها آنذاك"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2024-israel-hezbollah-war-escalates-in-lebanon-270"]={"title":"تصاعد حرب إسرائيل وحزب الله في لبنان","location":"لبنان وشمال إسرائيل","story":"تصاعدت المواجهة بين إسرائيل وحزب الله بصورة دراماتيكية في 2024، وشملت ضربات إسرائيلية في أنحاء لبنان، وإطلاق حزب الله صواريخ وقذائف نحو إسرائيل، وقتل قادة كبار في الحزب وعمليات برية إسرائيلية في جنوب لبنان. ونزحت أعداد كبيرة من المدنيين وارتفعت الخسائر بشدة.","context":"تطور القتال من صراع حدودي بدأ بعد 7 أكتوبر إلى مواجهة عسكرية أوسع.","aftermath":"غير التصعيد ميزان القوى في لبنان وقاد في النهاية إلى ترتيبات هشة لوقف إطلاق النار.","sourceStatus":"التصعيد والغارات والقتال البري والنزوح موثقة على نطاق واسع. تبقى تقييمات الهجمات الفردية والامتثال للقانون الإنساني الدولي موضع نزاع"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2024-icj-advisory-opinion-on-israel-s-occupation-and-settlement-policies-271"]={"title":"الرأي الاستشاري لمحكمة العدل الدولية بشأن الاحتلال وسياسات الاستيطان الإسرائيلية","location":"محكمة العدل الدولية، لاهاي","story":"في يوليو 2024 أصدرت محكمة العدل الدولية رأيًا استشاريًا خلص إلى أن استمرار وجود إسرائيل في الأرض الفلسطينية المحتلة غير قانوني وتناول الآثار الناشئة عن سياسات الاستيطان والضم. ورفضت إسرائيل استنتاجات الرأي وانتقدت الإجراءات.","context":"هذا تطور قانوني دولي لا حدث عسكري، ويُعرض منفصلًا للتمييز بين الأحكام القانونية والسياسات والعنف.","aftermath":"أصبح الرأي مرجعًا مهمًا في النقاش القانوني والدبلوماسي بشأن الاحتلال والاستيطان.","sourceStatus":"الرأي الاستشاري وثيقة قضائية ذات سلطة، لكنه استشاري وليس حكمًا يفصل في قضية نزاعية بين دول وافقت على اختصاص المحكمة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2025-gaza-ceasefire-and-hostage-prisoner-exchanges-272"]={"title":"وقف إطلاق النار في غزة وتبادل الرهائن والأسرى","location":"قطاع غزة وإسرائيل","story":"أنتجت ترتيبات وقف إطلاق النار خلال الحرب التي تلت 7 أكتوبر عمليات تبادل أُطلق فيها رهائن إسرائيليون محتجزون في غزة مقابل أسرى ومعتقلين فلسطينيين. وأنهى وقف نار لاحق بوساطة أمريكية اتُفق عليه في أكتوبر 2025 القتال واسع النطاق، رغم استمرار ضربات إسرائيلية وبقاء قضايا سياسية وإنسانية وأمنية كبرى دون حل.","context":"جمعت الترتيبات قضية الرهائن والأسرى بمحاولة وقف الحرب دون الوصول إلى تسوية سياسية شاملة.","aftermath":"خفض وقف النار حجم القتال لكنه لم ينشئ سلامًا مستقرًا ولم يحل قضايا حكم حماس وأمن إسرائيل وإعادة إعمار غزة.","sourceStatus":"وقف إطلاق النار وعمليات التبادل موثقة. بقي التنفيذ غير مكتمل ولم ينتج الاتفاق تسوية سياسية شاملة أو ينهِ العنف بالكامل"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2026-gaza-after-the-2025-ceasefire-continuing-strikes-and-humanitarian-crisis-273"]={"title":"غزة بعد وقف إطلاق النار لعام 2025: استمرار الضربات والأزمة الإنسانية","location":"قطاع غزة","story":"بحلول 2026 كان وقف إطلاق النار في أكتوبر 2025 قد أنهى الحرب واسعة النطاق لكنه لم ينتج سلامًا مستقرًا. واستمرت ضربات إسرائيلية، ولم تُنزع أسلحة حماس، وبقيت غزة مدمرة بعد سنوات الحرب. واستمرت حالات النقص الحاد والبنية التحتية المتضررة والنزوح في التأثير على المدنيين.","context":"يتعامل المؤشر مع الوضع كتاريخ ما زال يتطور لا كنهاية متفق عليها للحرب.","aftermath":"بقي الوضع الإنساني والأمني هشًا ويعتمد على استمرار تنفيذ وقف النار وترتيبات سياسية مستقبلية.","sourceStatus":"حتى أكتوبر 2026. تشير تقارير رويترز إلى استمرار الضربات رغم وقف إطلاق النار وإلى بقاء أزمات غزة الإنسانية وأزمة الطاقة شديدة. ولأن الظروف مستمرة في التغير ينبغي التعامل مع هذا المؤشر كسجل متطور"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2026-u-s-israel-campaign-against-iran-274"]={"title":"الحملة الأمريكية الإسرائيلية ضد إيران","location":"إيران والشرق الأوسط الأوسع","story":"في 2026 توسع الصراع الإقليمي إلى حملة عسكرية أمريكية إسرائيلية مباشرة ضد إيران، وصفها مسؤولون أمريكيون بعملية Epic Fury. وأنتجت الحرب تداعيات إقليمية كبيرة وأثرت في الدبلوماسية وأمن الطاقة والدول المجاورة.","context":"يمثل الحدث مرحلة جديدة انتقلت فيها المواجهة مع إيران من حرب ظل وتبادلات محدودة إلى حملة عسكرية مباشرة وأوسع.","aftermath":"ما تزال آثار الحملة على إيران وإسرائيل ودول الخليج ولبنان والنظام الإقليمي تتطور.","sourceStatus":"حتى أكتوبر 2026. تؤكد تقارير رويترز الحملة الأمريكية الإسرائيلية ضد إيران. وما تزال التفاصيل العملياتية والعواقب تتطور وينبغي تحديثها مع توفر سجلات رسمية وأرشيفية أقوى"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2026-israel-hezbollah-ceasefire-after-renewed-lebanon-escalation-275"]={"title":"وقف إطلاق النار بين إسرائيل وحزب الله بعد تجدد التصعيد في لبنان","location":"إسرائيل ولبنان","story":"بعد تجدد القتال المرتبط بالصراع الإقليمي الأوسع وافقت إسرائيل وحزب الله على وقف إطلاق نار أعلنته الولايات المتحدة في يونيو 2026. وبقيت قوات إسرائيلية في جنوب لبنان ووقعت ضربات مبكرة حول بداية وقف النار، ما أبرز هشاشة الترتيب.","context":"جاء وقف النار بعد مرحلة أخرى من التصعيد وكان جزءًا من محاولة احتواء الحرب الإقليمية الأوسع.","aftermath":"بقيت متانة الاتفاق ومسألة الوجود العسكري وترتيبات الحدود مفتوحة.","sourceStatus":"حتى أكتوبر 2026. أفادت رويترز بتأكيد وقف إطلاق النار من مسؤول أمريكي ومسؤول إسرائيلي ومصادر في حزب الله. وتبقى استدامته سؤالًا متطورًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-2026-2026-you-are-here-276"]={"title":"2026 — أنت هنا","location":"الوقت الحاضر","story":"يصل الخط الزمني إلى الحاضر في أكتوبر 2026. ويبقى السجل التاريخي مفتوحًا: غزة في بيئة هشة بعد الحرب ووقف إطلاق النار، والعنف والنزوح الإسرائيلي الفلسطيني لم يُحلا، والمواجهة الإقليمية الأوسع التي تشمل إسرائيل وإيران وحزب الله أنتجت حروبًا ووقفات إطلاق نار جديدة.","context":"هذه نقطة نهاية حية للخط الزمني وليست خلاصة تاريخية نهائية. تُعرض الأحداث المعاصرة بحذر مع الفصل بين الحقائق الموثقة والادعاءات القانونية والنتائج التي ما تزال تتطور.","aftermath":"الفصل التالي ما زال يُكتب، ولذلك ينبغي تحديث المؤشر مع تغير ترتيبات وقف النار والرهائن والحروب والتحقيقات والتسويات السياسية.","sourceStatus":"هذه نقطة نهاية حية وليست خلاصة تاريخية مستقرة. قد تتغير الحقائق المعاصرة وأرقام الضحايا والنتائج القانونية والترتيبات السياسية مع ظهور أدلة وسجلات موثوقة جديدة"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1919-proskurov-pogrom-108"]={"title":"פוגרום פרוסקורוב","location":"פרוסקורוב, אוקראינה","story":"בפברואר 1919, במהלך מלחמת האזרחים באוקראינה, הרגו חיילים הקשורים לכוחותיו של סימון פטליורה מאות יהודים בפרוסקורוב בפוגרום גדול.","context":"הפוגרום היה חלק מגל רחב של אלימות אנטי־יהודית במהלך מלחמות האזרחים והמאבקים הלאומיים שלאחר מלחמת העולם הראשונה.","aftermath":"הטבח הפך לאחד הפוגרומים הידועים ביותר של התקופה והמחיש את הסכנה הקיצונית לקהילות יהודיות באזורי המלחמה.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1920-nebi-musa-riots-109"]={"title":"מהומות נבי מוסא","location":"ירושלים","story":"אלימות במהלך חגיגות נבי מוסא כללה התקפות על הקהילה היהודית בירושלים על רקע החרפת המתחים הפוליטיים הערביים–יהודיים בתקופת המנדט הבריטי.","context":"האירוע היה חלק מן העימות הפוליטי והקהילתי המתפתח בארץ בתקופת המנדט.","aftermath":"המהומות העמיקו את חוסר האמון והובילו לשינויים בהתארגנות הביטחונית היהודית.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1921-jaffa-riots-110"]={"title":"מהומות יפו","location":"יפו והסביבה","story":"אלימות ערבית–יהודית ביפו ובאזורים סמוכים גרמה להרוגים ולפצועים בשתי הקהילות והעמיקה את המתחים בתקופת המנדט.","context":"האלימות התרחשה בתוך מתחים לאומיים, פוליטיים וחברתיים גוברים בין ערבים ליהודים.","aftermath":"האירועים החריפו את ההפרדה והחששות הביטחוניים והובילו לתגובות מצד שלטונות המנדט.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1929-hebron-massacre-and-1929-palestine-riots-111"]={"title":"טבח חברון ומהומות תרפ״ט","location":"חברון וארץ ישראל המנדטורית","story":"במהלך אלימות נרחבת ב־1929 הרגו תוקפים ערבים 67 יהודים בחברון. יהודים הותקפו גם במקומות אחרים, בעוד ערבים נהרגו בעימותים ובידי כוחות בריטיים.","context":"הטבח בחברון היה חלק מגל אלימות רחב יותר, ולכן יש להבחין בין האירוע המקומי לבין כלל נפגעי מהומות 1929.","aftermath":"הקהילה היהודית העתיקה בחברון פונתה לאחר הטבח והאלימות העמיקה את הסכסוך בתקופת המנדט.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1929-safed-massacre-during-the-1929-riots-112"]={"title":"טבח צפת במהלך מהומות תרפ״ט","location":"צפת, ארץ ישראל המנדטורית","story":"במהלך מהומות 1929 תקפו ערבים תושבים יהודים בצפת, הרגו יהודים ושרפו ובזזו בתים יהודיים.","context":"זהו אירוע מזוהה בתוך גל האלימות הרחב של 1929, המיוצג גם באירועים אחרים בציר הזמן.","aftermath":"הקהילה היהודית בצפת ספגה הרוגים, פציעות ונזק לרכוש והמתחים באזור החריפו.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1933-nazi-seizure-of-power-begins-systematic-persecution-of-german-jews-113"]={"title":"עליית הנאצים לשלטון מתחילה רדיפה שיטתית של יהודי גרמניה","location":"גרמניה","story":"לאחר שאדולף היטלר נעשה קנצלר ב־30 בינואר 1933, המשטר הנאצי הפך במהירות אידאולוגיה אנטישמית למדיניות ממשלתית. יהודים סבלו מאיומים, תקיפות, הדרה ממוסדות ציבור ומערכת מתרחבת של חוקים מפלים.","context":"סמן זה עוקב אחר ההסלמה מאידאולוגיה אנטישמית למדיניות מדינה, הדרה משפטית, נישול כלכלי ואלימות גלויה יותר ויותר.","aftermath":"הצעדים בידדו, רוששו וסיכנו בהדרגה את הקהילות היהודיות וסייעו ליצור את המסגרת המוסדית לרדיפה הקיצונית ולרצח ההמוני שבאו בהמשך.","sourceStatus":"מתועד בהרחבה ברשומות גרמניות, בדיווחים בני התקופה ובארכיוני השואה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1933-nationwide-nazi-boycott-of-jewish-businesses-114"]={"title":"חרם נאצי ארצי על עסקים יהודיים","location":"גרמניה","story":"ב־1 באפריל 1933 ארגנה המפלגה הנאצית חרם ארצי על עסקים בבעלות יהודית ועל בעלי מקצוע יהודים. אנשי SA עמדו מחוץ לחנויות ולמשרדים כדי להפחיד לקוחות. אף שהחרם הרשמי נמשך יום אחד, הוא סימן תחילת מסע לאומי להוצאת יהודים מן החיים הכלכליים בגרמניה.","context":"החרם היה שלב מוקדם בהפיכת האנטישמיות למדיניות ממוסדת של הדרה כלכלית.","aftermath":"הצעדים הכלכליים נגד יהודים התרחבו בשנים הבאות והובילו לנישול שיטתי יותר.","sourceStatus":"מתועד בהרחבה; החרם אורגן בידי רשויות המפלגה הנאצית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1933-civil-service-law-excludes-jews-from-government-employment-115"]={"title":"חוק שירות המדינה מדיר יהודים ממשרות ממשלתיות","location":"גרמניה","story":"החוק לשיקום שירות המדינה המקצועי מ־7 באפריל סילק יהודים רבים ומתנגדים פוליטיים ממשרות ממשלתיות. זה היה אחד הצעדים המשפטיים הגדולים הראשונים להדרה שיטתית של יהודים מן החיים הציבוריים בגרמניה.","context":"החקיקה ממחישה את המעבר המהיר מאפליה פוליטית לחוק מדינה מחייב.","aftermath":"ההדרה התרחבה בהמשך למקצועות ולמוסדות נוספים וסייעה לבודד את יהודי גרמניה.","sourceStatus":"החקיקה ויישומה מתועדים ישירות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1935-nuremberg-laws-strip-jews-of-rights-and-impose-racial-definitions-116"]={"title":"חוקי נירנברג שוללים זכויות מיהודים ומטילים הגדרות גזעיות","location":"נירנברג / גרמניה הנאצית","story":"חוקי נירנברג שללו מיהודי גרמניה אזרחות מלאה ואסרו נישואין ויחסי מין בין יהודים לבין מי שסווגו כבעלי דם גרמני או קרוב לו. הרשויות הנאציות הגדירו זהות יהודית לפי מוצא גזעי ולא לפי אמונה אישית.","context":"החוקים הפכו את האפליה הגזעית לעיקרון משפטי מרכזי של המדינה הנאצית.","aftermath":"הם העמיקו את בידוד היהודים והכשירו צעדי נישול, גירוש ורדיפה נוספים.","sourceStatus":"חקיקה נאצית ופרקטיקה מנהלית מתועדות בהרחבה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1936-1936-1939-arab-revolt-attacks-on-jewish-civilians-117"]={"title":"המרד הערבי 1936–1939: התקפות על אזרחים יהודים","location":"ארץ ישראל המנדטורית","story":"המרד הערבי נגד השלטון הבריטי וההגירה היהודית ההמונית כלל התקפות על אזרחים ויישובים יהודיים, לצד דיכוי בריטי ותגובות חמושות יהודיות.","context":"האירוע היה חלק ממרד רחב נגד הבריטים ומסכסוך לאומי מתעצם; אלימות בוצעה במסגרות שונות בידי כמה צדדים.","aftermath":"המרד שינה את מדיניות בריטניה, את ההתארגנות הצבאית היהודית ואת היחסים בין הקהילות לקראת סוף המנדט.","sourceStatus":"רמת ודאות גבוהה מאוד; אירועים בודדים דורשים מקורות נפרדים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1937-escalating-exclusion-and-aryanization-of-jewish-economic-life-118"]={"title":"החרפת ההדרה וה״אריזציה״ של החיים הכלכליים היהודיים","location":"גרמניה","story":"מ־1937 ועד 1939 אילצה המדיניות הנאצית יותר ויותר יהודים לצאת ממקצועות ומעסקים והעבירה רכוש בבעלות יהודית לבעלות לא־יהודית בתנאי כפייה. התהליך, שכונה אריזציה, רושש משפחות יהודיות ובודד אותן עוד יותר.","context":"הנישול הכלכלי היה חלק מן ההסלמה השיטתית של רדיפת יהודי גרמניה.","aftermath":"המדיניות צמצמה את יכולת הקיום הכלכלית של יהודים והגבירה את הלחץ להגר.","sourceStatus":"מתועד בהרחבה בצווים נאציים, ברשומות רכוש ובמחקר השואה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1938-kristallnacht-november-pogrom-119"]={"title":"ליל הבדולח / פוגרום נובמבר","location":"גרמניה ואוסטריה","story":"מנהיגי הנאצים שחררו גל אלימות אנטי־יהודית ארצי: בתי כנסת נשרפו, עסקים ובתים נהרסו, יהודים נרצחו וכ־26,000 גברים יהודים נכלאו במחנות ריכוז.","context":"הפוגרום סימן מעבר בולט מרדיפה משפטית וכלכלית לאלימות המונית מאורגנת בידי המשטר.","aftermath":"האירוע האיץ הגירה, נישול וכליאה והיה שלב מרכזי בדרך לרדיפה הקטלנית בזמן המלחמה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1939-german-invasion-of-poland-and-persecution-of-polish-jews-120"]={"title":"פלישת גרמניה לפולין ורדיפת יהודי פולין","location":"פולין הכבושה","story":"גרמניה פלשה לפולין ב־1 בספטמבר 1939. כוחות גרמניים ורשויות הכיבוש החלו מיד להשפיל יהודים, לכפות עבודת כפייה, לשדוד, לעקור ולהפעיל אלימות. האוכלוסייה היהודית הגדולה של פולין עברה תחת שלטון נאצי.","context":"זהו שלב מרכזי בכרונולוגיית השואה שבו הרדיפה הנאצית התרחבה עם הכיבוש למיליוני יהודים נוספים.","aftermath":"הכיבוש הוביל לריכוז יהודים, גטאות, גירושים ובהמשך לרצח המוני שיטתי.","sourceStatus":"מתועד בהרחבה ברשומות גרמניות, בעדויות ראייה ובארכיוני השואה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1940-nazi-ghettos-isolate-jewish-communities-in-occupied-poland-121"]={"title":"הגטאות הנאציים מבודדים קהילות יהודיות בפולין הכבושה","location":"פולין הכבושה בידי גרמניה","story":"הרשויות הגרמניות אילצו יהודים לעבור לרבעים עירוניים סגורים או מוגבלים שנודעו כגטאות. גטאות כמו לודז' וורשה סבלו מצפיפות קיצונית, רעב, מחלות ועבודת כפייה, ובהמשך שימשו נקודות ריכוז לגירוש למרכזי הרג.","context":"הגטאות היו חלק ממערכת רדיפה שהתקדמה מבידוד וניצול אל גירוש ורצח המוני.","aftermath":"מאות אלפים מתו מתנאי החיים או גורשו בהמשך למרכזי הרג.","sourceStatus":"מתועד בהרחבה ברשומות מנהל גרמניות, תצלומים, יומנים ועדויות ניצולים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-farhud-122"]={"title":"הפרהוד","location":"בגדאד, עיראק","story":"ב־1–2 ביוני 1941 פרצה בבגדאד אלימות אנטי־יהודית שכללה הרג ופציעת יהודים, ביזה והרס נרחבים.","context":"הפרהוד התרחש בתוך משבר פוליטי בעיראק בזמן מלחמת העולם השנייה, לאחר קריסת המשטר הפרו־צירי של רשיד עלי.","aftermath":"האירוע ערער עמוקות את תחושת הביטחון של יהודי עיראק ונעשה נקודת ציון בזיכרון הקהילה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-ias-i-pogrom-123"]={"title":"פוגרום יאשי","location":"יאשי, רומניה","story":"רשויות ויחידות צבא רומניות, בסיוע חיילים גרמנים בחלק מן המקרים, רצחו לפחות 8,000 יהודים במהלך פוגרום יוני 1941 וברכבות המוות הקשורות אליו.","context":"האירוע היה חלק מרדיפת ורצח יהודי רומניה בתקופת השואה ובוצע במעורבות מרכזית של הרשויות הרומניות.","aftermath":"אלפי יהודים נרצחו והקהילה נפגעה באופן קטסטרופלי.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-lviv-pogrom-124"]={"title":"פוגרום לבוב","location":"לבוב, אוקראינה הכבושה בידי גרמניה","story":"לאחר הכיבוש הגרמני של לבוב השתתפו כוחות גרמניים, פעילים לאומנים אוקראינים, אנשי מיליציה ואזרחים מקומיים בהשפלה, הכאה ורצח של יהודים.","context":"האירוע התרחש בימים הראשונים של הכיבוש הגרמני ובתוך הסלמה מהירה של אלימות אנטי־יהודית.","aftermath":"הפוגרום היה חלק מתחילת ההשמדה ההמונית של יהודי האזור תחת הכיבוש הנאצי.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-jedwabne-massacre-125"]={"title":"טבח ידוובנה","location":"ידוובנה, פולין הכבושה בידי גרמניה","story":"מאות מתושבי ידוובנה היהודים נרצחו ביולי 1941 בידי שכנים פולנים בנוכחות משטרה גרמנית; שאלות על מידת היוזמה וההכוונה הגרמנית ממשיכות להיחקר.","context":"האחריות הישירה של מבצעים מקומיים מתועדת, לצד נוכחות ושליטה גרמנית באזור; היבטים של היוזמה הגרמנית נותרו נושא למחקר.","aftermath":"הקהילה היהודית המקומית הושמדה כמעט לחלוטין.","sourceStatus":"רמת ודאות גבוהה מאוד; היבטים מסוימים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-ponary-mass-killings-begin-126"]={"title":"תחילת הרציחות ההמוניות בפונאר","location":"ליד וילנה, ליטא","story":"יחידות אס־אס ומשטרה גרמניות, בסיוע משתפי פעולה ליטאים, רצחו בפונאר יהודים מווילנה ומהסביבה. בסופו של דבר נרצחו באתר עשרות אלפי יהודים.","context":"פונאר היה אתר מרכזי של רצח בירי בתקופת השואה במזרח אירופה.","aftermath":"הרציחות השמידו חלק גדול מן האוכלוסייה היהודית של וילנה והאזור.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-che-mno-killing-center-begins-mass-murder-127"]={"title":"מרכז ההרג חלמנו מתחיל ברצח המוני","location":"חלמנו, פולין הכבושה בידי גרמניה","story":"הרצח ההמוני בחלמנו החל בדצמבר 1941 באמצעות משאיות גז. גרמניה הנאצית רצחה שם לפחות 152,000 יהודים.","context":"חלמנו היה מרכז ההרג הנאצי הראשון שבו נעשה שימוש שיטתי בגז לצורך רצח המוני.","aftermath":"המרכז שימש להשמדת קהילות יהודיות, במיוחד מאזור ורטגאו וגטו לודז'.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-holocaust-mass-shootings-and-extermination-128"]={"title":"השואה: ירי המוני והשמדה","location":"אירופה הכבושה בידי גרמניה","story":"גרמניה הנאצית ובעלות בריתה ומשתפי הפעולה עמה רצחו באופן שיטתי כשישה מיליון יהודים אירופים באמצעות ירי, מרכזי הרג, גטאות, הרעבה, עבודת כפייה ושיטות נוספות.","context":"זהו אירוע־על בציר הזמן; אירועים נפרדים מתעדים אתרי הרג, גירושים, פוגרומים ומעשי התנגדות ספציפיים.","aftermath":"השואה החריבה קהילות יהודיות ברחבי אירופה והותירה השלכות דמוגרפיות, פוליטיות ותרבותיות עמוקות.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-rumbula-massacre-129"]={"title":"טבח רומבולה","location":"ליד ריגה, לטביה הכבושה בידי גרמניה","story":"אנשי אס־אס ומשטרה גרמנים וכוחות עזר לטביים רצחו בסוף 1941 כ־25,000 יהודים מגטו ריגה וכ־1,000 יהודים מגרמניה ביער רומבולה.","context":"הטבח היה אחד ממבצעי הירי ההמוני הגדולים בשואה לפני התרחבות מרכזי ההרג.","aftermath":"רוב תושבי גטו ריגה שנכללו באקציה נרצחו בתוך ימים ספורים.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-babi-yar-massacre-130"]={"title":"טבח באבי יאר","location":"קייב, אוקראינה הכבושה בידי גרמניה","story":"ב־29–30 בספטמבר 1941 רצחו אנשי איינזצגרופה C ומשתפי פעולה 33,771 גברים, נשים וילדים יהודים בגיא באבי יאר.","context":"הרצח התרחש לאחר כיבוש קייב והיה דוגמה מרכזית לשיטת ההשמדה בירי המוני.","aftermath":"האתר המשיך לשמש את הנאצים לרצח קבוצות נוספות במהלך הכיבוש.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-operation-barbarossa-and-einsatzgruppen-mass-shootings-131"]={"title":"מבצע ברברוסה והירי ההמוני של האיינזצגרופן","location":"השטחים הסובייטיים הכבושים בידי גרמניה","story":"לאחר פלישת גרמניה לברית המועצות ביוני 1941 ביצעו יחידות הרג ניידות, בסיוע כוחות גרמניים נוספים וכוחות עזר מקומיים במקומות שונים, ירי המוני ביהודים ובקבוצות יעד אחרות. קהילות יהודיות שלמות נרצחו סמוך לבתיהן.","context":"הפלישה סימנה הסלמה מכרעת מרדיפה וגטאות לרצח המוני שיטתי בשטחי ברית המועצות הכבושים.","aftermath":"הירי ההמוני רצח מאות אלפי יהודים והיה מרכיב מרכזי בהתפתחות השואה.","sourceStatus":"מתועד בהרחבה בדוחות מבצעיים גרמניים, רשומות מלחמה, קברי אחים ועדויות ניצולים ועדים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-kamianets-podilskyi-massacre-132"]={"title":"טבח קמניץ־פודולסקי","location":"קמניץ־פודולסקי, אוקראינה הסובייטית הכבושה","story":"בסוף אוגוסט 1941 רצחו כוחות אס־אס ומשטרה גרמניים, בסיוע כוחות תחת פיקוד גרמני, עשרות אלפי יהודים ליד קמניץ־פודולסקי. רבים מן הקורבנות גורשו קודם משטח בשליטה הונגרית; גם יהודים אוקראינים מקומיים נרצחו.","context":"הטבח היה אחד ממבצעי הרצח ההמוני הגדולים הראשונים לאחר מבצע ברברוסה.","aftermath":"האירוע הדגים את המעבר המהיר לרצח המוני של אוכלוסיות יהודיות שלמות.","sourceStatus":"מתועד בהרחבה; כ־23,600 יהודים דווחו כנרצחים באקציה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-odessa-massacre-under-romanian-occupation-133"]={"title":"טבח אודסה תחת הכיבוש הרומני","location":"אודסה והאזור הסובב, אוקראינה הכבושה","story":"לאחר שכוחות רומניים וגרמניים כבשו את אודסה ביצעו הרשויות הרומניות פעולות תגמול המוניות נגד יהודים בעקבות פיצוץ במטה הצבאי הרומני. יהודים נורו, נתלו, נשרפו במבנים וגורשו לאתרי הרג ולמחנות בטרנסניסטריה שבשליטת רומניה.","context":"האירוע היה חלק מרדיפת ורצח היהודים תחת הממשל הרומני באזור.","aftermath":"הרציחות והגירושים השמידו חלק ניכר מן הקהילה היהודית המקומית.","sourceStatus":"התפקיד הרומני והרצח ההמוני מתועדים בהרחבה; מספרי הנפגעים משתנים לפי התחום הגאוגרפי והכרונולוגי הנכלל"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-belzec-killing-center-134"]={"title":"מרכז ההרג בלז'ץ","location":"בלז'ץ, פולין הכבושה בידי גרמניה","story":"בלז'ץ הפך למרכז הרג במסגרת מבצע ריינהרד. כ־435,000 יהודים נרצחו בו, רובם המכריע בתאי גזים.","context":"בלז'ץ היה אחד משלושת מרכזי ההרג המרכזיים של מבצע ריינהרד להשמדת יהודי הגנרלגוברנמן.","aftermath":"כמעט כל המגורשים שנשלחו לבלז'ץ נרצחו, והמחנה פורק לאחר סיום פעולות ההרג העיקריות.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-sobibor-killing-center-135"]={"title":"מרכז ההרג סוביבור","location":"סוביבור, פולין הכבושה בידי גרמניה","story":"סוביבור הוקם כמרכז הרג במסגרת מבצע ריינהרד. לפחות 167,000 יהודים נרצחו בו.","context":"המחנה נועד בעיקר לרצח המוני של יהודים שגורשו מאזורים שונים באירופה הכבושה.","aftermath":"לאחר מרד האסירים ב־1943 פירקו הגרמנים את המחנה וניסו לטשטש את עקבותיו.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-treblinka-ii-killing-center-136"]={"title":"מרכז ההרג טרבלינקה II","location":"טרבלינקה, פולין הכבושה בידי גרמניה","story":"טרבלינקה II פעל כמרכז הרג במסגרת מבצע ריינהרד. אנשי המשטר הנאצי רצחו בו לפי ההערכות כ־925,000 יהודים.","context":"טרבלינקה היה אחד מאתרי הרצח ההמוני הקטלניים ביותר של השואה.","aftermath":"לאחר מרד אסירים ב־1943 פורק האתר ונעשו ניסיונות להסוות את תפקידו.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-auschwitz-birkenau-mass-murder-of-jews-137"]={"title":"הרצח ההמוני של יהודים באושוויץ־בירקנאו","location":"אושוויץ־בירקנאו, פולין הכבושה בידי גרמניה","story":"אושוויץ־בירקנאו נעשה מתחם הריכוז וההרג הגדול ביותר של גרמניה הנאצית. כמיליון יהודים נרצחו במתחם אושוויץ.","context":"האתר שילב מחנה ריכוז, עבודת כפייה ומערכת רצח המוני, בעיקר באמצעות תאי גזים.","aftermath":"אושוויץ נעשה אחד הסמלים המרכזיים של השואה ושל רצח יהודי אירופה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-great-action-deportation-of-warsaw-jews-to-treblinka-138"]={"title":"האקציה הגדולה: גירוש יהודי ורשה לטרבלינקה","location":"ורשה, פולין הכבושה בידי גרמניה","story":"מיולי עד ספטמבר 1942 גירשו הרשויות הגרמניות כ־265,000 יהודים מגטו ורשה לטרבלינקה ורצחו כ־35,000 יהודים בגטו במהלך המבצע.","context":"הגירוש היה חלק ממבצע ריינהרד ומחיסול הקהילות היהודיות בפולין הכבושה.","aftermath":"רוב אוכלוסיית הגטו גורשה ונרצחה; הנותרים התארגנו בהמשך להתנגדות חמושה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-operation-reinhard-139"]={"title":"מבצע ריינהרד","location":"פולין הכבושה בידי גרמניה","story":"מבצע ריינהרד היה התוכנית הנאצית לרצח יהודי הגנרלגוברנמן בפולין הכבושה. מרכזי ההרג העיקריים היו בלז'ץ, סוביבור וטרבלינקה, לצד גירושים וירי המוני.","context":"האירוע הוא מסגרת־על; מרכזי ההרג והגירושים המרכזיים מיוצגים גם כאירועים נפרדים בציר הזמן.","aftermath":"המבצע השמיד את רוב הקהילות היהודיות באזור והיה מרכיב מרכזי בפתרון הסופי.","sourceStatus":"מתועד בהרחבה; סמנים נפרדים מספקים אומדני קורבנות ספציפיים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1943-warsaw-ghetto-uprising-140"]={"title":"מרד גטו ורשה","location":"ורשה, פולין הכבושה בידי גרמניה","story":"לוחמים יהודים התנגדו למבצע הגירוש הגרמני הסופי שהחל ב־19 באפריל 1943. לפחות 7,000 יהודים מתו בלחימה או במקומות מסתור בזמן שהכוחות הגרמניים החריבו את הגטו.","context":"המרד היה פעולת התנגדות יהודית מזוינת נגד חיסול הגטו וגירוש תושביו.","aftermath":"המרד דוכא והגטו נהרס, אך הוא נעשה סמל מרכזי להתנגדות יהודית בשואה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1943-operation-harvest-festival-141"]={"title":"מבצע חג הקציר","location":"מחוז לובלין, פולין הכבושה בידי גרמניה","story":"אנשי אס־אס ומשטרה גרמנים רצחו עשרות אלפי עובדי כפייה יהודים במחוז לובלין במהלך מבצע חג הקציר בנובמבר 1943.","context":"המבצע נועד לחסל את האוכלוסייה היהודית שנותרה במחנות עבודת הכפייה המרכזיים באזור לובלין.","aftermath":"זה היה אחד ממבצעי הירי ההמוני הגדולים ביותר שביצעו הגרמנים נגד יהודים ביום ובפרק זמן קצר.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1943-bia-ystok-ghetto-uprising-142"]={"title":"מרד גטו ביאליסטוק","location":"ביאליסטוק, פולין הכבושה","story":"כאשר הכוחות הגרמניים החלו בחיסול הסופי של גטו ביאליסטוק באוגוסט 1943, פתחו לוחמי המחתרת היהודית במרד חמוש. ההתנגדות הוכרעה ורוב היהודים שנותרו גורשו למרכזי הרג ולמחנות.","context":"המרד היה ניסיון התנגדות מאורגן מול חיסול הגטו וגירוש תושביו.","aftermath":"רוב הקהילה שנותרה גורשה או נרצחה לאחר דיכוי ההתנגדות.","sourceStatus":"מתועד היטב ברשומות גרמניות, בדיווחי מחתרת ובעדויות ניצולים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1943-sobibor-uprising-and-mass-escape-143"]={"title":"מרד סוביבור והבריחה ההמונית","location":"מרכז ההרג סוביבור, פולין הכבושה","story":"ב־14 באוקטובר 1943 ארגנו אסירים יהודים בסוביבור מרד, הרגו כמה אנשי אס־אס ושומרים וניסו בריחה המונית. מאות פרצו מן המחנה; מספר קטן יותר שרד את המלחמה.","context":"המרד היה אחת מפעולות ההתנגדות הגדולות בתוך מרכז הרג נאצי.","aftermath":"המרד תרם להחלטה הגרמנית לפרק את מרכז ההרג ולטשטש את עקבותיו.","sourceStatus":"מתועד בהרחבה בעדויות ניצולים, ברשומות גרמניות ובחקירות שלאחר המלחמה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1943-treblinka-prisoner-uprising-144"]={"title":"מרד האסירים בטרבלינקה","location":"טרבלינקה II, פולין הכבושה","story":"ב־2 באוגוסט 1943 תפסו אסירים במרכז ההרג טרבלינקה נשק, הציתו חלקים מן המחנה וניסו בריחה המונית. מאות עברו את גדר המחנה, אך רבים ניצודו ונרצחו; מספר קטן יותר שרד את המלחמה.","context":"המרד היה התנגדות מאורגנת של אסירים בתוך אחד ממרכזי ההרג המרכזיים של מבצע ריינהרד.","aftermath":"המרד פגע במחנה והיה בין הגורמים שקדמו לפירוקו בידי הגרמנים.","sourceStatus":"המרד מתועד בהרחבה בעדויות ניצולים, ברשומות גרמניות ובמחקר שלאחר המלחמה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1944-deportation-of-hungarian-jews-to-auschwitz-birkenau-145"]={"title":"גירוש יהודי הונגריה לאושוויץ־בירקנאו","location":"הונגריה → אושוויץ־בירקנאו","story":"לאחר שגרמניה כבשה את הונגריה במרץ 1944 ריכזו וגירשו הרשויות ההונגריות, בשיתוף אנשי אס־אס גרמנים, יהודים במהירות. בין מאי ליולי גורשו כ־440,000 יהודים, רובם לאושוויץ־בירקנאו, ושם נרצח רובם.","context":"הגירושים היו מן המבצעים המהירים והגדולים ביותר של השלב האחרון בשואה.","aftermath":"בתוך שבועות ספורים הושמד חלק עצום מיהדות הונגריה שמחוץ לבודפשט.","sourceStatus":"מתועד בהרחבה ברשומות גירוש, תיעוד גרמני והונגרי, תצלומים ועדויות ניצולים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1944-auschwitz-sonderkommando-revolt-146"]={"title":"מרד הזונדרקומנדו באושוויץ","location":"אושוויץ־בירקנאו, פולין הכבושה","story":"ב־7 באוקטובר 1944 מרדו אסירי זונדרקומנדו יהודים באושוויץ־בירקנאו. הם תקפו שומרי אס־אס ופגעו בקרמטוריום IV באמצעות חומרי נפץ שהוברחו בידי אסירות יהודיות שעבדו במפעל סמוך.","context":"המרד היה ניסיון התנגדות של אסירים שנכפו לעבוד במתקני הרצח והשרפה.","aftermath":"המרד דוכא והמשתתפים הוצאו להורג, אך הקרמטוריום ניזוק והאירוע נעשה סמל להתנגדות בתוך אושוויץ.","sourceStatus":"מתועד בהרחבה ברשומות המחנה ובעדויות ניצולים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1944-liquidation-of-the-o-dz-ghetto-147"]={"title":"חיסול גטו לודז'","location":"לודז', פולין הכבושה","story":"ב־1944 חיסלו הרשויות הגרמניות את גטו לודז', מן הגטאות הגדולים והממושכים בפולין הכבושה. רוב היהודים שנותרו גורשו לאושוויץ־בירקנאו, לאחר שגירושים קודמים שלחו עשרות אלפים לחלמנו.","context":"החיסול היה השלב האחרון בפירוק אחת הקהילות היהודיות הגדולות שנותרו בגטאות.","aftermath":"רוב תושבי הגטו שנותרו גורשו למרכזי הרג ורק מיעוט שרד.","sourceStatus":"החיסול והגירושים מתועדים בהרחבה ברשומות גרמניות, בתיעוד הגטו ובעדויות ניצולים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1945-death-marches-during-the-collapse-of-nazi-germany-148"]={"title":"צעדות המוות בזמן קריסת גרמניה הנאצית","location":"מרכז ומזרח אירופה","story":"כאשר צבאות בעלות הברית התקרבו למחנות הריכוז, פינו אנשי האס־אס אסירים לעומק גרמניה. אסירים, ובהם יהודים רבים, אולצו לצעוד ולהיטלטל בתנאי חורף קשים; שומרים רצחו מי שלא יכלו להמשיך ורבים אחרים מתו מחשיפה, רעב ותשישות.","context":"הפינויים נועדו להעביר אסירים הרחק מהצבאות המתקדמים והפכו לשלב קטלני נוסף בחודשי המלחמה האחרונים.","aftermath":"עשרות אלפי אסירים מתו בצעדות ובפינויים לפני שחרור המחנות וסיום המלחמה.","sourceStatus":"מתועד בהרחבה בפינויים רבים; המספרים הכוללים משתנים משום שהתרחשו צעדות רבות ונפרדות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1946-kielce-pogrom-149"]={"title":"פוגרום קיילצה","location":"קיילצה, פולין","story":"המון, שאליו הצטרפו כמה שוטרים וחיילים, רצח ניצולי שואה יהודים ויהודים אחרים בקיילצה; לפחות 42 יהודים נרצחו.","context":"האירוע היה אלימות אנטי־יהודית לאחר השואה והמחיש את הסכנה שנמשכה עבור ניצולים שחזרו או ניסו לבנות מחדש את חייהם.","aftermath":"הפוגרום האיץ את יציאתם של יהודים רבים מפולין לאחר המלחמה והעמיק את תחושת חוסר הביטחון.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1946-king-david-hotel-bombing-150"]={"title":"פיצוץ מלון המלך דוד","location":"ירושלים, ארץ ישראל המנדטורית","story":"ב־22 ביולי 1946 פוצץ ארגון האצ״ל את האגף הדרומי של מלון המלך דוד בירושלים, שבו שכנו משרדי הממשל והצבא הבריטיים. 91 בני אדם נהרגו, ובהם ערבים, בריטים, יהודים ואחרים.","context":"הפיגוע היה חלק מן המאבק של ארגוני המחתרת היהודיים נגד שלטון המנדט הבריטי.","aftermath":"הפיצוץ החריף את העימות עם בריטניה והפך לאחד האירועים השנויים במחלוקת של תקופת המנדט.","sourceStatus":"הפיגוע, מבצעיו ומספר ההרוגים מתועדים בהרחבה; קיימת מחלוקת על האזהרות ועל תגובת הבריטים לפני הפיצוץ"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1947-fajja-bus-attacks-151"]={"title":"התקפות האוטובוסים ליד פג'ה","location":"ליד פתח תקווה, ארץ ישראל המנדטורית","story":"ב־30 בנובמבר 1947, יום לאחר הצבעת האו״ם על החלוקה, תקפו חמושים ערבים אוטובוסים יהודיים. ההתקפות היו בין האירועים הפותחים של שלב מלחמת האזרחים בסכסוך 1947–1949.","context":"האירוע התרחש מיד לאחר החלטת החלוקה ובתוך הסלמה מהירה של אלימות בין הקהילות.","aftermath":"ההתקפות סימנו את המעבר לעימות מזוין רחב יותר בארץ ישראל המנדטורית.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1947-1947-1949-palestine-war-arab-israeli-war-152"]={"title":"מלחמת 1947–1949 בארץ ישראל / מלחמת ערב–ישראל","location":"ארץ ישראל המנדטורית / ישראל","story":"הלחימה החלה לאחר הצבעת האו״ם על החלוקה; לאחר הכרזת העצמאות של ישראל במאי 1948 נכנסו צבאות ערביים שכנים למלחמה. אזרחים ולוחמים יהודים וערבים ספגו אבדות כבדות ועקירה.","context":"המלחמה כללה תחילה מלחמת אזרחים בין כוחות יהודיים וערביים ובהמשך מלחמה בין־מדינתית.","aftermath":"המלחמה הקימה את מדינת ישראל, שינתה גבולות, יצרה משברי פליטים ועקירה והותירה סכסוכים טריטוריאליים ופוליטיים בלתי פתורים.","sourceStatus":"רמת ודאות גבוהה מאוד; נרטיבים וחלק מן הנתונים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1947-un-partition-plan-and-outbreak-of-civil-war-in-mandatory-palestine-153"]={"title":"תוכנית החלוקה של האו״ם ופרוץ מלחמת האזרחים בארץ ישראל המנדטורית","location":"ארץ ישראל המנדטורית","story":"ב־29 בנובמבר 1947 המליצה העצרת הכללית של האו״ם לחלק את הארץ למדינה ערבית ולמדינה יהודית, עם משטר בינלאומי לירושלים. הנהגת הסוכנות היהודית קיבלה את החלוקה כבסיס למדינה; מנהיגים ערבים דחו אותה. הלחימה בין כוחות ערביים פלסטיניים לכוחות יהודיים החריפה כמעט מיד.","context":"החלטה 181 הייתה המלצה בינלאומית לחלוקה והפכה לנקודת מפנה פוליטית ומלחמתית.","aftermath":"האלימות התרחבה במהירות והובילה למלחמת 1948, להקמת ישראל ולעקירה רחבת היקף.","sourceStatus":"החלטה 181 וההסלמה שאחריה מתועדות בהרחבה; פרשנויות לגבי אחריות, כוונות והוגנות התוכנית נותרו שנויות במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-hadassah-medical-convoy-massacre-154"]={"title":"טבח שיירת הדסה","location":"ירושלים","story":"באפריל 1948 ארב כוח ערבי לשיירה שהובילה אנשי רפואה ואספקה לבית החולים הדסה ולאוניברסיטה העברית בהר הצופים; 78 יהודים נהרגו.","context":"האירוע התרחש בתוך הקרבות והמצור סביב ירושלים במהלך מלחמת האזרחים של 1947–1948.","aftermath":"הטבח העמיק את האלימות והפגיעה בשירותים רפואיים ובגישה להר הצופים.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-deir-yassin-massacre-155"]={"title":"טבח דיר יאסין","location":"דיר יאסין, ליד ירושלים","story":"ב־9 באפריל 1948 תקפו לוחמי האצ״ל ולח״י את הכפר הערבי הפלסטיני דיר יאסין. יותר ממאה מתושבי הכפר, ובהם אזרחים, נהרגו. הטבח הפך לסמל מרכזי של הסבל הפלסטיני ותרם לפחד במהלך מלחמת 1948.","context":"האירוע היה חלק ממלחמת האזרחים וחשוב להציגו לצד התקפות על יהודים ואירועי עקירה פלסטיניים באותה תקופה.","aftermath":"החדשות על הטבח תרמו לפחד ולבריחה במקומות אחרים והאירוע נותר מרכזי בזיכרון הפלסטיני.","sourceStatus":"ההתקפה והרג אזרחים מתועדים היטב; המספר המדויק וחלק מפרטי הקרב נדונו במחקר, והערכות מודרניות מציבות בדרך כלל את מספר ההרוגים סביב 100–110"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-kfar-etzion-massacre-156"]={"title":"טבח כפר עציון","location":"כפר עציון, דרומית לירושלים","story":"ב־13 במאי 1948 נפל כפר עציון לידי הלגיון הערבי וכוחות ערביים מקומיים לאחר לחימה ממושכת. מספר גדול של מגינים ותושבים יהודים נהרגו לאחר קריסת ההגנה ורק מעטים שרדו. יתר יישובי גוש עציון נכנעו למחרת.","context":"האירוע התרחש בשלב האחרון של מלחמת האזרחים, ערב סיום המנדט הבריטי.","aftermath":"נפילת הגוש נעשתה סמל מרכזי בזיכרון הישראלי של מלחמת 1948.","sourceStatus":"נפילת כפר עציון וההרג ההמוני מתועדים היטב; המקורות שונים לגבי הנסיבות המדויקות של מות יחידים לאחר הכניעה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-declaration-of-the-state-of-israel-157"]={"title":"הכרזת מדינת ישראל","location":"תל אביב","story":"ב־14 במאי 1948 הכריז דוד בן־גוריון על הקמת מדינת ישראל עם סיום המנדט הבריטי. ההכרזה הפכה את מלחמת האזרחים המתמשכת לעימות בין־מדינתי כאשר צבאות ערביים שכנים נכנסו לשטח המנדט לשעבר.","context":"האירוע היה נקודת מעבר מרכזית מהיישוב היהודי למדינה ריבונית בתוך מלחמה פעילה.","aftermath":"ישראל קמה כמדינה, והמלחמה התרחבה מיד עם התערבות צבאות ערב.","sourceStatus":"ההכרזה והמעבר הצבאי המיידי מתועדים ישירות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-arab-armies-enter-palestine-and-the-first-arab-israeli-war-expands-158"]={"title":"צבאות ערב נכנסים לארץ והמלחמה הערבית–ישראלית הראשונה מתרחבת","location":"ישראל / שטח ארץ ישראל המנדטורית לשעבר","story":"החל ב־15 במאי נכנסו צבאות מצרים, עבר הירדן, סוריה, עיראק ולבנון למלחמה בעקבות הכרזת העצמאות של ישראל. המלחמה כללה כעת את המדינה הישראלית החדשה, כוחות ערביים פלסטיניים ומספר מדינות ערביות שכנות.","context":"לממשלות ערב השונות היו מטרות צבאיות ופוליטיות שונות, ולכן אין לתאר את ההתערבות כאסטרטגיה אחידה לחלוטין.","aftermath":"העימות התרחב למלחמה בין־מדינתית שהסתיימה בהסכמי שביתת הנשק של 1949.","sourceStatus":"התערבות צבאות ערב השכנים מתועדת בהרחבה; המטרות והחישובים הפוליטיים השתנו בין הממשלות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-fall-of-the-jewish-quarter-of-jerusalem-s-old-city-159"]={"title":"נפילת הרובע היהודי בעיר העתיקה בירושלים","location":"ירושלים","story":"לאחר מצור ולחימה נכנע הרובע היהודי בעיר העתיקה ללגיון הערבי של עבר הירדן ב־28 במאי 1948. התושבים היהודים פונו מן הרובע והמגינים שנותרו בחיים נשבו. בתי כנסת ואתרים יהודיים נוספים ניזוקו או נהרסו לאחר מכן בתקופת השלטון הירדני.","context":"האירוע היה חלק מן המאבק על ירושלים במלחמת 1948.","aftermath":"העיר העתיקה נותרה בשליטה ירדנית עד 1967 ותושביה היהודים של הרובע לא יכלו לשוב בתקופה זו.","sourceStatus":"הכניעה והפינוי מתועדים היטב; תיאורי ההרס המאוחר משתנים לפי האתר והמקור"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-lydda-and-ramle-fighting-killings-and-palestinian-expulsion-160"]={"title":"לוד ורמלה: לחימה, הרג וגירוש פלסטינים","location":"לוד ורמלה","story":"כוחות ישראליים כבשו את לוד ורמלה ביולי 1948 במסגרת מבצע דני. אזרחים נהרגו במהלך הלחימה בלוד, ולאחר מכן רוב האוכלוסייה הערבית הפלסטינית של שתי הערים גורשה או נאלצה לברוח מזרחה. האירוע מרכזי בוויכוח ההיסטורי על משבר הפליטים הפלסטינים.","context":"האירוע מדגים שגם פעולות צבאיות ישראליות וגירוש פלסטינים הם חלק הכרחי מן התמונה המלאה של מלחמת 1948.","aftermath":"עשרות אלפי פלסטינים נעקרו והערים עברו לשליטה ישראלית.","sourceStatus":"הכיבוש והעקירה ההמונית מתועדים היטב; היסטוריונים חלוקים לגבי היבטים של הפקודות, מספרי ההרוגים והמנגנונים המדויקים של הגירוש"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-palestinian-refugee-and-displacement-crisis-161"]={"title":"משבר הפליטים והעקירה הפלסטיני","location":"פלסטין / מדינות ערב השכנות","story":"במהלך מלחמת 1947–1949 מאות אלפי ערבים פלסטינים ברחו או גורשו מבתיהם בשטח שהפך לישראל. הסיבות השתנו לפי מקום ושלב במלחמה וכללו גירוש ישיר, בריחה מקרבות, פחד מהתקפה והתמוטטות החברה הפלסטינית. ישראל מנעה בדרך כלל מרוב הפליטים לשוב לאחר המלחמה.","context":"העקירה ההמונית אינה שנויה במחלוקת, אך המשקל היחסי של הסיבות והאחריות במקומות מסוימים נותר נושא מרכזי למחלוקת היסטורית ופוליטית.","aftermath":"משבר הפליטים נעשה אחת הסוגיות המרכזיות והמתמשכות בסכסוך הישראלי–פלסטיני.","sourceStatus":"העקירה רחבת ההיקף אינה שנויה במחלוקת; מאזן הסיבות והאחריות ביישובים מסוימים נותר אחד הנושאים השנויים ביותר במחלוקת בתולדות הסכסוך"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-assassination-of-un-mediator-folke-bernadotte-162"]={"title":"רצח מתווך האו״ם פולקה ברנדוט","location":"ירושלים","story":"ב־17 בספטמבר 1948 נרצח בירושלים מתווך האו״ם הרוזן פולקה ברנדוט בידי חברי לח״י, ארגון מחתרת יהודי. ברנדוט מונה לתווך במלחמה הערבית–ישראלית והציע הסדרים בנושאי גבולות, ירושלים ופליטים.","context":"האירוע מתעד אלימות פוליטית שביצע ארגון יהודי ואינו מוצג כאירוע שבו יהודים היו הקורבנות.","aftermath":"הרצח עורר גינוי בינלאומי והאיץ צעדים ישראליים נגד לח״י.","sourceStatus":"הרצח ואחריות לח״י מתועדים היטב ברשומות האו״ם ובמקורות היסטוריים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1949-1949-armistice-agreements-end-major-fighting-163"]={"title":"הסכמי שביתת הנשק של 1949 מסיימים את הלחימה העיקרית","location":"ישראל ומדינות ערב השכנות","story":"ישראל חתמה ב־1949 על הסכמי שביתת נשק נפרדים עם מצרים, לבנון, ירדן וסוריה. ההסכמים סיימו את הלחימה הבין־מדינתית העיקרית אך לא יצרו הסכמי שלום כוללים. קווי שביתת הנשק נעשו הגבולות המעשיים עד מלחמת 1967.","context":"ההסכמים סיימו את השלב הצבאי העיקרי של מלחמת 1948 בלי לפתור את הסכסוך הרחב.","aftermath":"הגבולות, סוגיית הפליטים ומעמד ירושלים נותרו בלתי פתורים והמשיכו לעצב את הסכסוכים הבאים.","sourceStatus":"ההסכמים וקווי שביתת הנשק מתועדים ישירות ברשומות האו״ם"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1919-proskurov-pogrom-108"]={"title":"بوغروم بروسكوروف","location":"بروسكوروف، أوكرانيا","story":"في فبراير 1919، خلال الحرب الأهلية في أوكرانيا، قتل جنود مرتبطون بقوات سيمون بتليورا مئات اليهود في بروسكوروف في بوغروم كبير.","context":"كان البوغروم جزءًا من موجة أوسع من العنف المعادي لليهود خلال الحروب الأهلية والصراعات القومية التي أعقبت الحرب العالمية الأولى.","aftermath":"أصبحت المذبحة من أشهر بوغرومات تلك الفترة وأظهرت الخطر الشديد الذي واجهته المجتمعات اليهودية في مناطق الحرب.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1920-nebi-musa-riots-109"]={"title":"اضطرابات النبي موسى","location":"القدس","story":"شمل العنف خلال موسم النبي موسى هجمات على المجتمع اليهودي في القدس وسط تصاعد التوتر السياسي العربي اليهودي في عهد الانتداب البريطاني.","context":"كانت الحادثة جزءًا من الصراع السياسي والمجتمعي المتنامي في فلسطين خلال الانتداب.","aftermath":"عمقت الاضطرابات انعدام الثقة وأدت إلى تغييرات في التنظيم الأمني اليهودي.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1921-jaffa-riots-110"]={"title":"اضطرابات يافا","location":"يافا والمنطقة المحيطة","story":"أدى العنف العربي اليهودي في يافا والمناطق المجاورة إلى قتلى وجرحى من المجتمعين وعمق توترات عهد الانتداب.","context":"وقع العنف وسط تصاعد التوترات القومية والسياسية والاجتماعية بين العرب واليهود.","aftermath":"فاقمت الأحداث الانقسام والمخاوف الأمنية وأدت إلى ردود من سلطات الانتداب.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1929-hebron-massacre-and-1929-palestine-riots-111"]={"title":"مذبحة الخليل واضطرابات فلسطين سنة 1929","location":"الخليل وفلسطين الانتدابية","story":"خلال أعمال العنف الواسعة سنة 1929 قتل مهاجمون عرب 67 يهوديًا في الخليل. كما تعرض يهود لهجمات في أماكن أخرى، بينما قُتل عرب في اشتباكات وعلى يد القوات البريطانية.","context":"كانت مذبحة الخليل جزءًا من موجة عنف أوسع، ولذلك ينبغي التمييز بين الحادثة المحلية ومجمل ضحايا اضطرابات 1929.","aftermath":"أُخلي المجتمع اليهودي القديم في الخليل بعد المذبحة وعمق العنف الصراع في عهد الانتداب.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1929-safed-massacre-during-the-1929-riots-112"]={"title":"مذبحة صفد خلال اضطرابات 1929","location":"صفد، فلسطين الانتدابية","story":"خلال اضطرابات 1929 هاجم عرب سكانًا يهودًا في صفد وقتلوا يهودًا وأحرقوا ونهبوا منازل يهودية.","context":"هذه حادثة محددة داخل موجة العنف الأوسع لسنة 1929 والممثلة أيضًا في أحداث أخرى في الخط الزمني.","aftermath":"تكبد المجتمع اليهودي في صفد قتلى وإصابات وأضرارًا بالممتلكات وتصاعد التوتر في المنطقة.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1933-nazi-seizure-of-power-begins-systematic-persecution-of-german-jews-113"]={"title":"استيلاء النازيين على السلطة يبدأ الاضطهاد المنهجي ليهود ألمانيا","location":"ألمانيا","story":"بعد أن أصبح أدولف هتلر مستشارًا في 30 يناير 1933 حوّل النظام النازي الأيديولوجيا المعادية للسامية بسرعة إلى سياسة حكومية. وواجه اليهود الترهيب والاعتداء والاستبعاد من المؤسسات العامة ونظامًا متوسعًا من القوانين التمييزية.","context":"يتتبع هذا المؤشر التصعيد من الأيديولوجيا المعادية للسامية إلى سياسة الدولة والإقصاء القانوني ونزع الملكية الاقتصادية والعنف المتزايد.","aftermath":"عزلت هذه الإجراءات المجتمعات اليهودية وأفقرتها وعرضتها للخطر تدريجيًا وساعدت في إنشاء الإطار المؤسسي للاضطهاد الأشد والقتل الجماعي لاحقًا.","sourceStatus":"موثق على نطاق واسع في السجلات الألمانية والتقارير المعاصرة وأرشيفات الهولوكوست"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1933-nationwide-nazi-boycott-of-jewish-businesses-114"]={"title":"مقاطعة نازية وطنية للأعمال اليهودية","location":"ألمانيا","story":"في 1 أبريل 1933 نظم الحزب النازي مقاطعة وطنية للمتاجر المملوكة لليهود وللمهنيين اليهود. ووقف أفراد قوات العاصفة خارج المتاجر والمكاتب لترهيب الزبائن. ورغم أن المقاطعة الرسمية استمرت يومًا واحدًا، فإنها دشنت حملة وطنية لإخراج اليهود من الحياة الاقتصادية الألمانية.","context":"كانت المقاطعة مرحلة مبكرة في تحويل معاداة السامية إلى سياسة مؤسسية للإقصاء الاقتصادي.","aftermath":"توسعت الإجراءات الاقتصادية ضد اليهود في السنوات التالية وأدت إلى نزع ملكية أكثر منهجية.","sourceStatus":"موثق على نطاق واسع؛ نظمت سلطات الحزب النازي المقاطعة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1933-civil-service-law-excludes-jews-from-government-employment-115"]={"title":"قانون الخدمة المدنية يستبعد اليهود من الوظائف الحكومية","location":"ألمانيا","story":"أزال قانون استعادة الخدمة المدنية المهنية الصادر في 7 أبريل كثيرًا من اليهود والمعارضين السياسيين من الوظائف الحكومية. وكان من أوائل الخطوات القانونية الكبرى للإقصاء المنهجي لليهود من الحياة العامة الألمانية.","context":"يوضح التشريع الانتقال السريع من التمييز السياسي إلى قانون دولة ملزم.","aftermath":"امتد الإقصاء لاحقًا إلى مهن ومؤسسات أخرى وساعد في عزل يهود ألمانيا.","sourceStatus":"التشريع وتطبيقه موثقان مباشرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1935-nuremberg-laws-strip-jews-of-rights-and-impose-racial-definitions-116"]={"title":"قوانين نورمبرغ تسلب اليهود حقوقهم وتفرض تعريفات عرقية","location":"نورمبرغ / ألمانيا النازية","story":"حرمت قوانين نورمبرغ يهود ألمانيا من المواطنة الكاملة وحظرت الزواج والعلاقات الجنسية بين اليهود ومن صُنّفوا من الدم الألماني أو القريب منه. وحددت السلطات النازية الهوية اليهودية وفق الأصل العرقي لا الاعتقاد الديني الشخصي.","context":"حولت القوانين التمييز العرقي إلى مبدأ قانوني مركزي للدولة النازية.","aftermath":"عمقت عزلة اليهود ومهدت لمزيد من نزع الملكية والطرد والاضطهاد.","sourceStatus":"تشريعات نازية وممارسة إدارية موثقة على نطاق واسع"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1936-1936-1939-arab-revolt-attacks-on-jewish-civilians-117"]={"title":"الثورة العربية 1936–1939: هجمات على المدنيين اليهود","location":"فلسطين الانتدابية","story":"شملت الثورة العربية ضد الحكم البريطاني والهجرة اليهودية الواسعة هجمات على مدنيين ومجتمعات يهودية، إلى جانب مكافحة التمرد البريطانية وردود مسلحة يهودية.","context":"كانت الحادثة جزءًا من تمرد واسع ضد البريطانيين ومن صراع قومي متصاعد؛ ووقع العنف في سياقات مختلفة ومن عدة أطراف.","aftermath":"غيرت الثورة السياسة البريطانية والتنظيم العسكري اليهودي والعلاقات بين المجتمعات قبيل نهاية الانتداب.","sourceStatus":"ثقة عالية جدًا؛ الحوادث الفردية تحتاج مصادر منفصلة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1937-escalating-exclusion-and-aryanization-of-jewish-economic-life-118"]={"title":"تصاعد إقصاء و«أرينة» الحياة الاقتصادية اليهودية","location":"ألمانيا","story":"من 1937 إلى 1939 أجبرت السياسة النازية اليهود بصورة متزايدة على الخروج من المهن والأعمال ونقلت الممتلكات اليهودية إلى ملكية غير يهودية بشروط قسرية. وأفقرت هذه العملية، المعروفة بالأرينة، الأسر اليهودية وعزلتها أكثر عن المجتمع الألماني.","context":"كان نزع الملكية الاقتصادية جزءًا من التصعيد المنهجي لاضطهاد يهود ألمانيا.","aftermath":"قلصت السياسة قدرة اليهود على البقاء اقتصاديًا وزادت الضغط للهجرة.","sourceStatus":"موثق على نطاق واسع بالمراسيم النازية وسجلات الملكية ودراسات الهولوكوست"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1938-kristallnacht-november-pogrom-119"]={"title":"ليلة الكريستال / بوغروم نوفمبر","location":"ألمانيا والنمسا","story":"أطلق قادة النازيين عنفًا وطنيًا ضد اليهود: أُحرقت المعابد ودُمرت المتاجر والمنازل وقُتل يهود وسُجن نحو 26 ألف رجل يهودي في معسكرات الاعتقال.","context":"مثل البوغروم انتقالًا بارزًا من الاضطهاد القانوني والاقتصادي إلى عنف جماعي منظم من النظام.","aftermath":"سرّع الحدث الهجرة ونزع الملكية والسجن وكان مرحلة رئيسية نحو الاضطهاد القاتل في زمن الحرب.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1939-german-invasion-of-poland-and-persecution-of-polish-jews-120"]={"title":"الغزو الألماني لبولندا واضطهاد يهود بولندا","location":"بولندا المحتلة","story":"غزت ألمانيا بولندا في 1 سبتمبر 1939. وبدأت القوات الألمانية وسلطات الاحتلال فورًا بإذلال اليهود وفرض العمل القسري والسرقة والتهجير والعنف. وخضع العدد الكبير من يهود بولندا للحكم النازي.","context":"كانت هذه مرحلة مركزية في تسلسل الهولوكوست، إذ وسع الاحتلال الاضطهاد النازي ليشمل ملايين اليهود الآخرين.","aftermath":"أدى الاحتلال إلى تجميع اليهود في الغيتوات والترحيل ثم القتل الجماعي المنهجي.","sourceStatus":"موثق على نطاق واسع في السجلات الألمانية وشهادات العيان وأرشيفات الهولوكوست"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1940-nazi-ghettos-isolate-jewish-communities-in-occupied-poland-121"]={"title":"الغيتوات النازية تعزل المجتمعات اليهودية في بولندا المحتلة","location":"بولندا المحتلة ألمانيًا","story":"أجبرت السلطات الألمانية اليهود على الانتقال إلى أحياء حضرية مغلقة أو مقيدة عُرفت بالغيتوات. وعانت غيتوات مثل لودج ووارسو من اكتظاظ شديد وجوع ومرض وعمل قسري، ثم استُخدمت نقاط تجميع للترحيل إلى مراكز القتل.","context":"كانت الغيتوات جزءًا من نظام اضطهاد تقدم من العزل والاستغلال إلى الترحيل والقتل الجماعي.","aftermath":"مات مئات الآلاف من ظروف الحياة أو رُحلوا لاحقًا إلى مراكز القتل.","sourceStatus":"موثق على نطاق واسع في السجلات الإدارية الألمانية والصور واليوميات وشهادات الناجين"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-farhud-122"]={"title":"الفرهود","location":"بغداد، العراق","story":"في 1–2 يونيو 1941 اندلع عنف معادٍ لليهود في بغداد أدى إلى قتل وجرح يهود ونهب ودمار واسع.","context":"وقع الفرهود وسط أزمة سياسية عراقية خلال الحرب العالمية الثانية بعد انهيار نظام رشيد عالي الموالي للمحور.","aftermath":"زعزع الحدث بشدة شعور يهود العراق بالأمان وأصبح محطة مركزية في ذاكرة المجتمع.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-ias-i-pogrom-123"]={"title":"بوغروم ياش","location":"ياش، رومانيا","story":"قتلت السلطات والوحدات العسكرية الرومانية، بمساعدة جنود ألمان في بعض الحالات، ما لا يقل عن 8,000 يهودي خلال بوغروم يونيو 1941 وقطارات الموت المرتبطة به.","context":"كان الحدث جزءًا من اضطهاد وقتل يهود رومانيا في الهولوكوست ونُفذ بمشاركة مركزية من السلطات الرومانية.","aftermath":"قُتل آلاف اليهود وتعرض المجتمع لكارثة واسعة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-lviv-pogrom-124"]={"title":"بوغروم لفيف","location":"لفيف، أوكرانيا المحتلة ألمانيًا","story":"بعد الاحتلال الألماني للمدينة شاركت قوات ألمانية ونشطاء قوميون أوكرانيون وأفراد ميليشيا ومدنيون محليون في إذلال اليهود وضربهم وقتلهم.","context":"وقع الحدث في الأيام الأولى للاحتلال الألماني وسط تصاعد سريع للعنف المعادي لليهود.","aftermath":"كان البوغروم جزءًا من بداية الإبادة الجماعية ليهود المنطقة تحت الاحتلال النازي.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-jedwabne-massacre-125"]={"title":"مذبحة يدفابنه","location":"يدفابنه، بولندا المحتلة ألمانيًا","story":"قُتل مئات السكان اليهود في يدفابنه في يوليو 1941 على يد جيران بولنديين بحضور الشرطة الألمانية؛ وما زالت جوانب التحريض والتوجيه الألماني موضع بحث تاريخي.","context":"المسؤولية المباشرة للمنفذين المحليين موثقة إلى جانب الوجود والسيطرة الألمانية في المنطقة؛ بعض جوانب المبادرة الألمانية ما تزال موضع بحث.","aftermath":"دُمر المجتمع اليهودي المحلي تقريبًا بالكامل.","sourceStatus":"ثقة عالية جدًا؛ بعض الجوانب موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-ponary-mass-killings-begin-126"]={"title":"بدء القتل الجماعي في بوناري","location":"قرب فيلنا، ليتوانيا","story":"قتلت وحدات الإس إس والشرطة الألمانية بمساعدة متعاونين ليتوانيين يهودًا من فيلنا والمناطق المحيطة في بوناري. وفي النهاية قُتل في الموقع عشرات الآلاف من اليهود.","context":"كان بوناري موقعًا رئيسيًا للقتل بالرصاص خلال الهولوكوست في شرق أوروبا.","aftermath":"أدت عمليات القتل إلى إبادة جزء كبير من السكان اليهود في فيلنا والمنطقة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-che-mno-killing-center-begins-mass-murder-127"]={"title":"مركز خيلمنو للقتل يبدأ القتل الجماعي","location":"خيلمنو، بولندا المحتلة ألمانيًا","story":"بدأ القتل الجماعي في خيلمنو في ديسمبر 1941 باستخدام شاحنات الغاز. وقتلت ألمانيا النازية هناك ما لا يقل عن 152 ألف يهودي.","context":"كان خيلمنو أول مركز قتل نازي استُخدم فيه الغاز بصورة منهجية للقتل الجماعي.","aftermath":"استُخدم المركز لإبادة مجتمعات يهودية، خاصة من منطقة فارتغاو وغيتو لودج.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-holocaust-mass-shootings-and-extermination-128"]={"title":"الهولوكوست: إطلاق النار الجماعي والإبادة","location":"أوروبا المحتلة ألمانيًا","story":"قتلت ألمانيا النازية وحلفاؤها والمتعاونون معها بصورة منهجية نحو ستة ملايين يهودي أوروبي عبر إطلاق النار ومراكز القتل والغيتوات والتجويع والعمل القسري ووسائل أخرى.","context":"هذا حدث شامل في الخط الزمني؛ وتوثق أحداث منفصلة مواقع قتل وترحيل وبوغرومات وأعمال مقاومة محددة.","aftermath":"دمر الهولوكوست المجتمعات اليهودية في أنحاء أوروبا وترك آثارًا ديموغرافية وسياسية وثقافية عميقة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-rumbula-massacre-129"]={"title":"مذبحة رومبولا","location":"قرب ريغا، لاتفيا المحتلة ألمانيًا","story":"قتل أفراد الإس إس والشرطة الألمان وقوات مساعدة لاتفية نحو 25 ألف يهودي من غيتو ريغا ونحو ألف يهودي ألماني في غابة رومبولا أواخر 1941.","context":"كانت المذبحة من أكبر عمليات القتل الجماعي بالرصاص في الهولوكوست قبل توسع مراكز القتل.","aftermath":"قُتل معظم سكان غيتو ريغا المستهدفين خلال أيام قليلة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-babi-yar-massacre-130"]={"title":"مذبحة بابي يار","location":"كييف، أوكرانيا المحتلة ألمانيًا","story":"في 29–30 سبتمبر 1941 قتل أفراد أينزاتسغروبه C ومتعاونون 33,771 رجلًا وامرأة وطفلًا يهوديًا في وادي بابي يار.","context":"وقع القتل بعد احتلال كييف وكان مثالًا رئيسيًا على الإبادة بإطلاق النار الجماعي.","aftermath":"واصل النازيون استخدام الموقع لقتل جماعات أخرى خلال الاحتلال.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-operation-barbarossa-and-einsatzgruppen-mass-shootings-131"]={"title":"عملية بارباروسا وإطلاق النار الجماعي للأينزاتسغروبن","location":"الأراضي السوفيتية المحتلة ألمانيًا","story":"بعد غزو ألمانيا للاتحاد السوفيتي في يونيو 1941 نفذت وحدات قتل متنقلة، بدعم قوات ألمانية أخرى ومساعدين محليين في مواقع مختلفة، عمليات إطلاق نار جماعي ضد اليهود وجماعات مستهدفة أخرى. وقُتلت مجتمعات يهودية كاملة قرب منازلها.","context":"مثل الغزو تصعيدًا حاسمًا من الاضطهاد والغيتوات إلى القتل الجماعي المنهجي في الأراضي السوفيتية المحتلة.","aftermath":"قتلت عمليات إطلاق النار مئات الآلاف من اليهود وكانت عنصرًا مركزيًا في تطور الهولوكوست.","sourceStatus":"موثق على نطاق واسع بالتقارير العملياتية الألمانية وسجلات الحرب والمقابر الجماعية وشهادات الناجين والشهود"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-kamianets-podilskyi-massacre-132"]={"title":"مذبحة كاميانيتس بوديلسكي","location":"كاميانيتس بوديلسكي، أوكرانيا السوفيتية المحتلة","story":"في أواخر أغسطس 1941 قتلت قوات الإس إس والشرطة الألمانية، بمشاركة قوات تحت القيادة الألمانية، عشرات الآلاف من اليهود قرب كاميانيتس بوديلسكي. وكان كثير من الضحايا قد رُحلوا من أراضٍ خاضعة للسيطرة المجرية، كما قُتل يهود أوكرانيون محليون.","context":"كانت المذبحة من أوائل عمليات القتل الجماعي الكبرى بعد عملية بارباروسا.","aftermath":"أظهر الحدث الانتقال السريع إلى قتل جماعي لمجتمعات يهودية كاملة.","sourceStatus":"موثق على نطاق واسع؛ أُبلغ عن مقتل نحو 23,600 يهودي في العملية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-odessa-massacre-under-romanian-occupation-133"]={"title":"مذبحة أوديسا تحت الاحتلال الروماني","location":"أوديسا والمنطقة المحيطة، أوكرانيا المحتلة","story":"بعد استيلاء القوات الرومانية والألمانية على أوديسا نفذت السلطات الرومانية أعمال انتقام جماعية ضد اليهود إثر انفجار في مقر عسكري روماني. وأُطلق النار على اليهود وشُنقوا وأُحرقوا في مبانٍ ورُحلوا إلى مواقع قتل ومعسكرات في ترانسنيستريا الخاضعة لرومانيا.","context":"كان الحدث جزءًا من اضطهاد وقتل اليهود تحت الإدارة الرومانية في المنطقة.","aftermath":"دمرت عمليات القتل والترحيل جزءًا كبيرًا من المجتمع اليهودي المحلي.","sourceStatus":"الدور الروماني والقتل الجماعي موثقان على نطاق واسع؛ تختلف أعداد الضحايا بحسب النطاق الجغرافي والزمني المحتسب"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-belzec-killing-center-134"]={"title":"مركز القتل بيلجيتس","location":"بيلجيتس، بولندا المحتلة ألمانيًا","story":"أصبح بيلجيتس مركز قتل ضمن عملية راينهارد. وقُتل فيه نحو 435 ألف يهودي، غالبيتهم الساحقة في غرف الغاز.","context":"كان بيلجيتس أحد مراكز القتل الثلاثة الرئيسية لعملية راينهارد الهادفة إلى إبادة يهود الحكومة العامة.","aftermath":"قُتل تقريبًا جميع المرحلين إلى بيلجيتس وفُكك المعسكر بعد انتهاء عمليات القتل الرئيسية.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-sobibor-killing-center-135"]={"title":"مركز القتل سوبيبور","location":"سوبيبور، بولندا المحتلة ألمانيًا","story":"أُنشئ سوبيبور كمركز قتل ضمن عملية راينهارد. وقُتل فيه ما لا يقل عن 167 ألف يهودي.","context":"خُصص المعسكر أساسًا للقتل الجماعي لليهود المرحلين من مناطق مختلفة من أوروبا المحتلة.","aftermath":"بعد انتفاضة السجناء سنة 1943 فكك الألمان المعسكر وحاولوا إخفاء آثاره.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-treblinka-ii-killing-center-136"]={"title":"مركز القتل تريبلينكا الثاني","location":"تريبلينكا، بولندا المحتلة ألمانيًا","story":"عمل تريبلينكا الثاني كمركز قتل ضمن عملية راينهارد. وقتل النازيون فيه ما يقدر بنحو 925 ألف يهودي.","context":"كان تريبلينكا من أكثر مواقع القتل الجماعي فتكًا في الهولوكوست.","aftermath":"بعد انتفاضة السجناء سنة 1943 فُكك الموقع وجرت محاولات لإخفاء دوره.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-auschwitz-birkenau-mass-murder-of-jews-137"]={"title":"القتل الجماعي لليهود في أوشفيتز-بيركيناو","location":"أوشفيتز-بيركيناو، بولندا المحتلة ألمانيًا","story":"أصبح أوشفيتز-بيركيناو أكبر مجمع نازي للاعتقال والقتل. وقُتل نحو مليون يهودي في مجمع أوشفيتز.","context":"جمع الموقع بين معسكر اعتقال والعمل القسري ونظام للقتل الجماعي، خصوصًا بغرف الغاز.","aftermath":"أصبح أوشفيتز أحد أبرز رموز الهولوكوست وقتل يهود أوروبا.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-great-action-deportation-of-warsaw-jews-to-treblinka-138"]={"title":"العملية الكبرى: ترحيل يهود وارسو إلى تريبلينكا","location":"وارسو، بولندا المحتلة ألمانيًا","story":"من يوليو إلى سبتمبر 1942 رحلت السلطات الألمانية نحو 265 ألف يهودي من غيتو وارسو إلى تريبلينكا وقتلت نحو 35 ألف يهودي داخل الغيتو خلال العملية.","context":"كان الترحيل جزءًا من عملية راينهارد ومن تدمير المجتمعات اليهودية في بولندا المحتلة.","aftermath":"رُحل وقُتل معظم سكان الغيتو، ونظم من تبقى لاحقًا مقاومة مسلحة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-operation-reinhard-139"]={"title":"عملية راينهارد","location":"بولندا المحتلة ألمانيًا","story":"كانت عملية راينهارد البرنامج النازي لقتل يهود الحكومة العامة في بولندا المحتلة. وكانت مراكز القتل الرئيسية بيلجيتس وسوبيبور وتريبلينكا، إلى جانب الترحيل وإطلاق النار الجماعي.","context":"هذا حدث شامل؛ وتمثل مراكز القتل وعمليات الترحيل الرئيسية أيضًا كأحداث منفصلة في الخط الزمني.","aftermath":"أبادت العملية معظم المجتمعات اليهودية في المنطقة وكانت عنصرًا مركزيًا في الحل النهائي.","sourceStatus":"موثق على نطاق واسع؛ توفر مؤشرات منفصلة تقديرات أكثر تحديدًا للضحايا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1943-warsaw-ghetto-uprising-140"]={"title":"انتفاضة غيتو وارسو","location":"وارسو، بولندا المحتلة ألمانيًا","story":"قاوم مقاتلون يهود عملية الترحيل الألمانية النهائية التي بدأت في 19 أبريل 1943. ومات ما لا يقل عن 7,000 يهودي في القتال أو المخابئ بينما دمرت القوات الألمانية الغيتو.","context":"كانت الانتفاضة مقاومة يهودية مسلحة لتصفية الغيتو وترحيل سكانه.","aftermath":"قُمعت الانتفاضة ودُمر الغيتو، لكنها أصبحت رمزًا مركزيًا للمقاومة اليهودية في الهولوكوست.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1943-operation-harvest-festival-141"]={"title":"عملية مهرجان الحصاد","location":"منطقة لوبلين، بولندا المحتلة ألمانيًا","story":"قتل أفراد الإس إس والشرطة الألمانية عشرات الآلاف من عمال السخرة اليهود في منطقة لوبلين خلال عملية مهرجان الحصاد في نوفمبر 1943.","context":"هدفت العملية إلى تصفية السكان اليهود الباقين في معسكرات العمل القسري الرئيسية في منطقة لوبلين.","aftermath":"كانت من أكبر عمليات إطلاق النار الجماعي التي نفذها الألمان ضد اليهود في يوم واحد وفترة قصيرة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1943-bia-ystok-ghetto-uprising-142"]={"title":"انتفاضة غيتو بياليستوك","location":"بياليستوك، بولندا المحتلة","story":"عندما بدأت القوات الألمانية التصفية النهائية لغيتو بياليستوك في أغسطس 1943 أطلق مقاتلو المقاومة اليهودية انتفاضة مسلحة. وهُزمت المقاومة ورُحل معظم اليهود الباقين إلى مراكز القتل والمعسكرات.","context":"كانت الانتفاضة محاولة مقاومة منظمة ضد تصفية الغيتو وترحيل سكانه.","aftermath":"رُحل أو قُتل معظم من بقي من المجتمع بعد قمع المقاومة.","sourceStatus":"موثق جيدًا في السجلات الألمانية وتقارير المقاومة وشهادات الناجين"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1943-sobibor-uprising-and-mass-escape-143"]={"title":"انتفاضة سوبيبور والهروب الجماعي","location":"مركز القتل سوبيبور، بولندا المحتلة","story":"في 14 أكتوبر 1943 نظم سجناء يهود في سوبيبور انتفاضة وقتلوا عدة أفراد من الإس إس والحراس وحاولوا الهرب جماعيًا. وخرج المئات من المعسكر؛ ونجا عدد أقل من الحرب.","context":"كانت الانتفاضة من أكبر أعمال المقاومة داخل مركز قتل نازي.","aftermath":"ساهمت الانتفاضة في قرار الألمان تفكيك مركز القتل وإخفاء آثاره.","sourceStatus":"موثق على نطاق واسع بشهادات الناجين والسجلات الألمانية وتحقيقات ما بعد الحرب"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1943-treblinka-prisoner-uprising-144"]={"title":"انتفاضة سجناء تريبلينكا","location":"تريبلينكا الثاني، بولندا المحتلة","story":"في 2 أغسطس 1943 استولى سجناء في مركز قتل تريبلينكا على أسلحة وأشعلوا أجزاء من المعسكر وحاولوا هروبًا جماعيًا. وعبر المئات محيط المعسكر، لكن كثيرين طوردوا وقُتلوا؛ ونجا عدد أقل من الحرب.","context":"كانت الانتفاضة مقاومة منظمة من السجناء داخل أحد مراكز القتل الرئيسية لعملية راينهارد.","aftermath":"ألحقت الانتفاضة أضرارًا بالمعسكر وكانت من التطورات التي سبقت تفكيكه على يد الألمان.","sourceStatus":"موثق على نطاق واسع بشهادات الناجين والسجلات الألمانية وأبحاث ما بعد الحرب"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1944-deportation-of-hungarian-jews-to-auschwitz-birkenau-145"]={"title":"ترحيل يهود المجر إلى أوشفيتز-بيركيناو","location":"المجر ← أوشفيتز-بيركيناو","story":"بعد احتلال ألمانيا للمجر في مارس 1944 جمعت السلطات المجرية، بالتعاون مع مسؤولي الإس إس الألمان، اليهود ورحلتهم بسرعة. وبين مايو ويوليو رُحل نحو 440 ألف يهودي، معظمهم إلى أوشفيتز-بيركيناو حيث قُتل غالبيتهم.","context":"كانت عمليات الترحيل من أسرع وأكبر عمليات المرحلة الأخيرة من الهولوكوست.","aftermath":"خلال أسابيع دُمر جزء هائل من يهود المجر خارج بودابست.","sourceStatus":"موثق على نطاق واسع بسجلات الترحيل والوثائق الألمانية والمجرية والصور وشهادات الناجين"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1944-auschwitz-sonderkommando-revolt-146"]={"title":"تمرد السوندركوماندو في أوشفيتز","location":"أوشفيتز-بيركيناو، بولندا المحتلة","story":"في 7 أكتوبر 1944 تمرد سجناء يهود من السوندركوماندو في أوشفيتز-بيركيناو. وهاجموا حراس الإس إس وألحقوا أضرارًا بالمحرقة الرابعة بمتفجرات هربتها سجينات يهوديات يعملن في مصنع قريب.","context":"كان التمرد محاولة مقاومة من سجناء أُجبروا على العمل في منشآت القتل والحرق.","aftermath":"قُمع التمرد وأُعدم المشاركون، لكن المحرقة تضررت وأصبح الحدث رمزًا للمقاومة داخل أوشفيتز.","sourceStatus":"موثق على نطاق واسع في سجلات المعسكر وشهادات الناجين"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1944-liquidation-of-the-o-dz-ghetto-147"]={"title":"تصفية غيتو لودج","location":"لودج، بولندا المحتلة","story":"في 1944 صفّت السلطات الألمانية غيتو لودج، أحد أكبر وأطول الغيتوات بقاءً في بولندا المحتلة. ورُحل معظم اليهود الباقين إلى أوشفيتز-بيركيناو، بعد أن أرسلت ترحيلات سابقة عشرات الآلاف إلى خيلمنو.","context":"كانت التصفية المرحلة الأخيرة في تفكيك أحد أكبر المجتمعات اليهودية المتبقية في الغيتوات.","aftermath":"رُحل معظم السكان الباقين إلى مراكز القتل ولم ينجُ إلا عدد قليل.","sourceStatus":"التصفية والترحيلات موثقة على نطاق واسع في السجلات الألمانية ووثائق الغيتو وشهادات الناجين"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1945-death-marches-during-the-collapse-of-nazi-germany-148"]={"title":"مسيرات الموت أثناء انهيار ألمانيا النازية","location":"وسط وشرق أوروبا","story":"مع اقتراب جيوش الحلفاء من معسكرات الاعتقال أخلى الإس إس السجناء نحو داخل ألمانيا. وأُجبر السجناء، ومنهم أعداد كبيرة من اليهود، على المسير والنقل في ظروف شتوية قاسية؛ وقتل الحراس من لم يستطيعوا المتابعة ومات آخرون من البرد والجوع والإرهاق.","context":"هدفت عمليات الإخلاء إلى نقل السجناء بعيدًا عن الجيوش المتقدمة وأصبحت مرحلة قاتلة إضافية في الأشهر الأخيرة للحرب.","aftermath":"مات عشرات الآلاف من السجناء في المسيرات والإجلاء قبل تحرير المعسكرات ونهاية الحرب.","sourceStatus":"موثق على نطاق واسع عبر عمليات إخلاء عديدة؛ تختلف الأعداد الإجمالية لأن مسيرات منفصلة كثيرة وقعت"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1946-kielce-pogrom-149"]={"title":"بوغروم كيلتسه","location":"كيلتسه، بولندا","story":"قتل حشد انضم إليه بعض أفراد الشرطة والجنود ناجين يهودًا من الهولوكوست ويهودًا آخرين في كيلتسه؛ وقُتل ما لا يقل عن 42 يهوديًا.","context":"كان الحدث عنفًا معاديًا لليهود بعد الهولوكوست وأظهر استمرار الخطر على الناجين العائدين أو الساعين لإعادة بناء حياتهم.","aftermath":"سرّع البوغروم خروج كثير من اليهود من بولندا بعد الحرب وعمق الشعور بانعدام الأمن.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1946-king-david-hotel-bombing-150"]={"title":"تفجير فندق الملك داود","location":"القدس، فلسطين الانتدابية","story":"في 22 يوليو 1946 فجر تنظيم الإرغون اليهودي الجناح الجنوبي من فندق الملك داود في القدس، حيث كانت توجد مكاتب إدارية وعسكرية بريطانية. قُتل 91 شخصًا بينهم عرب وبريطانيون ويهود وآخرون.","context":"كان التفجير جزءًا من صراع التنظيمات السرية اليهودية ضد حكم الانتداب البريطاني.","aftermath":"صعّد التفجير المواجهة مع بريطانيا وأصبح من أكثر أحداث عهد الانتداب إثارة للجدل.","sourceStatus":"الهجوم ومنفذوه وعدد القتلى موثقون على نطاق واسع؛ يستمر الخلاف حول التحذيرات والاستجابة البريطانية قبل الانفجار"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1947-fajja-bus-attacks-151"]={"title":"هجمات حافلات فجة","location":"قرب بتاح تكفا، فلسطين الانتدابية","story":"في 30 نوفمبر 1947، بعد يوم من تصويت الأمم المتحدة على التقسيم، هاجم مسلحون عرب حافلات يهودية، وكانت الهجمات من الوقائع الافتتاحية لمرحلة الحرب الأهلية في صراع 1947–1949.","context":"وقعت الحادثة مباشرة بعد قرار التقسيم وسط تصاعد سريع للعنف بين المجتمعين.","aftermath":"أشارت الهجمات إلى الانتقال نحو صراع مسلح أوسع في فلسطين الانتدابية.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1947-1947-1949-palestine-war-arab-israeli-war-152"]={"title":"حرب فلسطين 1947–1949 / الحرب العربية الإسرائيلية","location":"فلسطين الانتدابية / إسرائيل","story":"اندلع القتال بعد تصويت الأمم المتحدة على التقسيم؛ وبعد إعلان إسرائيل استقلالها في مايو 1948 دخلت جيوش عربية مجاورة الحرب. وتكبد المدنيون والمقاتلون اليهود والعرب خسائر كبيرة وتهجيرًا.","context":"شملت الحرب أولًا حربًا أهلية بين قوات يهودية وعربية ثم تحولت إلى حرب بين دول.","aftermath":"أنشأت الحرب دولة إسرائيل وغيرت الحدود وخلقت أزمات لجوء وتهجير وتركت نزاعات إقليمية وسياسية دون حل.","sourceStatus":"ثقة عالية جدًا؛ السرديات وبعض الأرقام موضع خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1947-un-partition-plan-and-outbreak-of-civil-war-in-mandatory-palestine-153"]={"title":"خطة الأمم المتحدة للتقسيم واندلاع الحرب الأهلية في فلسطين الانتدابية","location":"فلسطين الانتدابية","story":"في 29 نوفمبر 1947 أوصت الجمعية العامة للأمم المتحدة بتقسيم فلسطين إلى دولتين عربية ويهودية مع نظام دولي للقدس. قبل قادة الوكالة اليهودية التقسيم أساسًا لإقامة دولة، ورفضه القادة العرب. وتصاعد القتال بين القوات العربية الفلسطينية واليهودية فورًا تقريبًا.","context":"كان القرار 181 توصية دولية بالتقسيم وأصبح نقطة تحول سياسية وعسكرية.","aftermath":"اتسع العنف بسرعة وقاد إلى حرب 1948 وقيام إسرائيل وتهجير واسع.","sourceStatus":"قرار 181 والتصعيد اللاحق موثقان على نطاق واسع؛ تبقى تفسيرات المسؤولية والنوايا وعدالة الخطة موضع خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-hadassah-medical-convoy-massacre-154"]={"title":"مذبحة قافلة هداسا الطبية","location":"القدس","story":"في أبريل 1948 نصب مسلحون عرب كمينًا لقافلة تقل عاملين طبيين وإمدادات إلى مستشفى هداسا والجامعة العبرية على جبل المشارف؛ وقُتل 78 يهوديًا.","context":"وقعت الحادثة ضمن القتال والحصار حول القدس أثناء مرحلة الحرب الأهلية من صراع 1947–1948.","aftermath":"عمقت المذبحة العنف وأثرت في الخدمات الطبية والوصول إلى جبل المشارف.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-deir-yassin-massacre-155"]={"title":"مذبحة دير ياسين","location":"دير ياسين، قرب القدس","story":"في 9 أبريل 1948 هاجم مقاتلو الإرغون وليحي قرية دير ياسين العربية الفلسطينية. وقُتل أكثر من مئة من سكان القرية، بينهم مدنيون. وأصبحت المذبحة رمزًا رئيسيًا للمعاناة الفلسطينية وأسهمت في الخوف خلال حرب 1948.","context":"كانت الحادثة جزءًا من الحرب الأهلية، ومن الضروري عرضها إلى جانب الهجمات على اليهود ووقائع التهجير الفلسطيني في الفترة نفسها.","aftermath":"ساهمت أخبار المذبحة في الخوف والفرار في أماكن أخرى وظلت مركزية في الذاكرة الفلسطينية.","sourceStatus":"الهجوم وقتل المدنيين موثقان بقوة؛ نوقش العدد الدقيق وبعض تفاصيل المعركة، وتضع الدراسات الحديثة عدد القتلى عادة في حدود 100–110"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-kfar-etzion-massacre-156"]={"title":"مذبحة كفار عتصيون","location":"كفار عتصيون، جنوب القدس","story":"في 13 مايو 1948 سقطت كفار عتصيون أمام الفيلق العربي وقوات عربية محلية بعد قتال طويل. وقُتل عدد كبير من المدافعين والسكان اليهود بعد انهيار الدفاعات ولم ينجُ إلا قليلون. واستسلمت بقية مستوطنات كتلة عتصيون في اليوم التالي.","context":"وقعت الحادثة في المرحلة الأخيرة من الحرب الأهلية عشية انتهاء الانتداب البريطاني.","aftermath":"أصبح سقوط الكتلة رمزًا مهمًا في الذاكرة الإسرائيلية لحرب 1948.","sourceStatus":"سقوط كفار عتصيون والقتل الجماعي موثقان جيدًا؛ تختلف الروايات حول الظروف الدقيقة لبعض الوفيات بعد الاستسلام"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-declaration-of-the-state-of-israel-157"]={"title":"إعلان دولة إسرائيل","location":"تل أبيب","story":"في 14 مايو 1948 أعلن دافيد بن غوريون قيام دولة إسرائيل مع انتهاء الانتداب البريطاني. وحول الإعلان الحرب الأهلية الجارية إلى صراع بين دول عندما دخلت جيوش عربية مجاورة أراضي الانتداب السابق.","context":"كان الحدث نقطة انتقال رئيسية من المجتمع اليهودي المنظم في فلسطين إلى دولة ذات سيادة وسط حرب قائمة.","aftermath":"قامت إسرائيل كدولة واتسعت الحرب فور تدخل الجيوش العربية.","sourceStatus":"الإعلان والتحول العسكري المباشر موثقان بصورة مباشرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-arab-armies-enter-palestine-and-the-first-arab-israeli-war-expands-158"]={"title":"الجيوش العربية تدخل فلسطين وتتسع الحرب العربية الإسرائيلية الأولى","location":"إسرائيل / أراضي فلسطين الانتدابية السابقة","story":"ابتداءً من 15 مايو دخلت جيوش مصر وشرق الأردن وسوريا والعراق ولبنان الحرب بعد إعلان استقلال إسرائيل. وأصبح الصراع يشمل الدولة الإسرائيلية الجديدة والقوات العربية الفلسطينية وعدة دول عربية مجاورة.","context":"كانت للحكومات العربية المختلفة أهداف عسكرية وسياسية متباينة، لذلك لا ينبغي تصوير التدخل كاستراتيجية موحدة بالكامل.","aftermath":"اتسع الصراع إلى حرب بين دول انتهت باتفاقيات الهدنة سنة 1949.","sourceStatus":"تدخل الجيوش العربية المجاورة موثق على نطاق واسع؛ اختلفت الأهداف والحسابات السياسية بين الحكومات"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-fall-of-the-jewish-quarter-of-jerusalem-s-old-city-159"]={"title":"سقوط الحي اليهودي في البلدة القديمة بالقدس","location":"القدس","story":"بعد حصار وقتال استسلم الحي اليهودي في البلدة القديمة للفيلق العربي التابع لشرق الأردن في 28 مايو 1948. وأُجلي السكان اليهود وأصبح المدافعون الناجون أسرى حرب. وتضررت أو دُمرت لاحقًا معابد ومواقع يهودية أخرى خلال الحكم الأردني.","context":"كانت الحادثة جزءًا من الصراع على القدس في حرب 1948.","aftermath":"بقيت البلدة القديمة تحت السيطرة الأردنية حتى 1967 ولم يتمكن سكان الحي اليهود من العودة خلال تلك الفترة.","sourceStatus":"الاستسلام والإجلاء موثقان جيدًا؛ تختلف أوصاف الدمار اللاحق بحسب الموقع والمصدر"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-lydda-and-ramle-fighting-killings-and-palestinian-expulsion-160"]={"title":"اللد والرملة: قتال وقتل وطرد فلسطينيين","location":"اللد والرملة","story":"استولت القوات الإسرائيلية على اللد والرملة في يوليو 1948 خلال عملية داني. وقُتل مدنيون أثناء القتال في اللد، ثم طُرد أو أُجبر معظم السكان العرب الفلسطينيين في المدينتين على الفرار شرقًا. وتبقى الحادثة مركزية في النقاش التاريخي حول أزمة اللاجئين الفلسطينيين.","context":"توضح الحادثة أن العمليات العسكرية الإسرائيلية وتهجير الفلسطينيين جزء ضروري من الصورة الكاملة لحرب 1948.","aftermath":"هُجر عشرات الآلاف من الفلسطينيين وانتقلت المدينتان إلى السيطرة الإسرائيلية.","sourceStatus":"الاستيلاء والتهجير الجماعي موثقان بقوة؛ يناقش المؤرخون جوانب الأوامر وأعداد القتلى والآليات الدقيقة للطرد"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-palestinian-refugee-and-displacement-crisis-161"]={"title":"أزمة اللاجئين والتهجير الفلسطيني","location":"فلسطين / الدول العربية المجاورة","story":"خلال حرب 1947–1949 فر أو طُرد مئات الآلاف من العرب الفلسطينيين من منازلهم في الأراضي التي أصبحت إسرائيل. واختلفت الأسباب بحسب المكان ومرحلة الحرب وشملت الطرد المباشر والفرار من القتال والخوف من الهجوم وانهيار المجتمع الفلسطيني. ومنعت إسرائيل عمومًا معظم اللاجئين من العودة بعد الحرب.","context":"التهجير واسع النطاق غير محل نزاع، لكن الوزن النسبي للأسباب والمسؤولية في مواقع محددة ما يزال موضوعًا رئيسيًا للخلاف التاريخي والسياسي.","aftermath":"أصبحت أزمة اللاجئين إحدى القضايا المركزية والدائمة في الصراع الإسرائيلي الفلسطيني.","sourceStatus":"التهجير واسع النطاق غير محل نزاع؛ يظل توازن الأسباب والمسؤولية في مناطق بعينها من أكثر موضوعات تاريخ الصراع إثارة للجدل"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-assassination-of-un-mediator-folke-bernadotte-162"]={"title":"اغتيال وسيط الأمم المتحدة فولكه برنادوت","location":"القدس","story":"في 17 سبتمبر 1948 اغتال أعضاء من ليحي، وهو تنظيم مسلح يهودي، وسيط الأمم المتحدة الكونت فولكه برنادوت في القدس. وكان قد عُين للتوسط في الحرب العربية الإسرائيلية واقترح ترتيبات للحدود والقدس واللاجئين.","context":"يوثق الحدث عنفًا سياسيًا نفذه تنظيم يهودي ولا يُعرض كحادثة كان اليهود فيها الضحايا.","aftermath":"أثار الاغتيال إدانة دولية وسرّع إجراءات إسرائيلية ضد ليحي.","sourceStatus":"الاغتيال ومسؤولية ليحي موثقان بقوة في سجلات الأمم المتحدة والمصادر التاريخية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1949-1949-armistice-agreements-end-major-fighting-163"]={"title":"اتفاقيات هدنة 1949 تنهي القتال الرئيسي","location":"إسرائيل والدول العربية المجاورة","story":"وقعت إسرائيل اتفاقيات هدنة منفصلة مع مصر ولبنان والأردن وسوريا سنة 1949. وأنهت الاتفاقيات القتال الرئيسي بين الدول لكنها لم تنشئ معاهدات سلام شاملة. وأصبحت خطوط الهدنة الحدود العملية حتى حرب 1967.","context":"أنهت الاتفاقيات المرحلة العسكرية الرئيسية من حرب 1948 دون حل الصراع الأوسع.","aftermath":"ظلت الحدود وقضية اللاجئين ووضع القدس دون حل واستمرت في تشكيل النزاعات اللاحقة.","sourceStatus":"الاتفاقيات وخطوط الهدنة موثقة مباشرة في سجلات الأمم المتحدة"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1800-jacob-is-given-the-name-israel-0"]={"title":"יעקב מקבל את השם ישראל","location":"כנען / המסורת המקראית","story":"לפי ספר בראשית, יעקב, בנו של יצחק ונכדו של אברהם, מקבל את השם ישראל. צאצאיו מכונים לאחר מכן בני ישראל. המקרא הוא המקור לסיפור זה; אין תאריך היסטורי מבוסס באופן עצמאי ליעקב, ולכן התאריך המוצג כאן הוא מיקום משוער לפי המסורת ולא תאריך ארכאולוגי.","context":"זוהי נקודת הפתיחה הסיפורית של האתר, ולא האירוע ההיסטורי הראשון המאומת באופן עצמאי. האתר מבדיל בין המסורת המקראית לבין עדויות חוץ־מקראיות וארכאולוגיות מאוחרות יותר.","aftermath":"השם ישראל הופך למרכיב מרכזי בזהות המקראית של צאצאי יעקב ובמסורות שנים־עשר שבטי ישראל.","sourceStatus":"סיפור מקראי מסורתי — ללא תיארוך עצמאי"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1750-bnei-yisrael-the-children-of-israel-1"]={"title":"בני ישראל — צאצאי ישראל","location":"המסורת המקראית","story":"בסיפור המקראי, צאצאי יעקב/ישראל נודעים כבני ישראל. שנים־עשר השבטים מיוחסים במסורת לבניו ולמשפחתו של יעקב. רשומה זו מבהירה את משמעות השם לפני שציר הזמן מגיע לעדויות עצמאיות על ישראל.","context":"זוהי מסגרת מסורתית של יוחסין וזהות שנשמרה בתנ״ך. אין לבלבל אותה עם הוכחה ארכאולוגית לכך שכל בני ישראל המאוחרים היו צאצאים של משפחה היסטורית אחת.","aftermath":"הכינוי בני ישראל הופך לשם קיבוצי חוזר בתורה ובספרות המקראית המאוחרת.","sourceStatus":"סיפור מקראי מסורתי"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1650-israel-s-family-goes-down-to-egypt-2"]={"title":"משפחת ישראל יורדת למצרים","location":"מצרים / המסורת המקראית","story":"ספר בראשית מתאר את יעקב/ישראל ובני ביתו עוברים למצרים בזמן רעב, לאחר שיוסף עלה שם למעמד בכיר. זהו חלק מסיפור המוצא המקראי של בני ישראל; לא זוהה מקור מצרי עצמאי המקובל במחקר כמתעד את יעקב או יוסף.","context":"הרשומה נכללת משום שהיא יסודית למסורת המובילה לסיפור יציאת מצרים. מיקומה הכרונולוגי משוער ואין לראות בו תאריך ארכאולוגי מבוסס.","aftermath":"בהמשך מתאר המקרא את צאצאי ישראל מתרבים במצרים ונכפים לעבודת כפייה.","sourceStatus":"סיפור מקראי מסורתי — התאריך אינו ודאי מבחינה היסטורית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1300-enslavement-of-bnei-yisrael-in-egypt-3"]={"title":"שעבוד בני ישראל במצרים","location":"מצרים / המסורת המקראית","story":"ספר שמות מתאר פרעה חדש המשעבד את בני ישראל ומטיל עליהם עבודת כפייה. הסיפור יסודי להיסטוריה ולזהות היהודית, אך המחקר לא מצא ראיות עצמאיות המבססות את השעבוד המקראי בהיקף ובצורה המתוארים.","context":"האתר מציג זאת כמסורת מקראית ולא כאירוע מצרי המתוארך בוודאות. במצרים העתיקה אכן התקיימו עבודת כפייה ואוכלוסיות משועבדות, אך עובדה זו כשלעצמה אינה מאמתת את סיפור יציאת מצרים.","aftermath":"לפי הסיפור המקראי, הדיכוי מוביל להנהגת משה וליציאת בני ישראל ממצרים.","sourceStatus":"סיפור מקראי מסורתי"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1250-the-exodus-from-egypt-4"]={"title":"יציאת מצרים","location":"מצרים ← סיני / המסורת המקראית","story":"לפי התורה, משה מוביל את בני ישראל מעבדות במצרים. יציאת מצרים הפכה לאחד מסיפורי היסוד של הזהות והזיכרון הדתי היהודי. חוקרים ממשיכים לדון אם הסיפור משמר זיכרונות של תנועות או אירועים היסטוריים מצומצמים יותר, אך יציאת מצרים כפי שהיא מסופרת במקרא לא הוכחה באופן עצמאי בארכאולוגיה.","context":"סמן זה מפריד במכוון בין מסורת דתית ותרבותית לבין היסטוריה המאומתת באופן עצמאי. התאריך הוא מיקום משוער לפי המסורת ולא תאריך מוכח.","aftermath":"הסיפור המקראי ממשיך במסע במדבר, בברית בסיני ובהתגבשות ישראל כעם הקשור בחוק ובמסורת משותפים.","sourceStatus":"סיפור מקראי מסורתי — לא הוכח באופן עצמאי בהיקף המתואר"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1240-amalek-attacks-bnei-yisrael-5"]={"title":"עמלק תוקף את בני ישראל","location":"רפידים / המסורת המקראית","story":"ספר שמות מתאר את עמלק תוקף את בני ישראל ברפידים במהלך המסע במדבר. טקסטים מקראיים מאוחרים יותר הופכים את עמלק לאויב חוזר בזיכרון הישראלי. אין עדות עצמאית בת התקופה המזהה בוודאות את הקרב המסוים הזה.","context":"מאחר שמדובר בסיפור של עימות מזוין שבו מעורבים בני ישראל, הוא נכלל בחלק המסורתי של הפרויקט, אך מסומן במפורש כסיפור מקראי ולא כהיסטוריה מאומתת באופן עצמאי.","aftermath":"העימות הופך למוטיב מתמשך בזיכרון המקראי והיהודי המאוחר.","sourceStatus":"סיפור מקראי מסורתי"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1230-joshua-and-warfare-in-canaan-6"]={"title":"יהושע והמלחמות בכנען","location":"כנען / המסורת המקראית","story":"ספר יהושע מתאר מסעות מלחמה ישראליים נגד ערים כנעניות לאחר תקופת המדבר. הארכאולוגיה מראה שכנען עברה שינויים פוליטיים וחברתיים גדולים בסוף תקופת הברונזה המאוחרת, אך אינה תומכת בשחזור פשוט שבו כל הערים בספר יהושע נפלו בכיבוש מאוחד אחד בדיוק כמתואר.","context":"חלק מהאתרים הנזכרים בספר יהושע עברו חורבן בתקופה הרחבה הרלוונטית, בעוד שבאתרים אחרים התמונה הארכאולוגית שונה. חצור, למשל, חרבה במאה ה־13 לפנה״ס, אך זהות האחראים לכך נותרה שנויה במחלוקת.","aftermath":"המסורת המקראית מציגה את המערכות כמובילות להתיישבות שבטי ישראל; השחזור ההיסטורי מצביע במקום זאת על תהליך מורכב של התהוות ישראל הקדומה בתוך כנען.","sourceStatus":"מסורת מקראית עם הקשר ארכאולוגי חלקי — הפרטים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1208-merneptah-stele-earliest-extra-biblical-reference-to-israel-7"]={"title":"מצבת מרנפתח: האזכור החוץ־מקראי הקדום ביותר של ישראל","location":"כנען","story":"כתובת ניצחון מלכותית מצרית המתוארכת לכ־1208 לפנה״ס כוללת את האזכור הלא־מקראי הקדום ביותר המקובל במחקר לעם בשם ישראל. מרנפתח טוען שהקבוצה הובסה במסעו בכנען. הכתב המצרי מזהה את ישראל כעם ולא כעיר, טריטוריה, ממלכה או מדינה.","context":"סמן זה הוא המעבר באתר מן הסיפור המקראי המסורתי לעדות מאומתת באופן עצמאי. הוא מראה שאוכלוסייה בשם ישראל התקיימה בכנען בערך ב־1208 לפנה״ס; הוא אינו מוכיח שממלכת ישראל המאוחרת כבר התקיימה. הצהרת פרעה היא טענת ניצחון מלכותית מצרית, לא הוכחה שעם ישראל הושמד.","aftermath":"עדויות מאוחרות מתקופת הברזל מתעדות את ישראל ויהודה כממלכות פוליטיות. התפתחותן המדויקת מאוכלוסיות ההר הקדומות נותרה נושא למחקר היסטורי וארכאולוגי.","sourceStatus":"כתובת מצרית בת התקופה — האזכור החוץ־מקראי הקדום ביותר המקובל לישראל"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1150-philistine-expansion-and-conflict-with-early-israel-8"]={"title":"התפשטות הפלשתים והעימות עם ישראל הקדומה","location":"דרום כנען / פלשת","story":"הפלשתים ייסדו תרבות חומרית ייחודית במישור החוף הדרומי עם היחלשות השליטה המצרית. הממצאים הארכאולוגיים תומכים בקיומם ובהתרחבותם של מרכזים פלשתיים והופכים עימות עם קבוצות ישראליות מתהוות לסביר מבחינה היסטורית, אף שלא ניתן לאמת באופן עצמאי את כל הסיפורים בספרי שופטים ושמואל.","context":"רשומה זו מבחינה בין הסיפור המקראי לבין העדויות הארכאולוגיות והחוץ־מקראיות כאשר המקורות אינם זהים.","aftermath":"מיקומה בציר הזמן מבוסס על הכרונולוגיה הרחבה הנתמכת ביותר; תאריכים עתיקים ופרטי מסעות מלחמה עשויים להישאר שנויים במחלוקת.","sourceStatus":"הארכאולוגיה תומכת בהתיישבות פלשתית ובעימות אזורי; עוצמת הראיות לפרטים המקראיים משתנה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1050-saul-and-the-philistine-wars-9"]={"title":"שאול והמלחמות בפלשתים","location":"ישראל / פלשת — הסיפור המקראי","story":"ספרי שמואל מתארים את שאול כמלך הראשון של ישראל ואת שלטונו כתקופה שנשלטה במידה רבה בידי מלחמות עם הפלשתים. העימות הפלשתי־ישראלי מתאים להקשר הרחב של תקופת הברזל הנתמך בארכאולוגיה, אך מסעותיו וכרונולוגיית שלטונו של שאול מוכרים בעיקר מן הסיפור המקראי.","context":"רשומה זו מבחינה בין הסיפור המקראי לבין העדויות הארכאולוגיות והחוץ־מקראיות כאשר המקורות אינם זהים.","aftermath":"מיקומה בציר הזמן מבוסס על הכרונולוגיה הרחבה הנתמכת ביותר; תאריכים עתיקים ופרטי מסעות מלחמה עשויים להישאר שנויים במחלוקת.","sourceStatus":"סיפור מקראי בתוך מסגרת היסטורית סבירה של עימות בתקופת הברזל"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1010-battle-of-mount-gilboa-and-death-of-saul-10"]={"title":"קרב הר הגלבוע ומות שאול","location":"הר הגלבוע — הסיפור המקראי","story":"לפי ספר שמואל א׳, כוחות פלשתיים הביסו את ישראל בהר הגלבוע. שאול ובניו, ובהם יהונתן, נהרגו בקרב. האירוע חשוב למעבר המקראי משושלת שאול לדוד, אך אין כתובת חיצונית בת התקופה המתעדת בוודאות את הקרב.","context":"רשומה זו מבחינה בין הסיפור המקראי לבין העדויות הארכאולוגיות והחוץ־מקראיות כאשר המקורות אינם זהים.","aftermath":"מיקומה בציר הזמן מבוסס על הכרונולוגיה הרחבה הנתמכת ביותר; תאריכים עתיקים ופרטי מסעות מלחמה עשויים להישאר שנויים במחלוקת.","sourceStatus":"סיפור מקראי — אינו מאומת באופן עצמאי"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1000-david-s-wars-and-rise-of-the-israelite-monarchy-11"]={"title":"מלחמות דוד ועליית המלוכה הישראלית","location":"ישראל / יהודה / פלשת","story":"המסורת המקראית מתארת את דוד מביס כוחות פלשתיים ומבסס שלטון מירושלים. הארכאולוגיה והכתובות תומכות בקיומן של יהודה וישראל בתקופת הברזל, בעוד שהיקף ממלכת דוד ועוצמתה הפוליטית נותרו שנויים במחלוקת. מצבת תל דן המאוחרת כוללת את הביטוי הנדון רבות 'בית דוד', המספק עדות חיצונית לשושלת דוד.","context":"רשומה זו מבחינה בין הסיפור המקראי לבין העדויות הארכאולוגיות והחוץ־מקראיות כאשר המקורות אינם זהים.","aftermath":"מיקומה בציר הזמן מבוסס על הכרונולוגיה הרחבה הנתמכת ביותר; תאריכים עתיקים ופרטי מסעות מלחמה עשויים להישאר שנויים במחלוקת.","sourceStatus":"לשושלת דוד יש תמיכה חוץ־מקראית; מסעות המלחמה הפרטניים מוכרים בעיקר מן המקרא"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1800-jacob-is-given-the-name-israel-0"]={"title":"يعقوب يُعطى اسم إسرائيل","location":"كنعان / التقليد الكتابي","story":"بحسب سفر التكوين، يُعطى يعقوب، ابن إسحاق وحفيد إبراهيم، اسم إسرائيل. ويُعرف نسله لاحقًا ببني إسرائيل. النص الكتابي هو مصدر هذه الرواية؛ ولا يوجد تاريخ تاريخي مستقل ثابت ليعقوب، لذلك فالتاريخ المعروض هنا تقدير تقليدي لا تاريخًا أثريًا.","context":"هذه نقطة البداية السردية للموقع وليست أول حدث تاريخي مثبت بصورة مستقلة. يميز الموقع بين التقليد الكتابي والأدلة اللاحقة خارج الكتاب المقدس والأثرية.","aftermath":"يصبح اسم إسرائيل محوريًا في الهوية الكتابية لنسل يعقوب وفي تقاليد أسباط إسرائيل الاثني عشر.","sourceStatus":"رواية كتابية تقليدية — غير مؤرخة بصورة مستقلة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1750-bnei-yisrael-the-children-of-israel-1"]={"title":"بنو إسرائيل — أبناء إسرائيل","location":"التقليد الكتابي","story":"في الرواية الكتابية يُعرف نسل يعقوب/إسرائيل باسم بني إسرائيل. وتُنسب الأسباط الاثنا عشر تقليديًا إلى أبناء يعقوب وعائلته. توضح هذه المادة معنى الاسم قبل وصول الخط الزمني إلى إشارات مستقلة إلى إسرائيل.","context":"هذا إطار تقليدي للنسب والهوية محفوظ في الكتاب المقدس العبري. ولا ينبغي الخلط بينه وبين إثبات أثري بأن جميع الإسرائيليين اللاحقين انحدروا من عائلة تاريخية واحدة.","aftermath":"يصبح تعبير بني إسرائيل تسمية جماعية متكررة في التوراة والأدب الكتابي اللاحق.","sourceStatus":"رواية كتابية تقليدية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1650-israel-s-family-goes-down-to-egypt-2"]={"title":"عائلة إسرائيل تنزل إلى مصر","location":"مصر / التقليد الكتابي","story":"يصف سفر التكوين انتقال يعقوب/إسرائيل وأهل بيته إلى مصر أثناء مجاعة، حيث كان يوسف قد ارتقى إلى منصب رفيع. وهذا جزء من رواية أصل بني إسرائيل في الكتاب المقدس؛ ولم يُحدد سجل مصري مستقل مقبول على نحو موثوق بأنه يوثق يعقوب أو يوسف.","context":"أُدرجت هذه المادة لأنها أساسية في الرواية التقليدية المؤدية إلى الخروج. وموقعها الزمني تقريبي ولا ينبغي اعتباره تاريخًا أثريًا ثابتًا.","aftermath":"تصف الرواية الكتابية لاحقًا تكاثر نسل إسرائيل في مصر وإخضاعهم للعمل القسري.","sourceStatus":"رواية كتابية تقليدية — التاريخ غير مؤكد تاريخيًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1300-enslavement-of-bnei-yisrael-in-egypt-3"]={"title":"استعباد بني إسرائيل في مصر","location":"مصر / التقليد الكتابي","story":"يصف سفر الخروج فرعونًا جديدًا يستعبد بني إسرائيل ويفرض عليهم العمل القسري. والرواية أساسية في التاريخ والهوية اليهودية، لكن المؤرخين لم يجدوا أدلة مستقلة تثبت الاستعباد الكتابي بالحجم أو الصورة الموصوفة.","context":"يعرض الموقع هذا كتقليد كتابي لا كحدث مصري مؤرخ بصورة مؤكدة. استخدمت مصر القديمة العمل القسري وعرفت جماعات مستعبدة، لكن هذه الحقيقة وحدها لا تثبت رواية الخروج.","aftermath":"في الرواية الكتابية يؤدي الاضطهاد إلى قيادة موسى وخروج بني إسرائيل من مصر.","sourceStatus":"رواية كتابية تقليدية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1250-the-exodus-from-egypt-4"]={"title":"الخروج من مصر","location":"مصر ← سيناء / التقليد الكتابي","story":"بحسب التوراة يقود موسى بني إسرائيل خارج العبودية في مصر. وأصبح الخروج من الروايات المركزية للهوية والذاكرة الدينية اليهودية. وما يزال الباحثون يناقشون ما إذا كانت القصة تحفظ ذكريات تحركات أو أحداث تاريخية أصغر، لكن الخروج كما ترويه النصوص لم يُثبت أثريًا بصورة مستقلة.","context":"يفصل هذا المؤشر عمدًا بين التقليد الديني والثقافي والتاريخ المثبت بصورة مستقلة. التاريخ تقدير تقليدي وليس تاريخًا مثبتًا.","aftermath":"تستمر الرواية الكتابية برحلة البرية والعهد في سيناء وتطور إسرائيل كشعب يجمعه قانون وتقليد مشتركان.","sourceStatus":"رواية كتابية تقليدية — غير مثبتة بصورة مستقلة بالحجم المروي"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1240-amalek-attacks-bnei-yisrael-5"]={"title":"عماليق يهاجمون بني إسرائيل","location":"رفيديم / التقليد الكتابي","story":"يصف سفر الخروج هجوم عماليق على الإسرائيليين في رفيديم أثناء رحلة البرية. وتجعل نصوص كتابية لاحقة عماليق عدوًا متكررًا في الذاكرة الإسرائيلية. ولا توجد أدلة مستقلة معاصرة تحدد هذه المعركة بعينها بصورة موثوقة.","context":"لأن هذه رواية عن صراع مسلح يشارك فيه بنو إسرائيل فهي تنتمي إلى قسم التاريخ التقليدي للمشروع، لكنها موسومة بوضوح كرواية كتابية لا كتاريخ مثبت بصورة مستقلة.","aftermath":"يصبح الصراع موضوعًا مستمرًا في الذاكرة الكتابية واليهودية اللاحقة.","sourceStatus":"رواية كتابية تقليدية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1230-joshua-and-warfare-in-canaan-6"]={"title":"يشوع والحروب في كنعان","location":"كنعان / التقليد الكتابي","story":"يصف سفر يشوع حملات إسرائيلية ضد مدن كنعانية بعد فترة البرية. وتظهر الآثار أن كنعان شهدت تغيرات سياسية واجتماعية كبيرة قرب نهاية العصر البرونزي المتأخر، لكنها لا تدعم إعادة بناء بسيطة سقطت فيها كل مدن يشوع في غزو موحد واحد تمامًا كما تروي القصة.","context":"تعرض بعض المواقع المذكورة في يشوع للدمار في الفترة العامة ذات الصلة، بينما تقدم مواقع أخرى تواريخ أثرية مختلفة. فحاصور مثلًا دُمرت في القرن الثالث عشر قبل الميلاد، لكن هوية المسؤولين عن ذلك ما تزال موضع نقاش.","aftermath":"يعرض التقليد الكتابي الحملات على أنها تقود إلى استيطان أسباط إسرائيل؛ أما إعادة البناء التاريخية فتشير إلى نشوء أكثر تعقيدًا لإسرائيل المبكرة داخل كنعان.","sourceStatus":"رواية تقليدية مع سياق أثري جزئي — التفاصيل محل نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1208-merneptah-stele-earliest-extra-biblical-reference-to-israel-7"]={"title":"لوحة مرنبتاح: أقدم إشارة خارج الكتاب المقدس إلى إسرائيل","location":"كنعان","story":"يتضمن نقش نصر ملكي مصري يعود إلى نحو 1208 قبل الميلاد أقدم إشارة غير كتابية مقبولة على نطاق واسع إلى شعب يسمى إسرائيل. يدعي مرنبتاح أن هذه الجماعة هُزمت خلال حملته في كنعان. وتحدد الكتابة المصرية إسرائيل كشعب لا كمدينة أو إقليم أو مملكة أو دولة.","context":"يمثل هذا المؤشر انتقال الموقع من الرواية الكتابية التقليدية إلى دليل مثبت بصورة مستقلة. ويظهر أن جماعة تُعرف باسم إسرائيل كانت موجودة في كنعان نحو 1208 قبل الميلاد؛ ولا يثبت أن مملكة إسرائيل اللاحقة كانت قائمة بالفعل. وعبارة الفرعون ادعاء نصر ملكي مصري وليست دليلًا على إبادة شعب إسرائيل.","aftermath":"توثق أدلة لاحقة من العصر الحديدي إسرائيل ويهوذا كمملكتين سياسيتين. وما يزال تطورهما الدقيق من جماعات المرتفعات المبكرة موضوع بحث تاريخي وأثري.","sourceStatus":"نقش مصري معاصر — أقدم إشارة خارج الكتاب المقدس مقبولة على نطاق واسع إلى إسرائيل"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1150-philistine-expansion-and-conflict-with-early-israel-8"]={"title":"توسع الفلسطينيين القدماء والصراع مع إسرائيل المبكرة","location":"جنوب كنعان / فلسطينيا القديمة","story":"أسس الفلسطينيون القدماء ثقافة مادية مميزة في السهل الساحلي الجنوبي مع تراجع السيطرة المصرية. وتدعم الأدلة الأثرية وجود المراكز الفلسطينية القديمة وتوسعها وتجعل الصراع مع الجماعات الإسرائيلية الناشئة معقولًا تاريخيًا، رغم أنه لا يمكن التحقق بصورة مستقلة من جميع القصص في القضاة وصموئيل.","context":"تميز هذه المادة بين الرواية الكتابية والأدلة الأثرية وخارج الكتاب المقدس عندما تختلف المصادر.","aftermath":"موضعها في الخط الزمني مبني على أفضل التسلسلات الزمنية العامة دعمًا؛ وقد تبقى التواريخ القديمة وتفاصيل الحملات موضع نقاش.","sourceStatus":"تدعم الآثار الاستيطان الفلسطيني القديم والصراع الإقليمي؛ وتتفاوت قوة الأدلة على التفاصيل الكتابية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1050-saul-and-the-philistine-wars-9"]={"title":"شاول وحروب الفلسطينيين القدماء","location":"إسرائيل / فلسطينيا القديمة — الرواية الكتابية","story":"تصف أسفار صموئيل شاول بأنه أول ملوك إسرائيل وتصوّر حكمه على أنه تهيمن عليه الحروب مع الفلسطينيين القدماء. ويتفق الصراع الإسرائيلي الفلسطيني القديم مع الإطار الأوسع للعصر الحديدي المدعوم أثريًا، لكن حملات شاول وتسلسل حكمه معروفان أساسًا من الرواية الكتابية.","context":"تميز هذه المادة بين الرواية الكتابية والأدلة الأثرية وخارج الكتاب المقدس عندما تختلف المصادر.","aftermath":"موضعها في الخط الزمني مبني على أفضل التسلسلات الزمنية العامة دعمًا؛ وقد تبقى التواريخ القديمة وتفاصيل الحملات موضع نقاش.","sourceStatus":"رواية كتابية ضمن إطار صراع معقول تاريخيًا في العصر الحديدي"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1010-battle-of-mount-gilboa-and-death-of-saul-10"]={"title":"معركة جبل جلبوع وموت شاول","location":"جبل جلبوع — الرواية الكتابية","story":"بحسب سفر صموئيل الأول هزمت قوات الفلسطينيين القدماء إسرائيل في جبل جلبوع. ومات شاول وأبناؤه، ومنهم يوناثان، خلال المعركة. والحدث مهم للانتقال الكتابي من سلالة شاول إلى داود، لكن لا يوجد نقش خارجي معاصر يوثق المعركة بصورة مؤكدة.","context":"تميز هذه المادة بين الرواية الكتابية والأدلة الأثرية وخارج الكتاب المقدس عندما تختلف المصادر.","aftermath":"موضعها في الخط الزمني مبني على أفضل التسلسلات الزمنية العامة دعمًا؛ وقد تبقى التواريخ القديمة وتفاصيل الحملات موضع نقاش.","sourceStatus":"رواية كتابية — غير مثبتة بصورة مستقلة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1000-david-s-wars-and-rise-of-the-israelite-monarchy-11"]={"title":"حروب داود وصعود الملكية الإسرائيلية","location":"إسرائيل / يهوذا / فلسطينيا القديمة","story":"يصور التقليد الكتابي داود وهو يهزم قوات الفلسطينيين القدماء ويؤسس حكمه من القدس. وتدعم الآثار والنقوش وجود يهوذا وإسرائيل في العصر الحديدي، بينما يبقى حجم مملكة داود ومدى نفوذها السياسي موضع نقاش. وتتضمن لوحة تل دان اللاحقة العبارة المعروفة 'بيت داود'، وهي دليل خارجي على سلالة داودية.","context":"تميز هذه المادة بين الرواية الكتابية والأدلة الأثرية وخارج الكتاب المقدس عندما تختلف المصادر.","aftermath":"موضعها في الخط الزمني مبني على أفضل التسلسلات الزمنية العامة دعمًا؛ وقد تبقى التواريخ القديمة وتفاصيل الحملات موضع نقاش.","sourceStatus":"لسلالة داود دعم خارج الكتاب المقدس؛ أما الحملات الفردية فمعروفة أساسًا من الرواية الكتابية"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-930-division-into-the-kingdoms-of-israel-and-judah-12"]={"title":"חלוקה לממלכות ישראל ויהודה","location":"ישראל ויהודה","story":"לאחר שלמה מתאר הסיפור המקראי את התפצלות המלוכה לממלכת ישראל בצפון ולממלכת יהודה בדרום. עד המאה התשיעית לפנה״ס שתי הממלכות מופיעות בכתובות חיצוניות ובממצא הארכאולוגי.","context":"האירוע מבחין בין הסיפור המקראי לבין העדויות הארכאולוגיות והחוץ־מקראיות במקומות שבהם המקורות שונים.","aftermath":"מיקומו בציר הזמן מבוסס על הכרונולוגיה הרחבה הנתמכת ביותר; הכרונולוגיה המקראית המדויקת עדיין נתונה לדיון.","sourceStatus":"יש ראיות חזקות לקיומן של ממלכות נפרדות בתקופת הברזל; הכרונולוגיה המקראית המדויקת שנויה במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-925-shoshenq-i-campaign-in-the-southern-levant-13"]={"title":"מסע שישק הראשון בדרום הלבנט","location":"יהודה / ישראל / דרום הלבנט","story":"פרעה שישק הראשון יצא למסע צבאי בלבנט במאה העשירית לפנה״ס. כתובות מצריות מספקות עוגן חיצוני למלחמה שפגעה ביישובים הקשורים לישראל וליהודה הקדומות; הקשר המדויק לסיפור המקראי על שישק עדיין נתון לדיון.","context":"האירוע מבחין בין גרעין היסטורי המתועד היטב לבין פרטים סיפוריים מאוחרים יותר שבהם נדרשת זהירות.","aftermath":"ההשלכות ומספרי הנפגעים מוצגים בזהירות; מספרים מדויקים אינם ניתנים כאשר המקורות ששרדו אינם מאפשרים ביטחון.","sourceStatus":"רמת ודאות גבוהה לגבי עצם המסע; שחזור היעדים המדויקים שנוי במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-853-battle-of-qarqar-ahab-of-israel-against-assyria-14"]={"title":"קרב קרקר: אחאב מלך ישראל נגד אשור","location":"קרקר, סוריה","story":"שלמנאסר השלישי מלך אשור תיעד קרב גדול בקרקר נגד קואליציה של שליטים מן הלבנט. הכתובת שלו מזכירה את אחאב הישראלי כחבר בקואליציה ומייחסת לו כוח משמעותי של מרכבות וחיל רגלים. זוהי עדות חיצונית חשובה לממלכת ישראל הצפונית ככוח אזורי.","context":"האירוע מבחין בין הסיפור המקראי לבין העדויות הארכאולוגיות והחוץ־מקראיות במקומות שבהם המקורות שונים.","aftermath":"מיקומו בציר הזמן מבוסס על הכרונולוגיה הרחבה הנתמכת ביותר; המספרים הצבאיים בכתובות מלכותיות עשויים לשקף תעמולה.","sourceStatus":"כתובת מלכותית אשורית בת התקופה; המספרים הצבאיים עשויים להיות תעמולתיים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-840-mesha-s-revolt-against-israel-15"]={"title":"מרד מישע נגד ישראל","location":"מואב / ממלכת ישראל","story":"מישע מלך מואב תיעד בכתובת מלכותית את השבתם של שטחים מידי ישראל. מצבת מישע היא מקור חוץ־מקראי בן התקופה בעל חשיבות יוצאת דופן להבנת העימות בין מואב לממלכת ישראל.","context":"האירוע מבחין בין גרעין היסטורי המתועד היטב לבין פרטים מאוחרים יותר שבהם נדרשת זהירות.","aftermath":"ההשלכות ומספרי הנפגעים מוצגים בזהירות; מספרים מדויקים אינם ניתנים כאשר המקורות ששרדו אינם מאפשרים ביטחון.","sourceStatus":"רמת ודאות גבוהה מאוד לגבי גרעין העימות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-840-aramean-wars-and-the-tel-dan-stele-16"]={"title":"המלחמות הארמיות ומצבת תל דן","location":"צפון ישראל / ארם־דמשק","story":"כתובת ניצחון ארמית שהתגלתה בתל דן מנציחה ניצחונות על מלכים הקשורים לישראל ול״בית דוד״. הכתובת מספקת עדות ישירה למלחמות בין ארם־דמשק לבין ממלכות ישראל ויהודה במאה התשיעית לפנה״ס.","context":"האירוע מבחין בין הסיפור המקראי לבין העדויות הארכאולוגיות והחוץ־מקראיות במקומות שבהם המקורות שונים.","aftermath":"מיקומו בציר הזמן מבוסס על הכרונולוגיה הרחבה הנתמכת ביותר; חלקים מן הכתובת פגומים ושחזורה דורש זהירות.","sourceStatus":"כתובת מונומנטלית בת התקופה או סמוכה לה; חלקים פגומים ולכן יש אי־ודאות בשחזור"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-734-tiglath-pileser-iii-invades-israel-and-the-levant-17"]={"title":"תגלת־פלאסר השלישי פולש לישראל וללבנט","location":"ממלכת ישראל / הגליל / הלבנט","story":"ההתפשטות האשורית תחת תגלת־פלאסר השלישי שינתה את האזור. מסעות בשנות ה־730 לפנה״ס החלישו את ממלכת ישראל הצפונית, סיפחו שטחים והובילו להגליות, וכך הכינו את הקרקע לכיבוש האשורי הסופי של שומרון כעבור כעשור.","context":"האירוע מבחין בין הסיפור המקראי לבין העדויות הארכאולוגיות והחוץ־מקראיות במקומות שבהם המקורות שונים.","aftermath":"מיקומו בציר הזמן מבוסס על הכרונולוגיה הרחבה הנתמכת ביותר; פרטי מסעות עתיקים עשויים להישאר נתונים לדיון.","sourceStatus":"ראיות אשוריות ומקראיות חזקות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-722-assyrian-conquest-of-samaria-18"]={"title":"כיבוש שומרון בידי אשור","location":"שומרון / ממלכת ישראל","story":"אשור כבשה את שומרון והביאה לקצה את ממלכת ישראל הצפונית; לאחר מכן התרחשו הגליות ויישוב מחדש של אוכלוסיות.","context":"האירוע הוא חלק מן התיעוד הכרונולוגי של אלימות מתועדת שבה היו מעורבות קהילות ישראליות ויהודאיות. המקור המצורף מספק הקשר היסטורי רחב יותר.","aftermath":"הכיבוש סיים את ממלכת ישראל הצפונית ושינה עמוקות את האוכלוסייה והמבנה הפוליטי באזור.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-701-assyrian-invasion-of-judah-and-fall-of-lachish-19"]={"title":"הפלישה האשורית ליהודה ונפילת לכיש","location":"ממלכת יהודה","story":"כוחות סנחריב החריבו אזורים נרחבים ביהודה וכבשו את לכיש; ירושלים שרדה את המסע.","context":"האירוע הוא חלק מן התיעוד הכרונולוגי של אלימות מתועדת שבה היו מעורבות קהילות יהודאיות. מקורות אשוריים, מקראיים וארכאולוגיים מאפשרים להשוות בין נקודות מבט שונות.","aftermath":"יהודה נפגעה קשות אך ירושלים והממלכה שרדו תחת לחץ אשורי.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-597-first-babylonian-capture-of-jerusalem-20"]={"title":"הכיבוש הבבלי הראשון של ירושלים","location":"ירושלים / ממלכת יהודה","story":"נבוכדנצר השני כבש את ירושלים לאחר מרד של יהודה. המלך יהויכין, אנשי החצר, חיילים, בעלי מלאכה ואליטות אחרות הוגלו לבבל. הגליה גדולה ראשונה זו קדמה לחורבן המאוחר יותר של ירושלים ובית המקדש הראשון.","context":"האירוע נכלל כדי להציג הן אלימות שהופנתה כלפי קהילות יהודאיות והן עימותים שבהם שליטים או פלגים יהודאיים היו בעצמם צד פעיל.","aftermath":"האירוע החל שלב מרכזי בגלות הבבלית והחליש את ממלכת יהודה לפני החורבן הסופי.","sourceStatus":"ראיות חזקות מן הכרוניקה הבבלית ומן המקרא"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-587-babylonian-destruction-of-jerusalem-and-first-temple-21"]={"title":"חורבן ירושלים ובית המקדש הראשון בידי בבל","location":"ירושלים / יהודה","story":"כוחות בבל כבשו את ירושלים, החריבו את בית המקדש הראשון והביאו לקצה את ממלכת יהודה.","context":"האירוע הוא חלק מן התיעוד הכרונולוגי של אלימות מתועדת נגד הקהילה היהודאית ושל התמוטטות הממלכה תחת האימפריה הבבלית.","aftermath":"החורבן והגלות שינו עמוקות את החיים, הזהות והמוסדות היהודאיים והפכו את בבל למרכז חשוב של חיים יהודיים.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-539-cyrus-conquers-babylon-and-permits-return-22"]={"title":"כורש כובש את בבל ומתיר שיבה","location":"בבל / האימפריה הפרסית / יהודה","story":"כורש השני מלך פרס כבש את בבל בשנת 539 לפנה״ס. המדיניות הפרסית אפשרה לעמים שהוגלו, ובהם יהודאים, לשקם מקדשים וקהילות. המקרא קושר מדיניות זו לשיבה מגלות בבל ולבנייה מחדש בירושלים.","context":"האירוע ממקם את השיבה בתוך המעבר הרחב משלטון בבלי לשלטון פרסי. פרטי השיבה היהודאית נשענים בחלקם על מקורות מקראיים.","aftermath":"השיבה לא הייתה מלאה; קהילה יהודית גדולה נשארה בבבל, בעוד ירושלים ויהודה החלו תהליך של שיקום תחת שלטון פרסי.","sourceStatus":"ראיות חזקות לכיבוש הפרסי ולמדיניות שיקום; פרטי השיבה ליהודה נשענים בחלקם על מקורות מקראיים"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-930-division-into-the-kingdoms-of-israel-and-judah-12"]={"title":"انقسام المملكة إلى إسرائيل ويهوذا","location":"إسرائيل ويهوذا","story":"بعد سليمان، تصف الرواية التوراتية انقسام الملكية إلى مملكة إسرائيل الشمالية ومملكة يهوذا الجنوبية. وبحلول القرن التاسع قبل الميلاد تظهر المملكتان في نقوش خارجية وفي السجل الأثري.","context":"يميز هذا الحدث بين الرواية التوراتية وبين الأدلة الأثرية وغير التوراتية حيث تختلف المصادر.","aftermath":"يعتمد موضعه في الخط الزمني على أفضل تسلسل زمني عام تدعمه الأدلة؛ ولا يزال التسلسل التوراتي الدقيق موضع نقاش.","sourceStatus":"الأدلة قوية على وجود مملكتين منفصلتين في العصر الحديدي؛ أما التسلسل الزمني التوراتي الدقيق فموضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-925-shoshenq-i-campaign-in-the-southern-levant-13"]={"title":"حملة شيشنق الأول في جنوب بلاد الشام","location":"يهوذا / إسرائيل / جنوب بلاد الشام","story":"قاد الفرعون المصري شيشنق الأول حملة في بلاد الشام في القرن العاشر قبل الميلاد. وتوفر النقوش المصرية مرجعًا خارجيًا لحرب أثرت في مستوطنات مرتبطة بإسرائيل ويهوذا المبكرتين؛ أما العلاقة الدقيقة مع رواية شيشق التوراتية فما تزال موضع نقاش.","context":"يميز هذا الحدث بين جوهر الحدث الموثق جيدًا وبين التفاصيل السردية اللاحقة التي تتطلب الحذر.","aftermath":"تُعرض النتائج وأعداد الضحايا بتحفظ، وتُحذف الأرقام الدقيقة عندما لا تسمح المصادر الباقية بالثقة بها.","sourceStatus":"ثقة عالية بوقوع الحملة؛ إعادة بناء الأهداف الدقيقة موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-853-battle-of-qarqar-ahab-of-israel-against-assyria-14"]={"title":"معركة قرقر: أخاب ملك إسرائيل ضد آشور","location":"قرقر، سوريا","story":"سجل الملك الآشوري شلمنصر الثالث معركة كبرى في قرقر ضد تحالف من حكام بلاد الشام. ويذكر نقشه أخاب الإسرائيلي ضمن التحالف وينسب إليه قوة كبيرة من المركبات والمشاة. وهذا دليل خارجي مهم على مكانة مملكة إسرائيل الشمالية كقوة إقليمية.","context":"يميز هذا الحدث بين الرواية التوراتية وبين الأدلة الأثرية وغير التوراتية حيث تختلف المصادر.","aftermath":"يعتمد موضعه على أفضل تسلسل زمني عام تدعمه الأدلة؛ وقد تكون الأرقام العسكرية في النقوش الملكية ذات طابع دعائي.","sourceStatus":"نقش ملكي آشوري معاصر؛ قد تكون الأرقام العسكرية دعائية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-840-mesha-s-revolt-against-israel-15"]={"title":"ثورة ميشع ضد إسرائيل","location":"موآب / مملكة إسرائيل","story":"سجل ميشع ملك موآب في نقش ملكي استعادة أراضٍ من إسرائيل. وتُعد مسلة ميشع مصدرًا معاصرًا غير توراتي بالغ الأهمية للصراع بين موآب ومملكة إسرائيل.","context":"يميز هذا الحدث بين جوهر الحدث الموثق جيدًا وبين التفاصيل اللاحقة التي تتطلب الحذر.","aftermath":"تُعرض النتائج وأعداد الضحايا بتحفظ، وتُحذف الأرقام الدقيقة عندما لا تسمح المصادر الباقية بالثقة بها.","sourceStatus":"ثقة عالية جدًا في جوهر الصراع"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-840-aramean-wars-and-the-tel-dan-stele-16"]={"title":"الحروب الآرامية ومسلة تل دان","location":"شمال إسرائيل / آرام دمشق","story":"يخلد نقش نصر آرامي اكتُشف في تل دان انتصارات على ملوك مرتبطين بإسرائيل و«بيت داود». ويوفر النقش دليلًا مباشرًا على الحروب بين آرام دمشق ومملكتي إسرائيل ويهوذا في القرن التاسع قبل الميلاد.","context":"يميز هذا الحدث بين الرواية التوراتية وبين الأدلة الأثرية وغير التوراتية حيث تختلف المصادر.","aftermath":"يعتمد موضعه على أفضل تسلسل زمني عام تدعمه الأدلة؛ أجزاء من النقش متضررة وتتطلب إعادة بنائها الحذر.","sourceStatus":"نقش تذكاري معاصر أو قريب من العصر؛ توجد أجزاء متضررة في إعادة البناء"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-734-tiglath-pileser-iii-invades-israel-and-the-levant-17"]={"title":"تغلث فلاسر الثالث يغزو إسرائيل وبلاد الشام","location":"مملكة إسرائيل / الجليل / بلاد الشام","story":"غير التوسع الآشوري في عهد تغلث فلاسر الثالث المنطقة. فقد أضعفت حملات ثلاثينيات القرن الثامن قبل الميلاد مملكة إسرائيل الشمالية وضمت أراضي وأدت إلى عمليات ترحيل، ممهدة للغزو الآشوري النهائي للسامرة بعد نحو عقد.","context":"يميز هذا الحدث بين الرواية التوراتية وبين الأدلة الأثرية وغير التوراتية حيث تختلف المصادر.","aftermath":"يعتمد موضعه على أفضل تسلسل زمني عام تدعمه الأدلة؛ وقد تبقى بعض تفاصيل الحملات القديمة موضع نقاش.","sourceStatus":"أدلة آشورية وتوراتية قوية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-722-assyrian-conquest-of-samaria-18"]={"title":"الغزو الآشوري للسامرة","location":"السامرة / مملكة إسرائيل","story":"غزت آشور السامرة وأنهت مملكة إسرائيل الشمالية، وتلت ذلك عمليات ترحيل وإعادة توطين للسكان.","context":"هذا الحدث جزء من السجل الزمني للعنف الموثق الذي شمل مجتمعات إسرائيلية ويهودية. ويوفر المصدر المرفق سياقًا تاريخيًا أوسع.","aftermath":"أنهى الغزو مملكة إسرائيل الشمالية وغير بصورة عميقة السكان والبنية السياسية في المنطقة.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-701-assyrian-invasion-of-judah-and-fall-of-lachish-19"]={"title":"الغزو الآشوري ليهوذا وسقوط لخيش","location":"مملكة يهوذا","story":"دمرت قوات سنحاريب مناطق واسعة من يهوذا واستولت على لخيش، بينما نجت القدس من الحملة.","context":"هذا الحدث جزء من السجل الزمني للعنف الموثق الذي شمل المجتمعات اليهودية. وتتيح المصادر الآشورية والتوراتية والأثرية مقارنة وجهات نظر مختلفة.","aftermath":"تضررت يهوذا بشدة، لكن القدس والمملكة بقيتا تحت ضغط آشوري.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-597-first-babylonian-capture-of-jerusalem-20"]={"title":"الاستيلاء البابلي الأول على القدس","location":"القدس / مملكة يهوذا","story":"استولى نبوخذ نصر الثاني على القدس بعد تمرد يهوذا. ورُحّل الملك يهوياكين وأفراد البلاط والجنود والحرفيون ونخب أخرى إلى بابل. وسبق هذا الترحيل الكبير الأول التدمير اللاحق للقدس والهيكل الأول.","context":"أُدرج الحدث لإظهار العنف الموجه إلى المجتمعات اليهودية وكذلك الصراعات التي كان فيها حكام أو فصائل يهودية أطرافًا فاعلة.","aftermath":"بدأ الحدث مرحلة رئيسية من السبي البابلي وأضعف مملكة يهوذا قبل دمارها النهائي.","sourceStatus":"أدلة قوية من السجل البابلي ومن النصوص التوراتية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-587-babylonian-destruction-of-jerusalem-and-first-temple-21"]={"title":"تدمير البابليين للقدس والهيكل الأول","location":"القدس / يهوذا","story":"استولت القوات البابلية على القدس ودمرت الهيكل الأول وأنهت مملكة يهوذا.","context":"هذا الحدث جزء من السجل الزمني للعنف الموثق ضد المجتمع اليهودي وانهيار المملكة تحت الإمبراطورية البابلية.","aftermath":"غير الدمار والسبي الحياة والهوية والمؤسسات اليهودية بصورة عميقة، وأصبحت بابل مركزًا مهمًا للحياة اليهودية.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-539-cyrus-conquers-babylon-and-permits-return-22"]={"title":"كورش يغزو بابل ويسمح بالعودة","location":"بابل / الإمبراطورية الفارسية / يهوذا","story":"غزا كورش الثاني ملك فارس بابل سنة 539 قبل الميلاد. وسمحت السياسة الفارسية للشعوب المهجرة، ومن بينها اليهوديون، بإعادة بناء المعابد والمجتمعات. وتربط النصوص التوراتية هذه السياسة بالعودة من السبي البابلي وإعادة البناء في القدس.","context":"يضع الحدث العودة ضمن الانتقال الأوسع من الحكم البابلي إلى الحكم الفارسي. وتعتمد تفاصيل العودة اليهودية جزئيًا على المصادر التوراتية.","aftermath":"لم تكن العودة كاملة؛ بقي مجتمع يهودي كبير في بابل، بينما بدأت القدس ويهوذا عملية إعادة بناء تحت الحكم الفارسي.","sourceStatus":"أدلة قوية على الغزو الفارسي وسياسة الاستعادة؛ تفاصيل العودة إلى يهوذا تعتمد جزئيًا على المصادر التوراتية"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1800-jacob-is-given-the-name-israel-0"]={"title":"יעקב מקבל את השם ישראל","location":"כנען / המסורת המקראית","story":"לפי ספר בראשית, יעקב, בנו של יצחק ונכדו של אברהם, מקבל את השם ישראל. צאצאיו נודעים לאחר מכן כבני ישראל. המקרא הוא המקור לסיפור זה; אין תאריך היסטורי עצמאי ומבוסס ליעקב, ולכן התאריך כאן הוא מיקום משוער בתקופה המסורתית ולא תאריך ארכאולוגי.","context":"זוהי נקודת הפתיחה הסיפורית של האתר, ולא האירוע ההיסטורי הראשון המאומת באופן עצמאי. האתר מבחין בין המסורת המקראית לבין עדויות חוץ־מקראיות וארכאולוגיות מאוחרות יותר.","aftermath":"השם ישראל נעשה מרכזי לזהות המקראית של צאצאי יעקב ולמסורות על שנים־עשר שבטי ישראל.","sourceStatus":"סיפור מקראי מסורתי — ללא תיארוך עצמאי"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1750-bnei-yisrael-the-children-of-israel-1"]={"title":"בני ישראל — צאצאי ישראל","location":"המסורת המקראית","story":"בסיפור המקראי, צאצאי יעקב/ישראל נודעים בשם בני ישראל. שנים־עשר השבטים מיוחסים במסורת לבניו ולמשפחתו של יעקב. אירוע זה מסביר את משמעות השם לפני שציר הזמן מגיע לעדויות החוץ־מקראיות העצמאיות על ישראל.","context":"זוהי מסגרת מסורתית של יוחסין וזהות שנשמרה בתנ״ך. אין לראות בה הוכחה ארכאולוגית למשפחה היסטורית אחת שממנה בהכרח יצאו כל בני ישראל המאוחרים.","aftermath":"המונח בני ישראל נעשה כינוי קולקטיבי חוזר בתורה ובספרות המקראית המאוחרת.","sourceStatus":"סיפור מקראי מסורתי"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1650-israel-s-family-goes-down-to-egypt-2"]={"title":"משפחת ישראל יורדת למצרים","location":"מצרים / המסורת המקראית","story":"ספר בראשית מתאר את יעקב/ישראל ובני ביתו עוברים למצרים בזמן רעב, לאחר שיוסף הגיע שם לעמדת סמכות. זהו חלק מסיפור המקור המקראי של בני ישראל; לא זוהתה עדות מצרית עצמאית ומבוססת המתעדת את יעקב או את יוסף.","context":"האירוע נכלל משום שהוא יסודי למסורת המובילה לסיפור יציאת מצרים. מיקומו בזמן משוער ואין לראות בו תאריך ארכאולוגי מבוסס.","aftermath":"בהמשך מתאר הסיפור המקראי את צאצאי ישראל מתרבים במצרים ונכפים לעבודת כפייה.","sourceStatus":"סיפור מקראי מסורתי — התאריך אינו ודאי מבחינה היסטורית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1300-enslavement-of-bnei-yisrael-in-egypt-3"]={"title":"שעבוד בני ישראל במצרים","location":"מצרים / המסורת המקראית","story":"ספר שמות מתאר פרעה חדש המשעבד את בני ישראל ומטיל עליהם עבודת כפייה. הסיפור הוא יסודי להיסטוריה ולזהות היהודית, אך היסטוריונים לא מצאו עדות עצמאית המבססת את השעבוד המקראי בהיקף או בצורה המתוארים.","context":"האתר מציג זאת כמסורת מקראית ולא כאירוע מצרי המתוארך בוודאות. במצרים העתיקה אכן התקיימו עבודות כפייה ועבדות, אך עובדה זו לבדה אינה מאמתת באופן עצמאי את סיפור יציאת מצרים.","aftermath":"לפי הסיפור המקראי, הדיכוי מוביל להנהגתו של משה וליציאת בני ישראל ממצרים.","sourceStatus":"סיפור מקראי מסורתי"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1250-the-exodus-from-egypt-4"]={"title":"יציאת מצרים","location":"מצרים ← סיני / המסורת המקראית","story":"לפי התורה, משה מוביל את בני ישראל מעבדות במצרים אל החירות. יציאת מצרים נעשתה לאחד הסיפורים המרכזיים בזהות ובזיכרון הדתי היהודי. החוקרים ממשיכים לדון בשאלה אם הסיפור משמר זיכרונות של תנועות או אירועים היסטוריים מצומצמים יותר, אך יציאת מצרים כפי שהיא מסופרת במקרא לא הוכחה באופן עצמאי בארכאולוגיה.","context":"האירוע מפריד במכוון בין מסורת דתית ותרבותית לבין היסטוריה המאומתת באופן עצמאי. התאריך הוא מיקום משוער בתקופה המסורתית ולא תאריך מוכח.","aftermath":"הסיפור המקראי ממשיך במסע במדבר, בברית בסיני ובהתפתחות ישראל כעם המאוחד בחוק ובמסורת משותפים.","sourceStatus":"סיפור מקראי מסורתי — לא הוכח באופן עצמאי בהיקף המתואר"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1240-amalek-attacks-bnei-yisrael-5"]={"title":"עמלק תוקף את בני ישראל","location":"רפידים / המסורת המקראית","story":"ספר שמות מתאר את עמלק תוקף את בני ישראל ברפידים במהלך המסע במדבר. טקסטים מקראיים מאוחרים יותר הופכים את עמלק לאויב חוזר בזיכרון הישראלי. אין עדות עצמאית בת התקופה המזהה בוודאות את הקרב המסוים הזה.","context":"מאחר שזהו סיפור על עימות מזוין שבו מעורבים בני ישראל, הוא נכלל בחלק ההיסטוריה המסורתית של הפרויקט, אך מסומן במפורש כסיפור מקראי ולא כהיסטוריה שאומתה באופן עצמאי.","aftermath":"העימות נעשה מוטיב מתמשך בזיכרון המקראי והיהודי המאוחר יותר.","sourceStatus":"סיפור מקראי מסורתי"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1230-joshua-and-warfare-in-canaan-6"]={"title":"יהושע והמלחמות בכנען","location":"כנען / המסורת המקראית","story":"ספר יהושע מתאר מסעות מלחמה של בני ישראל נגד ערים כנעניות לאחר תקופת המדבר. הארכאולוגיה מראה שכנען עברה שינויים פוליטיים וחברתיים גדולים בסוף תקופת הברונזה המאוחרת, אך אינה תומכת בשחזור פשוט שבו כל הערים שבספר יהושע נפלו בכיבוש מאוחד אחד בדיוק כפי שמתואר.","context":"חלק מהאתרים הנזכרים בספר יהושע חוו חורבן בתקופה הכללית הרלוונטית, בעוד שבאתרים אחרים התמונה הארכאולוגית שונה. חצור, למשל, נחרבה במאה ה־13 לפנה״ס, אך זהות האחראים לכך עדיין נתונה במחלוקת.","aftermath":"המסורת המקראית מציגה את המסעות כמובילים להתיישבות שבטי ישראל; השחזור ההיסטורי מצביע במקום זאת על תהליך מורכב של צמיחת ישראל הקדומה מתוך כנען.","sourceStatus":"מסורת מקראית עם הקשר ארכאולוגי חלקי — הפרטים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1208-merneptah-stele-earliest-extra-biblical-reference-to-israel-7"]={"title":"מצבת מרנפתח: האזכור החוץ־מקראי הקדום ביותר של ישראל","location":"כנען","story":"כתובת ניצחון מלכותית מצרית המתוארכת לסביבות 1208 לפנה״ס מכילה את האזכור החוץ־מקראי הקדום ביותר המקובל במחקר לעם בשם ישראל. מרנפתח טוען שקבוצה זו הובסה במסעו בכנען. הכתב המצרי מזהה את ישראל כעם ולא כעיר, טריטוריה, ממלכה או מדינה.","context":"אירוע זה הוא המעבר באתר מן הסיפור המקראי המסורתי לעדות המאומתת באופן עצמאי. הוא מראה שאוכלוסייה שנקראה ישראל התקיימה בכנען בסביבות 1208 לפנה״ס; הוא אינו מוכיח שממלכת ישראל המאוחרת כבר התקיימה. דברי פרעה הם טענת ניצחון מלכותית מצרית, לא הוכחה שעם ישראל הושמד.","aftermath":"עדויות מתקופת הברזל מתעדות מאוחר יותר את ישראל ויהודה כממלכות פוליטיות. התפתחותן המדויקת מאוכלוסיות קדומות יותר באזור ההר ממשיכה להיות נושא למחקר היסטורי וארכאולוגי.","sourceStatus":"כתובת מצרית בת התקופה — האזכור החוץ־מקראי הקדום ביותר המקובל לישראל"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1150-philistine-expansion-and-conflict-with-early-israel-8"]={"title":"התפשטות הפלשתים והעימות עם ישראל הקדומה","location":"דרום כנען / פלשת","story":"הפלשתים ביססו תרבות חומרית ייחודית במישור החוף הדרומי עם נסיגת השליטה המצרית. הממצא הארכאולוגי תומך בקיומם ובהתרחבותם של מרכזים פלשתיים והופך עימות עם קבוצות ישראליות מתהוות לסביר מבחינה היסטורית, אף שלא ניתן לאמת באופן עצמאי את כל הסיפורים בספרי שופטים ושמואל.","context":"האירוע מבחין בין הסיפור המקראי לבין העדויות הארכאולוגיות והחוץ־מקראיות במקומות שבהם המקורות שונים.","aftermath":"מיקומו בציר הזמן מבוסס על הכרונולוגיה הרחבה הנתמכת ביותר; תאריכים קדומים ופרטי מסעות מלחמה עדיין עשויים להיות שנויים במחלוקת.","sourceStatus":"הארכאולוגיה תומכת בהתיישבות פלשתית ובעימות אזורי; חוזק הראיות לפרטים המקראיים משתנה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1050-saul-and-the-philistine-wars-9"]={"title":"שאול והמלחמות בפלשתים","location":"ישראל / פלשת — הסיפור המקראי","story":"ספרי שמואל מתארים את שאול כמלך הראשון של ישראל ואת תקופת שלטונו כמאופיינת במלחמות עם הפלשתים. העימות הפלשתי־ישראלי מתאים להקשר הרחב של תקופת הברזל הנתמך בארכאולוגיה, אך מסעותיו האישיים של שאול והכרונולוגיה שלו ידועים בעיקר מן הסיפור המקראי.","context":"האירוע מבחין בין הסיפור המקראי לבין העדויות הארכאולוגיות והחוץ־מקראיות במקומות שבהם המקורות שונים.","aftermath":"מיקומו בציר הזמן מבוסס על הכרונולוגיה הרחבה הנתמכת ביותר; תאריכים קדומים ופרטי מסעות מלחמה עדיין עשויים להיות שנויים במחלוקת.","sourceStatus":"סיפור מקראי בתוך הקשר היסטורי סביר של עימות בתקופת הברזל"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1010-battle-of-mount-gilboa-and-death-of-saul-10"]={"title":"קרב הר הגלבוע ומות שאול","location":"הר הגלבוע — הסיפור המקראי","story":"לפי ספר שמואל א׳, כוחות פלשתיים הביסו את ישראל בהר הגלבוע. שאול ובניו, ובהם יהונתן, מתו בקרב. האירוע חשוב למעבר המקראי משושלת שאול לדוד, אך אין כתובת חיצונית בת התקופה המתעדת בוודאות את הקרב.","context":"האירוע מבחין בין הסיפור המקראי לבין העדויות הארכאולוגיות והחוץ־מקראיות במקומות שבהם המקורות שונים.","aftermath":"מיקומו בציר הזמן מבוסס על הכרונולוגיה הרחבה הנתמכת ביותר; תאריכים קדומים ופרטי מסעות מלחמה עדיין עשויים להיות שנויים במחלוקת.","sourceStatus":"סיפור מקראי — ללא עדות עצמאית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1000-david-s-wars-and-rise-of-the-israelite-monarchy-11"]={"title":"מלחמות דוד ועליית המלוכה הישראלית","location":"ישראל / יהודה / פלשת","story":"המסורת המקראית מתארת את דוד מביס כוחות פלשתיים ומבסס שלטון מירושלים. הארכאולוגיה והכתובות תומכות בקיומן של יהודה וישראל בתקופת הברזל, בעוד שהיקפה ועוצמתה המדינית של ממלכת דוד עדיין שנויים במחלוקת. מצבת תל דן המאוחרת יותר כוללת את הביטוי הנדון רבות ״בית דוד״ ומספקת עדות חיצונית לשושלת דוידית.","context":"האירוע מבחין בין הסיפור המקראי לבין העדויות הארכאולוגיות והחוץ־מקראיות במקומות שבהם המקורות שונים.","aftermath":"מיקומו בציר הזמן מבוסס על הכרונולוגיה הרחבה הנתמכת ביותר; תאריכים קדומים ופרטי מסעות מלחמה עדיין עשויים להיות שנויים במחלוקת.","sourceStatus":"לשושלת דוידית יש תמיכה חוץ־מקראית; מסעות המלחמה האישיים ידועים בעיקר מן המקרא"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1800-jacob-is-given-the-name-israel-0"]={"title":"يعقوب يُعطى اسم إسرائيل","location":"كنعان / التقليد التوراتي","story":"بحسب سفر التكوين، يُعطى يعقوب، ابن إسحاق وحفيد إبراهيم، اسم إسرائيل. ويُعرف نسله بعد ذلك باسم بني إسرائيل. النص التوراتي هو مصدر هذه الرواية؛ ولا يوجد تاريخ مستقل مثبت ليعقوب، لذلك فإن التاريخ المعروض هنا موضع تقريبي ضمن الحقبة التقليدية وليس تاريخًا أثريًا.","context":"هذه هي نقطة البداية السردية للموقع وليست أول حدث تاريخي موثق بصورة مستقلة. يميز الموقع بين التقليد التوراتي وبين الأدلة اللاحقة غير التوراتية والأثرية.","aftermath":"أصبح اسم إسرائيل محوريًا في الهوية التوراتية لنسل يعقوب وفي تقاليد أسباط إسرائيل الاثني عشر.","sourceStatus":"رواية توراتية تقليدية — غير مؤرخة بصورة مستقلة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1750-bnei-yisrael-the-children-of-israel-1"]={"title":"بنو إسرائيل — أبناء إسرائيل","location":"التقليد التوراتي","story":"في الرواية التوراتية، أصبح نسل يعقوب/إسرائيل يُعرف باسم بني إسرائيل. وتُنسب الأسباط الاثنا عشر تقليديًا إلى أبناء يعقوب وعائلته. يوضح هذا الحدث معنى الاسم قبل أن يصل الخط الزمني إلى الإشارات المستقلة الموثقة إلى إسرائيل.","context":"هذا إطار تقليدي للنسب والهوية محفوظ في الكتاب المقدس العبري. ولا ينبغي الخلط بينه وبين دليل أثري يثبت وجود عائلة تاريخية واحدة انحدر منها جميع الإسرائيليين اللاحقين.","aftermath":"أصبح تعبير بني إسرائيل تسمية جماعية متكررة في التوراة وفي الأدب الكتابي اللاحق.","sourceStatus":"رواية توراتية تقليدية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1650-israel-s-family-goes-down-to-egypt-2"]={"title":"عائلة إسرائيل تنزل إلى مصر","location":"مصر / التقليد التوراتي","story":"يصف سفر التكوين انتقال يعقوب/إسرائيل وأهل بيته إلى مصر أثناء مجاعة، بعد أن وصل يوسف هناك إلى منصب ذي سلطة. وهذا جزء من رواية الأصل التوراتية لبني إسرائيل؛ ولم يُعثر على سجل مصري مستقل وموثوق يوثق يعقوب أو يوسف.","context":"أُدرج هذا الحدث لأنه أساسي في التقليد الذي يقود إلى قصة الخروج. موضعه الزمني تقريبي ولا ينبغي اعتباره تاريخًا أثريًا مثبتًا.","aftermath":"تصف الرواية التوراتية لاحقًا ازدياد نسل إسرائيل في مصر وإخضاعهم للعمل القسري.","sourceStatus":"رواية توراتية تقليدية — التاريخ غير مؤكد تاريخيًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1300-enslavement-of-bnei-yisrael-in-egypt-3"]={"title":"استعباد بني إسرائيل في مصر","location":"مصر / التقليد التوراتي","story":"يصف سفر الخروج فرعونًا جديدًا يستعبد بني إسرائيل ويفرض عليهم العمل القسري. والرواية أساسية في التاريخ والهوية اليهودية، لكن المؤرخين لم يجدوا دليلًا مستقلًا يثبت الاستعباد التوراتي بالحجم أو الصورة الموصوفين.","context":"يعرض الموقع هذا بوصفه تقليدًا توراتيًا لا حدثًا مصريًا مؤرخًا بصورة مؤكدة. استخدمت مصر القديمة العمل القسري وكان فيها مستعبدون، لكن هذه الحقيقة وحدها لا تثبت بصورة مستقلة رواية الخروج.","aftermath":"في الرواية التوراتية، يؤدي الاضطهاد إلى قيادة موسى وخروج بني إسرائيل من مصر.","sourceStatus":"رواية توراتية تقليدية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1250-the-exodus-from-egypt-4"]={"title":"الخروج من مصر","location":"مصر ← سيناء / التقليد التوراتي","story":"بحسب التوراة، يقود موسى بني إسرائيل من العبودية في مصر إلى الحرية. وأصبح الخروج أحد أكثر الروايات مركزية في الهوية والذاكرة الدينية اليهودية. ويواصل الباحثون النقاش حول ما إذا كانت القصة تحفظ ذكريات لتحركات أو أحداث تاريخية أصغر، لكن الخروج التوراتي كما رُوي لم يُثبت بصورة مستقلة في علم الآثار.","context":"يفصل هذا الحدث عمدًا بين التقليد الديني والثقافي وبين التاريخ الموثق بصورة مستقلة. التاريخ المعروض تقدير ضمن الحقبة التقليدية وليس تاريخًا مثبتًا.","aftermath":"تستمر الرواية التوراتية برحلة الصحراء والعهد في سيناء وتطور إسرائيل كشعب مرتبط بشريعة وتقاليد مشتركة.","sourceStatus":"رواية توراتية تقليدية — لم تُثبت بصورة مستقلة بالحجم المروي"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1240-amalek-attacks-bnei-yisrael-5"]={"title":"عماليق يهاجم بني إسرائيل","location":"رفيديم / التقليد التوراتي","story":"يصف سفر الخروج هجوم عماليق على بني إسرائيل في رفيديم أثناء رحلة الصحراء. وتجعل نصوص كتابية لاحقة من عماليق عدوًا متكررًا في الذاكرة الإسرائيلية. ولا يوجد دليل مستقل معاصر يحدد هذه المعركة بعينها بصورة موثوقة.","context":"لأن هذه رواية عن صراع مسلح شارك فيه بنو إسرائيل، فهي مدرجة في قسم التاريخ التقليدي للمشروع، لكنها موسومة بوضوح كرواية توراتية لا كتاريخ موثق بصورة مستقلة.","aftermath":"أصبح الصراع موضوعًا دائمًا في الذاكرة الكتابية واليهودية اللاحقة.","sourceStatus":"رواية توراتية تقليدية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1230-joshua-and-warfare-in-canaan-6"]={"title":"يشوع والحروب في كنعان","location":"كنعان / التقليد التوراتي","story":"يصف سفر يشوع حملات إسرائيلية ضد مدن كنعانية بعد فترة الصحراء. ويُظهر علم الآثار أن كنعان شهدت تغيرات سياسية واجتماعية كبيرة في نهاية العصر البرونزي المتأخر، لكنه لا يؤيد تصورًا بسيطًا سقطت فيه كل المدن المذكورة في يشوع ضمن غزو موحد واحد تمامًا كما تروي القصة.","context":"شهدت بعض المواقع المذكورة في يشوع دمارًا خلال الفترة العامة ذات الصلة، بينما تقدم مواقع أخرى تاريخًا أثريًا مختلفًا. فحاصور مثلًا دُمرت في القرن الثالث عشر قبل الميلاد، لكن هوية المسؤولين عن ذلك لا تزال موضع نقاش.","aftermath":"يعرض التقليد التوراتي الحملات باعتبارها مؤدية إلى استيطان أسباط إسرائيل؛ أما إعادة البناء التاريخية فتشير إلى نشوء معقد لإسرائيل المبكرة من داخل كنعان.","sourceStatus":"رواية تقليدية مع سياق أثري جزئي — التفاصيل موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1208-merneptah-stele-earliest-extra-biblical-reference-to-israel-7"]={"title":"مسلة مرنبتاح: أقدم إشارة خارج الكتاب المقدس إلى إسرائيل","location":"كنعان","story":"يحتوي نقش نصر ملكي مصري يعود إلى نحو 1208 قبل الميلاد على أقدم إشارة غير توراتية مقبولة على نطاق واسع إلى شعب يُدعى إسرائيل. يدعي مرنبتاح أن هذه الجماعة هُزمت خلال حملته في كنعان. وتحدد الكتابة المصرية إسرائيل كشعب لا كمدينة أو إقليم أو مملكة أو دولة.","context":"يمثل هذا الحدث انتقال الموقع من الرواية التوراتية التقليدية إلى الأدلة الموثقة بصورة مستقلة. فهو يبين وجود جماعة تُعرف باسم إسرائيل في كنعان بحلول نحو 1208 قبل الميلاد؛ ولا يثبت أن مملكة إسرائيل اللاحقة كانت قائمة بالفعل. وعبارة الفرعون ادعاء نصر ملكي مصري وليست دليلًا على إبادة شعب إسرائيل.","aftermath":"توثق أدلة العصر الحديدي لاحقًا إسرائيل ويهوذا كمملكتين سياسيتين. ولا يزال تطورهما الدقيق من جماعات المرتفعات الأقدم موضوعًا للبحث التاريخي والأثري.","sourceStatus":"نقش مصري معاصر — أقدم إشارة خارج الكتاب المقدس مقبولة على نطاق واسع إلى إسرائيل"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1150-philistine-expansion-and-conflict-with-early-israel-8"]={"title":"التوسع الفلسطيني والصراع مع إسرائيل المبكرة","location":"جنوب كنعان / فلستيا","story":"أسس الفلسطينيون ثقافة مادية مميزة في السهل الساحلي الجنوبي مع تراجع السيطرة المصرية. وتدعم الأدلة الأثرية وجود المراكز الفلسطينية وتوسعها وتجعل الصراع مع الجماعات الإسرائيلية الناشئة معقولًا تاريخيًا، رغم أنه لا يمكن التحقق بصورة مستقلة من جميع القصص في سفري القضاة وصموئيل.","context":"يميز هذا الحدث بين الرواية التوراتية وبين الأدلة الأثرية وغير التوراتية حيث تختلف المصادر.","aftermath":"يعتمد موضعه في الخط الزمني على أفضل تسلسل زمني عام تدعمه الأدلة؛ وقد تبقى التواريخ القديمة وتفاصيل الحملات موضع نقاش.","sourceStatus":"يدعم علم الآثار الاستيطان الفلسطيني والصراع الإقليمي؛ وتختلف قوة الأدلة على التفاصيل التوراتية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1050-saul-and-the-philistine-wars-9"]={"title":"شاول والحروب مع الفلسطينيين","location":"إسرائيل / فلستيا — الرواية التوراتية","story":"يصف سفرا صموئيل شاول بأنه أول ملوك إسرائيل ويصوران عهده باعتباره مهيمنًا عليه بالحرب مع الفلسطينيين. ويتوافق الصراع الفلسطيني الإسرائيلي مع الإطار الأوسع للعصر الحديدي المدعوم أثريًا، لكن حملات شاول الفردية وتسلسلها الزمني معروفان أساسًا من الرواية التوراتية.","context":"يميز هذا الحدث بين الرواية التوراتية وبين الأدلة الأثرية وغير التوراتية حيث تختلف المصادر.","aftermath":"يعتمد موضعه في الخط الزمني على أفضل تسلسل زمني عام تدعمه الأدلة؛ وقد تبقى التواريخ القديمة وتفاصيل الحملات موضع نقاش.","sourceStatus":"رواية توراتية ضمن سياق تاريخي معقول لصراع في العصر الحديدي"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1010-battle-of-mount-gilboa-and-death-of-saul-10"]={"title":"معركة جبل جلبوع وموت شاول","location":"جبل جلبوع — الرواية التوراتية","story":"بحسب سفر صموئيل الأول، هزمت القوات الفلسطينية إسرائيل في جبل جلبوع. ومات شاول وأبناؤه، ومن بينهم يوناثان، في المعركة. والحدث مهم للانتقال التوراتي من سلالة شاول إلى داود، لكن لا يوجد نقش خارجي معاصر يوثق المعركة بصورة مؤكدة.","context":"يميز هذا الحدث بين الرواية التوراتية وبين الأدلة الأثرية وغير التوراتية حيث تختلف المصادر.","aftermath":"يعتمد موضعه في الخط الزمني على أفضل تسلسل زمني عام تدعمه الأدلة؛ وقد تبقى التواريخ القديمة وتفاصيل الحملات موضع نقاش.","sourceStatus":"رواية توراتية — غير موثقة بصورة مستقلة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1000-david-s-wars-and-rise-of-the-israelite-monarchy-11"]={"title":"حروب داود وصعود الملكية الإسرائيلية","location":"إسرائيل / يهوذا / فلستيا","story":"يصور التقليد التوراتي داود وهو يهزم القوات الفلسطينية ويؤسس حكمه من القدس. وتدعم الآثار والنقوش وجود يهوذا وإسرائيل في العصر الحديدي، بينما لا يزال حجم مملكة داود ونطاق نفوذها السياسي موضع نقاش. وتتضمن مسلة تل دان اللاحقة العبارة المعروفة «بيت داود»، مما يوفر دليلًا خارجيًا على سلالة داودية.","context":"يميز هذا الحدث بين الرواية التوراتية وبين الأدلة الأثرية وغير التوراتية حيث تختلف المصادر.","aftermath":"يعتمد موضعه في الخط الزمني على أفضل تسلسل زمني عام تدعمه الأدلة؛ وقد تبقى التواريخ القديمة وتفاصيل الحملات موضع نقاش.","sourceStatus":"توجد أدلة خارج الكتاب المقدس على السلالة الداودية؛ أما الحملات الفردية فمعروفة أساسًا من الرواية التوراتية"};

